 \label{thm:PTAS for sparse games}
For any $k$, there is a PTAS for the Nash equilibrium problem in
$k$-sparse bimatrix games.

\label{lemma: restated lipton markakis mehta}
Let $\G=(R,C)$ be a normalized bimatrix game and $(x,y)$ a Nash
equilibrium of $\G$. Let $\X$ be the distribution formed by
taking $t=\lceil 16 \log n /\epsilon^2 \rceil$ independent random
samples from $x$ and defining the uniform distribution on the
samples, and similarly define $\cal Y$ by taking samples from $y$.
Then with probability at least $1-\frac{4}{n}$ the following are
satisfied
\begin{enumerate}
\item the pair $(\X,\cal{Y})$ is an $\epsilon$-Nash equilibrium of $\G$; \label{assertion 1 in LMM restated}
\item $|e_i^{\text{\tiny T}} R \Y - e_i^{\text{\tiny T}} R y| \le \epsilon/2$, for all $i\in[n]$; \label{assertion 2 in LMM restated}
\item $|\X^{\text{\tiny T}} C e_j - x^{\text{\tiny T}} C e_j| \le \epsilon/2$, for all $j \in [n]$; \label{assertion 3 in LMM restated}
\end{enumerate}

 \label{claim:cardinality of good multisets is large}
The sets $\A$ and $\B$ satisfy
$$|\A| \ge \left(1-\frac{4}{n}\right)\left( \delta n \right)^t \text{~and~} |\B| \ge  \left(1-\frac{4}{n}\right)\left( \delta n \right)^t.$$

\label{claim: probability of success of linear support large} If $\X', \Y'$ are the uniform distributions over random multisets $A'$ and $B'$ then
\begin{align}
&\Pr \left[ (\X',\Y') \text{ is an $\epsilon$-Nash equilibrium} \right] \notag\\&~~~~~~~~~~~~~~~~~ =  \Omega \left(\delta^2 \cdot n^{-32 \log(1/\delta)/{\epsilon^2}}\right). \label{eq:large support games final probability}
\end{align}

 \label{lem: claim about the properties of strategy of the row player at eps-equilibrium}
Let $\epsilon <1$. If $(x,y)$ is an $\epsilon$-Nash equilibrium of the game $\G_S$, where $x$ is the mixed strategy of the row player and $y$ that of the column player, then the following properties are satisfied by $x$:
\begin{enumerate}
\item $x_i = 0$, for all $i \notin S$;

\item $\ell_1(x, u_S) \le 8 \epsilon$, where $u_S$ is the uniform distribution over $S$, and $\ell_1(x, u_S)$ represents the $\ell_1$ distance between distributions $x$, $u_S$.
\end{enumerate}

\label{claim:superpolynomially many disjoint balls}
There is a family of $\Omega\left(
n^{(.8-34\epsilon)\log_2 n}\right)$ disjoint such balls.

 \label{theorem: no subexponential oblivious PTAS}
For any constant $c\ge 0$, $\epsilon <1$, no oblivious $\epsilon$-approximation algorithm for anonymous games with $2$ strategies and $3$ player types has probability of success larger than $n^{-c} \cdot 2^{-\Omega(1 /
\epsilon^{1/3})}$.

 \label{theorem: structural result for approximate equilibria}
For every $\epsilon >0$, there exists some integer $k=O(1/\epsilon)$ such
that for any $n$-player $2$-strategy anonymous game with payoffs in
$[-1,1]$ there is an $\epsilon$-Nash equilibrium such that

\begin{enumerate}
\item either at most $k^3$ players randomize, and their mixed strategies are integer multiples of $1/k^2$; \label{item in structural result: a few players randomize}
\item or all players who randomize use the same mixed strategy, and this strategy is an integer multiple of $\frac{1}{kn}$.\label{item in structural result: many players randomize}
\end{enumerate}

 \label{lem: bound on l1 from bound on the sum of the half of them}
Let $\{a_i\}_{i=1}^{\ell}$ be real numbers satisfying the following properties for some $k \in \mathbb{R}_+$:
\begin{enumerate}
\item $a_1 \ge a_2 \ge \ldots \ge a_{\ell}$; \label{strange lemma:cond:1}

\item $\sum_{i=1}^{\ell}a_i =0$; \label{strange lemma:cond:2}

\item $\sum_{i=1}^{\ell/2}a_i \le k$. \label{strange lemma:cond:3}
\end{enumerate}
Then
\begin{align}
\sum_{i=1}^{\ell}|a_i| \le 4k. \label{eq:strange lemma:bound on l1 distance}
\end{align}

\label{claim: lower bound: players B and C cannot be both supported on strategy 1}
In every $\delta'$-Nash equilibrium with $\delta' < \delta$,
$$\Pr[\text{B plays $1$}]=0 \text{~or~}\Pr[\text{C plays $1$}]=0.$$

\label{claim:lower bound:many sets}
There exists a subset $T \subseteq \mathcal{T}^k_{\epsilon}$ such
that:
\begin{enumerate}
\item for every $\P, \Q \in T$: $d(\P,\Q) >0$; \label{item in lower bound construction:property 1}
\item $|T| \ge 2^{\Omega \left(\left({1 \over \epsilon}\right)^{1/3}\right)}$; \label{item in lower bound construction:property 2}
\end{enumerate}

 \label{thm:roos}
Let $\mathcal{P}:=(p_i )_{i=1}^n$ be an arbitrary set of probability
values in $[0,1]$ and $\mathcal{X}:=(X_i)_{i=1}^n$ a collection of
independent indicators with $\E[X_i]=p_i$, for all $i\in [n]$; also
let $X:=\sum_i X_i$. Then, for all $m \in \{0,\ldots,n\}$ and any $p
\in (0,1)$,
\begin{align}
Pr[X = m]  = \sum_{\ell = 0}^n \alpha_{\ell}(\mathcal{P}, p)\cdot
\delta^{\ell}\mathcal{B}_{n,p}(m), \label{eq:krawtchouk expansion}
\end{align}
where in the above $\alpha_0(\mathcal{P},p):=1$,
\begin{align}
\alpha_{\ell}(\mathcal{P},p):= \sum_{1 \le k(1) < \ldots < k(\ell)
\le n} \prod_{r=1}^{\ell}(p_{k(r)}-p),~~\text{for all }\ell \in
[n], \label{eq: krawtchouk coefficients}
\end{align}
and
$$\delta^{\ell}\mathcal{B}_{n,p}(m):=\frac{(n-\ell)!}{n!} \frac{\partial^{\ell}}{\partial p^{\ell}}\mathcal{B}_{n,p}(m),$$
and for the purposes of the last definition we interpret
$$\mathcal{B}_{n,p}(m):=b(m,n,p)$$ as a function of the arguments
$m,n,p$ in the natural way:
$$b(m,n,p):=
\begin{cases}
{n \choose m} p^m (1-p)^{n-m},~\text{for}~n,m \in Z_{+},~m \le n;\\
~~~0,~~~~~~~~~~~~~~~~~\text{otherwise}.
\end{cases}$$

\label{lemma:agreeing coefficients}
For sets $\P$ and $\Q$ satisfying property $(C_d)$, and for all $p$:
$$\alpha_{\ell}(\mathcal{P},p) = \alpha_{\ell}(\mathcal{Q},p),~~~\text{for all $\ell=0,\ldots,d$}.$$

 \label{theorem:binomial appx theorem for large guys}
Let $\mathcal{P}:=(p_i )_{i=1}^n \in [1/2,1)^n$ and $\mathcal{Q}:=(q_i)_{i=1}^n \in [1/2,1)^n$ be two collections of  probability values in $[1/2,1)$. Let also $\mathcal{X}:=(X_i)_{i=1}^n$ and $\mathcal{Y}:=(Y_i)_{i=1}^n$ be two collections of independent indicators with $\E[X_i]=p_i$ and $\E[Y_i]=q_i$, for all $i \in [n]$. If for some $d \in [n]$ Condition $(C_d)$ is satisfied, then
$$\left|\left|\sum_{i}{X_i}~;~\sum_{i}{Y_i} \right|\right|= 20(d+1)^{1/4} 2^{-(d+1)/2}.$$

