\label{defn:alg-nat-pf}
	Let $\cM\subseteq\F[x_1,\ldots,x_n]$ be a set of monomials $\cM=\{\vx^\va\}_\va$, and let the set $\Span(\cM)\eqdef\{\sum_{\vx^\va\in \cM} c_\va\vx^\va: c_\va\in\F\}$ be all linear combinations of these monomials.  Let $\cC\subseteq\Span(\cM)$ and $\cD\subseteq \F[\{c_\va\}_{\vx^\va\in \cM}]$ be classes of polynomials, where the latter is in $|\cM|$ many variables. 

	A polynomial $D\in\cD$ is an \demph{algebraic $\cD$-natural proof against $\cC$}, also called a \demph{distinguisher}, if
	\begin{enumerate}
		\item $D$ is a non-zero polynomial.\label{defn:alg-nat-pf:nz}
		\item For all $f\in\cC$, $D$ vanishes on the coefficient vector of $f$, that is, $D(\coeff_{\cM}(f))=0$.\label{defn:alg-nat-pf:vanish}
			\qedhere
	\end{enumerate}

\label{defn:alg-PRF}
	Let $\cM\subseteq\F[x_1,\ldots,x_n]$ be a set of monomials $\cM=\{\vx^\va\}_\va$, and let the set $\Span(\cM)\eqdef\{\sum_{\vx^\va\in \cM} c_\va\vx^\va: c_\va\in\F\}$ be all linear combinations of these monomials.  Let $\cC\subseteq\Span(\cM)$ and $\cD\subseteq \F[\{c_\va\}_{\vx^\va\in \cM}]$ be classes of polynomials, where the latter is in $|\cM|$ many variables. 

	$\cC$ is a \demph{$\cC$-succinct hitting set for $\cD$} if $\cH\eqdef\{\coeff_\cM(f):f\in\cC\}$ is a hitting set for $\cD$.  That is, $D\in\cD$ is non-zero iff $D|_\cH$ is non-zero, that is, there is some $f\in\cC$ such that $D(\coeff_\cM(f))\ne 0$.

\label{thm:natural-proofs-implies-no-succinct-hitting-set}
	Let $\cM\subseteq\F[x_1,\ldots,x_n]$ be a set of monomials $\cM=\{\vx^\va\}_\va$, and let the set $\Span(\cM)\eqdef\{\sum_{\vx^\va\in \cM} c_\va\vx^\va: c_\va\in\F\}$ be all linear combinations of these monomials.  Let $\cC\subseteq\Span(\cM)$ and $\cD\subseteq \F[\{c_\va\}_{\vx^\va\in \cM}]$ be classes of polynomials, where the latter is in $|\cM|$ many variables.

	Then there is an algebraic $\cD$-natural proof against $\cC$ iff $\cC$ is not a $\cC$-succinct hitting set for $\cD$.

\label{defn:succ-gen}
	Let $\cM\subseteq\F[x_1,\ldots,x_n]$ be a set of monomials $\cM=\{\vx^\va\}_\va$, and let the set $\Span(\cM)\eqdef\{\sum_{\vx^\va\in \cM} c_\va\vx^\va: c_\va\in\F\}$ be all linear combinations of these monomials.  Let $\cC\subseteq\Span(\cM)$ and $\cD\subseteq \F[\{c_\va\}_{\vx^\va\in \cM}]$ be classes of polynomials, where the latter is in $|\cM|$ many variables.  Further, let $\cC'\subseteq\F[x_1,\ldots,x_n,y_1,\ldots,y_\ell]$ be another class of polynomials.

	We say that a polynomial map $\cvG:\F^\ell\to\F^\cM$ is a \demph{$\cC$-succinct generator for $\cD$ computable in $\cC'$} if
	\begin{enumerate}
		\item The polynomial $G(\vx,\vy)\eqdef \sum_{\vx^\va\in\cM} \cG_{\vx^\va}(\vy)\cdot\vx^\va$ is a polynomial in $\cC'$, where $\cG_{\vx^\va}(\vy)$ is the polynomial computed by the $\vx^\va$-coordinate of $\cvG$.\label{defn:succ-gen:indexing}
		\item For every value $\vaa\in\F^\ell$, the polynomial $G(\vx,\vaa)\in\cC$.\label{defn:succ-gen:output}
		\item $\cvG$ is a generator for $\cD$. That is, $D\in\cD$ is a non-zero polynomial in $\F[\vc]$ iff $D\circ \cvG\not\equiv 0$ in $\F[\vy]$, meaning that $D(\coeff_\cM (G(\vx,\vy)))\ne 0$ as a polynomial in $\F[\vy]$, where we think of $G(\vx, \vy)$ as a polynomial in the ring $\left( \F[\vy] \right) [\vx]$  and take these coefficients with respect to the $\vx$ variables, so that $\coeff_\cM (G(\vx,\vy))\in\F[\vy]^\cM$.\label{defn:succ-gen:gen}
			\qedhere
	\end{enumerate}

\label{fact:universal}
	Let $\F$ be a field, and let $n,s\ge 1$ and $d\ge 0$. Then there is a $\poly(n,d,s)$-size algebraic circuit $U\in\F[x_1,\ldots,x_n,y_1,\ldots,y_r]$ with $r\le \poly(n,d,s)$ such that $U$ can be constructed in time $\poly(n,d,s)$, and
	\begin{itemize}
		\item $\deg_\vx U(\vx,\vy)\le d$
		\item $\deg_\vy U(\vx,\vy)\le \poly(d)$
		\item If $f\in\F[\vx]$ has $\deg_\vx f\le d$ and $f$ is computed by a size $s$ circuit, then there is some $\vaa\in\F^r$ such that $f(\vx)=U(\vx,\vaa)$.
	\end{itemize}

