\label{th:dictionary-textindexing-HAM}
Let $0 < \eps < 1$ and $(1+\eps) k < d$. 
If there is a data structure for exact (resp., $(1+\eps)$-approximate) text indexing with $k$ mismatches that for a text of length $n$ has construction time $T_{c} (n)$, query time $T_q (n)$, and space $S(n)$, then there is a data structure for exact (resp., $(1+\eps)$-approximate) dictionary look-up with $k$ mismatches that for a dictionary of $d$-length strings of total length $n$ has construction time $T_{c} (3n + 2d) + \mathrm{poly} (d^{\log d})$, query time $T_q (3n + 2d)$, and space $S(3n + 2d)$.

\label{cor:SETH-text-indexing-HAM}
Assuming SETH, for any constant $\delta > 0$ there exists $d = \Theta(\log n)$, and $k = \Theta(\log n)$ such that 
any data structure for text indexing with $k$ mismatches for a string of length $n$ that can be constructed in polynomial time has query time $\Omega (n^{1-\delta})$.

\label{th:dictionary-textindexing-ED}
Let $0 < \eps < 1$ and $(1+\eps) k < d$. 
Suppose there is a data structure for exact (resp., $(1+\eps)$-approximate) text indexing with $k$ differences that for a text of length $n$ has construction time $T_{c} (n)$, query time $T_q (n)$, and space $S(n)$. Then there is a data structure for exact (resp., $(1+\eps)$-approximate) dictionary look-up with $k$ differences that for a dictionary of total length $n$ has construction time $T_{c} (3n+2d)$, query time $T_q (3n + 2d)$, and space $S(3n+2d)$.

\label{def:OV}
Given two sets $A,B$ of $n$ vectors in $\mathbb \{0,1\}^d$ as input, find a pair of vectors $a\in A$, $b\in B$ such that
$\ip{a}{b}=0$, where the inner product is taken in $\mathbb{Z}$.\footnote{Our definition is slightly different than some of the literature, for example, \cite{chen2019equivalence}, which is searching among pairs inside one set. Those two definitions are equivalent up to constant in complexities.}

Given two sets $A,B$ of $n$ points in $\mathbb R^d$ and a distance measure $\Delta$, find a pair of points $a\in A$, $b\in B$ such that 
\begin{align}
    \Delta(a,b)= \min_{a\in A,b\in B} \Delta(a,b).
\end{align}

Given two sets $A,B$ of $n$ points $\in \mathbb R^d$ and a distance measure $\Delta$, find a pair of points $a\in A$, $b\in B$ such that 
\begin{align}
    \Delta(a,b) \leq (1+\xi)\min_{a\in A,b\in B} \Delta(a,b).
\end{align}

\label{def:fg}
Let $p(n)$ and $q(n)$ be non-decreasing functions of $n$. Problem $\mathsf{P}$ is ($p,q$)-reducible to problem $\mathsf{Q}$, denoted as $(\mathsf{P},p)\leq_{\FG} (\mathsf{Q},q)$, if for every $\epsilon$, there exist $\delta>0$, an algorithm $R$ for solving $\mathsf{P}$ with access to an oracle for $\mathsf{Q}$, a constant $d$, and an integer $k(n)$, such that for every $n\ge 1$, the algorithm $R$ takes any instance of $\mathsf{P}$ of size $n$ and 
\begin{itemize}
    \item $R$ runs in at most $d\cdot (p(n))^{1-\delta}$-time, 
    \item $R$ produces at most $k(n)$ instances of $\mathsf{Q}$ adaptively, that is, the $j$th instance $X_j$ is a function of $\{(X_i,y_i)\}_{1\leq i<j}$ where $X_i$ is the $i$th instance produced and $y_i$ is the answer of the oracle for $\mathsf{Q}$ on instance $X_i$, and 
    \item the sizes $n_i$ of the instances $X_i$ for any choice of oracle answers $y_i$ obeys the inequality
    \begin{align}\label{eq:fgr}
        \sum_{i=1}^{k(n)} (q(n_i))^{1-\epsilon} \leq d\cdot (p(n))^{1-\delta}.
    \end{align}
\end{itemize}

\label{thm:classical_fg}
\begin{align}
    (\mathsf{CNF\text{-}SAT}_{n},2^n)\leq_{\FG} (\OV_{n_1,d_1},n_1^2)\leq_{\FG} (\BCP_{n_2,d_2},n_2^2)\leq_{\FG} (\CP_{n_3,d_3},n_3^2),
\end{align}
where $d_1=\Theta(\log n_1)$, $d_2=\Theta(\log n_2)$ and $d_3=(\log  n_3)^{\Omega(1)}$.

\label{def:oisgood}
Let $X:=\{x_1,\dots,x_n\}$ be an instance of some problem and $\ora_X$ be the corresponding quantum oracle. To realize $\ora_X$, we do not need to write down the whole $X$; instead, we can just design a quantum circuit to realize the mapping 
\begin{align}
    \ket{i}\ket{0} \xrightarrow{\ora_X} \ket{i}\ket{x_i}.
\end{align}

\label{def:qfgr}
Let $p(n)$ and $q(n)$ be nondecreasing functions of $n$. Let $\mathsf{P}$ and $\mathsf{Q}$ be two problems in the quantum query model and $\A_{\epsilon}$ be an $\epsilon$-oracle for $\mathsf{Q}$ with error probability $\epsilon\leq 1/3$. $\mathsf{P}$ is quantum ($p,q$)-reducible to $\mathsf{Q}$, denoted as $(\mathsf{P},p)\leq_{\QFG} (\mathsf{Q},q)$, if for every $\epsilon$, there exits a $\delta>0$, and algorithm $R$ with access to $\A_{\epsilon}$, a constant $d$, and an integer $k(n)$, such that for every $n\ge 1$, the algorithm $R$ takes any instance of $\mathsf{P}$ of size $n$ and satisfies the following: 
\begin{itemize}
    \item $R$ can solve $\mathsf{P}$ with success probability at least $2/3$ in time at most $d\cdot p(n)^{1-\delta}$.
    \item $R$ performs at most $k(n)$ quantum queries to $A_\epsilon$. Specifically, in the $j^{th}$ query, let $\mathbf{X}_j:= \{X_{1,j},X_{2,j},\dots\}$ be a set instances of $\mathsf{Q}$. Then, $R$ realizes the oracles $\{\ora_{X_{1,j}},\ora_{X_{2,j}},\dots\}$ in superposition and applies $A_{\eps}$ to solve the instances.
    \item The following inequality holds.
    \begin{align*}
        \sum_{j=1}^{k(n)}c(\mathbf{X}_j)\cdot q(n_j)^{1-\epsilon} \leq d\cdot p(n)^{1-\delta}, 
    \end{align*}
    where $c(\mathbf{X}_j)$ is the time required for $R$ to realize the oracles $\{\ora_{X_{1,j}},\ora_{X_{2,j}},\dots\}$ in superposition and $n_j := \max_{i}|X_{i,j}|$. 
\end{itemize}

\label{lem:sat_q_ov}
\begin{align}
    (\mathsf{CNF\text{-}SAT}_{n},2^{n/2})\leq_{\QFG} (\OV_{n_1,d_1},n_1),
\end{align}
where $n_1=2^{n/2}$ and $d_1=\Theta(n)$.

\label{lem:qbcp_to_cp}
For $d=\Theta(\log n)$,
\begin{align}
    (\BCP_{n,d},n)\leq_{\QFG} (\CP_{n',d'},n'),
\end{align}
where $n' = n^{O(1)}$ and $d'=(\log n)^{c}$ for some constant $c$ and all points have $\{0,1\}$ entries with the Hamming metric.

\label{def:contact_dim}
For any graph $G=(V,E)$, a mapping $\tau:V\rightarrow \R^d$ is said to realize $G$ if for some $\beta>0$, the following holds for every distinct vertices $u,v$:
\begin{align}
    \|\tau(u)-\tau(v)\|_2  =&~\beta ~ \text{if~} \{u,v\}\in E,\\
    \|\tau(u)-\tau(v)\|_2  > &~\beta ~ \text{otherwise.}\notag
\end{align}
The contact dimension of $G$, denoted by $\mathrm{cd}(G)$, is the minimum $d\in \N$ such that there exists $\tau:V\rightarrow \R^d$ realizing $G$.

 \label{lem:cover}
For any bipartite graph $G(A\dot \cup B, E_G)$ where $|A|=|B|=n$ and $E_G\ne \emptyset$, there exist side-preserving permutations $\pi_1,\dots, \pi_k:A\cup B\rightarrow A\cup B$ where $k\leq \frac{2n^2\ln n}{|E_G|}+1$ such that
\begin{align}
    \underset{i\in [k]}{\bigcup} E_{G_{\pi_i}} = E_{K_{n,n}}.
\end{align}
Moreover, such permutations can be found in $O(n^6\log n)$ time.

\label{lem:ov_q_bcp}
For $d=\Theta(\log n)$, 
\begin{align} 
    (\OV_{n,d},n)\leq_{\QFG} (\BCP_{n,d'},n),
\end{align}
where $d'=\Theta(\log n)$.

\label{thm:zov_map}
Let $b,\ell$ be two sufficiently large integers. There is a classical reduction $\psi_{b,\ell}:\{0,1\}^{b\cdot\ell}\rightarrow \Z^\ell$ and a set $V_{b,\ell}\subseteq \Z$, such that for every $x,y\in \{0,1\}^{b\cdot \ell}$,
\begin{align}\label{eq:zov_iff}
    \ip{x}{y}=0~\Leftrightarrow~\ip{\psi_{b,\ell}(x)}{\psi_{b,\ell}(y)}\in V_{b,\ell}
\end{align}
and
\begin{align}
    0\leq \psi_{b,\ell}(x)_i< \ell^{6^{\log^* (b)}\cdot b}
\end{align}
for all possible $x$ and $i\in [\ell]$. Moreover, the computation of $\psi_{b,\ell}(x)$ takes $\poly(b\cdot \ell)$ time, and the set $V_{b,\ell}$ can be constructed in $O\left( \ell^{O(6^{\log^* (b)}\cdot b)}\cdot \poly(b\cdot \ell) \right)$ time.

\label{lem:ov_2_zov}
For $d=\Theta(\log n)$,
\begin{align}
    (\OV_{n,d}, n)\leq_{\QFG} (\ZOV_{n,d'}, n).
\end{align}
where $d'=2^{O(\log^* n_2)}$.

\label{lem:zov_2_bcp}
For $d=2^{O(\log^* n)}$,
\begin{align}
    (\ZOV_{n,d}, n)\leq_{\QFG} (\BCP_{n,d'}).
\end{align}
where $d'=d^2+2$.

  \label{lemma:cp-ecp}
Let $m$ be the number of bits needed to encode each coordinate as a bit string and $d$ be the dimension.
Given an oracle $\ora$ for $\eCP$, there exists an algorithm $A^{\ora}$  that runs in time and query complexity $O(m+\log d )$ that solves the $\CP$.

\label{def:hypergrid}
Let $d, \epsilon, L>0$. A hypergrid $G_{d,\epsilon,L}$ in the space $[0,L]^d$ consists of all  $\eps$-boxes 
\begin{align}
    g := [a_1,b_1)\times [a_2,b_2)\times \cdots \times [a_d,b_d), 
\end{align}
such that
$b_1-a_1=\cdots =b_d-a_d=\epsilon/\sqrt{d}$ \footnote{The diagonal length of an $\eps$-box is $\epsilon$.}, and $a_i$ is divisible by $\epsilon$ for all $i\in [d]$.

\label{defn:kneighbor}
  Let $\epsilon\in \mathbb{R}$. Let $g_1, g_2$ be two $\eps$-boxes in a hypergrid where $\id(g_1) = (x_1,\dots,x_d)$ and $\id(g_2) = (x'_1,\dots,x'_d)$. We say that $g_1$ and $g_2$ are each other's \emph{$\epsilon$-neighbor} if 
\begin{align}
    \sqrt{\sum_{i=1}^d \|x_i-x'_i\|^2} \leq \epsilon
\end{align}

\label{obs:2step}
Let $p_1,p_2\in [0,L]^d$ be any two distinct points.  
\begin{itemize}
    \item If $p_1$ and $p_2$ are in the same $\epsilon$-box, then $\Delta(p_1, p_2) \leq \epsilon$.
    \item If $\Delta(p_1, p_2)\leq \epsilon$, then $g(\id(p_1))$ must be an $\epsilon$-neighbor of $g(\id(p_2))$. 
\end{itemize}

Let $\mathcal{F}$ be a family of permutations on $f:[n]\rightarrow [n]$. $\mathcal{F}$ is $\epsilon$-approximate $d$-wise independent if for any $x_1,\dots,x_d\in [n]$ and for all $y_1,\dots,y_d\in [n]$, 
\begin{align}
    &\frac{1-\epsilon}{n\cdot(n-1)\cdot (n-d+1)}\leq ~ \Pr\left[\bigwedge_{i=1}^n f_i(x_i) = y_i\right] \leq ~  \frac{1+\epsilon}{n\cdot(n-1)\cdot (n-d+1)}.
\end{align}

\label{lem:ehash}
Let $n$ be an even power of a prime number. For any $t\leq n$, $\epsilon>0$, there exists an $\epsilon$-approximate $t$-wise independent family $\mathcal{F}=\{\pi_j| j\in [R]\}$ of permutations $\pi_j: [n]\rightarrow [n]$ such that: 
\begin{itemize}
    \item $R = O\left( \left(n^{t^2}\cdot \epsilon^{-t}\right)^{3+o(1)}   \right)$; 
    \item given $i,j$, $\pi_j(i)$ can be computed in time $O(t\log^2 n)$.
\end{itemize}

In $\xieBCP$, we are given two sets $A,B$ of $n$ points $\in \mathbb R^d$, a distance measure $\Delta$, and $\xi$. The goal is to do the following
\begin{enumerate}
     \item If there exists a pair of points $a\in A$, $b\in B$ such that $\Delta(a,b) \leq \epsilon$, output the pair $(a,b)$.
     \item If for all pairs of points $a\in A$, $b\in B$, $\Delta(a,b) > (1+\xi)\epsilon$,  returns \textsf{no}.
 \end{enumerate}

\label{lemma:represent}
Let $g$ and $g'$ be $\frac{\xi\epsilon}{2\sqrt{d}}$-boxes. If $g$ and $g'$ are $\epsilon$-neighbors, then for all $p \in g$ and $p' \in g'$, 
  $\Delta(p, p') \leq (1+\xi)\epsilon$.

\label{thm:main_lbs}
    	The following unconditional lower bounds hold:
    	\begin{itemize}
    	    \item[\emph{1.}] If $\mathsf{GIP}^k_n$ is $(1/2 + \varepsilon)$-close under the uniform distribution to a function in $\FORMULA[s] \circ \mathcal{G}$, then $$s \;=\; \Omega \! \left ( \frac{n^2}{k^2 \cdot 16^k \cdot \big ({R}^{(k)}_{\varepsilon/(2n^2)}(\mathcal{G}) + \log n \big )^2 \cdot \log^2 (1/\varepsilon)} \right ).$$

    	    \item[\emph{2.}] If $\mathsf{MKtP} \in \FORMULA[s] \circ \mathcal{G}$, then  
    	    $$
               s \;=\; \widetilde{\Omega} \! \left( \frac{n^2}{k^2\cdot16^{k}\cdot R^{(k)}_{1/3}(\mathcal{G})}\right).
    	    $$

    	    \item[\emph{3.}] If $\mathsf{MCSP} \in \FORMULA[s] \circ \mathsf{XOR}$, then $s = \widetilde{\Omega}(n^2)$, where $\widetilde{\Omega}$ hides inverse $\mathsf{polylog}(n)$ factors.
    	\end{itemize}

\label{def:pac}
        Let $\mathcal{C}$ be a class of Boolean functions. We say that a randomized algorithm $A$ \emph{learns} $\mathcal{C}$ if, when $A$ is given oracle access to ${\rm EX}\cprn{f,\mathcal{D}}$ and inputs $1^n$, $\varepsilon$, and $\delta$, the following holds. For every $n$-variate function $f \in \mathcal{C}$, distribution $\mathcal{D}$ supported over $\bool^n$, and real-valued parameters $\varepsilon > 0$ and $\delta > 0$, $A^{{\rm EX}\prn{f,\mathcal{D}}}(1^n, \varepsilon, \delta)$ outputs  with probability at least $1-\delta$ over its internal randomness and the randomness of the example oracle ${\rm EX}\cprn{f,\mathcal{D}}$ a description of a hypothesis $h:\brkts{0,1}^n\to\brkts{0,1}$ such that
        \begin{align*}
            \Prob_{x\sim\mathcal{D}}\csqbra{f\cprn{x}=h\cprn{x}} \;\geq\; 1-\varepsilon.
        \end{align*}
        The \emph{sample complexity} of a learning algorithm is the maximum number of random examples from ${\rm EX}\cprn{f,\mathcal{D}}$ requested during its execution.

 \label{def:nat_prop}
Let $\Gamma$ be a combinatorial property, $\mathcal{C}$ be a circuit class, $\mathfrak{D}$ be a \emph{(}uniform or non-uniform\emph{)} complexity class, and $s \colon \mathbb{N} \to \mathbb{N}$. We say that $\Gamma$ is a $\mathfrak{D}$-natural property useful against $\mathcal{C}[s]$ if there exists $n_0 \in \mathbb{N}$ for which the following holds:
\begin{itemize}
\item \textsf{Constructivity}: $L_\Gamma \in \mathfrak{D}$, i.e., for every $n$, $f_n \stackrel{?}{\in}\Gamma_n$ is decidable in $\mathfrak{D}$.
\item \textsf{Largeness}: For every $n \geq n_0$, $\Pr_{f \sim \mathcal{F}_n}[f \in \Gamma_n] \geq 1/2$.
\item \textsf{Usefulness}: For every $n \geq n_0$, $\mathcal{C}_n[s(n)] \cap \Gamma_n = \emptyset$.
\end{itemize}
If $\mathfrak{D} = \mathsf{BQP}$, we say that $\Gamma$ is a \emph{quantum} natural property.

\label{defn:qnaturalprop}
We say that there is a \emph{(}promise\emph{)} $\mathsf{BQP}$-quantum natural property against $\mathcal{C}$-circuits of size $s$ if there is a quantum algorithm $\calD$ operating over inputs of the form $N = 2^n$ for which the following holds for every large enough parameter $n$:
\begin{itemize}
\item \textsf{Constructiveness:} $\calD$ runs in time polynomial on its input length $N$.
\item \textsf{$s(n)$-hardness:} For every 
$f \in \mathcal{C}_n[s(n)]$, $\calD$ accepts $\mathsf{tt}(f)$ with probability at most $1/3$.
\item \textsf{Density:} There is a set $\Gamma_n \subseteq \{0,1\}^N$ of density $|\Gamma_n|/2^N \geq 1/2$ such that, for every $w \in \Gamma_n$, $\mathsf{fnc}^w \notin \mathcal{C}_n[s(n)]$ and $\calD$ accepts $w$ with probability at least $2/3$.
\end{itemize}

 [Downward self-reducibility]\label{def:downward-selfreducible}
A function $f \colon \{0,1\}^* \to \{0,1\}$ is said to be downward self-reducible if there is a deterministic polynomial-time oracle procedure $A^f$ such that\emph{:}
\begin{enumerate}
 \item[\emph{1.}] On any input $x$ of length $n$, $A^f(x)$ only makes queries of length $< n$.
 \item[\emph{2.}] For every input $x$, $A^f(x) = f(x)$.
\end{enumerate}

 [Random self-reducibility]\label{def:random-selfreducible}
A function $f\colon \{0,1\}^* \to \{0,1\}$ is said to be random self-reducible if there are constants $a, b, c \geq 1$ and polynomial-time computable functions $g \colon \{0,1\}^* \to \{0,1\}^*$ and $h \colon \{0,1\}^* \to \{0,1\}$ satisfying the following conditions\emph{:}

\begin{enumerate}
\item[\emph{1.}] For large enough $n$, for every $x \in \{0,1\}^n$ and for each $i \in \mathbb{N}$ such that $i\in [n^a]$, $g(i,x,r) \sim~\mathcal{U}_n$ when $r \sim \mathcal{U}_{n^{c}}$.
\item[\emph{2.}] For large enough $n$ and for every function $\tilde{f}_n \colon \{0,1\}^n \to \{0,1\}$ that is $(1/n^b)$-close to $f$ on $n$-bit strings, for every $x \in \{0,1\}^n$\emph{:}
$$f(x) = h\big(x, r, \tilde{f}_n(g(1,x,r)), \tilde{f}_n(g(2,x,r)), \ldots , \tilde{f}_n(g(n^a, x, r))\big)$$
with probability $\geq 1-2^{-2n}$ when $r \sim \mathcal{U}_{n^{c}}$.
\end{enumerate}

 \label{t:TV_language} There is a language $L^\star \subseteq \{0,1\}^*$ satisfying the following properties:
\begin{itemize}
    \item $L^\star \in \mathsf{PSPACE}$. In particular, there is a positive constant $d_\star$ such that $L$ on inputs of length $n$ can be computed in time $O(2^{n^{d_\star}})$. 
    \item $L^\star$ is complete for $\mathsf{PSPACE}$ with respect to deterministic polynomial-time reductions.
    \item $L^\star$ is downward-self-reducible and random-self-reducible, with parameters $a_\star$, $b_\star$, and $c_\star$ in Definition \ref{def:random-selfreducible}.
\end{itemize}

[[Diagonalization Lemma, see e.g.~{\cite[Corollary 2]{DBLP:conf/coco/OliveiraS17}}]
\label{lem:diag}
For every $k \in \mathbb{N}$, there exists a language $L_k \in \mathsf{PSPACE}$ such that $L_k$ cannot be computed by Boolean circuits of size $n^k$ whenever $n$ is sufficiently large.

\label{thm:quantum_tight_connection}
For every circuit class $\mathcal{C}$ that is closed under restrictions of input variables to constants $0$ and $1$, at least one of the following lower bounds holds:

\begin{enumerate}
\item For every $k \in \mathbb{N}$ there exists a language $L \in \mathsf{BQE}$ that cannot be computed by general Boolean circuits of size $n^k$, for sufficiently large input lengths $n$.
\item There exists a universal constant $\upsilon \geq 1$ for which the following holds. If there is a promise quantum natural property against $\mathcal{C}[n^a]$, for $a > 1$, then there exists a language $L \in \mathsf{E}$ that cannot be computed by $\mathcal{C}$-circuits of size $n^{a/\upsilon}$, for infinitely many input lengths $n$.
\end{enumerate}

\label{cor:lbs-from-qnp}
Let $\mathcal{C}$ be a circuit class. 
Suppose that for every $a \geq 1$ there is a promise quantum natural property against $\mathcal{C}[n^a]$. Then for every constant $b \geq 1$ we have $\mathsf{BQE} \nsubseteq \mathcal{C}[n^b]$.

\label{lem:nw}
Let $n$ and $t$ be positive integers such that $1 \leq n  \leq t \leq 2^n$, $f \colon \01^n\rightarrow \01$, and consider the corresponding function $\NW^f \colon \01^m\rightarrow \01^t$, where $m  = c n^2$. Let $\mathcal{D}$ be an inherently probabilistic circuit defined over $t$ input bits that satisfies
\begin{align}\label{eq:distinguisher-NW}
\left| \Pr_{s\in \01^m,\,\mathcal{D}} \big [\mathcal{D}(\NW^f(s)) = 1 \big ]
- \Pr_{y\in \01^t,\,\mathcal{D}} \big [\mathcal{D}(y) = 1\big ]
\right | \;\geq\; \gamma.
\end{align}
There exists a probabilistic algorithm $\calB$ with oracle access to $f$ that, given an input $1^t$, runs in time $\mathsf{poly}(t)$ and outputs a deterministic oracle circuit $\mathcal{A}^{\mathcal{O}}$ of size $O(t^2)$ for which the following holds. For any choice of $\mathcal{D}$ as above, with probability $\Omega(\gamma/t^2)$ over the internal randomness of $\mathcal{B}^f$, the generated circuit $\mathcal{A}^\mathcal{O}$ satisfies 


\begin{align}\label{eq:conclusion-nw}
\Pr_{x \in \{0,1\}^n,\,\mathcal{D}}\left[\calA^{\mathcal{D}}(x) = f(x)\right] 
 \geq \frac{1}{2} + \frac{\gamma}{2t}.
\end{align}

\label{lem:nw_quantum} Let $s_F, s_D, t \colon \mathbb{N} \to \mathbb{N}$ and $\gamma \colon \mathbb{N} \to [0,1]$ be constructive functions, where $n \leq t(n) \leq 2^n$ for every $n$. There exists a sequence $\{\mathcal{C}_n^{\mathsf{NW}}\}_{n \geq 1}$ of quantum circuits $\mathcal{C}_n^{\mathsf{NW}}$ such that:
\begin{itemize}
    \item[\emph{(}i\emph{)}] \emph{Input:} Each circuit $\mathcal{C}_n^{\mathsf{NW}}$ gets as input strings $1^n$, $1^{t(n)}$, $\mathsf{code}(D)$, and $\mathsf{code}(F)$, where $\mathsf{code}(D)$ encodes a quantum circuit $D$ of size $\leq s_D(n)$ over $t(n)$ input bits, and $\mathsf{code}(F)$ encodes a quantum circuit $F$ of size $\leq s_F(n)$ over $n$ input bits.
    \item[\emph{(}ii\emph{)}] \emph{Uniformity and Size:} Each circuit $\mathcal{C}_n^{\mathsf{NW}}$ is of size $S(n) = \mathsf{poly}(t(n), s_F(n), s_D(n))$, and there is a uniform deterministic algorithm that given $1^n$ runs in time $\mathsf{poly}(S(n))$ and prints the string $\mathsf{code}(\mathcal{C}_n^{\mathsf{NW}})$.
    \item[\emph{(}iii\emph{)}] \emph{Output and Correctness:} Suppose that the input circuit $F$ computes a Boolean function $f \colon \{0,1\}^n \to \{0,1\}$, and consider the associated function $\mathsf{NW}^f \colon \{0,1\}^{m(n)} \to \{0,1\}^{t(n)}$, where $m(n) = cn^2$. In addition, assume that the input circuit $D$ satisfies
    \begin{align}\label{eq:distinguisher-NW_quantum}
\left| \Pr_{s\in \01^{m(n)},\,D} \big [D(\NW^f(s)) = 1 \big ]
- \Pr_{y\in \01^{t(n)},\,D} \big [D(y) = 1\big ]
\right | \;\geq\; \gamma(n).
\end{align}
Then with probability $\Omega(\gamma(n)/t(n)^2)$ over its output measurement, $\mathcal{C}_n^{\mathsf{NW}}$ produces a string $\mathsf{code}(A)$ encoding a quantum circuit $A$ of size $O(t(n)^2 \cdot s_D(n))$ such that   
\begin{align}\label{eq:conclusion-nw-quantum}
\Pr_{x \in \{0,1\}^n,\,A}\left[A(x) = f(x)\right] \eqdef \E_{x \sim \{0,1\}^n,\; A}\Big[ \norm{\Pi_{f(x)}A\ket{x}\ket{0^{\ell}}}\Big ] 
 \;\geq\; \frac{1}{2} + \frac{\gamma(n)}{2t(n)}.
\end{align}
\end{itemize}

\label{thm:ijkw}
There exists a universal constant $C \geq 1$ for which the following holds. Let $n \geq 1$ be a positive integer,  $k$ be an even integer, and let $\varepsilon, \delta > 0$ satisfy 
\begin{equation}\label{eq:IJKW_relation_eps_delta}
k \geq C \cdot \frac{1}{\delta} \cdot \left [ \log \! \left( \frac{1}{\delta} \right )  + \log \! \left  ( \frac{1}{\varepsilon} \right ) \right ].
\end{equation}
If $\algoIJKW$ is an inherently probabilistic circuit defined over $\mathcal{S}_{n,k}$ with $k$ output bits such that
\begin{align}\label{eq:assumption-ijkw}
\E_{B \sim \calS_{n,k},\; \algoIJKW}\left[\algoIJKW(B) = g^k(B)\right] 
 \geq \eps,
\end{align}
then there is a randomized oracle circuit $\mathcal{B}^\mathcal{O}$ of size $\mathsf{poly}(n,k,\log(1/\delta), 1/\varepsilon)$ such that
\begin{equation}\label{eq:IJKW_conclusion}
\E_{\substack{x \sim \univ,\\y \sim \{0,1\}^*,\;\algoIJKW}}\Big [\mathcal{B}^\algoIJKW(x,y) = g(x)\Big ] \geq 1 - \delta.
\end{equation}
Moreover, there is a uniform randomized algorithm $\mathcal{D}$ that, given $n$, $k$, $\varepsilon$, and $\delta$ satisfying the conditions of the theorem, access to a description of $\algoIJKW$, and the ability to run $\algoIJKW$ on a given input $B \in \mathcal{S}_{n,k}$, computes in time $\mathsf{poly}(n,k,\log(1/\delta), 1/\varepsilon)$  and outputs with probability $\zeta = \Omega(\varepsilon^2)$ over its internal randomness and the randomness of $\algoIJKW$ a description of a circuit $\mathcal{B}^{\mathcal{O}}$ with  this property.

For an edge $(A,B') \in \Is$, we define 
\begin{align}
\ErrCons(A,B') = \E_{\substack{x \in \NB}}
\big[p_{\mathsf{err}}(x,B') \big],
\end{align}

where $p_{\mathsf{err}}(x,B') = \Pr_{y \sim \algoIJKW(B')}[y|_x \neq g(x) \mid y|_A = g^{k/2}(A)]$.

\label{def:excellent}


We call an edge $(A,B)$ $(\eta , \gamma, \alpha)$-{\em excellent} if it is $(\eta, \gamma)$-good~and





\begin{align}\label{eq:def-excellent}
\E_{\substack{B' \sim \mathcal{W}_\Is(A)}} \left[ \ErrCons(A,B')
    \right] \leq \alpha,
\end{align}
where the distribution $\mathcal{W}_\Is(A)$, supported over $N_\Is(A)$, is defined as follows: for each $B' \in N_\Is(A)$, let $p_\mathsf{cons}(B') = \Pr_{\algoIJKW}\big[\algoIJKW(B')|_A = g^{k/2}(A)\big]$. Moreover, let $p_{\mathsf{tot}}(A) = \sum_{B' \in N_\Is(A)} p_{\mathsf{cons}}(B')$. Then each~$B'$ is assigned probability $p_\mathsf{cons}(B')/p_{\mathsf{tot}}(A)$.

\label{lem:excellent-is-abundant}
For any $\alpha < \frac{1}{2}$,
if $\E_{B\in  \mathcal{S}_k}\left[ \mathsf{Corr}(B) \right] \geq \eps$ then at least an $(\varepsilon/3 - \frac{62208}{\alpha^3 \cdot \varepsilon^5} \cdot e^{-\frac{\alpha}{96}\cdot k})$-fraction of the edges $(A,B) \in \Is$ are $(\eps/3,\eps/3,\alpha)$-excellent.

\label{c:claim_star}
For every $(\varepsilon/3, \varepsilon/3)$-good edge $(A,B)$, 
\begin{center}
    if $\Pr_{B'' \sim \mathcal{W}_I(A)}[B''~ \text{is}~A\text{-heavy}] > \alpha/2$ then $\Pr_{B' \sim N_\Is(A)}[B'~ \text{is}~A\text{-heavy} \wedge p_{\mathsf{cons}}(B') \geq \varepsilon^*] > \frac{\alpha}{108} \cdot \varepsilon^3$,
\end{center}
where $\varepsilon^* \eqdef (\alpha/8)\cdot (\varepsilon^2/9)$ and $p_{\mathsf{cons}}(B') = \Pr_{v' \sim \algoIJKW(B')}[v'|_A = g^{k/2}(A)]$.

\label{thm:ijkw_quantum}
There exists a universal constant $C \geq 1$ for which the following holds. Let $n \geq 1$ be a positive integer,  $k$ be an even integer, and let $\varepsilon, \delta > 0$ satisfy 
\begin{equation}\label{eq:IJKW_relation_eps_delta_quantum}
k \;\geq\; C \cdot \frac{1}{\delta} \cdot \left [ \log \! \left( \frac{1}{\delta} \right )  + \log \! \left  ( \frac{1}{\varepsilon} \right ) \right ].
\end{equation}
If $\algoIJKW$ is a quantum circuit of size at most $s$ defined over $\mathcal{S}_{n,k}$ with $k$ output bits such that
\begin{align}\label{eq:assumption-ijkw_quantum}
\E_{B \sim \calS_{n,k},\; \algoIJKW}\left[\algoIJKW(B) = g^k(B)\right] \eqdef \E_{B \sim \calS_{n,k},\; \algoIJKW}\left[\norm{\Pi_{g^{k}(B)}\algoIJKW\ket{B,0^m}}^2 \right]  
 \;\geq\; \eps,
\end{align}
then there is a quantum circuit $\mathcal{B}$ of size $\mathsf{poly}(n,k,s,\log(1/\delta), 1/\varepsilon)$ such that
\begin{equation}\label{eq:IJKW_conclusion_quantum}
\E_{x \sim \{0,1\}^n,\; \mathcal{B}}\Big [\mathcal{B}(x) = g(x)\Big ] \eqdef \E_{x \sim \{0,1\}^n,\; \mathcal{B}}\Big[ \norm{\Pi_{g(x)}\mathcal{B}\ket{x,0^{m'}}}\Big ] \;\geq\; 1 - \delta.
\end{equation}
Moreover, a quantum circuit $\mathcal{B}$ of this form can be constructed with noticeable probability from a quantum circuit $\algoIJKW$ as above by a uniform sequence of quantum circuits, a statement which is formalised as follows. For any choice of constructive functions $\varepsilon = \varepsilon(n)$, $\delta = \delta(n)$, and $k = k(n)$ satisfying the conditions of the theorem, and for any constructive function $s = s(n)$, there is a uniform family $\{\mathcal{C}_n^{\mathsf{IJKW}}\}_{n \geq 1}$ of quantum circuits $\mathcal{C}^{\mathsf{IJKW}}_n$ of size $\mathsf{poly}(n,k,s, \log(1/\delta), 1/\varepsilon)$ for which the following holds. If $\mathcal{C}^{\mathsf{IJKW}}_n$ is given as input a string $\mathsf{code}(\algoIJKW)$ describing a quantum circuit $\algoIJKW$ with the properties above, then when its output is measured it produces with probability $\zeta = \Omega(\varepsilon^2)$ a string $\mathsf{code}(\mathcal{B})$ describing a quantum circuit $\mathcal{B}$ of the desired size and success probability.

\label{lem:dsr_quantum}
Let $s_P \colon \mathbb{N} \to \mathbb{N}$ be a constructive function. Let $L^\star$ be the language from Theorem \ref{t:TV_language}. There is a sequence $\{\mathcal{C}_n^{\mathsf{DR}}\}_{n \geq 1}$ of deterministic circuits $\mathcal{C}_n^{\mathsf{DR}}$ for which the following holds:
\begin{itemize}
    \item[\emph{(}i\emph{)}] \emph{Input:} Each circuit $\mathcal{C}_n^{\mathsf{DR}}$ gets as input $1^n$ and a string $\mathsf{code}(P_{n - 1})$ that describes a quantum circuit $P_{n-1}$ of size $\leq s_P(n-1)$.
    \item[\emph{(}ii\emph{)}] \emph{Uniformity and Size:} Each circuit $\mathcal{C}^{\mathsf{DR}}_n$ is of size $S(n) = \mathsf{poly}(n, s_P(n-1))$, and there is a deterministic algorithm that when given $1^n$ prints $\mathsf{code}(\mathcal{C}^{\mathsf{DR}}_n)$ in time $\mathsf{poly}(S(n))$.
    \item[\emph{(}iii\emph{)}] \emph{Output and Correctness:} If $P_{n - 1}$ computes $L^\star$ on inputs of length $n - 1$ then $\mathcal{C}^{\mathsf{DR}}_n$ outputs the description of a quantum circuit $P_n$ of size $\mathsf{poly}(n, s_P(n-1))$ that computes $L^\star$ on inputs of length $n$.






\end{itemize}

\label{lem:quantum_self_reducibility_lemma}
Let $s_A, s_P, t \colon \mathbb{N} \to \mathbb{N}$ be constructive functions. Moreover, let $L^\star$ be the language from Theorem \ref{t:TV_language}, and $a_\star, b_\star$ be the associated constants. There is a sequence $\{\mathcal{C}^{\mathsf{SR}}_n\}_{n \geq 1}$ of quantum circuits $\mathcal{C}^{\mathsf{SR}}_n$ for which the following holds:
\begin{itemize}
    \item[\emph{(}i\emph{)}] \emph{Input:} Each circuit $\mathcal{C}^{\mathsf{SR}}_n$ gets as input $1^n$ and strings $\mathsf{code}(P_{n-1})$, $\mathsf{code}(A_1), \ldots, \mathsf{code}(A_{t(n)})$, where $P_{n-1}$ is a quantum circuit of size $\leq s_P(n-1)$ and each $A_i$ is a quantum circuit of size~$\leq s_A(n)$.
    \item[\emph{(}ii\emph{)}] \emph{Uniformity and Size:} Each circuit $\mathcal{C}^{\mathsf{SR}}_n$ is of size $S(n) = \mathsf{poly}(n,t(n),s_A(n),s_P(n-1))$, and there is a deterministic algorithm that when given $1^n$ prints $\mathsf{code}(\mathcal{C}^{\mathsf{SR}}_n)$ in time $\mathsf{poly}(S(n))$.
    \item[\emph{(}iii\emph{)}] \emph{Output and Correctness:} Assume that $P_{n - 1}$  computes $L^\star$ on inputs of length $n - 1$, and that there exists $i \in [t(n)]$ such that
    \begin{align}
    \label{eq:goodAi}
    \Pr_{x \sim \{0,1\}^n,\,A_i}[A_i(x) = L^\star(x)] \;\geq\; 1 - n^{-2b_\star-a_\star}.
    \end{align}
    Then with probability at least $1 - 1/500n^2$ over its output measurement, $\mathcal{C}^{\mathsf{SR}}_n$ generates the description $\mathsf{code}(B_n)$ of a quantum circuit $B_n$ of size $\mathsf{poly}(n,s_A(n))$ that correctly computes $L^\star$ on inputs of length $n$. In other words, for every $x \in \{0,1\}^n$,
    $$
    \Pr_{B_n}[B_n(x) = L^\star(x)] \geq 2/3.
    $$
\end{itemize}

\label{t:main_PRG_restated}
Suppose that $\mathsf{PSPACE} \nsubseteq \mathsf{BQSUBEXP}$. In other words, there is a language $L \in \mathsf{PSPACE}$ and $\gamma > 0$ such that $L \notin \mathsf{BQTIME}[2^{n^\gamma}]$. Then, for some choice of constants $\alpha \geq 1$ and $\lambda \in (0,1/5)$, there is an infinitely often $(\ell, m, s, \varepsilon)$-generator $G = \{G_n\}_{n \geq 1}$, where 
$\ell(n) \leq n^\alpha$, $m(n) = \lfloor 2^{n^\lambda} \rfloor$,  $s(m) = 2^{n^{2\lambda}} \geq \mathsf{poly}(m)$ \emph{(}for any polynomial\emph{)}, and $\varepsilon(m) = 1/m.$

\label{lem:main_PRG}
There exist universal constants $C_U \geq C_Q \geq C_P \geq 1$ for which the following holds. Let $s_P(n) \eqdef 2^{C_P \cdot n^{2 \lambda}}$ for every $n \geq 1$. For every $j \in \{\kappa, \ldots, n\}$, there is a  quantum circuit $Q'_j$ such~that:
\begin{itemize}
    \item[\emph{(}i\emph{)}] \emph{Input:} $Q'_j$ expects as input the description of a quantum circuit $P_{j - 1}$ of size $\leq s_P(j-1).$
    \item[\emph{(}ii\emph{)}] \emph{Size and Uniformity:} $Q'_j$ is a circuit of size $\leq 2^{C_Q  \cdot j^{2 \lambda}}$. Moreover, there is a deterministic algorithm that when given $1^j$ prints $\mathsf{code}(Q'_j)$ in time $\leq 2^{C_U \cdot j^{2 \lambda}}$.
    \item[\emph{(}iii\emph{)}] \emph{Output and Correctness:} If the input circuit $P_{j - 1}$ correctly computes $f_{j - 1}$, then with probability at least $1 - 1/100j^2$ over its output measurement, $Q'_j$ generates the description of a circuit $P_j$ of size $\leq s_P(j)$ that  computes $f_j$.
\end{itemize}

