If $\Phi$ is a set of two-sorted formulas, then $\Phi$-IND axioms are the formulas
\begin{equation}
  \phi(0) \wedge \forall x (\phi(x)\to \phi(x+1))\to \forall z \phi(z),
\end{equation}
where $\phi$ is any formula in $\Phi$. The formula $\phi(x)$ may have other free variables than $x$ of both sorts.

The number minimization axioms (or the least number principle axioms) for a set $\Phi$ of formulas are denoted by $\Phi$-MIN and consist of the formulas
\begin{equation}
    \phi(y)\to \exists x\leq y (\phi(x)\wedge \neg \exists H<x \,\phi(z)),
\end{equation}
where $\phi$ is a formula in $\Phi$. Similarly, the number maximization axioms for $\Phi$ are denoted by $\Phi$-MAX and consist of the formulas 
\begin{equation}
    \phi(0)\to \exists x\leq y (\phi(x)\wedge \neg \exists H\leq y(x<z\wedge \phi(z))),
\end{equation}
where $\phi$ is a formula in $\Phi$. In the above definitions, $\phi$ is permitted to have free variables of both sorts, in addition to $x$.

 If $\Phi$ is a set of two-sorted formulas, then $\Phi$-COMP is the set of all formulas
\begin{equation}
    \forall x\exists X\leq x\,\forall y< x \, y\in X \equiv \phi(y),
\end{equation}
where $\phi$ is any formula in $\Phi$, and $X$ does not occur free in $\phi(y)$. The formula $\phi(y)$ may have other free variables than $y$ of both sorts.

\label{4cases}
If $\mathbb{A}$ is a nontrivial finite idempotent algebra with WNU operation, then at least one of the following is true:
\begin{itemize}
    \item $\mathbb{A}$ has a nontrivial binary absorbing subuniverse,
    \item $\mathbb{A}$ has a nontrivial centrally absorbing subuniverse,
    \item $\mathbb{A}$ has a nontrivial PC quotient,
    \item $\mathbb{A}$ has a nontrivial affine quotient.
\end{itemize}

A \emph{directed input graph} is a pair $\mathcal{X} = (V_\mathcal{X},E_\mathcal{X})$ with $V_\mathcal{X}(i)$ for all $i<V_\mathcal{X}=n$ and $E_\mathcal{X}(i,j)$ being a binary relation on $V_\mathcal{X}$ (there is an edge from $i$ to $j$). A \emph{target digraph with domains} is an $(n+2)$-tuple of sets $\ddot{\mathcal{A}}=( V_{\ddot{\mathcal{A}}},E_{\ddot{\mathcal{A}}},D_0,...,$ $D_{n-1})$, where
\begin{itemize}
    \item $V_{\ddot{\mathcal{A}}}< \langle n,l\rangle$ is the set corresponding to the superdomain,
    \item $\forall i<n,\,D_i< l$ is the subset of length $l$ corresponding to the domain of variable $x_i$,
    \item $V_{\ddot{\mathcal{A}}}(i,a)\iff  D_i(a)$,
    \item $E_{\ddot{\mathcal{A}}}<\langle\langle n,l\rangle,\langle n,l\rangle \rangle$ is the set encoding relations $E^{ij}_{\ddot{\mathcal{A}}}(a,b)$ (there is an edge $(a,b)$ between $D_i$ and $D_j$): 
\begin{equation}
    \begin{split}
       &E_{\ddot{\mathcal{A}}}(u,v)\rightarrow \exists i,j<n\,\exists a,b<l\,\, u = \langle i,a\rangle\wedge v = \langle j,b\rangle\wedge\\
       &\hspace{80pt} D_i(a)\wedge D_j(b).
    \end{split}
\end{equation}
\end{itemize}
Sometimes we will use the notation $E^{ij}_{\ddot{\mathcal{A}}}(a,b)$ instead of $E_{\ddot{\mathcal{A}}}(\langle i,a \rangle, \langle j,b\rangle)$ for brevity sake. We will denote a pair of sets $\Theta =(\mathcal{X},\ddot{\mathcal{A}})$, satisfying all above conditions, by DG$(\Theta)$, and will call $\Theta$ an instance. This representation will allow us to construct a homomorphism from $\mathcal{X}$ to $\ddot{\mathcal{A}}$ with respect to different relations $E^{ij}_{\ddot{\mathcal{A}}}$ and different domains for all vertices $x_1,...,x_n$.


A map $H$ is a \emph{homomorphism between input digraph} $\mathcal{X}=(V_{\mathcal{X}},E_{\mathcal{X}})$, $V_{\mathcal{X}}=n$ \emph{and target digraph with domains} $\ddot{\mathcal{A}}=(V_{\ddot{\mathcal{A}}},E_{\ddot{\mathcal{A}}},D_0,...,D_{n-1})$, $V_\mathcal{A}<\langle n,l\rangle$ if $H$ is a homomorphism from $\mathcal{X}$ to $\ddot{\mathcal{A}}$ sending each $i\in V_\mathcal{X}$ to domain $D_i$ in $V_{\ddot{\mathcal{A}}}$.
The statement that there exists such an $H$ can be expressed by the $\Sigma^{1,b}_{1}$-formula
\begin{equation}\label{HOMINSTAG}
 \begin{split}
&\hspace{10pt}\ddot{HOM}(\mathcal{X},\ddot{\mathcal{A}}) \iff \exists H < \langle n,\langle n,l\rangle\rangle \big(MAP(V_\mathcal{X}, n,V_{\ddot{\mathcal{A}}},\langle n,l\rangle,H)\wedge \\
&\hspace{35pt}(\forall i<n,s<\langle n,l\rangle \,\, H(i)=s\rightarrow \exists a<l, s=\langle i,a\rangle\wedge D_i(a))\wedge \\
&\hspace{100pt}\forall i_1,i_2<n,\forall j_1,j_2<\langle n,l\rangle\\
&\hspace{40pt}(E_{\mathcal{X}}(i_1,i_2)\wedge H(i_1)=j_1\wedge H(i_2)=j_2\rightarrow E_{\ddot{\mathcal{A}}}(j_1,j_2)).
 \end{split}
\end{equation}

An instance $\Theta = (\mathcal{X}, \ddot{\mathcal{A}})$ with $V_{\mathcal{X}}=n$, $V_{\ddot{\mathcal{A}}}<\langle n,l \rangle$ is $1$-consistent if it satisfies the following $\Sigma^{1,b}_0$-definable relation
\begin{equation}
    \begin{split}
        &\hspace{50pt}1C(\mathcal{X}, \ddot{\mathcal{A}})\iff \forall i<n, \forall a\in D_i, \forall j<n, \\
        &(E_{\mathcal{X}}(i,j) \rightarrow \exists b \in D_j, E^{ij}_{\mathcal{A}}(a,b))\wedge(E_{\mathcal{X}}(j,i) \rightarrow \exists b \in D_j, E^{ji}_{\mathcal{A}}(b,a)).
    \end{split}
\end{equation}
The instance $\Theta = (\mathcal{X}, \ddot{\mathcal{A}})$ is cycle-consistent if it is $1$-consistent and any undirected cycle $\mathcal{C}_t$ that can be homomorphically mapped into $\mathcal{X}$ with $H(0)=x_k$ can be homomorphically mapped into $\ddot{\mathcal{A}}$ for any $a\in D_k$. Cycle-consistency is expressed by the following $\Pi^{1,b}_2$-formula
\begin{equation}\label{DEFINITIONOFCYCLECONSISTENCY}
    \begin{split}
        &\hspace{20pt}CC(\mathcal{X},  \ddot{\mathcal{A}})\iff 1C(\mathcal{X}, \ddot{\mathcal{A}})\wedge \forall k<n,\forall a\in D_k,\forall t<n, \forall V_{\mathcal{C}_t}=t,\\
        & \forall E_{\mathcal{C}_t}\leq 4t^2,\forall H<\langle t,n \rangle,\big[ CYCLE(V_{\mathcal{C}_t},E_{\mathcal{C}_t})\wedge HOM(\mathcal{C}_t,\mathcal{X},H)\wedge H(0,k)\\   
        &\hspace{85pt}\rightarrow\exists H'< \langle t,\langle t,l\rangle\rangle, \ddot{HOM}(\mathcal{C}_t,\ddot{\mathcal{A}},H') \wedge\\
        &\hspace{10pt}\wedge\forall i<n,j<t\, (H(j)=i\rightarrow \exists b\in D_i,\, H'(j)=\langle i,b\rangle)\wedge H'(0)=\langle k,a\rangle\big].
    \end{split}
\end{equation}

We say that an instance $\Theta = (\mathcal{X}, \ddot{\mathcal{A}})$ with $V_{\mathcal{X}}=n$, $V_{\ddot{\mathcal{A}}}<\langle n,l \rangle$ is linked if it satisfies the following $\Sigma^{1,b}_1$-relation
\begin{equation}\label{HOMINSTAG}
\begin{split}
&\hspace{10pt}LNKD(\mathcal{X}, \ddot{\mathcal{A}}) \iff\forall i<n, \forall a,b\in D_{i},\, Linked(a,b,i,i,\Theta).
\end{split}
\end{equation}

A fragmented instance is an instance whose input digraph $\mathcal{X}$ is not connected. For an instance $\Theta = (\mathcal{X},  \ddot{\mathcal{A}})$ with $V_{\mathcal{X}}=n$ we define this by the following $\Sigma^{1,b}_1$-definable relation, where $PSS$ encodes a proper subset.
\begin{equation}\label{HOMINSTAG}
 \begin{split}
&\hspace{30pt}FRGM(\mathcal{X}, \ddot{\mathcal{A}}) \iff \exists V^1_\mathcal{X}, \exists V^2_\mathcal{X}, V^1_\mathcal{X}=V^2_\mathcal{X} = n\wedge \\
&\wedge PSS(V^1_\mathcal{X},V_\mathcal{X})\wedge PSS(V^2_\mathcal{X},V_\mathcal{X})\wedge (\forall i<n,\,V^1_\mathcal{X}(i)\leftrightarrow \neg V^2_\mathcal{X}(i))\wedge \\
&\hspace{40pt}\wedge \forall i\in V^1_\mathcal{X},\forall j\in V^2_\mathcal{X},\,\,\neg E_{\mathcal{X}}(i,j)\wedge \neg E_{\mathcal{X}}(j,i).
 \end{split}
\end{equation}

We say that an instance $\Theta = (\mathcal{X}, \ddot{\mathcal{A}})$ with $V_{\mathcal{X}}=n$, $V_{\ddot{\mathcal{A}}}<\langle n,l \rangle$ is irreducible if any its subinstance is fragmented, or linked, or its solution set is subdirect. To express it we use the $\Pi^{1,b}_2$-formula 
\begin{equation}\label{HOMINSTAG}
 \begin{split}
&\hspace{20pt}IRD(\mathcal{X}, \ddot{\mathcal{A}})\iff \forall \mathcal{X'} = (V_{\mathcal{X'}},  E_{\mathcal{X'}}), \forall V_{\mathcal{X'}}=n, \forall E_{\mathcal{X'}}<4n^2,\\ 
&\hspace{0pt}\big(SINST(\mathcal{X}',\mathcal{X})\rightarrow FRGM(\mathcal{X'}, \ddot{\mathcal{A}})\vee LNKD(\mathcal{X'}, \ddot{\mathcal{A}})\vee SSS(\mathcal{X'}, \ddot{\mathcal{A}})      \big).
 \end{split}
\end{equation}

A pair of sets $\Theta=(\mathcal{X},\ddot{\mathcal{A}})$ is a CSP instance over constraint language $\Gamma_{\mathcal{A}}$ on $A$ of size $l$ if the following $\Sigma^{1,b}_0$-relation is true.
\begin{equation}
    \begin{split}
        &INST(\Theta,\Gamma_{\mathcal{A}})\iff DG(\Theta)\wedge \forall i<n, |D_i|=l\wedge\\
        &\hspace{20pt}\wedge \forall i,j<n,a,b<l, \exists s <|\Gamma_{\mathcal{A}}|, E_{\ddot{\mathcal{A}}}(\langle i,a \rangle,\langle j,b \rangle)\leftrightarrow \Gamma_{\mathcal{A}}^2(s,a,b)\wedge\\
        &\hspace{120pt}\wedge\forall i<n,a<l,\exists s<|\Gamma_{\mathcal{A}}|, D_i(a)\leftrightarrow \Gamma_{\mathcal{A}}^1(s,a).
    \end{split}
\end{equation}

For any constraint language $\Gamma_{\mathcal{A}}$ over set $A$ of size $l$, fixed algebra $\mathbb{A}=(A,\Omega)$ with $\Omega$ being an $m$-ary special WNU operation, and finitely many subuniverses $D$ of $\mathbb{A}$ and binary absorbing subuniverses $B$ of $\mathbb{D}$ the \emph{binary absorption axiom scheme} is denoted by BA$_\mathcal{A}$-axioms and consists of the finitely many formulas of the following form 
\begin{equation}
\begin{split}
&\hspace{30pt}BA_{\mathcal{A},B,D}=_{def}\forall\mathcal{X}=(V_{\mathcal{X}},E_{\mathcal{X}}),\forall\ddot{\mathcal{A}}=(V_{\ddot{\mathcal{A}}},E_{\ddot{\mathcal{A}}},D_0,...,D_{n-1}),\\
&\hspace{45pt}\big(PSS(B,D)\wedge SwNU_m(\Omega,D)\wedge SwNU_m(\Omega,B)\wedge\\
&\hspace{55pt}\wedge\exists T <(3l)^{2^3}, Pol_{2}(T,D, \Gamma_{\mathcal{A}})\wedge BAS(B,D,T) \wedge\\
&\hspace{55pt}\wedge  INST(\Theta,\Gamma_{\mathcal{A}})\wedge CC(\mathcal{X},\ddot{\mathcal{A}})\wedge IRD(\mathcal{X},\ddot{\mathcal{A}})\wedge \\
&\hspace{125pt}\exists i<n, D_i=D\wedge\\ 
&\hspace{20pt}HOM(\mathcal{X},\ddot{\mathcal{A}})\big)\rightarrow HOM(\mathcal{X},\ddot{\mathcal{A}}=(V_{\ddot{\mathcal{A}}},E_{\ddot{\mathcal{A}}},D_0,...,B,...,D_{n-1})).
\end{split}
\end{equation}

For any constraint language $\Gamma_{\mathcal{A}}$ over set $A$ of size $l$, fixed algebra $\mathbb{A}=(A,\Omega)$, with $\Omega$ being an $m$-ary special WNU operation, and finitely many subuniverses $D$ of $\mathbb{A}$ and central subuniverses $C$ of $\mathbb{D}$ we denote the \emph{central subuniverse axiom scheme} by CR$_\mathcal{A}$-axioms. The scheme embraces the finitely many formulas of the following form
\begin{equation}
\begin{split}
&\hspace{25pt}CR_{\mathcal{A},D,C}=_{def}\forall \mathcal{X}=(V_{\mathcal{X}},E_{\mathcal{X}}),\forall\ddot{\mathcal{A}}=(V_{\ddot{\mathcal{A}}},E_{\ddot{\mathcal{A}}},D_0,...,D_{n-1}),\\
&\hspace{40pt}\big(PSS(C,D)\wedge SwNU_m(\Omega,D)\wedge SwNU_m(\Omega,C)\wedge\\
&   \hspace{45pt}\ \exists S<(4l)^{2^4},\,Pol_3(S, D,\Gamma_{\mathcal{A}})\wedge CRS(C,D,S) \wedge  \\
&\hspace{50pt}\wedge  INST(\Theta,\Gamma_{\mathcal{A}})\wedge CC(\mathcal{X},\ddot{\mathcal{A}})\wedge IRD(\mathcal{X},\ddot{\mathcal{A}})\wedge \\
&\hspace{125pt}\exists i<n, D_i=D\wedge\\ 
&\hspace{20pt}HOM(\mathcal{X},\ddot{\mathcal{A}})\big)\rightarrow HOM(\mathcal{X},\ddot{\mathcal{A}}=(V_{\ddot{\mathcal{A}}},E_{\ddot{\mathcal{A}}},D_0,...,C,...,D_{n-1})).
\end{split}
\end{equation}

