\label{thm:msor1-nd}
\MSOR{1} parameterized by $\nd + |\phi|$ is fixed-parameter tractable.
Furthermore, for a yes instance of \MSOR{1}, finding a shortest $\TJ(\phi)$-sequence is fixed-parameter tractable with the same parameter.

\label{obs:nd-rshape}
$R \subseteq V$ has shape $\shape_{S}$ ($\shape_{S'}$)
if and only if $R = S$ ($R = S'$, resp.).

\label{lem:nd-shape}
If $R, R' \subseteq V$ have the same shape,
then $G \models \phi(R)$ if and only if $G \models \phi(R')$.

\label{cor:msor2-vc}
\MSOR{2} parameterized by $\vc + |\phi|$ is fixed-parameter tractable.
Furthermore, for a yes instance of \MSOR{2}, finding a shortest $\TJ$-sequence is fixed-parameter tractable with the same parameter.

\label{thm:msor2-td+k}
\MSOR{2} parameterized by $\td + k + |\phi|$ is fixed-parameter tractable, where $k$ is the size of input sets.
Furthermore, for a yes instance of \MSOR{2}, finding a shortest $\TJ$-sequence is fixed-parameter tractable with the same parameter.

\label{cor:msor1-cd+k}
\MSOR{1} parameterized by $\cd + k + |\phi|$ is fixed-parameter tractable, where $k$ is the size of input sets.
Furthermore, for a yes instance of \MSOR{1}, finding a shortest $\TJ(\phi)$-sequence is fixed-parameter tractable with the same parameter.

\label{thm:pspcae-c_td=3}
For some fixed $\phi$,
\MSOR{1} is PSPACE-complete on uncolored forests of depth~$3$.

\label{lem:nonclean-interval}
If $S_{i}$ and $S_{i'}$ are clean, $i + 1 < i'$, and $S_{j}$ is not clean for all $j$ with $i < j < i'$,
then $\mathcal{S}_{i'}$ can be obtained from $\mathcal{S}_{i}$ by a split or a merge.

\label{prop:symm_evasive}
  For every non-constant symmetric boolean function $f: \boolfn{n}$,
  \begin{enumerate}
  \item $f$ is evasive (has $\Depth(f)=n$). (See eg.\ Lemma 14.19
    \cite{Jukna-BFCbook}.)
  \item Hence, for any weights $w_i$, $\wDepth(f,[w_1,w_2,...,w_n] ))=\sum_i w_i$.
  \end{enumerate}

\label{prop:prop_rank_tree}
  For any binary tree $T$, 
\begin{enumerate}
\item \label{item-rank-size} (Rank and Size relationship): $\Rank(T) \le \log(\Size(T)) \le \Depth(T)$. 
\item \label{item-monotonicity} (Monotonicity of the Rank): Let $T'$ be any subtree of $T$, and let $T''$ be an arbitrary binary tree of higher rank than $T'$. If  $T'$ is replaced by $T''$ in $T$, then the rank of the resulting tree is not less than the rank of $T$.
\item \label{item-leaf-depth-rank} (Leaf Depth and Rank): If all leaves in $T$ have depth at least $r$, then $\Rank(T)\ge r$.
\end{enumerate}

\label{prop:rank_size}
  For a non-constant Boolean function $f: \boolfn{n}$,
$$\Rank(f)\le \log \Size(f) \le \Rank(f)\log \left(\frac{e n}{\Rank(f)}\right).$$

\label{thm:game-rank}
For any $X$-complete relation $R \subseteq X \times W$, where $X =
\boolset{n}$, $\Rank(R) = \Value(R)$.  In particular, 
for a boolean function $f: \boolfn{n}$, $\Rank(f) =
\Value(R_f)$.

\label{prop:game-size}
For any $X$-complete relation $R \subseteq X \times W$, where $X =
\boolset{n}$, $\log\Size(R) = \AValue(R)$.  In particular, 
for a boolean function $f: \boolfn{n}$, $\log\Size(f) =
\AValue(R_f)$.

\label{thm:rank-tribes}
  For every $n\ge 1$,
  \begin{enumerate}
  \item $\Rank(\Tribes_{n,m}) = \Rank(\dTribes_{n,m}) = n$ for $m\ge 2$.
  \item $\Rank(\AND_n \circ \Parity_m) = n(m-1) +1$ for $m\ge 1$.
  \end{enumerate}

\label{prop:depth-cert}
For every boolean function $f: \boolfn{n}$,
$$\Cert(f) \le \Depth(f)  \le \CertZ(f)\CertO(f)$$

\label{lem:mincert-rank}
  For every Boolean function $f$,
  $\minCert(f) \le \Rank(f)$. This is tight for $\OR_n$.

\label{lem:symm-cert}
  For every symmetric Boolean function $f$ on $n$ variables, $\Cert(f)=n-\minGap(f)$ and $n-\Cert(f)+1 \le \Rank(f)
  \le \Cert(f)$. Both the inequalities on rank are tight for $\Maj_{2k+1}$.

\label{lem:cert-not-ub}
 Certificate Complexity does not always bound $\Rank$ from above; for $k\ge1$ and $n=4^k$ the
 function $f = (\AND_2\circ \OR_2)^{\otimes k}$ on $n$ variables has $\Rank(f) = \Omega(Cert(f)^2)$.

\label{prop:depth-compose}
    For Boolean functions $f,g$, 
  $\Depth(f\circ g)=\Depth(f)\Depth(g)$.

\label{lem:compose-rank-example}
For general Boolean functions $f$ and $g$, $\Rank(f\circ g)$ cannot be bounded by any function of $\Rank(f)$
and $\Rank(g)$ alone.

{theorem}{thmComposeRankUb}\label{thm:compose-rank-ub}
  For non-constant boolean functions $g_1, \ldots , g_n$ with $\Rank(g_i)=r_i$, and for $n$-variate  non-constant booolean function $f$,
$$\Rank(f\circ(g_1,g_2,...,g_n)) \le \wDepth(f,[r_1,r_2,...,r_n] ).$$

\label{prop:compose-rank-max-lb}
  For  non-constant boolean functions  $f,g$,  
$$\Rank(f\circ g) \ge \max\{\Rank(f),\Rank(g)\}.$$

{theorem}{thmComposeRankLb}\label{thm:compose-rank-lb}
  For non-constant boolean functions $g_1, \ldots , g_n$ with $\Rank(g_i)=r_i$, and for $n$-variate  non-constant boolean function $f$,

  \begin{align*}
    \Rank(f\circ(g_1,g_2,...,g_n)) & \ge \wDepth(f,[r_1-1,r_2-1,...,r_n-1] ) + 1 \\
    & \ge \wDepth(f,[r_1,r_2,...,r_n] ) - (n-1).
  \end{align*}

\label{corr:iterated-rank}
 For $k\ge 1$ and non-constant boolean functions $f$,
\[ \Depth(f)^{k-1} (\Rank(f)-1) +1 \le \Rank(f^{\otimes k}) \le \Depth(f)^{k-1} \Rank(f). \]

Inversion minimization on trees is the computational problem with the following specification:
\begin{description}
\item[Input:] A rooted tree $T$ with leaf set $X$ of size $n$, and a ranking $\ranking$ of $X$.
\item[Output:] $\MInv(T,\ranking)$, the minimum of $\Inv_\ranking(\ordering)$ over all possible orderings of $T$, where $\ordering$ denotes the left-to-right ranking of $X$ induced by the ordering of $T$.
\end{description}
For any fixed tree $T$ with leaf set $X$, we use the short-hand $\Pi_T$ to denote the computational problem that takes as input a ranking $\ranking$ of $X$ and outputs $\MInv(T,\ranking)$.

\label{thm:main:special}
Let $T$ be a tree without nodes of degree 1 such that the leaf child sets have size at most $k$, at most one of them is odd, and if there exists an odd one, say $\leafchildset(v^*)$, then all ancestors of $v^*$ have empty leaf child sets. The query complexity of inversion minimization on $T$ is at least $\log_2(n!) - O(k \log k)$. In particular, the lower bound applies to:
\begin{itemize}
\item perfect trees of even degree $k$, and
\item full binary ($k=2$) trees with at most one leaf without a sibling leaf.
\end{itemize}

\label{lemma:k-ary:subtree-sensitivity}
Consider a tree $T$ with $n \doteq \lvert\leafset(T)\rvert$ leaves, and some node $v$ in $T$ with $\ell \doteq \lvert\leafset(T_v)\rvert$ leaves. We have
\[s(\Pi_T) \ge \frac{\ell(n-\ell)}{n}-1. \]

\label{fact:k-ary:balance}
If $T$ is a tree of degree $k$ with $n$ leaves, there exists a node $v$ in $T$ such that $\ell \doteq \lvert\leafset(T_v)\rvert = \alpha 
\cdot n$, where $\frac{1}{k+1} \le \alpha \le \frac{k}{k+1}$.

Given a tree $T$, a ranking $\ranking$ of the leaves of $T$, and an ordering $\ordering$ of $T$, a root inversion of $\ordering$ with respect to $\ranking$ is an inversion $(\ell_1,\ell_2)$ of $\ordering$ with respect to $\ranking$ for which the lowest common ancestor $\LCA(\ell_1,\ell_2)$ is the root of $T$. The number of root inversions of $\ordering$ with respect to $\ranking$ in $T$ is denoted by $\RInv(T,\ranking,\ordering)$. The minimum number of root inversions in $T$ with respect to $\ranking$ is denoted 
\begin{equation}\label{eq:MRInv}
\MRInv(T,\ranking) \doteq \min_\ordering \RInv(T,\ranking,\ordering),
\end{equation}
where $\ordering$ ranges over all possible orderings of $T$.

\label{lemma:sensitivity:lipschitz}    
Given a tree $T$, if a subtree $T_{v^*}$ with $\ell$ leaves is replaced with a tree $T'_{v^*}$ with the same number of leaves, resulting in the tree $T'$, then
\[|s(\Pi_T)-s(\Pi_{T'})| \le \frac{\ell(\ell-1)}{n}. \]

\label{prop:sensitivity:criterion}
Let $T$ be a binary tree, $\ranking$ a ranking of the leaves of $T$, $\transposition$ an adjacent-rank transposition, $\ell_\lo$ and $\ell_\hi$ the two leaves affected by $\transposition$ under $\ranking$ such that $\ranking$ ranks $\ell_\lo$ before $\ell_\hi$. Referring to the notation in Figure~\ref{fig:sensitivity:binary}, we have that 
\begin{align}
\MInv(T,\ranking) = \MInv(T, \transposition \ranking)
&\Leftrightarrow \DInv_\ranking(L_\lo,L_\hi) = \DInv_\ranking(\{\ell_\lo\},\{\ell_\hi\}) \label{eq:criterion:binary:simple} \\
&\Leftrightarrow \DInv_\ranking(A,B) = |A_<| - |A_>| + |B_>| - |B_<|.
\label{eq:criterion:binary:simple:refined}
\end{align}

\label{thm:gaussian:main}
There exists a constant $C$ such that for all integers $a,b\ge 1$ and $0\le k\le ab$, 
\begin{equation}\label{eq:gaussian:main}
\Pr[\XInvD_{a,b}=k]\le \frac{C}{\sqrt{ab(a+b)}}. 
\end{equation}

\label{lemma:sensitivity:root}
There exists a constant $c$ such that for every binary tree $T$ with at leaves 3 leaves and a root of degree 2, the root sensitivity of $T$ is at least 
\begin{equation}\label{eq:root:bound}
1 - \frac{c}{\sqrt{n_1 n_2 (n_1+n_2)}},
\end{equation}
where $n_1$ and $n_2$ denote the number of leaves in the subtrees rooted by the two children of the root.

\label{claim:sensitivity:sum}
There is a constant $c'$ such that for all binary trees $T$ with $n$ leaves 
\begin{equation}
  \sum_v \sqrt{\frac{n_{v,1}n_{v,2}}{n_{v,1}+n_{v,2}}} \le c'n,
\end{equation}
where the sum ranges over all nodes $v$ of degree 2 such that $T_v$ contains at least 3 leaves.

\label{lemma:yaos-principle}
Let $\Pi$ be a problem in the comparison-query model, $\eps \in [0,1/2]$, and $\dist$ a distribution on the inputs $\ranking$.
\begin{equation}\label{eq:yao}
\RQ_{\eps}(\Pi) \ge \frac{1}{2}\DistQ_{2\eps}(\Pi, \dist). 
\end{equation}

	\label{claim:sensitivity:average}
Let $\Pi$ be a problem in the comparison-query model with $n$ items, $\dist$ the uniform distribution on the inputs $\ranking$, and $g: [1,\infty) \to \mathbb{R}$ a nondecreasing log-convex function with $g(x) = x!$ for $x \in [n]$.
\[\DistQ_0(\Pi,\dist)\ge \log_2 (g(s(\Pi)+1)/n) \]

\label{claim:sensitivity:partial}
Let $\Pi$ be a problem in the comparison-query model with $n$ items, $\dist$ the uniform distribution on the inputs $\ranking$, $\eps\in [0,1]$, and $g: [1,\infty) \to \mathbb{R}$ a nondecreasing log-convex function with $g(x) = x!$ for $x \in [n]$.
\begin{equation}\label{eq:prop:sensitivity:randomized}
\DistQ_{\eps}(\Pi,\dist)\ge \log_2 \left(\frac{g(s(\Pi)+1-2(n-1)\eps)}{n}\right)
\end{equation}

\label{prop:connectivity:equivalence}
Let $T$ be a tree without nodes of degree 1. The following two conditions are equivalent:
\begin{itemize}
\item[(a)] For any two siblings $u_1$ and $u_2$ that are not both leaves, at least one of $\lvert\leafset(T_{u_1})\rvert$ or $\lvert\leafset(T_{u_2})\rvert$ is even.
\item[(b)] At most one leaf child set is odd, and if there exists a node $v^*$ with an odd leaf child set $\leafchildset(v^*)$, then all ancestors of $v^*$ have an empty leaf child set.
\end{itemize}
In the case of binary trees, (b) can be simplified to: At most one leaf has a non-leaf sibling.

\label{prop:mann-whitney:cc-bound}
    \begin{equation}\label{eq:mann-whitney:cc-bound}
        \traces(\Pi_T) \ge \frac{(a+b)!}{2(m^*)!^{a/m^*}(n^*)!^{b/n^*}}.
    \end{equation}

