\label{fact:charfn-mult}
For independent random variables $X,Y$,
\[\charfn_{X+Y}(t)=\charfn_X(t)\charfn_Y(t). \]

\label{claim:cross-inversion-property}
Let $A$ and $B$ be arrays, and let $AB$ be the concatenation of $A$ with $B$. Then
\[\Inv(AB)=\Inv(A)+\Inv(B)+\XInv(A,B). \]

\label{claim:inversion-charfn}
We have
\[\charfn_a(t)=\prod_{k=1}^{a}\left(\frac{e^{it(k-1)}}{k}\cdot\frac{\sin(kt/2)}{\sin(t/2)}\right). \]

