\label{def:fpt-reduction}
	Let $P\subseteq\Sigma^*\times\mathbb N,Q\subseteq\Gamma^*$ be two PPs.
	One says that $P$ is \emph{fpt-reducible} to $Q$, $P\fptreduction Q$, if there exists an $\FPT$-computable function $f\colon\Sigma^*\times\mathbb N\to\Gamma^*\times\mathbb N$ such that
	\begin{itemize}
		\item for all $(x,k)\in\Sigma^*\times\mathbb N$ we have that $(x,k)\in P\Leftrightarrow f(x,k)\in Q$,
		\item there exists a computable function $g\colon\mathbb N\to\mathbb N$ such that for all $(x,k)\in\Sigma^*\times\mathbb N$ and $f(x,k)=(x',k')$ we have that $k'\leq g(k)$.
	\end{itemize}

\label{def:wt}
	For every $t\geq 1$, we let $\W t\dfn [\p\WD\text-\PiForm t]^{\FPT}$. 
	The class $\W t$ forms the $t$-th level of the $\W{}$-hierarchy.

\label{theorem-wsat}
	For every $t\geq 1$ the following problems are $\W t$-complete under fpt-reductions.
	\begin{itemize}
		\item $\p\wsatpos{t,1}{}$ if $t$ is even and  $\p\wsatneg{t,1}{}$ if $t$ is odd.
		\item $\p\wsat{t,d}{}$ for every $t,d\geq 1$.
	\end{itemize}

\label{thm:WT-INC-W2}
There is an $\FO(\subseteq)$-formula $\varphi$ with $\forall\exists$-quantifier prefix for which 
the problem $\p\WTD_\varphi$ is $\W2$-complete.

\label{thm:WT-I}
\begin{enumerate}
\item For all $t\in\mathbb N$ there is an $\IND$-formula $\varphi_t$ such that  $\p\WTD_{\varphi_t}$ is $\W t$-complete.
\item There is  an $\IND$-formula  $\varphi_w$ such that  $\p\WTD_{\varphi_w}$ is $\W\Ptime$-complete.
\item There is a $\IND$-sentence $\varphi$, such that the problem $\p\WTD_\varphi$ is $\para\NP$-complete.
\item $[\p\WTD\text-\IND]^{\FPT}=\para\NP$.
\end{enumerate}

\label{ex:3-colorable}
We can \kl{define} $\COLORABLE{3}$ on~$\GRAPH$
with the $\SigmaLFOL{1}$-\kl{formula}
\begin{equation*}
  \ExistsRel{C_0, C_1, C_2} \;
  \ForAllNode{\FOVar[1]} \, \WellColored\Of{\FOVar[1]},
\end{equation*}
where
$C_0$, $C_1$ and~$C_2$ are \kl{unary} \kl{second-order variables}
intended to represent
the sets of \kl{nodes} colored with $0$, $1$ and~$2$,
respectively,
$\FOVar[1]$ is a \kl{first-order variable},
and
\begin{equation*}
  \intro*\WellColored\Of{\FOVar[1]} =
  \Bigl( \,
    \BigOR_{\lalign{i \in \Range{3}*}} \InRel{C_i}{\FOVar[1]}
  \, \Bigr)
  \, \AND \,
  \Bigl( \,
    \BigAND_{\lalign{i,j \in \Range{3}*:\, i \neq j}}
    \NOT
    \bigl(
      \InRel{C_i}{\FOVar[1]}
      \AND
      \InRel{C_j}{\FOVar[1]}
    \bigr)
  \, \Bigr)
  \, \AND \:
  \ForAllNbNode{\FOVar[2]}{\FOVar[1]}
  \Bigl( \,
    \BigAND_{\lalign{i \in \Range{3}*}}
    \NOT
    \bigl(
      \InRel{C_i}{\FOVar[1]}
      \AND
      \InRel{C_i}{\FOVar[2]}
    \bigr)
  \, \Bigr)
\end{equation*}
states that
the \kl{node} represented by~$\FOVar[1]$ is correctly colored.
More precisely,
the first two conjuncts express that
$\FOVar[1]$~is assigned one color and one color only,
while the third conjunct expresses that
$\FOVar[1]$'s color is different from its \kl{neighbors}' colors.
\lipicsEnd

\label{ex:hamiltonian}
A \kl{Hamiltonian cycle} can be seen as
a Hamiltonian path extended with an additional \kl{edge}
connecting the endpoints of the path.
In turn,
a Hamiltonian path
can be seen as a special case of a spanning tree,
where each \kl{node} has at most one child.
Using the previous spanning-tree construction,
this allows us to \kl{define} $\HAMILTONIAN$ on~$\GRAPH$
with the following $\SigmaLFOL{3}$\nobreakdash-\kl{formula}:
\begin{equation*}
  \ExistsRel{P} \:
  \ForAllRel{X} \:
  \ExistsRel{Y, Z} \:
  \ForAllNode{\FOVar[1]} \,
  \bigl(
    \PointsToUnique{\Root}\Of{\FOVar[1]}
    \, \AND \,
    \Fml{MaxOneChild}\Of{\FOVar[1]}
    \, \AND \,
    \Fml{SeesLeafIfRoot}\Of{\FOVar[1]}
  \bigr)
\end{equation*}
Here,
$\PointsToUnique{\Root}\Of{\FOVar[1]}$
is an instantiation of
the \kl{formula} schema from Example~\ref{ex:one-selected}
with the \kl{subformula} $\Root$ from Example~\ref{ex:not-all-selected},
which ensures that $P$~represents a spanning tree;
\begin{equation*}
  \Fml{MaxOneChild}\Of{\FOVar[1]}
  \, = \,
  \ForAllNbNode{\FOVar[2],\FOVar[3]}{\FOVar[1]} \:\!
  \bigl(
    \InRel{P}{\FOVar[2], \FOVar[1]}
    \AND
    \InRel{P}{\FOVar[3], \FOVar[1]}
    \, \IMP \,
    \FOVar[2] \Equal \FOVar[3]
  \bigr)
\end{equation*}
states that $\FOVar[1]$~has at most one child in the spanning tree;
and
\begin{equation*}
  \Fml{SeesLeafIfRoot}\Of{\FOVar[1]}
  \, = \,
  \Root\Of{\FOVar[1]}
  \, \IMP \,
  \ExistsNbNode{\FOVar[2]}{\FOVar[1]} \,
  \bigl(
    \NOT \InRel{P}{\FOVar[2], \FOVar[1]}
    \, \AND \,
    \ForAllNbNode{\FOVar[3]}{\FOVar[2]} \:\!
    (
      \NOT \InRel{P}{\FOVar[3], \FOVar[2]}
    )
  \bigr)
\end{equation*}
states that if $\FOVar[1]$~is the root,
then it is \kl{adjacent} to the (unique) leaf~$\FOVar[2]$;
this leaf cannot be the root's child,
since a \kl{Hamiltonian cycle} requires at least three \kl{nodes}.
\lipicsEnd

\label{thm:local-fagin}
On arbitrary \kl{graphs},
a \kl(graph){property} can be \kl{verified}
by a \kl{locally polynomial machine}
if and only if
it can be \kl{defined} by a \kl{formula} of
the \kl{existential fragment} of \kl{local second-order logic}.
In symbols,
$\NLP = \SigmaLFO{1}\On{\GRAPH}$.

\label{thm:local-hierarchy-equivalence}
The \kl{locally polynomial hierarchy}
and the \kl{local second-order hierarchy} on \kl{graphs}
are levelwise equivalent from level~$1$ onwards.
More precisely,
$\SigmaLP{\Level} = \SigmaLFO{\Level}\On{\GRAPH}$
and
$\PiLP{\Level} = \PiLFO{\Level}\On{\GRAPH}$
for all $\Level \in \Positives$.

\label{prp:lp-vs-nlp}
Some \kl{graph properties} can be \kl{verified} but not \kl{decided}
by a \kl{locally polynomial machine},
even when restricted to \kl{graphs} of \kl{bounded structural degree}.
More precisely,
$\LP\On{\bGRAPH{\MaxDegree}} \subsetneqq \NLP\On{\bGRAPH{\MaxDegree}}$
for all $\MaxDegree \geq 2$,
and a fortiori
$\LP \subsetneqq \NLP$.

\label{cor:lp-complementation}
The class of \kl{graph properties}
\kl{decidable} by a \kl{locally polynomial machine}
is not closed under \kl{complementation},
even when restricted to \kl{graphs} of \kl{bounded structural degree}.
More precisely,
$\LP\On{\bGRAPH{\MaxDegree}} \neq \coLP\On{\bGRAPH{\MaxDegree}}$
for all $\MaxDegree \geq 3$,
