\begin{description}
    \item[Input] A pair $(n,C)$, where $C: \B^n \times \B^n \mapsto \B$ is a circuit of $\poly(n)$ size.
    \item[Solutions] $(K,K)$ indices $U = \{u_1, u_2 \ldots u_{K}\}$ and $V = \{v_1, v_2 \ldots v_{K}\}$ such that $(U, V)$ forms either a {\bf biclique} or an {\bf independent set}.
\end{description}

\label{def:rand_reduct}
    A \emph{randomized decision tree reduction} from relation $R \subseteq \{0, 1\}^n \times O$ to $Q \subseteq \{0, 1\}^m \times O'$ is a distribution $D$ of depth-$d$ decision tree reductions from $R$ to $Q$, such that for any $x \in \{0,1\}^n$, 
    \[\Pr_{((f_i), (g_o)) \sim D } [(x, g_o(x)) \in R  \Leftarrow (f(x), o) \in Q] \geq \frac{1}{2}.\]

\label{def:pseudoexpectation}
Let $n \geq d$ be positive integers.
Let $\mathcal{P}_{n,d}$ be the collection of all degree $\leq d$ multilinear polynomials over variables $x_1, \dots, x_n$.
An operator $\psE: \mathcal{P}_{n,d} \rightarrow \RR$ is a \emph{degree-$d$ pseudoexpectation operator} if it satisfies the following three properties:
\begin{itemize}
    \item {\bf Linearity.} $\psE$ is linear.
    \item {\bf Normalized.} $\psE[1] = 1$.
    \item {\bf Nonnegativity.} $\psE[C] \geq 0$ for all degree $\leq d$ conjunctions $C$.
\end{itemize}
Furthermore, if $R \subseteq \B^n \times O$ is a query total search problem, then $\psE$ is \emph{$R$-Nonwitnessing} if it additionally satisfies the following property:
\begin{itemize}
    \item {\bf $R$-Nonwitnessing.} $\psE[C] = 0$ for any conjunction $C$ witnessing $R$.
\end{itemize}
If $\mathcal{F}$ is any sequence of degree $\leq d$ multilinear polynomials, then we write $\psE[\mathcal{F}] := \sum_{p \in \mathcal{F}} \psE[p]$.

Let $x_1, \ldots, x_n$ be a set of $\B$-valued variables, and let $d \leq n$.
A \emph{degree-$d$ pseudodistribution} over these variables is a family of probability distributions \[ \mathcal{D} = \set{\mathcal{D}_S : S \subseteq [n], |S| \leq d}, \] such that the following properties hold:
\begin{itemize}
    \item For each set $S \subseteq [n]$, $|S| \leq d$, $\mathcal{D}_S$ is supported on $\set{0,1}^S$, interpreted as boolean assignments to variables in $\set{x_i : i \in S}$.
    \item For each $S, T \subseteq [n]$, $|S|, |T| \leq d$, we have $\mathcal{D}_S^{S \cap T} = \mathcal{D}_T^{S \cap T} = \mathcal{D}_{S \cap T}$, where $\mathcal{D}_A^{B}$ for $B \subseteq A$ is the marginal distribution of variables in $B$ with respect to $\mathcal{D}_A$. 
\end{itemize}

\label{def:collision-free}
Let $R \subseteq \B^n \times O$ be a total query search problem, let $d, t$ be positive integers, and let $\varepsilon > 0$ be a real parameter.
Let $\psE$ be a degree $D \geq d$ pseudoexpectation operator.
Then $\psE$ is \emph{$(d,t,\varepsilon)$-collision-free for $R$} if it satisfies the following property:
\begin{itemize}
    \item {\bf $t$-Collision-Freedom.} $\displaystyle \psE[\mathcal{F}] \leq \varepsilon$, for every $t$-witnessing family $\mathcal{F}$ of degree $\leq d$ conjunctions.
\end{itemize}

\label{thm:lb}
Let $t, d, M, N, M', N'$ be positive integers chosen so that $M \geq tN + 1$, $M' \geq (t-1)N' + 1$, and $(t-1)d^2 \leq N/2$.
Then the $\ourPigeon{(t+1)}{M}{N}$ problem does not have a depth-$d$ decision-tree reduction to $\ourPigeon{t}{M'}{N'}$.

\label{lemma:useless_h1h2}
    For any $\pmap^{(1)}$ and $o$,
    $$\Pr_{j^* \sim U_N} [\uEvent(\pmap^{(2)}, o) \,|\, \uEvent(\pmap^{(1)}, o)] = 1 - \negl(\log N).$$

\label{lem:hit}
        For a depth-$k$ reduction $(f_i, g_o)$,
        $$\Pr_{\pmap^{(1)} \sim D_N} [\hitI(\pmap^{(1)}, o) \Leftarrow (f(\pmap^{(1)}), o) \in Q] \leq \ps_{k-1}$$

\label{lemma:nothit_h1h2}
    For any $\pmap^{(1)}$ and $o$,
    $$\Pr_{j^* \sim U_N} [\neg \hitJ(\pmap^{(1)}, o, j^*) \,|\,\neg \hitI(\pmap^{(1)}, o)] = 1 - \negl(\log N).$$

Let $R \subseteq \B^n \times O$ be a query total search problem, and let $\psE$ be a degree-$d$ pseudoexpectation operator.
Then $\psE$ is \emph{$\varepsilon$-nonwitnessing for $R$} if the following property holds:
\begin{itemize}
    \item {\bf $\varepsilon$-Nonwitnessing.} $\psE[C] \leq \varepsilon$ for any degree-$d$ conjunction $C$ witnessing $R$.
\end{itemize}
Note that $0$-nonwitnessing is synonymous with $R$-nonwitnessing (cf.~\cref{def:pseudoexpectation}).

\label{thm:gluable-implies-pap}
Let $R = \set{R_n \subseteq \B^n \times O_n}$ be a query total search problem not contained in $\PPADS^{dt}$, and suppose $t = O(\poly(\log n))$.
If $R$ is $(p(\log(n)), t)$-gluable for any polynomial function $p$, then $R \not \in t\text{-}\PPP^{dt}$.

 \label{thm:sa-theorem}
Let $R \in \TFNP^{dt}$ be a total query search problem.
Then $R \in \PPADS^{dt}$ if and only if for some constant $c$, $R$ admits a $\log^c(n)$-degree, $n^{\log^c(n)}$-magnitude $\ZZ$-Sherali-Adams proof of totality.

    This problem is defined on a set of $n$ nodes, denoted by $[n]$, where the node $1$ is ``distinguished''.
    For input, we are given a neighbourhood $N_u \subseteq [n]$ of size $|N(u)| \leq 2$ for each node $u \in [n]$.
    Given this list of neighbourhoods, we create an undirected graph $G$ where we add an edge $uv$ if and only if $u \in N(v)$ and $v \in N(u)$. We say $u \in [n]$ is a \emph{leaf} if it has in-degree $1$ and out-degree $0$.
    The goal of the search problem is to output either
    \begin{enumerate}
	   \item $1$, if $1$ is not a leaf in $G$, or \hfill \emph{(no distinguished leaf)}
	   \item $u \neq 1$, if $u$ is a leaf in $G$. \hfill \emph{(proper leaf)}
    \end{enumerate}
    The class $\PPA^{dt}$ contains all query total search problems with $\poly(\log(n))$-complexity reductions to $\leaf$.

The $\sod_n$ problem is defined on the $[n] \times [n]$ grid, where the node $(1,1)$ is ``distinguished''.
As input, for each grid node $u=(i,j) \in [n] \times [n]$, we are given an ``active bit" $a_u \in \B$. Furhter, we are given a \emph{successor} $s_u \in [n]$, interpreted as naming a node $(i+1, s_u)$ on the next row.
We say a node $u$ is \emph{active} if $a_u = 1$, otherwise it is \emph{inactive}. A node $u$ is a \emph{proper sink} if $u$ is inactive but some active node has $u$ as a successor.
The goal of the search problem is to output either
\begin{enumerate}
	\item \label{sod1} $(1,1)$, if $(1,1)$ is inactive \hfill \emph{(inactive distinguished source)}
	\item \label{sod2} $(n, j)$, if $(n,j)$ is active, \hfill \emph{(active sink)}
	\item \label{sod3} $(i, j)$ for $i \leq n-1$, if $(i,j)$ is active and its successor is a proper sink. \hfill \emph{(proper sink)}
\end{enumerate}
We define the class $\PLS^{dt}$ to be all total query search problems with $\poly(\log(n))$-complexity $\sodLong$-formulations.

\label{def:uplc}
    A universe of elements $\B^n$ is considered.
    \begin{description}
        \item[Input] A circuit $P: \B^n \mapsto \B^{n-1}$.
        \item[Solutions] A set of $n$ distinct strings $a_1 \ldots a_n$ such that for every $j$ the strings $P(a_j), P(a_{j+1}) \ldots P(a_n)$ agree on the prefix of length $j$. 
    \end{description}

\label{def: tuplc}
    Let $n = 2^{\ell}$ be a power of $2$, and a universe of elements $U = [2^n+1]$ is considered.
    \begin{description}
        \item[Input] A circuit $P: U \mapsto \B^{n}$.
        \item[Solutions] A set of $n+1$ distinct strings $a_0 \ldots a_{n}$ such that for every $i \in \{0, 1, \ldots, \ell\}$, the strings $P(a_{n - {2^i}}), P(a_{n - {2^i} + 1}) \ldots P(a_n)$ agree on the prefix of length $n-i$. 
    \end{description}

\label{def:YZ}
    Fix an error correcting code $C \subseteq \Sigma^n$ on alphabet $\Sigma$. Let $(h_k)$ be a family of $\lambda$-wise independent functions from $C$ to $\{0,1\}^n$.

    \begin{description}
        \item[Input] The input encodes $n$ mapping $f_1, \ldots, f_n: \Sigma \rightarrow \{0, 1\}$. We define $f: \Sigma^n \rightarrow \B^n$ as $f(a_1 a_2 \ldots a_n) \coloneqq (f_1(a_1), f_2(a_2), \ldots, f_n(a_n))$. 
        \item[Solutions] The goal is to find a key $k$ and $t$ codewords $c^{(1)} \ldots, c^{(t)} \in C$ such that $f(c^{(i)}) \oplus h_k(c^{(i)}) = 0^n$, for all $i \in [t]$.
    \end{description}

    The parameters satisfy $ n < \lambda \ll t = \poly(n)$, $|C| \geq 2^{2n}$, and $|\Sigma| = 2^{\poly(n)}$.

Let $A$ be a~set and $R,R' \in {\mathscr R}_A$.
We say that $R'$ can be obtained from $R$ by 
\begin{enumerate}
\item \emph{projecting} if $R'$ is of arity $k$, $R$ is of arity $k+n$ and for all $s \in A^k$, $R'(s) = \inf_{t \in A^n} R(s,t)$.
\item \emph{non-negative scaling} 
 if there exists $r \in {\mathbb Q}_{\geq 0}$ such that $R = r R'$;
 \item  \emph{shifting} if there exists $s \in {\mathbb Q}$ such that $R = R' + s$. 
\end{enumerate}
If $R$ is of arity $k$, then the relation that contains all minimal-value tuples of $R$ is 
\[\Opt(R) := \{t \in \Feas(R) \mid R(t) \leq R(s) \text{ for every } s \in A^k\}.\]

\label{def:pp-constr}
Let $\bA, \bB$ be valued structures. Then  $\bB$ has a~\emph{pp-construction} in $\bA$ if $\bB$ 
is fractionally homomorphically equivalent to a~structure $\bB'$ which is a~pp-power of $\bA$.

\label{def:pres}
A fractional operation $\omega \in {\mathscr F}_A^{(\ell)}$ \emph{improves}
a valued relation $R \in {\mathscr R}^{(k)}_A$ if for all $t^1,\dots,t^{\ell} \in A^k$ 
\begin{align}
E := E_\omega[f \mapsto R(f(t^1,\dots,t^{\ell}))]
\text{ exists, and } \quad 
E \leq
\frac{1}{\ell} \sum_{j = 1}^{\ell} R(t^j). \label{eq:fpol}
\end{align}

\label{def:E-N-O}
If $t \in \Q^k$ for some $k \in \N$, we define
\begin{align*}
E_t &:=\{(p,q) \in [k]^2 \mid t_p=t_q\},  \\
N_t &:=\{(p,q) \in [k]^2 \mid t_p\neq t_q\}, \text{ and} \\
O_t &:=\{(p,q) \in [k]^2 \mid t_p<t_q\},
\end{align*}
where $<$ is the natural order over $\Q$.

\label{obs:order-type}
Let $\bA$ be valued structure with finite signature $\tau$ such that $\Aut(\Q;<) \subseteq \Aut(\bA)$ and let $R \in \tau$ be any valued relation of arity $k$.
Then for every $t, t' \in \Q^k$ such that $E_t = E_{t'}$ and $O_t = O_{t'}$ it holds that $R(t)=R(t')$.

\label{lem:constant-pol}
Let $\bA$ be a~valued structure with domain $A$ and finite relational signature $\tau$ such that there exists a~unary constant operation $c \in \fPol(\bA)$. 
Then $\vcsp(\bA)$ is in P.

 \label{lem:ess-crisp}
Let $\bA$ be a~valued structure. Then $\fPol(\bA)$ contains $\pi^2_1$ if and only if 
$\bA$ is essentially crisp.

\label{thm:crisp-hard} 
If $\bA$ is a~relational structure such that $\Aut(\bA) = \Sym(\mathbb Q)$, then exactly one of the following cases applies. 
\begin{itemize}
    \item $\const \in \Pol(\bA)$ or $\inj \in \Pol(\bA)$.
    In this case, for every reduct $\bA'$ of $\bA$ with a~finite signature, $\CSP(\bA')$ is in P.
    \item The relation $\Dis$
    has a~primitive positive definition in $\bA$.
    In this case, $\bA$ pp-constructs $K_3$ and $\bA$ has a~reduct $\bA'$ with a~finite signature such that $\CSP(\bA')$ is NP-complete.
    \end{itemize}

\label{lem:r}
Let $\bA$ be a~valued structure such that $\Aut(\bA) = \Sym(\Q)$.
Suppose that $\fPol(\bA)$ contains $\inj$. Then $\vcsp(\bA)$ is in P.

\label{thm:def-ord}
Let $\bA$ be a~relational structure with a~finite signature such that $\Aut(\Q;<)\subseteq\Aut(\bA)$. Then it satisfies at least one of the following:
\begin{itemize}
\item $\bA$ primitively positively defines $\Betw$, $\Cyc$, or $\Sep$.
\item $\const \in \Pol(\bA)$.
\item $\Aut(\bA)=\Sym(\Q)$.
\item There is a~primitive positive definition of $<$ in $\bA$.
\end{itemize}

  \label{def:lex_ll} 
Let $e_{<0},e_{>0}$ be endomorphisms of $(\mathbb{Q};<)$ satisfying $e_{<0}(x)<0$ and $e_{>0}(x)>0$ for every $x\in \mathbb{Q}$.

The operation $\lex$ is any binary operation on $ \mathbb{Q}$ satisfying $\lex(x,y) <\lex(x',y')$ iff $x<x'$, or $x=x'$ and $y<y'$ for all $x,x',y,y'\in \mathbb{Q}$.

We denote by $\lele$ the operation on $\mathbb{Q}$ defined by 

\[\lele(x,y) = \begin{cases}
      \lex(e_{<0}(x),e_{<0}(y)) &\text{if } x \leq  0, \\
      \lex(e_{>0}(y),e_{>0}(x)) &\text{if } x > 0.
\end{cases}
\]

\label{def:mi}
Let $e_<$, $e_=$ and $e_>$ be endomorphisms of $(\Q;<)$ satisfying
for all $x, \varepsilon \in \Q$, $\varepsilon > 0$,
$e_= (x) < e_{>}(x) < e_{<}(x) < e_{=}(x+\varepsilon).$
We denote by $\mi$  the binary operation on $\Q$ defined by
\[\mi(x,y) = \begin{cases}
      e_{<}(x) &\text{if } x < y, \\
      e_=(x) &\text{if } x = y, \\
      e_>(y) &\text{if } x > y.
\end{cases}
\]

\label{def:mx}
Let $e_=$ and $e_{\neq}$ be any endomorphisms
of $(\Q;<)$ satisfying
for all $x, \varepsilon \in \Q$, $\varepsilon > 0$, 
$e_{\neq}(x) < e_= (x) < e_{\neq}(x+\varepsilon).$
We denote by $\mx$  the binary operation on $\Q$ defined by
\[\mx(x,y) = \begin{cases}
      e_{\neq}(\min(x,y)) &\text{if } x \neq y, \\
      e_=(x) &\text{if } x = y.
\end{cases}
\]

\label{prop:pp}
Let $\bA$ be a~relational structure such that $\Pol(\bA)$ contains $\min$, $\mi$, or $\mx$.
Then $\Pol(\bA)$ contains $\pi\pi$.

 \label{thm:tcsp}
Let $\bA$ be a~relational structure with $\Aut(\Q; <)\subseteq \Aut(\bA)$. Then exactly one of the following is true.
\begin{enumerate}
    \item At least one of the operations $\const$, $\min$, $\mx$, $\mi$, $\lele$, or one of their duals lies in $\Pol(\bA)$. In this case, for every reduct $\bA'$ of $\bA$ with a~finite signature, $\CSP(\bA')$ is P. 
    \item $\bA$ primitively positively defines one of the relations $\Betw$, $\Cyc$, $\Sep$, $T_3$, $-T_3$, or $\Dis$. In this case, $\bA$ has a~reduct $\bA'$ with a~finite signature such that $\CSP(\bA')$ is NP-complete.
\end{enumerate}
Moreover, if $\bA$ has a finite signature, then it is decidable whether item 1 or item 2 holds.

\label{thm:tcsp-pwnu}
Let $\bA$ be a~relational structure such that $\Aut(\Q;<) \subseteq \Aut(\bA)$. Then exactly one of the following is true:
\begin{enumerate}
\item $\Pol(\bA)$ contains a~pwnu polymorphism. In this case, for every reduct $\bA'$ of $\bA$ with a finite signature, $\CSP(\bA')$ is in P.
\item $\bA$
pp-constructs $K_3$. In this case, there exists a reduct $\bA'$ of $\bA$ with a finite signature such that $\CSP(\bA')$ is NP-complete.
\end{enumerate}

 \label{lem:lex-algo}
Let $\bA$ be a~valued structure over a finite signature such that $\Aut(\Q; <)\subseteq \Aut(\bA)$. Suppose that $\checked{\lele} \in \fPol(\bA)$ \checked{or $\lele^* \in \fPol(\bA)$.}

Then $\VCSP(\bA)$ is in P.

\label{lem:3-val-rels}
Let $\bA$ be a~valued structure such that $\Aut(\Q;<) \subseteq \Aut(\bA)$. Let $(<)_0^\infty \in \langle \bA \rangle$. Let $\alpha, \beta, \gamma \in \mathbb{Q} \cup \{\infty\}$ be such that 
\begin{itemize}
\item $\alpha < \min(\beta, \gamma) < \infty$, or
\item $\beta \neq \gamma$ and $\beta, \gamma < \infty$.
\end{itemize}
If $R_{\alpha, \beta, \gamma} \in \langle \bA \rangle$, then
$\Cyc \in \langle \bA \rangle$.

\label{lem:soft-neq}
Let $\bA$ be a~valued $\tau$-structure such that $\Aut(\bA) = \Aut(\Q; <)$ and $(<)_0^\infty \in \langle\bA\rangle$. Suppose that $\bA$ is not essentially crisp. Then one of the following holds:
\begin{itemize}
    \item $\Cyc \in \langle \bA \rangle$,
    \item $(\neq)_0^1 \in \langle \bA \rangle$, or
    \item $R_{1,0,\infty} \in \langle \bA \rangle$.
\end{itemize}

\label{lem:lex-viol-crisp}
Let $\bA$ be a~valued structure such that $\Aut(\bA)=\Aut(\Q;<)$ and $(<)_0^\infty \in \langle \bA \rangle$. Suppose that $\checked{\lele, \lele^*} \notin \Pol(\Q; \langle \bA \rangle_0^\infty)$ and that $\bA$ is not  essentially crisp.
Then $\langle \bA \rangle$ contains one of the relations $\Betw$, $\Cyc$, $\Sep$, $T_3$, $-T_3$, or $\Dis$.

\label{thm:tvcsp-clas}
Let $\bA$ be a~valued structure
such that $\Aut(\Q; <) \subseteq \Aut(\bA)$. Then at least one of the following holds:
\begin{enumerate}
    \item $\langle \bA \rangle$ contains one of the relations $\Betw$, $\Cyc$, $\Sep$, $T_3$ (see Definition~\ref{def:rels}), $-T_3$, or $\Dis$ (see~\eqref{eq:D}). In this case, $\bA$ has  a reduct $\bA'$ over a finite signature such that $\VCSP(\bA')$ is NP-complete.
    \item $\const \in \fPol(\bA)$.

    \item \checked{$\lele \in \fPol(\bA)$ or $\lele^* \in \fPol(\bA)$.}


    \item $\pi_1^2 \in \fPol(\bA)$ and $\fPol(\bA)$ contains \checked{$\min$, $\mx$, $\mi$}, or one of their duals.

\end{enumerate}
In cases 2--4, for every reduct $\bA'$ of $\bA$ over a finite signature, $\VCSP(\bA')$ is in P.

\checked{Case 1 is mutually exclusive with each of the cases 2--4.}

\label{cor:tvcsp-clas}
Let $\bA$ be a~valued structure with a~finite signature such that $\Aut(\Q; <) \subseteq \Aut(\bA)$. Then exactly one of the following holds.
\begin{enumerate}
\item $\langle \bA \rangle$ contains one of the relations $\Betw$, $\Cyc$, $\Sep$, $T_3$, $-T_3$, or $\Dis$. In this case, $\VCSP(\bA)$ is NP-complete.
\item $(\Q; \langle \bA \rangle_0^\infty)$ is preserved by one of the operations $\const$, $\min$, $\mx$, $\mi$, $\lele$, or one of their duals. In this case, $\VCSP(\bA)$ is in P.
\end{enumerate}

\label{cor:clas-refor}
Let $\bA$ be a~valued structure with a finite signature such that $\Aut(\Q; <) \subseteq \Aut(\bA)$. Then exactly one of the following holds.
\begin{enumerate}
\item $\bA$, \checked{or, equivalently, $(A; \langle \bA \rangle_0^\infty)$} pp-constructs $K_3$. In this case, $\VCSP(\bA)$ is NP-complete.
\item $\Pol(\Q; \langle \bA \rangle_0^\infty)$ contains a~pwnu operation. In this case, $\VCSP(\bA)$ is in P.
\end{enumerate}

\label{defn: monotone indexing}
For an even integer $n > 0$, define $\mIND_n$, as follows: The function $\mIND_n$ is defined on $n + \binom{n}{n/2}$ (which is $\Theta(2^n/\sqrt{n})$) variables, where the latter $\binom{n}{n/2}$ variables are indexed by all $n$-bit strings of Hamming weight exactly $n/2$. For $(x, y) \in \zone^{n + \binom{n}{n/2}}$, define
\[
    \mIND_n(x, y) = \begin{cases}
    0 & |x| < n/2\\
    1 & |x| > n/2\\
    y_x & \textnormal{otherwise}.
    \end{cases}
\]

\label{lem: yao}
    For finite sets $D, E$ and a function $f: D \to E$, we have $\sR(f) \geq k$ if and only if there exists a distribution $\mu : D \to [0,1]$ such that $\sD_\mu(f) \geq k$.
    Here, $\sD_\mu(f)$ is the minimum depth of a deterministic decision tree that computes $f$ to error at most $1/3$ when inputs are drawn from the distribution $\mu$.

\label{thm: ambainis}
    Let $D, E$ be finite sets, let $n$ be a positive integer, and let $f : D^n \to E$ be a function. Let $X, Y$ be two sets of inputs such that $f(x) \neq f(y)$ for all $(x, y) \in X \times Y$. Let $R \subseteq X \times Y$ be such that
    \begin{itemize}
        \item For every $x \in X$, there are at least $m$ different $y \in Y$ with $(x, y) \in R$,
        \item for every $y \in Y$, there are at least $m'$ different $x \in X$ with $(x, y) \in R$,
        \item for every $x \in X$ and $i \in [n]$, there are at most $\ell$ different $y \in Y$ such that $(x, y) \in R$ and $x_i \neq y_i$,
        \item for every $y \in Y$ and $i \in [n]$, there are at most $\ell'$ different $x \in X$ such that $(x, y) \in R$ and $x_i \neq y_i$.
    \end{itemize}
    Then $\sQ(f) = \Omega\rbra{\frac{mm'}{\ell\ell'}}$.

Let $f : \zone^n \to \zone$ and $x \in \zoneu$. A partial assignment $p \in \cbra{0, 1, \su, *}^n$ is called a \emph{certificate} for $\uf$ at $x$ if 
\begin{itemize}
    \item $x$ is consistent with $p$, and
    \item $\uf(y) = \uf(x)$ for all $y$ consistent with $p$.
\end{itemize}
The size of this certificate is $|p| := \abs{\cbra{i \in [n] : p_i \neq *}}$. The \emph{domain of $p$} is said to be $\cbra{i \in [n] : p_i \neq *}$.

\label{obs: unstable zero one certificates intersect}
    Let $f : \zone^n \to \zone, x \in \uf^{-1}(0)$ and $y \in \uf^{-1}(1)$. Let $c^x, c^y$ be minimum certificates for $\uf$ at $x$ and $y$, respectively, and let $C^x$ and $C^y$ be their domains, respectively. Then there exists an index $i \in C^x \cap C^y$ such that one of the following holds:
    \begin{itemize}
        \item $c^x_i = 0$ and $c^y_i = 1$, or
        \item $c^x_i = 1$ and $c^y_i = 0$.
    \end{itemize}

{theorem}{muxdepth}
    \label{thm:muxdepth}
    $\depth_\un(\fmux_n) = 2^n+n$

{theorem}{muxsize}
    \label{thm:muxsize}
    $2\cdot 4^n \leq \size_\un(\fmux_n) \leq 4^{n+1} - 3^n$.

{theorem}{dthfdt}
    \label{thm:dthfdt}
    $2\size(f)-1 \leq \size_\un(f) \leq 2^{\size(f)} - 1$.

{theorem}{andsize}
    \label{thm:andsize}
    $\size_\un(\fand_n) = 2^{n+1}-1$.

{theorem}{smalldepth}
    \label{thm:smalldepth}
    For any $n \geq 1$, there is a non-degenerate Boolean function on $n+2^{n+1}-1$ inputs that has a hazard-free decision tree of depth $2n+1$.

{theorem}{imp}
    \label{thm:imp}
    Let $f$ be any function. Then, $\size_\un(f) \geq m+M$ where $m$ is the number of prime implicants of $f$ and $M$ is the number of prime implicates of $f$.

{theorem}{dtcc}
    \label{thm:dtcc}
    $\cc_\un(f) \leq \depth_\un(f) \leq 4\cc_\un^3(f)$.

{theorem}{sbscc}
    \label{thm:sbscc}
    Let $f$ be a function. Let $k_1$ and $k_2$ be such that $f$ has a hazard-free $k_1$-DNF formula and a hazard-free $k_2$-CNF formula. Then, we have:
    \begin{equation*}
