pseudo-variance,

\ifnum\confversion=1
\small
\begin{gather*}
\tildecov(\zee_{S,\alpha},\zee_{T,\beta}) 
= \tildeEx{ \zee_{S,\alpha} \cdot \zee_{T,\beta} } - \tildeEx{\zee_{S,\alpha}} \tildeEx{\zee_{T,\beta}} \\	
\tildeVar{\zee_{S,\alpha}} ~=~ \tildecov(\zee_{S,\alpha},\zee_{S,\alpha})
