\label{def:polytime-extractor}
    A quantum polynomial-time machine $\mathcal{C}$ is a uniformly generated family of quantum circuits $\mathcal{C} = \{\mathcal{C}_n\}_{n}$, where, for some polynomials $p, q, r$, $\mathcal{C}_n$ takes as input a string $z \in \Sigma^*$ with $|z| = n$, a $p(n)$-qubit quantum state $\ket{\phi}$, and $q(n)$ auxiliary qubits in state $\ket{0}^{\otimes q(n)}$, consists of $r(n)$ gates.
In particular, we call it an efficient machine.

Let $\mathcal{S}=(\tau^A,\tau^B,\ket{\psi}\in\mathcal{H}_A\otimes\mathcal{H}_B)$ and $\widetilde{\mathcal{S}}=( \{\widetilde{\tau}^A \},\{\widetilde{\tau}^B \},\ket{\widetilde{\psi}} \in \widetilde{\mathcal{H}}_A \otimes \widetilde{\mathcal{H}}_B )$ be two quantum strategies for a game $\mathcal{G}=\big(\lambda,\mu,\mathcal{I}_A,\mathcal{I}_B,\mathcal{O}_A,\mathcal{O}_B\big)$. We say  $\mathcal{S}$ is $\delta$-close to  $\widetilde{\mathcal{S}}$ 

if there are Hilbert spaces $\mathcal{H}_A^{aux}$ and $\mathcal{H}_B^{aux}$,  isometries $V_A:\mathcal{H}_A\rightarrow \widetilde{\mathcal{H}}_A\otimes\mathcal{H}_A^{aux}$ and $V_B:\mathcal{H}_B\rightarrow\widetilde{\mathcal{H}}_B\otimes\mathcal{H}_B^{aux}$, and a unit vector $\ket{aux}\in\mathcal{H}_A^{aux}\otimes\mathcal{H}_B^{aux}$ such that
\begin{align}
    \norm{ (V_A\otimes V_B)(\tau^A(x)\otimes \tau^B(y)\ket{\psi}) - (\widetilde{\tau}^A(x)\otimes\widetilde{\tau}^B(y)\ket{\widetilde{\psi}})\otimes\ket{aux} }^2\leq\delta
\end{align}
for all $(x,y)\in\mathcal{I}_A\times\mathcal{I}_B$.

\label{def:xz-local-hamiltonian}
    The XZ $k$-Local Hamiltonian problem, for $k \in \mathbb{N}$ and parameters $\alpha, \beta \in [0,1]$
    with $\alpha<\beta$, is the following promise problem. Let $n$ be the number of qubits of a quantum system.
    The input is a sequence of $m(n)$
    values $\gamma_1,...,\gamma_{m(n)}\in [-1,1]$ and $m(n)$
    Hamiltonians $H_1, \ldots, H_{m(n)}$
    where $m$ is a polynomial in $n$, and for each $i\in [m(n)]$,
    $H_i$ is of the form $\bigotimes_{j \in n} \sigma_{W_j} \in  \{\sigma_X, \sigma_Z, \sigma_I\}^{\otimes n}$ with
    $|\{j | j \in [n] \textrm{ and } \sigma_{W_j} \neq \sigma_I \}| \leq k$.
    For $H = \frac{1}{m(n)} \sum_{j = 1}^{m(n)} \gamma_j H_j$, one of the following two conditions hold.
    \begin{description}
        \item[\quad Yes.]
        {There exists a
          state $\ket{\psi} \in \complex^{2^{n}}$ such that
          $\bra{\psi} H \ket{\psi}
            \leq \alpha(n)$}
        \item[\quad No.]
        {For all states $\ket{\psi} \in \complex^{2^{n}}$
          it holds that
          $\bra{\psi} H \ket{\psi}
            \geq \beta(n) .$
            }
    \end{description}

    A one-round two-prover entangled proof system for a problem $A=(A_{yes}, A_{no})$, with completeness $c$ and soundness $s$, is a polynomial-time computable function that takes an instance $x \in A$ to a description of a non-local game $\mathcal{G}_x$ 
satisfies the following conditions. 
\ \begin{description}
        \item[\quad Completeness.]
        {For every
          $x \in A_{yes}$ we have
          $\omega^*(\mathcal{G}_x) \geq c$}
        \item[\quad Soundness.]
        {For every
          $x \in A_{no}$ we have
          $\omega^*(\mathcal{G}_x) \leq s$.}
    \end{description}

\label{defn:SZKMIP*}
    A one-round two-prover entangled proof system for a problem $A=(A_{yes}, A_{no})$ is \emph{statistical zero-knowledge} if for every $x \in A_{yes}$ there exists an honest prover strategy $\mathcal{S}_h$ satisfying the following.



    \begin{description}
        \item[\quad Completeness.]
        {Provers using $\mathcal{S}_h$ win the game with probability at least $c$, i.e
          $\omega^*(\mathcal{G}_x, \mathcal{S}_h) \geq c$.}
        \item[\quad Simulability.]
        {For any PPT (probabilistic polynomial-time) malicious verifier $\widehat{V}$ there exists a PPT simulator $Sim_{\widehat{V}}$ with output distribution that is $\epsilon$-close to $View(\widehat{V}(x),\mathcal{S}_h)$ in statistical distance for some negligible function $\epsilon(|x|)$.}
    \end{description}

\label{thm:rigidity}
There exists a constant $C>0$ such that the following holds. For any $\epsilon>0$, $n\in\mathbb{N}$, and strategy $\mathcal{S}=(\tau^A,\tau^B,\ket{\psi}_{AB}\in\mathcal{H}_A\otimes\mathcal{H}_B)$ for the $n$-qubit LWPBT with winning probability $1-\epsilon$, there are isometries $V_A:\mathcal{H}_A\rightarrow (\mathbb{C}^2)^{\otimes n}\otimes\mathcal{H}_A^{aux},V_B:\mathcal{H}_B\rightarrow(\mathbb{C}^2)^{\otimes n}\otimes\mathcal{H}_B^{aux}$ and a unit vector $\ket{aux}\in\mathcal{H}_A^{aux}\otimes\mathcal{H}_B^{aux}$ such that
\begin{equation*}
   \norm{ (V_A\otimes V_B)\big(Id_{\mathcal{H}_A} \otimes W_B(a)\ket{\psi}_{AB}\big)-\big(Id_{\mathbb{C}^{2^n}} \otimes \sigma_W(a)\ket{\Phi^+}^{\otimes n}\big)\otimes\ket{aux} } \leq Cn^{6}\epsilon^{1/4}
\end{equation*}
for all $W(a)\in\mathcal{I}_B$.

In particular, we have
\begin{equation*}
   \norm{W_B(a)\ket{\psi}_{AB}-V_B^\dagger \sigma_W(a)V_B\ket{\psi}_{AB}} \leq Cn^{6}\epsilon^{1/4}
\end{equation*}
for all $W(a)\in\mathcal{I}_B$.

