\label{def:LtPalt}
A language $L\in\LtP$ if there is a ternary relation $R$ computable in time $s(n)$, where $s$ is a polynomial,
\[R\subseteq\{0,1\}^n\times\{0,1\}^{s(n)}\times\{0,1\}^{s(n)},\]
denoted $R_x(u,v)$ for $x\in\{0,1\}^n$, $u,v\in\{0,1\}^{s(n)}$,
such that, for every fixed $x$, it defines a linear order on $s(|x|)$-size strings such that:
\begin{itemize}
    \item for every $x\in L$, the minimal element of this order starts with bit 1,
    \item for every $x\notin L$, the minimal element of this order starts with bit 0.
\end{itemize}

\label{def:StP}
A language $L\in\StP$ if there is a polynomial-time computable ternary relation 
$R\subseteq\{0,1\}^n\times\{0,1\}^{s(n)}\times\{0,1\}^{s(n)}$,
denoted $R_x(u,v)$ for $x\in\{0,1\}^n$, $u,v\in\{0,1\}^{s(n)}$,
such that:
\begin{itemize}
    \item for every $x\in L$, there exists $w^{(1)}$ such that $\forall v\ R_x(w^{(1)},v) = 1$,
    \item for every $x\notin L$, there exists $w^{(0)}$ such that $\forall u\ R_x(u,w^{(0)}) = 0$.
\end{itemize}

\label{def:prOtP}
    A promise problem $\Pi=(\Pi_\YES,\Pi_\NO)$ belongs to\/ $\prOtP$
    if there is a polynomial-time deterministic Turing machine $A$ such that\/
    for every $n\in\mathbb{N}$, there exist $w^{(0)}_n$, $w^{(1)}_n$ (called \emph{irrefutable certificates}) that satisfy for every $x\in\{0,1\}^n$:
    \begin{itemize}
        \item If $x\in\Pi_\YES$, then for every $v$, $A(x,w^{(1)}_n,v)=1$,
        \item If $x\in\Pi_\NO$, then for every $u$, $A(x,u,w^{(0)}_n)=0$.
    \end{itemize}
    No assumption on the behaviour of $A$ is made outside the promise set
    except that it stops (accepts or rejects) in polynomial time.

$\OtP$ is the respective class of languages (that is, it corresponds
to the case of\/ $\Pi_\YES=\overline{\Pi_\NO}$).

\label{def:SBP}
A language $L$ is in $\SBP$ if there exist $\varepsilon > 0$, $k,\ell \in \N$ and a polynomial-time computable predicate $B(x,r)$ such that
\begin{itemize}
\item If $x \in L$ then $\implies \Pr_{r}[B(x,r) = 1] \geq (1 + \varepsilon) \cdot \frac{1}{2^{n^k}} $,  
\item If $x \not \in L$  then $\implies \Pr_{r}[B(x,r) = 1] \leq (1 - \varepsilon) \cdot \frac{1}{2^{n^k}}$. 
\end{itemize}
where $n = \size{x}$ and $r$ is uniformly distributed on $\{0,1\}^{n^\ell}$.

\label{def:SSE/WSSE}
Let $C$ be a Boolean circuit and $m\ge1$ be an integer given in binary representation. 
Then\/ $\SSE \eqdef (\SSE_{\YES}, \SSE_{\NO})$, where
\begin{eqnarray*}
\SSE_{\YES} &=& \condset{(C,m)}{\ct{x}C(x) \geq m} , \\
\SSE_{\NO} &=& \condset{(C,m)}{\ct{x}C(x) \leq m/2}. 
\end{eqnarray*}
If $C$ is a non-deterministic circuit, we denote the corresponding problem by $\WSSE$.

