\label{def:dual-adversary-bound}
Let $f : \D \to \{0,1\}$ be a function, and for all $x \in \D$, let $O_x$ be a unitary operation on $\H$, referred to as the oracle. Then, the adversary bound for $f$ with input oracles $\{O_x\}_{x \in \D}$ is the following optimization program:
\begin{align*}
    \min\quad & \max_{x \in \D} \norm{\ket{w_x}}^2, \\
    \text{s.t.}\quad & \bra{w_x}((I - O_x^{\dagger}O_y) \otimes I_{\W})\ket{w_y} = \delta_{f(x) \neq f(y)}, & \forall x,y \in \D, \\
    & \ket{w_x} \in \H \otimes \mathcal{W}, & \forall x \in \D, \\
    & \W \text{ Hilbert space}.
\end{align*}

\label{thm:graph-composition}
Let $G = (V,E)$ be an undirected graph with $s,t \in V$, $s \neq t$, such that $s$ and $t$ are connected in $G$. Let $\mathcal{P}$ be the graph composition of $G$ with source node $s$, sink node $t$, and span programs $(\mathcal{P}^e)_{e \in E}$. Let $x \in \D$. Then,
\begin{enumerate}[nosep]
    \item $w_+(x,\mathcal{P}) = R_{G,s,t,r^+}$, where for all $e \in E$, $r^+_e = w_+(x,\mathcal{P}^e)$.
    \item $w_-(x,\mathcal{P}) = R_{G,s,t,r^-}^{-1}$, where for all $e \in E$, $r^-_e = w_-(x,\mathcal{P}^e)^{-1}$.
\end{enumerate}

\label{thm:witness-upper-bounds}
Let $G = (V,E)$ be an undirected graph, and let $s,t \in V$ with $s \neq t$, such that $s$ and $t$ are connected in $G$. Let $\mathcal{P}$ be the graph composition of $G$ with source node $s$, sink node $t$, and span programs $(\mathcal{P}_e)_{e \in E}$ on a common domain $\D$.
\begin{enumerate}[nosep]
    \item Suppose that $x \in \D$ is a positive instance for $\mathcal{P}$. Let $P \subseteq E$ be an $st$-path in $G$ such that for all $e \in E$, $x$ is a positive instance for $\mathcal{P}_e$. Then, $w_+(x,\mathcal{P}) \leq \sum_{e \in P} w_+(x,\mathcal{P}_e)$.
    \item Suppose that $x \in \D$ is a negative instance for $\mathcal{P}$. Let $C \subseteq E$ be an $st$-cut in $G$, i.e., a set of edges such that every path from $s$ to $t$ has to intersect $C$ at least once, such that for all $e \in C$, $x$ is a negative instance for $\mathcal{P}_e$. Then, $w_-(x,\mathcal{P}) \leq \sum_{e \in C} w_-(x,\mathcal{P}_e)$.
\end{enumerate}

\label{thm:implementation-graph-composition}
Let $\mathcal{P} = (\H, x \mapsto \H(x), \K, \ket{w_0})$ on $\D$ be a graph composition of $G = (V,E)$, with source node $s$, sink node $t$, and edge span programs $(\mathcal{P}_e)_{e \in E}$, where for all $e \in E$, $\mathcal{P}_e = (\H^e, x \mapsto \H^e(x), \K^e, \ket{w_0^e})$. Suppose we have implementations of the following operations:
\[\overline{R}_{\H(x)} : \ket{e}\ket{\psi} \mapsto \ket{e}(2\Pi_{\H^e(x)} - I)\ket{\psi}, \qquad \overline{R}_\K : \ket{e}\ket{\psi} \mapsto \ket{e}(2\Pi_{\K^e} - I)\ket{\psi},\]
and
\[\overline{C}_{\ket{w_0}} : \ket{e}\ket{\bot} \mapsto \ket{e}\frac{\ket{w_0^e}}{\norm{\ket{w_0^e}}}, \qquad R_{\mathcal{C}_{G,r}} = 2\Pi_{\mathcal{C}_{G,r}} - I, \qquad \text{and} \qquad C_{\ket{f_{G,s,t,r}^{\min}}} : \ket{\bot} \mapsto \frac{\ket{f_{G,s,t,r}^{\min}}}{\norm{\ket{f_{G,s,t,r}^{\min}}}}.\]
Then, we have
\[R_{\H(x)} = \overline{R}_{\H(x)}, \qquad R_{\K} = -\overline{R}_{\K}R_{\mathcal{C}_{G,r}}, \qquad \text{and} \qquad C_{\ket{w_0}} = \overline{C}_{\ket{w_0}}(C_{\ket{f^{\min}_{G,s,t,r}}} \otimes I),\]
and as such the costs of implementing the routines $R_{\H(x)}$, $R_{\K}$ and $C_{\ket{w_0}}$ in the circuit model are
\begin{center}
    \begin{tabular}{r|cccccc}
        & $\overline{R}_{\H(x)}$ & $\overline{R}_{\K}$ & $\overline{C}_{\ket{w_0}}$ & $R_{\mathcal{C}_{G,r}}$ & $C_{\ket{f_{G,s,t,r}^{\min}}}$ & Additional gates \\\hline
        $R_{\H(x)}$ & $1$ & $0$ & $0$ & $0$ & $0$ & $0$ \\
        $R_{\K}$ & $0$ & $1$ & $0$ & $1$ & $0$ & $O(1)$ \\
        $C_{\ket{w_0}}$ & $0$ & $0$ & $1$ & $0$ & $1$ & $0$
    \end{tabular}
\end{center}

\label{lem:tree-decomposition}
Let $G = (V,E)$ be a graph with resistances $r : E \to \R_{>0}$. Let $E_1, \dots, E_k \subseteq E$ such that $G|_{E_1}, \dots, G|_{E_k}$ is a tree decomposition of $G$. Then,
\[\mathcal{C}_{G,r} = \bigoplus_{j=1}^k \mathcal{C}_{G|_{E_j},r|_{E_j}}.\]

\label{lem:parallel-decomposition}
Let $G = (V,E)$ be a graph with resistances $r : E \to \R_{>0}$. Let $E_1, \dots, E_k \subseteq E$, such that $G|_{E_1}, \dots, G|_{E_k}$ is a parallel decomposition of $G$. Let $\mathcal{E} : \C^k \to \H_E = \Span\{\ket{e} : e \in E\}$, that for all $j \in [k]$ performs the mapping
\begin{equation}
    \label{eq:parallel-embedding}
    \mathcal{E}: \ket{j}\ket{\bot} \mapsto \ket{j}\frac{\ket{f_j}}{\norm{\ket{f_j}}}, \qquad \text{with} \qquad \ket{f_j} = \ket{f^{\min}_{G|_{E_j},s,t,r|_{E_j}}} \in \C^{E_j}.
\end{equation}
Then,
\begin{equation}
    \label{eq:parallel-decomposition}
    \mathcal{C}_{G,r} = \mathcal{E}\left(\mathcal{C}'\right) \oplus \bigoplus_{j=1}^k \mathcal{C}_{G|_{E_j},r|_{E_j}}, \quad \text{with} \quad \mathcal{C}' = \Span\left\{\ket{\psi}\right\}^{\perp}, \quad \text{and} \quad \ket{\psi} = \sum_{j=1}^k \frac{1}{\norm{\ket{f_j}}}\ket{j}.
\end{equation}

\label{lem:planar-dual-circulation-space}
Let $G = (V,E)$ be a connected, undirected, planar graph, where every edge $e \in E$ has an implicit direction meaning that it goes from $e_-$ to $e_+$. Let $G^{\dagger} = (F^{\dagger},E^{\dagger})$ be a planar dual of $G$, where every edge $e$ is associated to a dual edge $e^{\dagger} \in E^{\dagger}$, that points from the face on the left of $e$ to the face on the right of $e$, as seen from the perspective of traversing $e$ in its implicit direction. Moreover, let $r : E \to [0,\infty]$ be resistances on $G$, and let $r^{\dagger} : E^{\dagger} \to [0,\infty]$ be defined by $r^{\dagger}_{e^{\dagger}} = 1/r_e$. Then, by identifying $\ket{e^{\dagger}} = \ket{e}$, and as such identifying $\H_{G^{\dagger}} = \H_G$, we find that
\[\H_G = \mathcal{C}_{G,r} \oplus \mathcal{C}_{G^{\dagger},r^{\dagger}} = \H_{G^{\dagger}}.\]

\label{def:logical-compositions}
Let $n \in \N$, and $\mathcal{P}_1, \dots, \mathcal{P}_n$ be span programs on $\D$. We define two special types of graph compositions:
\begin{enumerate}[nosep]
    \item Let $G$ be a line graph with $n$ edges, and let $s$ and $t$ be the endpoints. We let $\mathcal{P}$ be the graph composition of $G$ with span programs $\mathcal{P}_1, \dots, \mathcal{P}_n$ on the edges, and we write $\mathcal{P} = \bigwedge_{j=1}^n \mathcal{P}_j$. We refer to this as the AND-composition of $\mathcal{P}_1, \dots, \mathcal{P}_n$.
    \item Let $G$ be a graph with $2$ nodes, $s$ and $t$, and $n$ parallel edges between them. We let $\mathcal{P}$ be the graph composition with span programs $\mathcal{P}_1, \dots, \mathcal{P}_n$ on the edges, and we write $\mathcal{P} = \bigvee_{j=1}^n \mathcal{P}_j$. We refer to this construction as the OR-composition of $\mathcal{P}_1, \dots, \mathcal{P}_n$.
\end{enumerate}

