[Guarantees of the Threshold Decay framework] \label{lemma:ThresDec-guarantees}
   Given $\epsilon \in (0,1)$, integer $T\geq 10$, $U \ge 2$, an $n \times n$ invertible RDDL matrix $\LL$ with integer entries in $[-U, U]$, and a nonnegative vector $\bb$ with integer weights in $[0,U]$, let $\xxbar := \LL^{-1} \bb$ denote the exact solution vector, \callalg{ThresholdDecay} has the following guarantees for all $t \in [0, T]$: 
   \begin{enumerate}
       \item  \label{induction:bound-b}
           $
           \norm{\widehat{\bb}^{(t)}}_1 \leq \frac{1}{(nU)^{t}} \norm{\bb}_1
           $.
           Moreover, if $t > 0$, 
           $\norm{\bbhat^{(t)}}_1 \leq \frac{1}{(nU)} \norm{\bbhat^{(t-1)}}_1
           $.
       \item  \label{induction:xtil-approx}
           $\widetilde{\xx}^{(t)} \approxbar_{\epsilon t / (4T)} \xxbar_{[n] \setminus S^{(t)}}$. Note that we define $\widetilde{\xx}^{(0)}$ to be a zero dimensional vector.
       \item \label{induction:bound-xbar}
           For all $i \in S^{(t+1)}$, $\xxbar_i < \frac{1}{(nU)^{2}} \| \bbhat^{(t)} \|_1 \le \frac{1}{(nU)^{t+2}} \norm{\bb}_1$.
   \end{enumerate}

 [Correctness of the Threshold Decay framework]\label{thm:ThresDec-correctness}
Given $\epsilon \in (0,1)$, integer $T\geq 10$, $U \ge 2$, an $n \times n$ invertible RDDL matrix $\LL$ with integer entries in $[-U, U]$, 
and a nonnegative vector $\bb$ with integer weights in $[0,U]$, \callalg{ThresholdDecay} produces a vector $\xxtil$ and a set $A \subseteq [n]$ such that $\xxtil$ has support $A$, with the following properties hold:  
    \begin{itemize}
        \item For any $i \in [n]$ with $(\LL^{-1} \bb)_i \geq (nU)^{-(T+1)} \norm{\bb}_1$, we have $i \in A$. 
        \item Our output is an entrywise $\exp(\eps)$-approximation on $A$, i.e.,  $\xxtil_A \approxbar_{\epsilon} (\LL^{-1} \bb)_A$.
        \item Specifically, when $T = n$, we have $\xxtil \approxbar_{\epsilon} \LL^{-1} \bb$.
    \end{itemize}

\label{lemma:b-bound}
   In \callalg{ThresholdDecay}, for any integer $t \in [0, T-1]$, let 
   \[
   \bbbar^{(t+1)} := 
       \bb_{S^{\left( t +1 \right)}}
       -
       \LL_{S^{\left( t +1 \right)}, [n] \setminus S^{(t+1)}}
       \xxtil^{\left( t+1 \right)}
   \]
       denote the RHS of Step \ref{ThresDec:updateB}, the entries are either zero or bounded by 
   \begin{align*}
       \frac{1}{4(nU)^2} \norm{\widehat{\bb}^{(t)}}_1
       \le 
       \bbbar^{(t+1)}_i
       \le
       \frac{2}{n^2 U} \norm{\widehat{\bb}^{(t)}}_1
   \end{align*}
   for all $i \in S^{(t+1)}$. Furthermore, since $\bbhat^{(t+1)} \approx_{(\eps/8T)} \bbbar^{(t+1)}$, we have for all $i \in S^{(t+1)}$, 
   \begin{align*}
       \frac{1}{8(nU)^2} \norm{\widehat{\bb}^{(t)}}_1
       \le 
       \bbhat^{(t+1)}_i
       \le
       \frac{4}{n^2 U} \norm{\widehat{\bb}^{(t)}}_1.
   \end{align*}

\label{lemma:solution-of-neighbors}
Let $\LL$ be an invertible SDDM matrix with integer weights in $[-U,U]$.
Let $i,j\in[n]$ such that $\LL_{ij} \neq 0$. Then $\LL^{-1} \ee^{(i)} \leq nU \cdot \LL^{-1} \ee^{(j)}$.

\label{lemma:zero_out_error}
Let $\LL \in \R^{n\times n}$ be an invertible SDDM matrix with weights in $[-U, U]$,
$\bb \in \R^{n}$, and $\xx = \LL^{-1} \bb$. Let $\theta >0$ and $C \subseteq [n]$ such that $\xx_{C} \leq \theta$. Moreover 
let $\yy$ be the solution obtained by discarding entries in $C$ and
solving on the remaining entries, $F:=[n] \setminus C$, i.e.  
\begin{align*}
    \yy := \Mbegin
        \yy_{F} \\
        \yy_{C}
    \Mend 
    =
    \Mbegin
        \LL_{F, F}^{-1} \bb_{F} \\
        \mathbf{0}
    \Mend.
\end{align*}
Then
\[
\norm{
    \yy
    -
    \xx
}_{2}
\leq
n^3 U \theta.
\]

For $k \ge 1$, a vector $\pp \in \R^n$ is called a $k$-prediction for vector $\vv \in \R^n$ if for all $i \in [n]$, 
