For an undirected graph $G = (V, E)$, let $F \subseteq S \subseteq V$, the (inner) boundary of $F$ with respect to the subgraph $S$ is
\begin{align*}
    \partial_S F := \{ v \in F : \exists w \in (S \setminus F), s.t., (v,w) \in E\}.
\end{align*}
For an $n \times n$ undirected matrix $\LL$, we define boundary with respect to the underlying graph $G = ([n], E)$ where $E = \{ (i,j) : \LL_{ij} \neq 0\}$. That is, for $F \subseteq S \subseteq [n]$,
\begin{align*}
    \partial_S F := \{ i \in F :  \exists j \in (S \setminus F), s.t., \LL_{ij} \neq 0\}.
\end{align*}
We write $\partial F := \partial_V F$ (or $\partial_{[n]} F$) when $S = V$ (or $S = [n]$).

\label{lemma:boundary-upper-bound}
   Let $\LL$ be an $n\times n$ invertible SDDM matrix with integer weights in $[-U,U]$, and $\bb$ be a nonnegative vector of dimension $n$, we denote $\xx := \LL^{-1} \bb$. Let $F$ be a set with $F \supseteq \{i \in [n] : \bb_i > 0 \}$, and let $C := [n] \setminus F$. Define the maximum entry of the reduced system in $F$ on $\partial F$, 
   \begin{align*}
       \Delta := \max_{u \in \partial F} (\LL_{F, F}^{-1} \bb_F)_u
   \end{align*}
   where we define the maximum to be zero if $\partial F = \emptyset$, then for any $i \in C$, we have $\xx_i \le n^3U \Delta$.

\label{lemma:find-near-pairs-with-fmm}
There exists an algorithm that
given any directed graph $G=(V,E,w)$ with $|V|=n$ and nonnegative integer $k$ computes the set of pairs $(i,j)$ with $d^{G}(i,j) \leq 2^k$ with $\Otil(n^{\omega})$ bit operations.

\label{lemma:all-close-pairs}
There exists an algorithm such that for any $\epsilon, \delta \in (0,1)$ and $n, U > 3$, given any invertible RDDL matrix $\LL \in \mathbb{R}^{n \times n}$ with integer entries in $[-U, U]$, its associated graph $G = ([n+1], E, w)$, and a random subset $S \subseteq [n]$ where each $i \in [n]$ is independently included in $S$ with probability $1/\sqrt{n}$, the algorithm—with probability at least $1 - \delta$ and using $\Otil\big(n^{\omega + 0.5} \log(U) \log(\delta^{-1} \epsilon^{-1})\big)$ bit operations—computes $\exp(\epsilon)$-approximations of $(\LL_{\overline{S}, \overline{S}}^{-1})_{g_i g_j}$ for all pairs $i, j \in \overline{S}$ satisfying $d^{G(\overline{S})}(i, j) \leq 2^k$, where:
\begin{itemize}
\item $\overline{S} = [n] \setminus S$,
  \item $2^k$ is the smallest power of two greater than $\sqrt{n} \log(n^2 \epsilon^{-1} \delta^{-1})$, and
  \item $i \mapsto g_i$ is the unique monotone mapping from $\overline{S}$ to $[|\overline{S}|]$.
\end{itemize}

\label{lemma:sparse-near-pair-compute}
There exists an algorithm such that for any $\epsilon, \delta \in (0,1)$ and $n, U > 3$, given any invertible RDDL matrix $\LL \in \mathbb{R}^{n \times n}$ with $m$ nonzero integer entries in $[-U, U]$, its associated graph $G = ([n+1], E, w)$, and a random subset $S \subseteq [n]$ where each $i \in [n]$ is independently included in $S$ with probability $1/\sqrt{n}$, the algorithm, with probability at least $1 - \delta$ and using $\Otil(m n^{1.5+o(1)}\log^{O(1)}(U \kappa\delta^{-1}\epsilon^{-1}))$ bit operations, computes $\exp(\epsilon)$-approximations of $(\LL_{\overline{S}, \overline{S}}^{-1})_{g_i g_j}$ for all pairs $i, j \in \overline{S}$ satisfying $d^{G(\overline{S})}(i, j) \leq 2^k$, where:
\begin{itemize}
