\label{def:most-killing}
We will say that a restriction $\rho$ enjoys the \emph{most-killing property} with respect to a trace $\tau = ((b_1, X_1), \dots, (b_\ell, X_\ell))$ if it holds that for every $k \in[\ell]$, the block $i \in [s] \setminus \{ b_1, \dots, b_{k-1}\}$ that is the most frequent block mentioned in $W_{\restriction \rho_{k-1}}$ happens to be precisely $b_k$ and $\rho_k$ satisfies the following conditions.
\begin{enumerate}
\itemsep=0pt
    \item If $e_i$ appears positively in at least $1/3$ of all the clauses in $W_{\restriction \rho_{k-1}}$ that mention block $i$, then $\rho_k(e_i) = 1$ and $\rho_k(x) = *$ for every other variable $x \neq e_i$ in block $i$.

    \item If $e_i$ does \emph{not} appear positively in at least $1/3$ of all the clauses in $W_{\restriction \rho_{k-1}}$ that mention block $i$, then $\rho_k(e_i) = 0$ and for every other variable in block $i$, $\rho_k$ assigns values to them respecting the ordering in $X_i = ( e_i, x_{i,1}, x_{i, 2}, \dots)$ and with the following priority. For $j = 1, \dots, |X_i|-1$,
    \begin{enumerate}
    \itemsep=0pt
        \item if $x_{i, j}$ appears positively more often than negatively in $W_{\restriction \rho_{k-1, \{e_i, x_{i, 1}, \dots, x_{i, j-1}\}}}$, then $\rho_k(x_{i, j}) = 1$; 
        \item if $x_{i, j}$ appears negatively more often than positively in $W_{\restriction \rho_{k-1, \{e_i, x_{i, 1}, \dots, x_{i, j-1}\}}}$, then $\rho_k(x_{i, j}) = 0$.
    \end{enumerate}
\end{enumerate}

\label{lemma:induction-restriction-PV}
Let $c \in \bbN$. The following is provable in $\SOT$. For every CNF formula $\varphi$  over $n$ variables and $\pi$ a correct Resolution refutation of $\Reff_s(\varphi)$, let $w \coloneq c\cdot \left\lceil \sqrt{s \log |\pi|} \right\rceil$ and let $W$ denote the set of clauses in $\pi$ of block-width larger than $w$. Then, for every $\ell$, the formula $\Psi(\varphi, \pi, s, \ell)$ defined as follows holds: if $\ell \leq w/2$, then there exists a restriction $\rho \in \{ 0,1,*\}^N$, where $N$ is the number of variables of the $\Reff_s(\varphi)$ formula, a trace $\tau = ((b_1, X_1), \dots, (b_\ell, X_\ell))$ and $d \leq \ell$ such that:
\begin{enumerate}[label=(\roman*)]
\itemsep=0pt
    \item $\rho$ is $d$-disabling;
    \item $\rho$ has the most-killing property according to $\tau$;
    \item $(3s)^\ell \cdot |W_{\restriction \rho}| \leq |W| \cdot (3s- w + \ell)^\ell$.
\end{enumerate}

\label{lemma:exp-bound-PV}
In $\PVO$, for all $n,m,p \in \Log$, if $n < m$ and $p \geq 1$, it holds that
