\label{def:reservation-invariant}
Let $\pi$ be a Resolution refutation of $\Reff_s(\varphi)$ for some CNF formula $\varphi(x_1, \dots, x_n)$, let $N$ be the number of variables of $\Reff_s(\varphi)$, $d \leq \operatorname{depth}(\pi)$, and let $\calC = (C_1, \dots, C_d)$ be a length-$d$ path in $\pi$ starting from $C_1 = \bot$. Let the $s$ blocks of $\Reff_s(\varphi)$ be arranged in a layered manner, so that there are $n$ layers, each containing $\lfloor s/n\rfloor$ blocks, with the remainder blocks left from the flooring operations collected all in the last layer, plus one additional layer on top with a single block corresponding to the root. We say that $\calC$ satisfies the \emph{reservation invariant} with respect to a sequence $A = (\alpha_1, \dots, \alpha_d)$ of restrictions $\alpha_i \in \{ 0,1,*\}^N$ if, for every $i \in [d]$,

\begin{enumerate}
\itemsep=0pt
    \item[(i)] the restriction $\alpha_i$ falsifies $C_i$;
    \item[(ii)] a block is only mentioned in $\alpha_i$ if it is either mentioned in $C_i$ or its parent according to $\alpha_i$ is mentioned in $C_i$, and, in particular, $\bw(\alpha_i)  \leq 3\bw(C_i)$;
    \item[(iii)] if $\alpha_i$ restricts some variable in block $B$ from layer $\ell$, then it does so in the following way: $B$ must contain exactly $\ell$ literals over the variables $x_1, \dots, x_\ell$ and no two literals for the same variable;
    \item[(iv)] the restriction $\alpha_i$ does not falsify any clause of $\Reff_s(\varphi)$;
    \item[(v)] the path determined by $\calC$ corresponds to $A$ in the following way: if $C_i$ was derived from $C_{i+1}$ by resolving over variable $v$, then $\alpha_{i+1}(v)$ is defined and $v$ appears in $C_{i+1}$ with polarity $1- \alpha_{i+1}(v)$.
\end{enumerate}

\label{lemma:induction-width-PV}
The following is provable in $\SOT$. For every CNF formula $\varphi$ over $n$ variables and $\pi$ a correct Resolution refutation of $\Reff_s(\varphi)$, for every $d$, the formula $\Psi(\varphi, \pi, s, d)$ defined as follows holds: if $1\leq d \leq \operatorname{depth}(\pi)$, then there exists a sequence $\calC = (C_1, \dots, C_d)$ of clauses of $\pi$ and a sequence $A = (\alpha_1, \dots, \alpha_d)$ of restrictions such that at least one of the following conditions holds:
\begin{enumerate}
\itemsep=0pt
    \item[(a)] there is $C_i \in \calC$ that satisfies $\bw(C_i) \geq 1/3 (\lfloor{s/n}\rfloor - 1 )$;
    \item[(b)] there is $C_i$ in and its corresponding restriction $\alpha_i$ that contain a satisfying assignment to $\varphi$;
    \item[(c)] the sequence $\calC$ is a path in $\pi$ starting at $C_1 = \bot$ and the reservation invariant holds for $\calC$ with respect to $A$.
\end{enumerate}

 \label{prop:mild-properties}
The following hold for every reasonably strong proof system $S$:
 \begin{enumerate}[label=(\roman*)]
 \itemsep=0pt
     \item the system $S$ is constructively closed under formula substitutions, i.e., given a proof of $\varphi(x_1, \dots, x_n)$ in size $s$ and formulas $\psi_1, \dots, \psi_n$, we can obtain a proof of $\varphi(\psi_1, \dots, \psi_n)$ in time $\poly(s, n, |\psi_1|, \dots, |\psi_n|)$;
     \item the system $S$ is constructively closed under \emph{modus ponens}, i.e., given an $S$-proof of $\varphi$ in size $s$ and an $S$-proof of $\varphi \to \psi$ in size $t$, we can obtain an $S$-proof of $\psi$ in time $\poly(s, t)$;
     \item the system $S$ is constructively closed under contrapositions, i.e., given an $S$-proof of $\neg \psi$ in size $s$ and an $S$-proof of $\varphi \to \psi$ in size $t$, we can obtain an $S$-proof of $\neg \varphi$ in time $\poly(s, t)$;
     \item the system $S$ \emph{implicationally simulates Resolution}: for every two CNF formulas $\varphi$ and $\psi$ such that Resolution performs the derivation $\varphi \vdash_\Res \psi$ in size $s$, there is an $S$-proof of $\varphi \to \psi$ in size $\poly(s)$.
 \end{enumerate}

\label{lemma:UB-consequence-basic}
Let $S \geq \Res$ be a propositional proof system closed under literal substitutions, modus ponens, contrapositions, and implicationally simulating Resolution.
Then, there exists $p(n, m, s) = \poly(n,m, s)$ such that for every $n$-variate CNF formula $\varphi$ with $m$ clauses, and every $t\geq p(n,m,s)$ if $S \vdash \neg \Reff_{t}(\Reff_s(\varphi))$ in size $\ell$, then $S \vdash \neg \varphi[2]$ in size $\poly(n, m, s, t, \ell)$.

\label{thm:fragment-characterization}
Let $S$ be a reasonably strong proof system. There is $p(n, m, s) =\poly(n,m, s)$ such that for every CNF formula $\varphi(x_1, \dots, x_n)$ with $m$ clauses, every $t \in \bbN$, and every $s \geq n^3$,
\begin{enumerate}[label=(\roman*)]
\itemsep=0pt
    \item if $S \vdash \neg \varphi$ in size $\ell$, then $S \vdash \neg \Reff_t(\Reff_{s}(\varphi_n))$ in size $\poly(n, m, s, t, \ell)$;
    \item if $S \vdash \neg \Reff_{p(n,m,s)}(\Reff_s(\varphi_n))$ in size $\ell$, then $S \vdash \neg \varphi_n$ in size $\poly(n, m, s, \ell)$.
\end{enumerate}
Furthermore, in both cases, given an $S$-proof of the left-hand side statement, one can obtain a proof of the right-hand side statement in polynomial time.

\label{thm:aut-on-Ref-EF}
Let $S$ be a reasonably strong proof system. Then, the following are equivalent:
\begin{enumerate}
    \item[(i)] $S$ is automatable;
    \item[(ii)] $S$ is automatable on $\Reff$ formulas.
\end{enumerate}

\label{thm:W-aut-on-Ref-EF}
Let $S$ be a reasonably strong proof system. Then, the following are equivalent:
\begin{enumerate}
    \item[(i)] $S$ is weakly automatable;
    \item[(ii)] $S$ is weakly automatable on $\Reff$ formulas.
\end{enumerate}

\label{thm:aut-on-Ref-Res}
The following hold for Resolution:
\begin{enumerate}
    \item[(i)] Resolution is automatable if, and only if, it is automatable on $\Reff$ formulas;
    \item[(ii)] Resolution is weakly automatable if, and only if, it is weakly automatable on $\Reff$ formulas.
\end{enumerate}

\label{cor:prop-unprovability}
For every propositional proof system $S \geq \Res$ implicationally simulating Resolution and closed under contrapositions and clause substitutions, if $S$ is not polynomially bounded, there exists a family of unsatisfiable CNF formulas $\{\psi_n\}_{n\in\bbN}$ on $N = \poly(n)$ variables and of size $|\psi_n| = \poly(n)$ such that
\begin{enumerate}
    \item[(i)] they require size at least $2^{N^{\Omega(1)}}$ to be refuted in Resolution;
    \item [(ii)] there is a polynomial $p(n)$ such that the formulas $\{ \neg \Reff_{p(n)}(\psi_n)\}_{n\in\bbN}$ are tautological but do not have polynomial-size proofs in $S$.
\end{enumerate}

\label{thm:fo-unprovable}
Let $T$ be a consistent first-order extending $\SOT$ with a set of axioms recognizable in polynomial time and admitting $\bbN$ as a model. Then, there exits a sequence of unsatisfiable propositional formulas $\{ \psi_{k, s} \}_{{k, s} \in \bbN}$ described uniformly by a polynomial-time algorithm given $k$ and $s$ in unary, where $\psi_{k,s}$  has $N = \poly(k, s)$ variables, and such that
\begin{enumerate} \itemsep=0pt
    \item[(i)] Resolution refutations of the formula $\psi_{k, s}$ require size $2^{N^{\Omega(1)}}$;
    \item[(ii)] there are constants $c >0$ and $N_0 \in \bbN$ such that the lower bound expressed by the first-order sentence $\forall k \forall s\forall \pi \left(  N > N_0 \land \operatorname{Ref}_{\Res}(\psi_{k, s}, \pi) \to |\pi| >  N^{c} \right)$ is independent of $T$.
\end{enumerate}

\label{cor:fo-unprovable}
    Let $T$ be a consistent first-order extending $\mathsf{Q}$ with a set of axioms recognizable in polynomial time. Then, there exits a sequence of unsatisfiable propositional formulas $\{ \psi_{k, s} \}_{{k, s} \in \bbN}$ described uniformly by a polynomial-time algorithm given $k$ and $s$ in unary, where $\psi_{k,s}$ has $N = \poly(k, s)$ variables, and such that
\begin{enumerate} \itemsep=0pt
    \item[(i)] Resolution refutations of the formula $\psi_{k, s}$ require size $2^{N^{\Omega(1)}}$;
    \item[(ii)] there is a constant $c > 0$ and $N_0 \in \bbN$ such that the lower bound expressed by the first-order sentence $\forall k \forall s\forall \pi \left(N > N_0 \land \operatorname{Ref}_{\Res}(\psi_{k, s}, \pi) \to |\pi| >  N^{c} \right)$ is unprovable in $T$, but true in $\bbN$.
\end{enumerate}

\label{def:clone}
    A \emph{clone} over $D$ is a set of operations $\mathcal{F} \subseteq \bigcup_{n \geq 1}\{f: D^n \to D\}$ for which the following holds:
    \begin{itemize}
        \item $\mathcal{F}$ contains the projection operation $\mathrm{proj}^n_i$ for every $n \geq 1$, $i \in [n]$.
        \item For every $m$-ary $g \in \mathcal{F}$ and $n$-ary $f_1, \ldots, f_m \in \mathcal{F}$, the $n$-ary function $g'$ defined by
        \[
        g': (x_1, \ldots, x_n) \mapsto g(f_1(x_1, \ldots, x_n), \ldots, f_m(x_1, \ldots, x_n))
        \]
        is also in $\mathcal{F}$.
    \end{itemize}

\label{def:2-3-minimal}
    A binary CSP instance $I = (V, \{R_u\}_{u \in V}, \{R_{u, v}\}_{u\neq v \in V})$ over domain $D$ is \emph{$(2,3)$-minimal} if 
    \begin{enumerate}
        \item[(a)] For every distinct $u, v\in V$, $R_{v,u} = \{(b, a) \mid (a, b) \in R_{u, v}\}$. 
        \item[(b)] For every distinct $u, v \in V$, $R_u = \{a \in D \mid \exists b \in D, (a, b) \in R_{u,v}\}$.
        \item[(c)] For every pairwise distinct $u,v,w \in V$ and $(a, b) \in R_{u,v}$, there exists $c \in R_w$ such that $(a, c) \in R_{u,w}$ and $(b, c) \in R_{v,w}$.
    \end{enumerate}

\label{lem:01all}
    Let $R \subset D^2$ be a binary relation. Then $R$ is preserved by the dual discriminator operation $d: D^3 \to D$ if and only if $R$ is of one of the following forms:
    \begin{itemize}
        \item $R = P \times Q$ for some $P, Q \subseteq D$.
        \item $R = (\{u\} \times Q) \cup (P \times \{v\})$ for some $u \in P \subseteq D$ and $v \in Q \subseteq D$.
        \item $R = \{(u, \pi(u)) \mid u \in P\}$ for some $P,Q \subseteq D$ and bijective $\pi: P \to Q$.
    \end{itemize}

\label{lem:greedy_correctness}
    Let $I = (V, \{R_u\}_{u \in V}, \{R_{u,v}\}_{u,v\in V})$ be a nontrivial (2,3)-minimal instance preserved by the dual discriminator operation. Let $u_0 \in V$, $a \in R_{u_0}$, $S$ be the set of variables fixed by assigning $a$ to $u_0$. For every $v \in S$, let $A_S(v)$ be the unique label that $v$ is fixed to by assigning $a$ to $u_0$. Let $A': V \backslash S \to D$ be any satisfying assignment for the induced (2,3)-minimal instance $I' = (V \backslash S, \{R_u\}_{u \in V \backslash S}, \{R_{u,v}\}_{u,v\in V \backslash S})$, then 
    \[
    A: V \to D, \quad A(v) = \left\{\begin{array}{ll}
        A_S(v) & \text{if } v \in S, \\
        A'(v) & \text{otherwise}
    \end{array}\right.
    \]
    is a satisfying assignment for $I$.

