\label{def: reduction}
Let $\mathcal{R}, \mathcal{Q}$ be two search problems. A many-to-one reduction from $\mathcal{R}$ to $\mathcal{Q}$ is defined as two polynomial time computable functions $f, g$ such that for all $x \in \pi_1(\mathcal{R}), y \in \{ 0, 1\}^*$, the following holds.
\[ (x, g(y)) \in \mathcal{R} \impliedby (f(x), y) \in \mathcal{Q} \]

\label{def: promiseTFSigma_i}
We say that a search problem $\mathcal{R} \subseteq \{ 0, 1\}^* \times \{ 0, 1\}^*$ is in the class \cc{PromiseF\Sigma_i^P} if it satisfies the following conditions.
\begin{enumerate}
    \item
    For all $x \in \pi_1(\mathcal{R})$, and for all $y$ s.t. $(x, y) \in \mathcal{R}$, $|y| \leq \poly(|x|)$.
    \item 
    There exists a polynomial time verifier $V$ and polynomials $p_1(n), \dots, p_{i-1}(n)$ such that the following holds: for all $x \in \pi_1(R)$, 
    \[(x, y) \in R \iff \forall z_1 \in \{ 0, 1\}^{p_1(|x|)} \exists z_2 \in \{ 0, 1\}^{p_2(|x|)} \forall z_3 \in \{ 0, 1\}^{p_3(|x|)} \dots V(x, y, z_1, \dots, z_{i-1})\text{ accepts.}\]
\end{enumerate}

\label{def: essentially_unique}
We say that a total search problem $\mathcal{R} \in \cc{TF\Sigma_i^P}$ ($i \geq 2$) has essentially unique solutions if there exist two verifiers $V_1, V_2$ such that the following hold.
\begin{enumerate}
    \item $V_1$ is testable in polynomial time with an \cc{\Sigma_{i-2}^P} oracle and $V_2$ is testable in polynomial time with an \cc{\Sigma_{i-1}^P} oracle.


    \item For all $x$, either there exists a $y$ such that $V_1(x, y) = 1$ and $(x, y) \in \mathcal{R}$, or else there exists a unique $y$ such that $V_2(x, y) = 1$ and $(x, y) \in \mathcal{R}$.
\end{enumerate}

For any relation $\mathcal{R}$ with essentially unique solutions and verifiers $V_1, V_2$, we define $\mathcal{R}_u$ as follows. 
\begin{enumerate}
    \item For any $x \in \pi_1(\mathcal{R})$ such that there exists $y$ where $V_1(x, y) = 1$, $(x, y) \in \mathcal{R}_u$ if and only if $y$ is the lexicographically smallest $y$ where $V_1(x,y) = 1$. 
    \item For any $x \in \pi_1(\mathcal{R})$ such that $V_1(x, y) = 0$ for all $y$, $(x, y) \in \mathcal{R}_u$ if and only if $(x, y) \in \mathcal{R}$.
\end{enumerate}

