\label{DIGRAPHSS}
A \emph{directed input graph} of size $n$ is a pair $\mathcal{X} = ([n], E_\mathcal{X})$, where $E_\mathcal{X}(i,j)$ is a binary relation on the vertex set $[n]$ indicating the presence of an edge from $i$ to $j$. A \emph{target digraph with domains} is a tuple of sets $\ddot{\mathcal{A}} = ([q], V_{\ddot{\mathcal{A}}}, E_{\ddot{\mathcal{A}}})$, where:
\begin{itemize}
    \item $V_{\ddot{\mathcal{A}}} < \langle n, q \rangle$ is the superdomain. The predicate $V_{\ddot{\mathcal{A}}}(i, a)$ indicates that the domain for variable $x_i$ contains the element $a$. For brevity, we write $D_i := V_{\ddot{\mathcal{A}}}^{[i]}$.

    \item $E_{\ddot{\mathcal{A}}} < \langle n, n, q, q \rangle$ encodes the allowed edges between domains. That is, $E_{\ddot{\mathcal{A}}}^{[ij]}(a,b)$ holds only if
    \begin{equation}
        \begin{gathered}
            E_{\ddot{\mathcal{A}}}^{[ij]}(a,b) \rightarrow D_i(a) \wedge D_j(b).
        \end{gathered}
    \end{equation}
\end{itemize}
We denote by the predicate DG$(\Theta)$ that a pair of sets $\Theta = (\mathcal{X}, \ddot{\mathcal{A}})$ satisfies all the above conditions. This representation allows us to model homomorphisms from $\mathcal{X}$ to $\ddot{\mathcal{A}}$, using edge relations $E_{\ddot{\mathcal{A}}}^{[ij]}$ and domain sets $D_i$ for all vertices $x_1, \ldots, x_n$.

\label{krjfhpakrhfgdrg}
A well-defined map $H < b_h$ from $[n]$ to $[q]$ is called a \emph{homomorphism between the input digraph} $\mathcal{X} = ([n], E_{\mathcal{X}})$ of size $n$ and the \emph{target digraph with domains} $\ddot{\mathcal{A}} = ([q], V_{\ddot{\mathcal{A}}}, E_{\ddot{\mathcal{A}}})$, where $V_{\ddot{\mathcal{A}}} < \langle n, q \rangle$, if $H$ maps each $i \in V_{\mathcal{X}}$ to its corresponding domain $D_i$ and preserves edges.
\begin{equation}\label{HOMINSTAG}
\begin{gathered}
Hom(\mathcal{X}, \ddot{\mathcal{A}}, H) \iff  
wMap_1([n], [q], H)\,\wedge (\forall i < n\, \forall a < q\, (H(i) = a \rightarrow D_i(a)))\,\wedge \\
\forall i, j < n\, \forall a, b < q\, 
(E_{\mathcal{X}}(i, j) \wedge H(i) = a \wedge H(j) = b \rightarrow E^{[ij]}_{\ddot{\mathcal{A}}}(a, b))
\end{gathered}
\end{equation}
The existence of such $H$ can be expressed by the $\Sigma^{1,b}_{1}$-formula $\exists H < b_h\,Hom(\mathcal{X}, \ddot{\mathcal{A}}, H)$. We will sometimes abbreviate the expression $\exists H < b_h,Hom(\mathcal{X}, \ddot{\mathcal{A}}, H)$ as $Hom(\mathcal{X}, \ddot{\mathcal{A}})$.

\label{jkjkajsflageee}
For any relational structure $\mathcal{A}$ that corresponds to an algebra with a Mal'tsev operation, theory $V^1$ proves the soundness of Mal'tsev algorithm:
\[
V^1 \vdash \forall \mathcal{X} \, \forall \ddot{\mathcal{A}} \, \forall R  \;\; \left( \mathrm{Comp}(R, \mathcal{X}, \ddot{\mathcal{A}}) \wedge R^{[\#E_{\mathcal{X}}]} = \emptyset \longrightarrow \neg \mathrm{Hom}(\mathcal{X}, \ddot{\mathcal{A}}) \right),
\]
where
\begin{gather*}
\mathrm{Comp}(R, \mathcal{X}, \ddot{\mathcal{A}}) \iff \forall i < n \; \forall a, b \in V^{[i]}_{\ddot{\mathcal{A}}} \;\;
R^{[0]}(i, a, b\bl, i, a\bl) \wedge \forall j \neq i < n \;\; R^{[0]}(i, a, b\bl, j, d_j\bl), \\
\forall 0 < l \leq \#E_{\mathcal{X}} \;\; R^{[l]} = next(R^{[l-1]}, \min(E_{\mathcal{X}_l}), E^{[\min(E_{\mathcal{X}_l})]}_{\ddot{\mathcal{A}}}).
\end{gather*}

\label{thm: Cubical Complex}
Let $F$ be a 3-SAT formula with $n$ variables. The set of satisfying assignments $S \subseteq \{0,1\}^n$ forms a cubical complex $C(F)$, where:
\begin{itemize}
    \item Vertices correspond to satisfying assignments.
    \item $k$-faces correspond to $k$-dimensional subcubes where all $2^k$ assignments satisfy $F$.
\end{itemize}
Topological queries about $C(F)$ (e.g., connectedness, Betti numbers) reduce to 3-SAT instances.

\label{thm:unstructured}
Let $F$ be a random 3-SAT instance at clause density $\alpha>4.26$.  Then with probability $1-o(1)$:
\begin{enumerate}
  \item Its solution space $S(F)$ decomposes into $2^{\Omega(n)}$ disconnected clusters.
  \item The cubical complex of $S(F)$ has exponentially large Betti numbers (e.g.\ $\beta_2(S(F))=2^{\Omega(n)}$).
  \item The primal constraint graph of $F$ has treewidth $\Omega(n)$.
\end{enumerate}
In particular, $S(F)$ admits no global ordering or low-dimensional traversal.

\label{thm:non-embedding-hardness}
Computing \(\beta_k(K)\) for \(k\ge 2\) on a cubical complex \(K\subseteq \{0,1\}^N\)
is \(\#\mathrm{P}\)-hard under polynomial-time Turing reductions. In particular, unless \(\#\mathrm{P}\subseteq\mathrm{FP}\), no algorithm in the standard Boolean decision-tree or subcube-query model can compute \(\beta_k(K)\) in worst-case time \(2^{o(N)}\).

\label{thm:random-3sat-betti}
For random 3‑SAT at clause density \(\alpha>4.26\),
\[
  \beta_2(S(F))\;\ge\;2^{c n}
\]
for some \(c>0\), with probability \(1-o(1)\).

\label{thm:Topological Hardness}
Let $F$ be a random 3‑SAT formula whose solution space $S(F)$ has Betti numbers $\beta_0 = 2^{\Omega(n)}$ and minimal inter-cluster Hamming separation $\delta = \Theta(n)$. Then:

\begin{enumerate}
    \item Any modification to $F$ that reduces $\beta_0$ to $O(poly(n))$ produces a structured 3-SAT instance in $\Pclass$.
    \item In the general case, no such modification exists without altering $F$'s logical content.
\end{enumerate}

\paragraph{Conclusion}
The topological complexity of $S(F)$ is an intrinsic computational barrier.

\label{thm:expander-family}
There exists a polynomial-time computable family of 3-SAT instances $\{F_N\}$ such that:
\begin{enumerate}
    \item Each $F_N$ is satisfiable
    \item $\beta_2(S(F_N)) \geq 2^{cN}$ for some $c > 0$
    \item The reduction $N \mapsto F_N$ is topology-preserving
\end{enumerate}

\label{thm:final-worst-case}
Let $\{F_N\}$ be the family of 3-SAT formulas constructed in Theorem~\ref{thm:betti-exp-worst} via embedding $(N,d,\epsilon)$-expander graphs $G_N$ (with $\beta_1(G_N) = \Omega(N)$). Then:
\begin{enumerate}
    \item $\beta_2(S(F_N)) \geq 2^{c N}$ for some constant $c > 0$ (Theorem~\ref{thm:betti-exp-worst}).
    \item Any algorithm deciding satisfiability for $F_N$ requires $2^{\Omega(N)}$ time (Theorem~\ref{thm:universal-lb}).
    \item $\{F_N\}$ is NP-complete (via Cook-Levin/3-COLOR reduction).
\end{enumerate}

Algebraic techniques (e.g., Nullstellensatz, Grobner bases) cannot circumvent the homology barrier:
\begin{itemize}
    \item Betti numbers remain invariant under algebraic transformations
    \item The disjoint cycle obstruction persists in any commutative ring
\end{itemize}

The homology obstruction is not $\mathbf{NP}$-natural:
\begin{itemize}
    \item $\beta_2$ is $\#\mathbf{P}$-hard to compute
    \item No efficient approximation exists under standard complexity assumptions
\end{itemize}

\label{lem:support-disjoint}
For the cycles $\{\gamma_i\}$ constructed in Lemma \ref{lem:homology-basis}:
\begin{enumerate}
    \item $\mathrm{supp}(\gamma_i) \cap \mathrm{supp}(\gamma_j) = \emptyset$ for $i \neq j$
    \item $\partial_2(\gamma_i) \neq 0$ and $\partial_2(\gamma_i) \notin \mathrm{im}\partial_3$
    \item Any linear combination satisfies:
    \[
    \sum c_i\gamma_i = 0 \in H_2(S(F_N)) \iff c_i = 0 \quad \forall i
    \]
\end{enumerate}

\label{thm:universal-homotopy-hardness}
Let $\mathcal{I}$ be a homotopy invariant of cubical complexes satisfying:
\begin{enumerate}
\item \textbf{Detects exponential complexity}: $\mathcal{I}(S(F)) = \mathsf{Exp}$ implies any 3-SAT algorithm requires $2^{\Omega(N)}$ time
\item \textbf{Preserved under homotopy equivalence}: $X \simeq Y \Rightarrow \mathcal{I}(X) \cong \mathcal{I}(Y)$
\end{enumerate}
Then computing $\mathcal{I}$ is $\#\mathsf{P}$-hard.

Under $\mathsf{P} \neq \mathsf{NP}$, no homotopy-invariant functor $\mathcal{F}: \mathsf{Cub} \to \mathsf{C}$ to a combinatorial category $\mathsf{C}$ can simultaneously:
\begin{enumerate}
\item Be computable in $\mathsf{poly}(N)$ time
\item Detect exponential solution-space complexity
\item Avoid the natural proofs barrier
\end{enumerate}

The algorithm:
\begin{itemize}
\item Correctly estimates $\beta_2 = 2^{\Omega(N)}$ w.h.p.
\item Requires $2^{\Omega(N)}$ time due to:
  \begin{enumerate}
  \item Exponential sample size needed
  \item \#P-hardness of Betti number computation
  \item Matrix rank in dimension $2^{\Omega(N)}$
  \end{enumerate}
\end{itemize}

\label{lem:local-indist}
Let $r\ge 1$ be fixed and let at most $q(n)$ radius-$r$ vertex-centered neighborhoods be inspected. 
If $p(n) > q(n)$, then one can choose the $m_n$ enabled sites so that none lies inside any of the inspected radius-$r$ balls. Consequently, every inspected radius-$r$ neighborhood is isomorphic (as a labeled incidence subgraph) in $F^{\mathrm{easy}}_{n}$ and $F^{\mathrm{hard}}_{n}$.

\label{lem:no-3face-filling}
In gadget \(i\), the unique 2-face \(\Gamma_i\) on coordinates \(\{u_i,v_i\}\)
is not contained in any 3-face of the cubical complex.

\label{lem:boundary-injectivity}
Let \(\Gamma_i\) be the 2-face on \(\{u_i,v_i\}\).  Then:
\begin{enumerate}
  \item \(\partial_2(\Gamma_i)\) is the sum of the four oriented edges flipping \(u_i\) or \(v_i\).
  \item For \(i\neq j\), the supports of \(\partial_2(\Gamma_i)\) and \(\partial_2(\Gamma_j)\) are disjoint.
  \item \(\Gamma_i\notin\mathrm{im}\,\partial_3\) (by Lemma~\ref{lem:no-3face-filling}), so \(\partial_2(\Gamma_i)\) is not the boundary of any 2-chain.
\end{enumerate}
Consequently, the homology classes \([\Gamma_i]\in H_2\bigl(S(F_N)\bigr)\) are linearly independent.

\label{def:sigtype_intro}
    Let $\mathcal{S}$ be a finite set of signatures. We say that $\mathcal{S}$ is of type\footnote{We point out that we have renamed the types of signatures to avoid introducing further concepts.}
    \begin{itemize}
        \item[1.] $\mathbb{T}[1]$ if $\chi(a,s)=0$ for all $s\in \mathcal{S}, a\geq 2$, 
        \item[2.] $\mathbb{T}[2]$ if $\chi(a,s)=0$ for all $s\in \mathcal{S}, a\geq 3$, but there exists $s\in \mathcal{S}$ with $\chi(2,s)\neq 0$, and
        \item[3.] $\mathbb{T}[\infty]$ otherwise, i.e., there exists $s\in \mathcal{S}$ and $a\geq 3$ such that $\chi(a,s)\neq 0$.
    \end{itemize}

\label{thm:main_uncol}
    Let $\mathcal{S}$ be a finite set of signatures. We set $\mathcal{S}_0 = \{s \in \mathcal{S} \mid s(0) = 0\}$.
    \begin{itemize}
        \item[1.] If $\mathcal{S} \setminus \mathcal{S}_0$ is of type $\mathbb{T}[1]$, then $\uni{\constuncolholantprob{2}}(\mathcal{S})$ can be solved in FPT-near-linear time.
        \item[2.] Otherwise $\uni{\constuncolholantprob{2}}(\mathcal{S})$ is $\#\mathrm{W}[1]$-complete. If, additionally, $\mathcal{S} \setminus \mathcal{S}_0$ is of type $\mathbb{T}[\infty]$, then $\uni{\constuncolholantprob{2}}(\mathcal{S})$ cannot be solved in time $f(k)\cdot |V(\Omega)|^{o(k/\log k)}$, unless ETH fails. \qed
    \end{itemize}

\label{thm:INTROmainParamThm}\label{main_para_intro}
Let $\mathcal{S}$ be a finite set of signatures. Let furthermore $\mathcal{S}_0 = \{s \in \mathcal{S} \mid s(0) = 0\}$. 
\begin{itemize}
\item[1.] If $\mathcal{S} \setminus \mathcal{S}_0$ is of type $\mathbb{T}[1]$, then $\uncolholantprob(\mathcal{S})$ can be solved in FPT-(near)-linear time, that is, in time $f(k, \hs) \cdot \tilde{O}(|\Omega|)$, where $\hs$ is the rank of the underlying hypergraph of $\Omega$.
\item[2.] If $\mathcal{S}\setminus \mathcal{S}_0$ is not of type $\mathbb{T}[1]$, then $\uncolholantprob(\mathcal{S})$ is $\#\mathrm{W}[1]$-hard.\\ In particular, for any $d \in \mathbb{Z}_{\geq 2}$, the problem $\uni{\constuncolholantprob{d}}(\mathcal{S})$ is $\#\mathrm{W}[1]$-hard. Furthermore, if $\mathcal{S} \setminus \mathcal{S}_0$ is of type $\mathbb{T}[\infty]$, then $\uni{\constuncolholantprob{d}}(\mathcal{S})$ cannot be solved in time $f(k)\cdot |V(\Omega)|^{o(k/\log(k))}$, for any computable function $f$, unless ETH fails. \qed
\end{itemize}

\label{thm:INTROPerfectMatchingReduction}\label{main_classical_intro}
Let $\mathcal{S}$ be a finite set of signatures and let $d\in \mathbb{Z}_{\geq 2}$.
\begin{itemize}
\item[1.] If $\mathcal{S}$ is of type $\mathbb{T}[1]$ (implying that all signatures $s\in \mathcal{S}$ satisfy $s(0)\neq 0$), then $\uni{\constuncolholantprob{d}}(\mathcal{S})$ can be solved in polynomial time.
\item[2.] Otherwise, $\uni{\constuncolholantprob{d}}(\mathcal{S})$ is $\#\mathrm{P}$-hard. \qed
\end{itemize}

Let $S \subseteq \mathbb{Z}_{\geq 0}$ be a finite set. For any $d \in \mathbb{Z}_{\geq 2}$,
\begin{enumerate}
\item $\text{\sc{Factor}}_d(S)$ is $\#\mathrm{P}$-hard.
\item If $0 \notin S$, $\text{\sc{Factor}}_d(S)$ is solvable in FPT-(near)-linear time, that is, in time $f(k) \cdot \tilde{O}(|G|)$, for some computable function $f$.
\item If $0 \in S$, $\text{\sc{Factor}}_d(S)$ is $\#\mathrm{W}[1]$-hard and cannot be solved in time $f(k) \cdot |V(G)|^{o(k/\log(k))}$, for any computable function $f$, unless ETH fails.
\end{enumerate}

\label{claim:subposetMobius}
Let $(P, \leq)$ be a poset and let $(Q, \leq)$ be a subposet of $(P, \leq)$ such that for any $\sigma \notin Q$ and $\rho \geq \sigma$, it holds $\rho \notin Q$.
Let $f : Q \to \mathbb{R}, g : Q \to \mathbb{R}$ such that $f(\sigma) = \sum_{\rho \in Q,\, \rho \geq \sigma}g(\rho)$. Then, $g(\sigma) = \sum_{\rho \in Q,\, \rho \geq \sigma}\mu(\sigma, \rho)\cdot f(\rho)$, where $\mu : P \times P \to \mathbb{R}$ is the Möbius function of the poset $(P, \leq)$.

\label{lem:uncolHomBasis}
Let $\mathcal{S}$ be a finite set of signatures and let $\Omega = (G, \{s_v\}_{v \in V(G)})$, $k \in \mathbb{N}$ be an instance of $\uni{\constuncolholantprob{\mathsf{r}}}(\mathcal{S})$, where $G$ is $\hs$-uniform. We have
\begin{equation}\label{eq:uncolHolantHomBasis}
\uncolholant(\Omega, k) = \sum_{\colGraph{F} \in \kgraphsGamma}\zeta_{k, \mathcal{S}}{\colGraph{F}}\cdot \Hom(\colGraph{F} \to \colGraph{G})\,,
\end{equation}
where
\begin{align}\label{eq:coeffColored}
\nonumber&\zeta_{k, \mathcal{S}}{\colGraph{F}}  &= \sum_{\colGraph{H} \in \kgraphsBHS}\frac1{\Aut\colGraph{H}}\prod_{v \in V(H)}\nu_H(v)(\deg_H(v))\sum_{\substack{\rho \in \mathsf{Part}\colGraph{H} \\ \colGraph{F} \cong \colGraph{H/\rho}}}\mu(\rho)\,.
\end{align}

\label{lem:uncolHomBasisRESTATED}
Let $s$ be a signature and let $\Omega = (G, \{s\}_{v \in V(G)})$, $k \in \mathbb{N}$ be an instance of $\uni{\uncolholantprob}(\{s\})$, where $G$ is $\hs$-uniform. We have
\begin{equation}\label{eq:uncolHolantHomBasisSimplified}
\uncolholant(\Omega, k) = \sum_{F \in \mathcal{G}_{\leq k}(\hs)}\zeta_{k, s}(F)\cdot \Hom(F\to G)\,,
\end{equation}
where
\begin{align}\label{eq:coeffColoredRestated}
\nonumber\zeta_{k, s}(F)  = \sum_{H \in \mathcal{G}_k(\hs)}\frac1{\Aut(H)}\prod_{v \in V(H)}s(\deg_H(v))\sum_{\substack{\rho \in \mathsf{Part}(H) \\ F \cong H/\rho}}\mu(\rho)\,.
\end{align}

\label{thm:mainParamThm}
Let $\mathcal{S}$ be a finite set of signatures. Let $\mathcal{S}_0 = \{s \in \mathcal{S} \mid s(0) = 0\}$. We have the following classification of the complexity of $\uncolholantprob(\mathcal{S})$.
\begin{itemize}
\item[1.] If $\mathcal{S} \setminus \mathcal{S}_0$ is of type $\mathbb{T}[1]$, then $\uncolholantprob(\mathcal{S})$ can be solved in FPT-(near)-linear time, that is, in time $f(k, \hs) \cdot \tilde{O}(|\Omega|)$, where $\hs$ is the rank of the underlying hypergraph of $\Omega$.
\item[2.] If $\mathcal{S}\setminus \mathcal{S}_0$ is not of type $\mathbb{T}[1]$, then $\uncolholantprob(\mathcal{S})$ is $\#\mathrm{W}[1]$-hard. In particular, for any $d \in \mathbb{Z}_{\geq 2}$, the problem $\uni{\constuncolholantprob{d}}(\mathcal{S})$ is $\#\mathrm{W}[1]$-hard. Furthermore, if $\mathcal{S} \setminus \mathcal{S}_0$ is of type $\mathbb{T}[\infty]$, then $\uni{\constuncolholantprob{d}}(\mathcal{S})$ cannot be solved in time $f(k)\cdot |V(\Omega)|^{o(k/\log(k))}$, for any computable function $f$ and any $d \geq 2$, unless ETH fails.
\end{itemize}

\label{prop:tensorprod} Let $F, G, H$ be $\hs$-uniform hypergraphs for some $\hs \in \mathbb{Z}_{\geq 2}$. We have
\begin{align*}
\Hom(F \to G \otimes H) = \Hom(F \to G) \cdot \Hom(F \to H)\,.
\end{align*}

\label{thm:raduPoly}
There is an algorithm for the following problem: output the value $\#\mathsf{ColHom}(H \to G)$ when given
\begin{itemize}
\item[$\bullet$] as input a number $a \in \mathbb{N}$, a colorful graph $H$, a colored graph $G$, and
\item[$\bullet$] oracle access for a graph motif parameter $p$ with $\max_{F\,\triangleleft\,p}|V(F)| \leq a$ such that $H^\circ\,\triangleleft\, p$, where $H^\circ$ is the underlying (uncoloured) graph corresponding to $H$.
\end{itemize}
The running time of the algorithm is bounded by $4^{\Delta(H)}\cdot\mathsf{poly}(|V(G)|, a).$

 \label{Prop:chi_vanishing_property}
Let $\{s\}$ be of type $\mathbb{T}[2]$, then
we have
\begin{enumerate}
    \item[a)] $\chi(\lambda, s) = 0$ if $|\lambda| < 2\cdot  \mathsf{len}(\lambda)-2$,
    \item[b)] $\chi(\lambda, s) = a_\lambda \cdot (s(2)-s(1)^2)^{\mathsf{len}(\lambda)-1}$ for some $a_\lambda \in \mathbb{Z}_{>0}$ if $|\lambda| = 2 \cdot \mathsf{len}(\lambda)-2$.
\end{enumerate}

\label{thm:infinityCoeffRestated}
Let $s$ be a signature with $s(0) = 1$, $k \in \mathbb{N}$ and $F \in \mathcal{G}_k$. Then we have
\[\zeta_{k, s}(F) = \frac1{\Aut(F)}\prod_{v \in V(F)}\chi(\deg_F(v), s)\,.\]

\label{thm:zeta_at_most_k_edges}
Let $s$ be a signature with $s(0) = 1$, $k \in \mathbb{N}$, and $F \in \mathcal{G}_{\leq k}$. Then we have
\begin{equation} \label{eqn:Theorem_general1}
    \zeta_{k, s}(F)=\frac{1}{\#\mathsf{Aut}(F)} \cdot \sum_{\substack{\lambda: E(F) \to \mathcal{P}\\\sum_e |\lambda(e)| = k }}\ \  \prod_{e \in E(F)} \frac{\mathsf{mult}(\lambda(e))}{|\lambda(e)|!}  \prod_{v \in V(F)} \chi(\mathsf{deg}(F, v, \lambda), s)\,,
\end{equation}
where the partitions $\mathsf{deg}(F, v, \lambda)$ are defined as
\[
\mathsf{deg}(F, v, \lambda) = \bigcup_{\substack{e \in E(F):\\ e \text{ incident to }v}} \lambda(e)\,. 
\]

For every positive integer $r\geq 3$, there is a deterministic polynomial time algorithm that, on input a natural number $t$ in unary, outputs a pair of graphs $(H,W)$ such that
\begin{itemize}
    \item $H$ is an $r$-regular graph.
    \item $W\cong W_{t\times t}$ and $W$ is a subgraph of $H$, that is, $V(W)\subseteq V(H)$.
\end{itemize}

\label{def: pseudoexp}
    Consider the pair $(\mathcal{P,Q})$. A degree-$2d$ \emph{pseudoexpectation} for $(\mathcal{P}, \mathcal{Q})$ is a linear functional $L:\mathbb{R}[x_1, \ldots, x_n]_{2d}\to \mathbb{R}$ such that 
    \begin{itemize}
        \item $L(1)=1$.
        \item $L(p)\geq 0$ for every $p\in\mathcal{M}(\mathcal{P}, \mathcal{Q})_{2d}$.
    \end{itemize}

\label{th:normal_form_archimedean_systems}
    Let $d$ and $k$ be fixed natural numbers such that $d\geq k\geq 1$. Consider a set of polynomial equalities $\mathcal{R}$ and let $(\mathcal{P,Q})$ be a degree-$2k$ Archimedean pair. If there exists a degree-$2d$ refutation of $(\mathcal{P \cup R,Q})$, then there exists also a refutation of the form 
    \begin{equation*}
        -1 = \sigma + \sum_{r\in \mathcal{R}}a_r r^2 + \sum_{p \in \mathcal{P}} h_p p + \sum_{q \in \mathcal{Q}} s_q q,
    \end{equation*}
    where $\sigma, s_q \in \Sigma$, $h_p \in \mathbb{R}[x_1, \ldots, x_n]$, and $a_r\in \mathbb{R}$ is a scalar. Further, the degrees of $\sigma, h_p p$, and $s_q q$ are all at most $2(d+k-1)$.

\label{th:reduction}
    Let $\mathcal{P} = \{p_1 = 0, \ldots, p_m = 0\}$ be a set of polynomial equality constraints, $\mathcal F=\{f_1,\dots,f_t\}$ be a Gröbner basis (in \texttt{grlex} order) for the ideal $\langle \mathcal{F} \rangle$ and let $r\in \mathbb R[x_1,\dots,x_n]_{2d}$.
    \begin{itemize}
        \item \emph{Reduction.} Let $r = \sigma + \sum_{i=1}^m h_i p_i + \sum_{i=1}^t q_i f_i$ be a degree-$2d$ $\sos$ proof of $r$ from $\mathcal{P \cup \mathcal{F}}$. Then the identity $\overline{r} = \overline{\sigma} + \sum_{i=1}^m \overline{h_i p_i}$ holds. Further, the RHS has degree at most $2d$ and size polynomial in the size of $r$ and $\mathcal{P \cup F}$.
        \item \emph{Reconstruction.} Suppose there exists an $\sos$ $\sigma$ and polynomials $h_i$ satisfying $\overline{r} = \overline{\sigma} + \sum_{i=1}^m \overline{h_i p_i}$ with $\max \{\deg{\sigma},\deg{h_i p_i}\} \leq 2d$ and with total size $\ell$. Then there exists a degree-$2d$ $\sos$ proof $r = \sigma + \sum_{i=1}^m h_i p_i + \sum_{i=1}^t q_i f_i$ of size $\poly(\ell)$ with degree at most $2d$.
    \end{itemize}

\label{def:action-on-poly}
    Let $G$ be a finite group that can act on the indices $1, \ldots, n$ (e.g., a subgroup of $S_n$). For $g \in G$ and a multi-index $\alpha = (\alpha_1, \ldots, \alpha_n) \in \mathbb{N}^n$, we define the action of $g$ on $\alpha$ as $g \cdot \alpha = (\alpha_{g^{-1}(1)}, \ldots, \alpha_{g^{-1}(n)})$.
    For a monomial $m = x^{\alpha}$, the \emph{action of $G$ on $m$} is defined for any $g \in G$ as:
    \begin{align*}
        g \cdot m := x^{g \cdot \alpha} = x_1^{\alpha_{g^{-1}(1)}} \cdots x_n^{\alpha_{g^{-1}(n)}} = x_{g(1)}^{\alpha_1} \cdots x_{g(n)}^{\alpha_n}.
    \end{align*}
    This action extends linearly to the set of polynomials $\mathbb{R}[x_1, \ldots, x_n]$. Thus, for a polynomial $p(x) = \sum_{i=0}^m a_i x^{\alpha_i}$, the action of $g \in G$ on $p$ is defined as $g \cdot p = \sum_{i=0}^m a_i (g \cdot x^{\alpha_i})$.

    A polynomial p is said to be \emph{$G$-invariant} if $g \cdot p = p$ for all $g \in G$. If $G=S_n$, where $S_n$ is the symmetric group on $n$ elements, the polynomial is called \emph{symmetric}.

\label{th:group_action_additivity_multiplicativity}
    Let $G$ be a finite group acting on polynomials as defined above. For any two polynomials $p,q \in \mathbb{R}[x_1, \ldots, x_n]$ and any $g \in G$, the action satisfies:
    \begin{itemize}
        \item \textit{Additivity:} $g \cdot (p+q) = g \cdot p + g \cdot q$.
        \item \textit{Multiplicativity:} $g \cdot (pq)  = (g \cdot p)(g \cdot q)$.
    \end{itemize}

\label{def:action-on-matrices}
    Let $S_n$ be the symmetric group of permutations of $n$ elements. Every permutation $\pi \in S_n$ of the indices of $x_1, \dots, x_n$ induces a permutation $\pi'\in S_{\omega_n^d}$ on the monomials in the monomial basis $\x_d$. Consider the permutation matrix $P_{\pi'}$ associated to $\pi'$, and let $Q\in \MS^{\omega_n^d}$ be a symmetric matrix whose entries are indexed by the monomial basis $\x_d$, i.e. $Q=(Q_{x^\alpha, x^\beta})$ for $x^\alpha, x^\beta$ entries of $\x_d$. The \emph{action} of $\pi \in S_n$ on $Q$ is given by
    \begin{equation*}
        \pi \star Q = P_{\pi'}Q P_{\pi'}^\top.
    \end{equation*}
    Equivalently, the entries of $ \pi \star Q $ satisfy $(\pi \star Q)_{x^\alpha, x^\beta} = Q_{\pi \cdot x^\alpha,\, \pi \cdot x^\beta}$. Moreover, for any $G$ subgroup of $S_n$, we say that $Q$ is \emph{$G$-invariant} if $\pi \star Q = Q$ for every $\pi \in G$.

\label{lemma:action-on-PSD-matrix}
    Let $d\in O(1)$ be an integer and let $S_n$ be the symmetric group of $n$ elements.
    \begin{enumerate}
        \item For $Q$ positive semidefinite matrix and for every $\pi\in S_n$, $Q'=\pi \star Q$ is positive semidefinite. 
        \item For $p\in \mathbb R[x_1,\dots,x_n]_{2d}$ polynomial of degree at most $2d$, and $Q\in \MS^{\omega_n^d}$ such that $p=\langle Q,\x_d\x_d^\top \rangle$, the action of $\pi\in S_n$ on $p$ is given by $\pi \cdot p = \langle \pi \star Q, \x_d \x_d^\top\rangle$.
    \end{enumerate}

\label{prop:invariant-sos}
    Let $p\in \mathbb{R}[x_1, \dots, x_n]_{2d}$ be a polynomial and let $G$ be a finite group. Assume that $p$ is $G$-invariant. Then, $p=\langle \overline{Q}, \x_d \x_d^\top\rangle$ for some $G$-invariant matrix $\overline{Q}$. 

    In addition, if $p$ is a sum of squares, then  $\overline{Q}$ can be taken positive semidefinite.

Let $G$ be a finite group acting on the polynomial ring $\mathbb R[x_1,\dots,x_n]$. The \emph{Reynolds operator} $R_G \colon \mathbb R[x_1,\dots,x_n] \to \mathbb R[x_1,\dots,x_n]$ is defined as
\begin{equation*}
    R_G(f) = \frac{1}{|G|} \sum_{g\in G} g\cdot f.
\end{equation*}

\label{th:invariant-system-averaged-sos}
    Let $G$ be a finite group and let $d$ be a fixed integer. Assume that the polynomials  $f,p_1, \dots, p_m$ and the set $\mathcal R=\{r_1, \dots, r_{\ell}\}$ are $G$-invariant. If there exists an $\sos$ proof of degree $2d$, $f=\sigma + \sum_{i=1}^m h_ip_i + \sum_{j=1}^{\ell} q_jr_j$, then there exists an $\sos$ proof of degree $2d$ of the form
    \begin{equation*}
        f=\tilde{\sigma} + \sum_{i=1}^m\tilde{h_i}p_i + \sum_{j=1}^{\ell} q_j'r_j,
    \end{equation*}    
    where the sum-of-squares $\tilde{\sigma}$ and each $\tilde{h}_i\in \mathbb R[x_1,\dots,x_n]$ are $G$-invariant.

\label{th:orbits_pairs_indices_under_symmetric_action}
    Let $k=O(1)$ be a fixed positive integer. Let $n_1, n_2, \ldots, n_k \in \mathbb{N}$ be such that $\sum_{i=1}^k n_i = n$. Consider the group $G = S_{n_1} \times S_{n_2} \times \ldots \times S_{n_k}$, which acts on the indices $1,2,\ldots,n$ by permuting the indices within each block $1, \ldots, n_1, n_1+1, \ldots, n_1 + n_2, \ldots, n$. Consider the sets $W = \{x \in \mathbb{N}^n\ | \ \sum_{i=1}^n x_i \leq d \}$ and $Y = \{(x,y) \in \mathbb{N}^n \times \mathbb{N}^n \ | \ \sum_{i=1}^n x_i \leq d, \sum_{i=1}^n y_i \leq d \}$.
    Let $x\in W$ and  $(x,y) \in Y$, let $g \in G$ act on $x$ as in \cref{def:action-on-poly} and define the action of $g$ on $(x,y)$ as
    \begin{equation*}
        g \cdot (x,y) = (g \cdot x, g \cdot y) = \left( (x_{g(1)}, x_{g(2)}, \ldots, x_{g(n)}), (y_{g(1)}, y_{g(2)}, \ldots, y_{g(n)} \right).
    \end{equation*}
    Then, for a fixed nonnegative integer $d$, the number of orbits of the action of $G$ on $W$ and $Y$ is bounded by a constant that depends only on $d$. Specifically, for $n \geq 2d$, the number of orbits is constant with respect to $n$.

\label{th:invariant-matrix-finite-decomposition}
    Let $k,d \in O(1)$ be fixed positive integers. Let $G = S_{n_1} \times S_{n_2} \times \ldots \times S_{n_k}$ be a group of block permutations of indices $1, \ldots, n$.
     \begin{enumerate}
         \item If $Q\in \MS^{\omega_n^d}$ is a symmetric $G$-invariant matrix, then $Q$ can be written as a linear combination $Q = \sum_{i=1}^\ell c_i Q_i$,
        where $c_i \in \mathbb{R}$, each $Q_i$ is a symmetric matrix whose entries have value only $0$ or $1$, and $\ell$ is bounded above and independent from $n$.
        \item  If $p\in \mathbb{R}[x_1, \dots, x_n]_{d}$ is a polynomial that is invariant under the action fo $G$, then $p$ can be written as $p=\sum_{i=1}^{\ell}c_ip_i$,
         where $c_i \in \mathbb{R}$, each $p_i$ is a polynomial of degree at most $d$, whose coefficients are either $0$ or $1$, and $\ell$  is bounded above and independent from $n$.
     \end{enumerate}

\label{lemma-corbi}
   Let $r\in \mathbb{R}[x]_d$, then 
   \begin{equation*}
       \|r\|_{\mathbb{R}[x]} \leq 3^{d+1}\max_{x\in [-1,1]^n}|r(x)|.
   \end{equation*}

\label{th:porkolab-invariant-SDP+LP} 
    Let $k_1,k_2,k_3= O(1)$ be fixed positive integers. Consider a matrix $A \in \mathbb{R}^{k_1\times (k_2+k_3)}$, symmetric matrices $Q_1, \dots , Q_{k_2}\in \MS^N$, and scalar $c\in \mathbb{R}^{k_1}$. Suppose the system
    \begin{align}\label{eq:lemma-SDP+LP-formulation}
        \sum_{i=1}^{k_2} a_iQ_i \succeq 0, \qquad
        A\Big(\begin{array}{c}
             a \\
             b
        \end{array}\Big) =c, \qquad
        a\in \mathbb{R}^{k_2},\ b\in \mathbb{R}^{k_3}
    \end{align}
    has a feasible solution. Then, it has a solution $\|(a,b) \| \leq 2^{\poly(\ell)}$, where $\ell$ is the total bit size of $Q_i, A$ and $c$.

\label{th:Porkolab_SDP_complexity}
    Any feasible system of the form
    \begin{align}\label{eq:Porkolab-thm}
        Q= Q_0 +\lambda_1Q_1+\dots +\lambda_{\ell} Q_{\ell} \succeq 0
    \end{align}
    has a solution $\lambda\in \mathbb R^{\ell}$ such that $\log \Vert \lambda \Vert = c\cdot n^{O(\min(\ell,n^2))}$, where $c \in \mathbb{N}$ is the maximum bit-length of the input coefficients and $\Vert \lambda \Vert$ is the Euclidean norm in $\mathbb{R}^{\ell}$.

\label{def:dinur's-template}
\quad
\begin{enumerate}
    \item Gap amplification, in which the \textit{promise gap} of a constraint satisfaction problem family is amplified at the cost of blowing up its alphabet size,
    \item Alphabet reduction, in which the locality of the constraint satisfaction problem family is reduced back to a constant, and the gap is shown not to shrink too much in the process.
\end{enumerate}

[Gap amplification] \label{thm:tp_amplification_intro} Let $H$ be a $k$--local Hamiltonian with $m$ terms, satisfying the conditions in \cref{definition:layered}. Then, its \emph{derandomised $2t$--fold tensor product amplification} $H^{(2t)}$ (formally defined in \cref{def:amplified_ham}) satisfies:

\begin{enumerate}
    \item[1.] $H^{(2t)}$ is $(2t\cdot k)$--local and has $d^{2t} \cdot m$ terms, where $d$ is the degree of some fixed expander graph family.
    \item[2.] \textbf{Completeness.} The lowest eigenvalue of $H^{(2t)}$ is bounded above by 
    \begin{equation}
        \lambda_{\min}(H^{(2t)}) \leq 2 t \times \lambda_{\min}(H)
    \end{equation}
    \item[3.] \textbf{Soundness.} The eigenvalue of $H^{(2t)}$ is bounded below by
    \begin{equation}
        \lambda_{\min}(H^{(2t)})\geq  \min\bigg[\Theta\bigg(\frac{\log t}{t}\bigg), \Theta\bigg(\sqrt{\frac{t}{\log t}} \times \lambda_{\min}(H)\bigg)\bigg],
    \end{equation}
\end{enumerate}
\noindent where the $\Theta$ notation obscures constants dependent on the choice of expander graph family and the original Hamiltonian $H$.

    [Layered Hamiltonians]\label{definition:layered} $H$ is said to be a \emph{layered Hamiltonian} if it admits a decomposition

    \begin{equation} \label{equation:H_definition}
    H = \sum_{\chi\in [g]} w_\chi \cdot H_\chi\;, \quad \text{ where each layer }\quad H_\chi = \E_{i\in [m_\chi]} \Pi^\chi_i \end{equation}
    \noindent  is the expectation over $m_\chi$ commuting projections, and the weights $\{w_\chi\}_{\chi\in [g]}$ are positive and $\sum_\chi w_\chi=1$. To quantify imbalance between the layers, we introduce the parameter 
\begin{equation}
    \omega_{\min} \equiv (\min_\chi w_\chi)^{-1}.
    \label{eq:min-weight-def}
\end{equation}

[Derandomised Tensor Product Amplification]\label{def:amplified_ham} Let $H$ be layered as in \cref{definition:layered}. We define the $t$-fold amplification $H^{(t)}$ of $H$ with respect to $\{\mathcal{F}_\chi\}_{\chi\in [g]}$ as
\begin{equation}
        H^{(t)} = \sum_{\chi \in [g]} w_\chi\cdot H^{(t)}_\chi,\quad  \text{where} \quad H^{(t)}_\chi\equiv \E_{f \in \cF_\chi}\bigg(\mathbb{I} - \bigotimes_{j\in [t]} \big(\mathbb{I}-\Pi^\chi_{f(j)}\big)\bigg).
    \end{equation}

[Second Moment Method]
For any non-negative random variable $X\geq 0$, 
\begin{equation}
    \mathbb{P}[X>0]\geq \frac{\mathbb{E}[X]^2}{\mathbb{E}[X^2]}
\end{equation}

[Markov's Inequality]\label{fact:markovs} For any non-negative random variable $X\geq 0$ and real parameter $a>1$,
\begin{equation}
    \mathbb{P}[X>a\cdot \mathbb{E}[X]]\leq \frac{1}{a}
\end{equation}

[First Moment Method]\label{fact:fmm} For any non-negative random variable $X\geq 0$,
\begin{equation}
    \mathbb{P}[X>0]\leq \mathbb{E}[X]
\end{equation}

[Second Moment Method]\label{fact:smm}
For any non-negative random variable $X\geq 0$, 
\begin{equation}
    \mathbb{P}[X>0]\geq \frac{\mathbb{E}[X]^2}{\mathbb{E}[X^2]}
\end{equation}

[\cite{tomamichel2017largely}, Lemma 6]\label{fact:tomamichel} Let $Z_1, \cdots Z_{n+k}$ be a collection of binary random variables. Let $S\subset [n+k], |S|=k$ be a uniformly random subset. Then, 

\begin{equation}
    \prs{}{\sum_{i\in S} Z_i \leq k\cdot \delta \text{ and } \sum_{i\in \Bar{S}}Z_i\geq n(\delta+\nu)} \leq \exp\bigg[-\frac{2\nu^2 nk^2}{(n+k)(k+1)}\bigg]
\end{equation}

[Spectral Expansion]\label{definition:spectral}
Let $G = (V, E)$ be an undirected $d$-regular graph, and let $A$ be its adjacency matrix. Let $d=\lambda_1\geq \lambda_2\geq \cdots \geq \lambda_n$ be its eigenvalues. Then $G$ is said to be a $\lambda$-spectral-expander if 
\begin{equation}
    \max_{i\neq 1} |\lambda_i| \leq  \lambda.
\end{equation}

\label{lemma:expander-quadratic}
    Let $P=A/d$ be the transition matrix of a $d$-regular $(d\cdot \mu)$-spectral-expander graph on $m$ vertices. Then, for all vectors $a, b\in [0, 1]^{\times m}$ and integer $t$:
    \begin{equation}
        a^T P^t b \leq \frac{1}{m} \|a\|_1\cdot  \|b\|_1 +\mu^{t} \big(\|a\|_1+  \|b\|_1\big)
    \end{equation}

[Violation Number Measurement] Fix a color $\chi\in [g]$. Given a state $\rho$ on $2t\cdot n$ qubits and a function $f:[2t]\rightarrow [m_\chi]$:
\begin{enumerate}
  \item Divide the $2t\cdot n$ qubits into $2t$ blocks of $n$ qubits, and measure each block as follows: On the $j$th block, perform the measurement $\{\mathbb{I}-\Pi^\chi_{f(j)}, \Pi^\chi_{f(j)}\}$ with outcome $b_j\in \{0, 1\}$. 
    \item Output $\sum_j b_j$.
\end{enumerate}
\label{def:colored-violation-number-meas}

[Subset Violation Number] Fix a color $\chi\in [g]$. Given a state $\rho$ on $2t\cdot n$ qubits, a function $f:[2t]\rightarrow [m_\chi]$ and a subset $S \subseteq [2t]$:
\begin{enumerate}
    \item Divide the $2t\cdot n$ qubits into $2t$ blocks of $n$ qubits, and for $j\in S$ measure $\{\mathbb{I}-\Pi^\chi_{f(j)}, \Pi^\chi_{f(j)}\}$ on the $j$th block with outcome $b_j\in \{0, 1\}$. 
    \item Output $\sum_{j\in S} b_j$.
\end{enumerate}
\label{def:colored-subset-violation-number-meas}

\label{lemma:Nmin}
   Consider $H_\chi^{(2t)}$ and $N_f^\chi$ as defined above. Then, for any state $\rho$:
   \begin{equation}
       \tr{H^{(2t)}_\chi \rho} = \E_{f \in \cF_\chi} \prs{\rho}{N^{\chi}_f > 0}.
   \end{equation}

\label{lemma:tilde_greater}
    Consider $H_\chi^{(2t)}$, $N_f^\chi$ and $N_{f, S}^\chi$ as defined above. Then, for any function $f$, state $\rho$, and subset $S$,
    \begin{equation}
        \tr{N^{\chi}_{f}\rho} \geq \tr{N^{\chi}_{f,S}\rho},\quad  \prs{\rho}{N^{\chi}_{f} > 0} \geq \prs{\rho}{N^{\chi}_{f,S} > 0}
    \end{equation}

 \label{lem:upperbound}
Fix a layered Hamiltonian $H$ as in \cref{definition:layered}, and the collection of function families $\{\mathcal{F}_\chi\}$ from \cref{definition:paths}. For any $t \in \N$, write $H^{(2t)} = \sum_\chi w_\chi H_\chi^{(2t)}$ to denote the derandomized $2t$-fold tensor product amplification of $H$ (\cref{def:amplified_ham}). The lowest eigenvalue of $H^{(2t)}$ is bounded from above by
\begin{align*}
\lambda_{\min}(H^{(2t)}) \leq 2 t \cdot \lambda_{\min}(H) \,.
\end{align*}

    [The Auxiliary Energy Measurement]\label{definition:aux_meas} Given any state $\rho$ on $n\cdot 2t$ qubits, a subset $S \subseteq [2t]$, and a threshold parameter $\alpha \in \R$:
    \begin{enumerate}
\item For $j\in[2t]$ define $\Pi^{\geq \alpha}_{\reg j}$ as the projection onto the direct sum of all eigenspaces of $H_{\reg j}$ with associated eigenvalue larger than $\alpha$.
\item For all $j \in \overline S$, measure $\{\mathbb{I} - \Pi^{\geq \alpha}_{\reg j}, \Pi^{\geq \alpha}_{\reg j}\}$ and call the outcome $c_j \in \bits$.
\item Output $c = (c_j)_{j \in \overline S}$.
\end{enumerate}

\label{lemma:de-finetti}
For each $j\in [2t]$, let the binary random variable $C_j$ denote the outcome of the measurement $\{\1 - \Pi^{\geq \alpha}_{\reg j}, \Pi^{\geq \alpha}_{\reg j}\}$ on any $2t\times n$ qubit state $\rho$. Then, for every $r\in [t]$,
    \begin{equation}
        \mathbb{E}_{|S|=t}\Pr_\rho \Big[\sum_{j \in S} C_j < 2r \; \text{ and }\; \sum_{i \in \overline S} C_i \geq 4r\Big]   \leq e^{-\frac{2 r^2}{t}}
    \end{equation}

 \label{theorem:lowerbound_simpler}
Fix a layered Hamiltonian $H$ as in \cref{definition:layered}, and the collection of function families $\{\mathcal{F}_\chi\}$ from \cref{definition:paths}. For any $t \in \N$, write $H^{(2t)} = \sum_\chi w_\chi H_\chi^{(2t)}$ to denote the derandomized $2t$-fold tensor product amplification of $H$ (\cref{def:amplified_ham}). The lowest eigenvalue of $H^{(2t)}$ is bounded from below by
\begin{align*}
\lambda_{\min}(H^{(2t)}) \geq \min\Big\{ \Theta\Big(\frac{\log t}{t}\Big) \:\:, \:\: \Theta\Big(\lambda_{\min}(H) \cdot \frac{t^{1/2}}{(\log t)^{1/2}}\Big) \Big\},
\end{align*}
where the big-O hides only constants that do not depend on $t$.

 \label{lem:lowerbound}
Let $H$ be a normalised sum of projectors on $n$ qubits as in \cref{equation:H_definition}, and fix any choice of parameters $t\in \mathbb{N}$, $r\in [t]$, $\alpha>0$, and the collection of expander walks $\{\mathcal{F}_\chi\}_{\chi\in [g]}$. Let $\rho$ be any ground state of $H^{(2t)}$, and define the probability of a high energy outcome:
\begin{align}
\Delta \coloneqq \E_{S\subseteq[2t], |S|=t} \sum_{c\in U_{\overline S}} \prs{\rho}{c}
\end{align}
\noindent with $U_{\bar{S}}$ as in \cref{eqn:us_def}. Let $C_\mu$ be the constant in \Cref{lemma:second_moment_Xs}, and let $\omega_{\min}$ be as in \Cref{eq:min-weight-def}.

Then, the lowest eigenvalue of the derandomised $t$-fold tensor product amplification $H^{(2t)}$ is bounded from below by
\begin{align}
\lambda_{\min}(H^{(2t)}) \geq \max\Big\{  \frac{2 \alpha r}{t}\Big(\Delta - e^{-2 r^2/t}\Big) , \;
& \frac{t (1-\Delta)}{1 + C_\mu \: + \: \omega_{\min} \cdot (1 + 8r + \alpha t + 2t \cdot e^{-8r^2/t})} \cdot \lambda_{\min}(H) \Big\}
\label{eqn:lower-bound}
\end{align}

\label{lem:high_energy_likely}
For any choice of parameters $\alpha > 0$ and $r \in [t]$ and any state $\rho$ on $2t\cdot n$ qubits it holds that
\begin{align*}
\sum_{\chi\in [g]}w_\chi\cdot \bigg(\E_{S\subseteq[2t], |S|=t} \E_{f \in \cF_\chi} \sum_{c\in U_{\overline S}} \prs{\rho}{c} \ \prs{\rho_{|S,\alpha,c}}{N^{\chi}_{f,S} >0} \, \bigg)\geq\,  \frac{2 \alpha r}{t}\Big(\E_{S} \sum_{c\in U_{\overline S}} \prs{\rho}{c}-e^{-\frac{2 r^2}{t}}\Big)\,.
\end{align*}
Here, $U_{\overline S}$ is defined as in \cref{eqn:us_def} and depends implicitly on $\alpha$ and $r$.

\label{lem:high_energy_unlikely}
Let $\rho$ be a ground state of the amplified Hamiltonian $H^{(2t)}$. Let $C_\mu$ be the constant in \Cref{lemma:second_moment_Xs}, and let $\omega_{\min}$ be as in \Cref{eq:min-weight-def}.
For any choice of parameters $\alpha > 0$ and $r \in [t]$ it holds that \emph{either}
\begin{align}
    \tr{H^{(2t)} \rho} \geq t \lambda_{\min}(H) \cdot \E_{|S|=t} \prs{\rho}{\overline{U}_{\overline{S}}}
\label{eq:lowenergy_lowerbound_trivial}
\end{align}
\emph{or}
\begin{align}
\sum_\chi w_\chi \cdot \E_{|S|=t} \E_{f \in \cF_\chi} \sum_{c\in \overline U_{\overline S}} \prs{\rho}{c} \ \prs{\rho_{|S,\alpha,c}}{ N^{\chi}_{f,S} >0} \,\geq\, \frac{t\cdot  \E_{|S| = t} \prs{\rho}{\overline{U}_{\overline{S}}}}{1 + C_\mu \: + \: \omega_{\min} \cdot (1 + 8r + \alpha t + 2t \cdot e^{-8r^2/t})} \times \lambda_{\min}(H) \,. \label{eqn:lowenergy_lowerbound}
\end{align}
Here, $U_{\overline S}$ is defined as in \cref{eqn:us_def} and depends implicitly on $\alpha$ and $r$, and $\prs{\rho}{\overline U_{\overline S}} = \sum_{c \in \overline U_{\overline S}}\prs{\rho}{c}$.

    [Weighted Violation Number]\label{definition:weighted_violation} Let $\sigma$ be an arbitrary state on $2t$ $n$-qubit registers. Consider the following random variable $X_{S}$, defined by measuring $\sigma$ as follows:
\begin{enumerate}
    \item Pick a color $\chi$ by flipping a $g$-sided die with weights $(w_1, \cdots, w_g)$.
    \item Pick a function $f\in\mathcal{F}_{\chi}$.
    \item Measure the observable $N_{f, S}^{\chi}$ (\cref{def:colored-subset-violation-number-meas}).
\end{enumerate}

\label{lemma:expectation_XS}
    For any state $\sigma$ on $2t$ $n$-qubit registers, the expectation of $X_S$ satisfies 
    \begin{equation}
       \mathbb{E}[X_S] =\sum_{j\in S}\Tr[H_{\reg j}\sigma]
    \end{equation}

[The second moment of $X_S$]\label{lemma:second_moment_Xs} There exists a constant $C_\mu\leq 2/(1-\mu)$ dependent just on the collection of expander graphs, such that for every state $\sigma$ on $2t$ $n$-qubit registers, 

\begin{align}
    \E[X_S^2]\leq (1+C_\mu)\sum_{j\in S}\Tr[H_{\reg j}\sigma] + \omega_{\min}\cdot  \sum_{i\neq j\in S}\Tr[H_{\reg i}\otimes H_{\reg j}\sigma]
    \label{eq:second-moment-Xs}
\end{align}

 \label{lem:2ndmoment}
Suppose that $\rho$ is a state such that for all $i$, 
\begin{align}
\tr{H_{\reg i} \rho} \leq \E_{|S|=t} \sum_{j \in S} \sum_{c\in \overline U_{\overline S}} \prs{\rho}{c} \ \tr{H_{\reg j} \rho_{|S,\alpha,c}} \,. \label{eqn:trivial_single_copy_bound}
\end{align}
Then for any choice of parameters $\alpha > 0$ and $r \in [t]$ it holds that
\begin{align*}
\E_{|S|=t} \sum_{c\in \overline U_{\overline S}} \prs{\rho}{c} \sum_{\substack{i,j \in S \\ i \neq j}} \tr{H_{\reg i} \cdot H_{\reg j} \rho_{|S, \alpha, c} }
\leq (8r + \alpha t + 2t \cdot e^{-\frac{8r^2}{t}}) \cdot \E_{|S|=t} \sum_{j \in S} \sum_{c\in \overline U_{\overline S}} \prs{\rho}{c} \tr{H_{\reg j} \rho_{|S, \alpha, c} } \,.
\end{align*}
Here, $U_{\overline S}$ is defined as in \cref{eqn:us_def} and depends implicitly on $\alpha$ and $r$.

\label{def:random-variable-X}
\quad
\begin{enumerate}
\item Sample $S \subset [2t]$ of size $|S| = t$.
\item Perform the auxiliary energy measurement on state $\rho$ on registers in $\overline S$, resulting in $c\in \bits^{\overline S}$.
\item If $c \in U_{\overline S}$, output 0. Else, output the random variable $X_S$, defined in \cref{definition:weighted_violation}.
\end{enumerate}

There exists a constant $C_\mu\leq 2/(1-\mu)$ dependent just on the collection of expander graphs, such that for every state $\sigma$ on $2t$ $n$-qubit registers, 
   \begin{align}
       \E[X_S^2]\leq (1+C_\mu)\sum_{j\in S}\Tr[H_{\reg j}\sigma] + \omega_{\min}\cdot  \sum_{i\neq j\in S}\Tr[H_{\reg i}\otimes H_{\reg j}\sigma]
   \end{align}

Suppose that $\rho$ is a state such that for all $i$, 
\begin{align}
\tr{H_{\reg i} \rho} \leq \E_{|S|=t} \sum_{j \in S} \sum_{c\in \overline U_{\overline S}} \prs{\rho}{c} \ \tr{H_{\reg j} \rho_{|S,\alpha,c}} \,. \label{eqn:trivial_single_copy_bound-2}
\end{align}
Then for any choice of parameters $\alpha > 0$ and $r \in [t]$ it holds that
\begin{align*}
\E_{|S|=t} \sum_{c\in \overline U_{\overline S}} \prs{\rho}{c} \sum_{\substack{i,j \in S \\ i \neq j}} \tr{H_{\reg i} \cdot H_{\reg j} \rho_{|S, \alpha, c} }
\leq (8r + \alpha t + 2t \cdot e^{-\frac{8r^2}{t}}) \cdot \E_{|S|=t} \sum_{j \in S} \sum_{c\in \overline U_{\overline S}} \prs{\rho}{c} \tr{H_{\reg j} \rho_{|S, \alpha, c} } \,.
\end{align*}
Here, $U_{\overline S}$ is defined as in \cref{eqn:us_def} and depends implicitly on $\alpha$ and $r$.

 \label{cor:lowerbound_simpler}
Suppose that $10^5 \leq t$.
Then 
\begin{align*}
\lambda_{\min}(H^{(2t)}) \geq \min\Big\{ \frac{1}{3}\frac{\log t}{t} \:\:, \quad \lambda_{\min}(H) \times \underbrace{\frac{t^{1/2}}{(\log t)^{1/2}}}_{\text{amplification factor}} \times \underbrace{\frac{1}{20} \big[\max\{1 + C_\mu, \, \omega_{\min}\}\big]^{-1}}_{\text{constant not depending on $t$}} \Big\}
\end{align*}

\label{assumption:balanced_H}
    Let $\{H_n\}_{n\in \mathbb{N}}$ be a family of $k$-$\mathsf{LH}$, where each $H_n$ is an expectation over $\poly(n)$ many $k$-local projections on $n$ qubits. Further, assume 
    \begin{enumerate}
        \item \textbf{Soundness-Completeness Gap.} There exists a negligible\footnote{We use the notation $\mathsf{negl}(n)$ (negligible) to denote $O(n^{-i})$ for every $i$.}  function $\mu(n)$ and a positive polynomial $p(n)$ such that 
        \begin{equation}
            \text{Either } \lambda_{min}(H_n)\leq \mu(n) = a, \text{ or } \lambda_{min}(H_n)\geq p(n) = b
        \end{equation}

        \item \textbf{Equitable Coloring.} The projections in $H_n$ can be partitioned into $g = O(1)$ commuting layers, wherein the weights in each layer is roughly balanced. In particular, there exists an explicit constant
        \begin{equation}
          (\cref{eq:min-weight-def})\text{ }\omega\equiv \omega_{min} = O(1)
        \end{equation}
    \end{enumerate}

[Iterated Amplification] \label{theorem:iterated_amplification}
Assume  $\{H_n\}_{n\in \mathbb{N}}$ be a family of $k$-$\mathsf{LH}[\mu(n), p(n); \omega]$ satisfying \cref{assumption:balanced_H}. Then, there exists an explicit constant $c(\omega)$ and a deterministic construction of a family of amplified Hamiltonians $\{\tilde{H}_n\}_n$ with the following parameters:
\begin{enumerate}
    \item \textbf{Instance Size.} Each $\tilde{H}_n$ is an expectation of $\poly(n)$ projections over $\poly(n)$ many qubits. The locality of each amplified projection is $k\cdot p(n)^{O(1)}$.

    \item \textbf{Amplified Promise Gap.} If $\lambda_{min}(H_n)\geq p(n)$ then $\lambda_{min}(\tilde{H}_n)\geq c(\omega)$; if $\lambda_{min}(H_n)\leq \mu(n)$ then $\lambda_{min}(\tilde{H}_n)\leq \mu(n)\cdot p(n)^{20}$.
\end{enumerate}

[Hamiltonian Simulation of Tensor-Product Hamiltonians]\label{lemma:ham_sim} Fix $T>0$, and let $\{\Pi_i\}_{i\in [a]}$ be a collection of $k$-local projections. Then, there exists a quantum circuit of $(k+1)$-local gates of depth $O(\log m)$ and size $O(m)$ which performs the Hamiltonian simulation $e^{i\Pi T}$ of the projection 
\begin{equation}
    \Pi = \mathbb{I} - \bigotimes_i^m (\mathbb{I}-\Pi_i).
\end{equation}

[Degree Reduction for FK Hamiltonians, \cite{Anshu2023CircuittoHamiltonianFT}]\label{claim:degree-reduction} Any $\mathsf{QMA}$ protocol involving an $n$-qubit verifier circuit $V$ with $T=\poly(n)$ two-qubit gates can be mapped into a $5-\mathsf{LH}[a, b]$ $H$ on $\poly(n)$ qubits with $a = 2^{-\poly(n)}$ and $b=a+1/\poly(n)$. Furthermore, 
\begin{enumerate}
    \item each qubit is involved in at most 7 terms in the Hamiltonian.
    \item each Hamiltonian term is an unweighted projection.
\end{enumerate}

[Detectability Lemma, e.g. {\cite[Lemma 2]{AAV16}}]\label{lemma:DL} Let $H = \mathbb{E}_{i\in[m]}\Pi_i$, where each $\Pi_i$ is a projection that commutes with all except at most $d$ of the other projections $\Pi_j$. Then, if $\lambda_{\mathsf{min}}(H)\geq \gamma$, we have for every state $\ket{\psi}$:
\begin{equation}
    \big\|\prod_{i\in [m]} \big(\mathbb{I}-\Pi_{i}\big)\ket{\psi}\big\|^2 \leq (1+m\gamma/d^2)^{-1}\;.
\end{equation}

[The Converse to the DL, e.g. {\cite[Lemma 4]{AAV16}}]\label{lemma:DL-conv} Let $A_1, \cdots A_g$ be projections. Then, if $\ket{\psi}$ is a state satisfying for some $\epsilon\in [0, 1]$,
\begin{equation}
    \big\|\prod_{\chi\in [g]}  A_i \ket{\psi}\big\|^2    \leq 1-\epsilon \;,
\end{equation}
then there exists a $\chi \in [g]$ such that $ \|A_\chi\ket{\psi}\|^2\leq 1-\frac{\epsilon}{4g}$.

[Amplification from the DL] \label{theorem:amp-from-dl} Assume that the minimum eigenvalue of $H$ is $\lambda_{\mathsf{min}}(H)\geq \gamma$. Then, the minimum eigenvalue of the amplified Hamiltonian $H^{(t)}$ from \autoref{eq:amp-H-DL} satisfies
\begin{equation}
    \lambda_{\mathsf{min}}(H^{(t)}) \geq \min\bigg( \Theta\big(g^{-2}\big), \quad \Omega\bigg( \frac{t\cdot m\cdot \gamma}{g^4}\bigg)\bigg)\;.
\end{equation}

\label{thm:noepsilon}
   For $\varepsilon>0$,
   $QC^{nt, 1-r^{-n}}(x)\lesssim QC^{t,\varepsilon}(x)$
   for some $r=r(\varepsilon) > 0$ and large enough $n\in\mathbb{N}$. (Proof in Appendix)

\label{lem:easytoeasyhardtohard}
