\label{thm:laplacian-and-prob-transition}
Let $M = (V,P)$ be an irreducible, reversible Markov process with stationary distribution $\pi$. Let $G$ be the corresponding graph with resistances $r$. Let $L$ be its Laplacian. Then,
\[L = \diag(\pi)(I - P) \qquad \Leftrightarrow \qquad P = I - \diag(\pi)^{-1}L.\]

\label{lem:fast-forwarding}
Let $M = (V,P)$ be an irreducible, reversible Markov process, with stationary distribution $\pi$. Let $\xi \in \R_V$ such that $\sum_{v \in V} \xi_v = 0$. We write $D = \diag(\pi)$, and $\widetilde{\xi} = D^{-1/2}\xi$. Then, we have the following two consequences:
\begin{enumerate}[nosep]
    \item For integer $t \geq 1$, $R_{\mathrm{eff}}(P;\xi) \leq t \cdot R_{\mathrm{eff}}(P^t;\xi)$.
    \item If the spectral gap of $P$ is $\delta$, we have $R_{\mathrm{eff}}(P;\xi) \leq \|\widetilde{\xi}\|_2^2/\delta$.
\end{enumerate}

\label{thm:transducers}
Let $R = \{(\ket{\sigma_x^{\pm}}, \pm\ket{\sigma_x^{\pm}}, O_x)\}_{x \in \D}$ be a state-reflection problem, with feasible solution $\{\ket{w_x^{\pm}}\}_{x \in \D}$. Let, let $\A \subseteq \V \oplus \H$ be a subspace such that
\[\Span\left\{\begin{bmatrix}
    \ket{\sigma_x^+} \\
    \ket{w_x^+}
\end{bmatrix}\right\}_{x \in \D} \subseteq \A \subseteq \Span\left\{\begin{bmatrix}
\ket{\sigma_x^-} \\
\ket{w_x^-}
\end{bmatrix}\right\}_{x \in \D}^{\perp}.\]
Then, the unitary $U = 2\Pi_A - I$ is such that $U(I \oplus O_x)$ implements $\ket{\sigma_x^{\pm}} \overset{U(I \oplus O_x)}{\rightsquigarrow} \pm\ket{\sigma_x^{\pm}}$.

\label{lem:rescale-state-reflection-problem}
Let $R = \{(\ket{\sigma_x^{\pm}}, \pm\ket{\sigma_x^{\pm}}, O_x)\}_{x \in \D}$ be state-reflection problem. Let $D \in \mathcal{L}(\mathcal{V})$ be an invertible operator, $\alpha_{\pm} \in \C$, and let $R' := \{(\alpha_+D\ket{\sigma_x^+}, \alpha_-(D^{-1})^{\dagger}\ket{\sigma_x^{\pm}}, O_x)\}_{x \in \D}$. Then, any feasible solution $w := \{\ket{w_x^{\pm}}\}_{x \in \D}$ for a state-reflection problem $R$ can be turned into a feasible solution $w' := \{\alpha_+\ket{w_x^+},\alpha_-\ket{w_x^-}\}_{x \in \D}$ for $R'$, where $x^{-\dagger} := (x^{-1})^{\dagger}$. Consequently,
\[\ADV(R) \leq \sqrt{\max_{x \in \D} \mathsf{R}_x^+(w) \cdot \max_{x \in \D} \mathsf{R}_x^-(w)}.\]

\label{thm:optimal-weight-assignment}
Let $T = (V,E)$ be a decision tree with root node $r \in V$. Its optimal weighting scheme is computed by setting all the weight of all the leaf nodes to $0$, and then for every internal node $v \in V$ with children $C_v \subseteq V$, recursively computing the semi-definite program
\begin{align*}
    w_v := \min\quad & \max_{c \in C_v} (w_c + X[c,c] + Y[c,c]) \\
    \text{s.t.}\quad & X[c_1,c_2] - Y[c_1,c_2] = 1, & \text{if } c_1,c_2 \in C_v, c_1 \neq c_2, \\
    & 0 \preceq X,Y \in \R^{C_v \times C_v}.
\end{align*}

\label{thm:divide-and-conquer}
Let $f^{\mathrm{aux}} : \Sigma^n \to \Lambda$ be an auxiliary function, and for all $s \in \Lambda$ and $i \in A$ with $A$ a finite set, let $f_i^{(s)} : \Sigma^n \to \{0,1\}$ and let $g^{(s)} : \{0,1\}^{\Lambda \times A} \to \{0,1\}$. Then, for any $x \in \Sigma^n$, we can compute $h^{f^{\mathrm{aux}}(x)}(x) := g^{(f^{\mathrm{aux}}(x))}((f_i^{(f^{\mathrm{aux}}(x))}(x))_{i \in A})$, with a feasible solution that satisfies
\[\mathsf{R}_x^+(w) \leq (\mathsf{R}^{\mathrm{aux}})_x^+ + (\mathsf{R}^{f^{\mathrm{aux}}(x)})_x^+, \qquad \text{and} \qquad \mathsf{R}_x^-(w) = (\mathsf{R}^{\mathrm{aux}})_x^- + (\mathsf{R}^{f^{\mathrm{aux}}(x)})_x^-.\]

\label{thm:quantum-walk-detection}
Let $(G, r, x \mapsto M_x, (v,x) \mapsto D_{v,x}, \{S_v\}_{v \in V}, \{U_e\}_{e \in E}, \{C_{v,D}\}_{v \in V, D \in \mathcal{S}})$ be an instance of quantum walk search. Let $\sigma,\tau \in \Delta_V$. We write $\D^+ = \{x \in \D : M_x \neq \varnothing\}$, and $\D^- = \D \setminus \D^+$. For all $x \in \D^+$, let $\mu_x \in \Delta_{\supp(\sigma)}$ and $\nu_x \in \Delta_{M_x \cap \supp(\tau)}$. Then, there is a span program $\mathcal{P}$, that solves the detection version of quantum walk search, with witness sizes
\begin{align*}
    w_+(x,\mathcal{P}) &\leq \sum_{v \in \supp(\sigma)} \frac{(\mu_x)_v^2}{\sigma_v}(\mathsf{S}_v)_x^+ + R_{\mathrm{eff}}(G, r \circ (\mathsf{U}_{\cdot})_x^+; \mu_x - \nu_x) + \sum_{v \in \supp(\tau) \cap M_x} \frac{(\nu_x)_v^2}{\tau_v}(\mathsf{C}_{v,D_{v,x}})_x^+, & \forall x \in \D^+, \\
    w_-(x,\mathcal{P}) &\leq \sum_{v \in \supp(\sigma)} \sigma_v(\mathsf{S}_v)_x^- + \sum_{e \in E} \frac{(\mathsf{U}_e)_x^-}{r_e} + \sum_{v \in \supp(\tau)} \tau_v(\mathsf{C}_{v,D_{v,x}})_x^-, & \forall x \in \D^-.
\end{align*}

\label{thm:quantum-walk-finding-unique}
Let $(G, r, x \mapsto M_x, (v,x) \mapsto D_{v,x}, \{S_v\}_{v \in V}, \{U_e\}_{e \in E}, \{C_{v,D}\}_{v \in V, D \in \mathcal{S}})$ be an instance of quantum walk search, with the promise that for all $x \in \D$, $M_x = \{m_x\}$. Let $\sigma,\tau \in \Delta_V$. For all $x \in \D$, let $\mu_x \in \Delta_{\supp(\sigma)}$. Then, we can find the marked vertex with complexities
\begin{align*}
    \mathsf{R}_x^+ &\leq \sum_{v \in \supp(\sigma)} \frac{(\mu_x)_v^2}{\sigma_v}(\mathsf{S}_v)_x^+ + R_{\mathrm{eff}}(G, r \circ (\mathsf{U}_{\cdot})_x^+; \mu_x - \nu_x) +  \frac{1}{\tau_{m_x}}(\mathsf{C}_{m_x,D_{m_x,x}})_x^+, & \forall x \in \D, \\
    \mathsf{R}_x^- &\leq \sum_{v \in \supp(\sigma)} \sigma_v(\mathsf{S}_v)_x^- + \sum_{e \in E} \frac{(\mathsf{U}_e)_x^-}{r_e} + \sum_{v \in \supp(\tau) \setminus \{m_x\}} \tau_v(\mathsf{C}_{v,D_{v,x}})_x^-, & \forall x \in \D.
\end{align*}

\label{thm:quantum-walk-finding-fixed-fraction}
Let $(G, r, x \mapsto M_x, (v,x) \mapsto D_{v,x}, \{S_v\}_{v \in V}, \{U_e\}_{e \in E}, \{C_{v,D}\}_{v \in V, D \in \mathcal{S}})$ be an instance of quantum walk search. Let $\sigma,\tau \in \Delta_V$, and suppose that for all $x \in \D$, we have $\P_{v \sim \tau}[v \in M_x] = \varepsilon$ for some fixed $\varepsilon > 0$. For all $x \in \D$, let $\mu_x \in \Delta_{\supp(\sigma)}$, and $\nu_x = (\tau|_{M_x})/\varepsilon$. Then, we can find the marked vertex with complexities
\begin{align*}
    \mathrm{R}_x^+ &\leq \sum_{v \in \supp(\sigma)} \frac{(\mu_x)_v^2}{\sigma_v}(\mathsf{S}_v)_x^+ + R_{\mathrm{eff}}(G, r \circ (\mathsf{U}_{\cdot})_x^+; \mu_x - \nu_x) + \frac{1}{\varepsilon^2}\sum_{v \in \supp(\tau) \cap M_x} \tau_v(\mathsf{C}_{v,D_{v,x}})_x^+, & \forall x \in \D, \\
    \mathrm{R}_x^- &\leq \sum_{v \in \supp(\sigma)} \sigma_v(\mathsf{S}_v)_x^- + \sum_{e \in E} \frac{(\mathsf{U}_e)_x^-}{r_e} + \sum_{v \in \supp(\tau) \setminus M_x} \tau_v(\mathsf{C}_{v,D_{v,x}})_x^-, & \forall x \in \D.
\end{align*}

\label{thm:mnrs}
Suppose we have the instance of quantum walk search $(G, r, x \mapsto M_x, (v,x) \mapsto D_{v,x}, \{S_v\}_{v \in V}, \{U_e\}_{e \in E}, \{C_{v,D}\}_{v \in V, D \in \mathcal{S}})$. Let $\pi$ be the stationary distribution of the random walk $P$ on $G$, and let $\delta$ be its spectral gap. For all $x \in \D_+$, let $\varepsilon_x := \P_{v \sim \pi}[v \in M_x]$, and we write $\varepsilon := \min_{x \in \D_+} \varepsilon_x$. Then, we can solve the detection version of the quantum walk search problem with a span program $\mathcal{P}$, whose complexities satisfy
\begin{align*}
    w_+(x,\mathcal{P}) &\in O(1), \\
    w_-(x,\mathcal{P}) &\in O\left(\underset{v \sim \pi}{\E}\left[\mathsf{S}_v^+\right] \cdot \underset{v \sim \pi}{\E} \left[(\mathsf{S}_v)_x^-\right] + \frac{1}{\varepsilon} \left(\frac{1}{\delta} \cdot \underset{\substack{v \sim \pi \\ w \sim P_{v\cdot}}}{\E} \left[\mathsf{U}^+_{vw}(\mathsf{U}_{vw})_x^-\right] + \underset{v \sim \pi}{\E} \left[\mathsf{C}_{v,D_{v,x}}^+(\mathsf{C}_{v,D_{v,x}})_x^-\right]\right)\right),
\end{align*}
for $x \in \D_+$ and $x \in \D_-$, respectively.

\label{thm:mso-discovery-b}
    \MSOTD\ on colored graphs in the token sliding and the token jumping models can be solved in time $g(|\phi|,b,tw)\cdot n$, for some computable function $g$ and where $tw$ is the treewidth of the input graph. 
    \MSOD\ on colored graphs in the token sliding and the token jumping models can be solved in time $g(|\phi|,b,cw)\cdot n^{2}$, for some computable function~$g$ and where $cw$ is the cliquewidth of the input graph.

\label{lem:logic-solution-discovery-modulator-stars-hardness-implications-of-conditions}
If $((H,\mathcal{C}), S, b, \phi)$ is a yes-instance of \FOD, then 
\begin{enumerate}
    \item[i.] each token that moves is moved exactly two token sliding steps and passes through a green connector node,
    \item[ii.] for each edge-block, the solution $T$ contains $2n$ leaves of exactly one edge-gadget in the edge-block, and
    \item[iii.] exactly $n(\kappa-1)$ tokens slide from exactly one vertex-gadget in each vertex-block.
\end{enumerate}

\label{lem:logic-solution-discovery-modulator-paths-hardness-implications-of-conditions}
If $((H,\mathcal{C}), S, b, \phi)$ is a yes-instance of \FOD, then 
\begin{itemize}
    \item[i.] each token that moves is moved exactly two token sliding steps and passes through a green connector node,
    \item[ii.] for each edge-block, the solution $T$ contains tokens on all $2n$ nodes of exactly one edge-gadget in the edge-block, and
    \item[iii.] exactly $n(\kappa-1)$ tokens slide from exactly one vertex-gadget in each vertex-block.
\end{itemize}

\label{obs:logic-solution-discovery-bandwidth-hardness-backward-order}
  None of the following modifications changes the validity of a solution or the number of token slides:
  \begin{enumerate}
    \item{} reordering token slides;
    \item{} making a path traversed by a token between an orange node and a node of another color in the same supernode friendly;
    \item{} making a path traversed by a token to a teal node after passing through an arc-gadget friendly; or
    \item{} swapping the destinations of two tokens that pass through the same node.
  \end{enumerate}

\label{def:deg-size}
 The \emph{size} of a $\qns/\qsa/\qsos$ refutation~$\pi$ ($\size(\pi)$) is the number of monomials (counted with repetition) in $q_p$, $q_u$ and $q$. The \emph{degree} of $\pi$ ($\deg(\pi)$) is the maximum degree of any of the polynomials $q_pp$, $q_u(1-2u)$, and~$q$. 

The \emph{Q-size} of $\pi$ \emph{($\qsize(\pi)$)} is  defined analogously to the $\size$ but accounts only for the monomials in the polynomials $q_u$. The existential Q-degree of $\pi$ \emph{($\qdeg(\pi)$)}  is the maximum existential degree of any $q_u$, where the existential degree is the highest number of existentially quantified variables in any monomial.

Let $n$ be an integer and $C_n$ be a circuit with inputs $x_1, \dots, x_n$ and a single output. 
We define
\begin{equation*}
	Q\text{-}C_n = \exists x_1 \cdots \exists x_n \forall u \exists t_1 \cdots \exists t_m. \big(u \nleftrightarrow C_n(x_1, \dots, x_n)\big)\ ,
\end{equation*}
where the additional variables $t_i$ are used for a Tseitin-encoding of the circuit $C_n$ into  CNF (the $i^\text{th}$ node in $C_n$ is represented by  variable $t_i$,  and if, e.g.,  node $i$ is an $\land$-gate between nodes $j$ and $k$, then we have clauses encoding $t_i\leftrightarrow( t_j\land t_k)$, and similarly for $\lor$ and $\neg$ gates).

{lem}{degreelemma}
\label{lem:sizedegree_general}
	Let $d,n,b \in \mathbb{N}^{\ge 0}$ and $Q.\varphi$ be a false QBF. Let $\pi$ be a $\qsos$ refutation of $Q.\varphi$ so that its $q_u$ polynomials contain, in total, fewer than $(1-\frac{d}{2n})^{-b}$ monomials of existential degree $> d$. Then there is a $\qsos$ refutation $\pi'$ of $Q.\varphi$ with $\qdeg(\pi')\le d+b$.

