A \emph{quantum interactive oracle proof} (quantum IOP) system, parameterized by functions $q(n)$ and $l(n): \mathbb{Z}_+ \to \mathbb{Z}_+$, consists of a quantum verifier $\texttt{V}$ satisfying the following conditions for any input of size $n$:

\begin{itemize}
    \item The verifier interacts with the prover for at most $\mathrm{poly}(n)$ rounds.
    \item In each round, the prover sends a {quantum} message to the verifier. The message length may vary between rounds.
    \item In each round, the verifier:
    \begin{itemize}
        \item applies a quantum circuit to his private qubits and to portions of the prover’s message, including qubits received in the current round as well as those retained from previous rounds,
        \item stores part of the prover’s message registers for use in later rounds.
    \end{itemize}
    \item After each interaction, the verifier returns the remainder of the prover's {quantum} message (i.e., the part not stored) and may optionally send back part of their own private {quantum} register.
    \item At the end of the protocol, the verifier outputs a single decision bit.
\end{itemize}
The main complexity parameters are:
\begin{itemize}
    \item The \textbf{query complexity} $q(n)$: the total number of qubits from the prover's messages accessed by the verifier across all rounds.
    \item The \textbf{communication complexity} $l(n)$: the total number of qubits in the prover's messages across all rounds.
\end{itemize}
We refer to such a system as a \emph{quantum IOP} if $q(n)$ is bounded by a constant.\footnote{In the formal Definition~\ref{def:gqiop}, we refer to this as the \emph{general} quantum IOP to distinguish it from the restricted and strong variants.}

We define the following variants of a \emph{quantum IOP}:
\begin{itemize}
    \item A system is called a \emph{restricted quantum IOP} if the private register sent back by the verifier is required to be \emph{classical}.
    \item It is called a \emph{strong quantum IOP} if the verifier must return the \emph{entire} prover's message register in each round (i.e., does not store any part of the message).
\end{itemize}

Let $\mathsf{P}$ be a register and $U_\mathsf{P}$ a unitary acting on it. Let $\mathsf{R}$ be a one-qubit register.
The controlled unitary $C(U_\mathsf{P}, \mathsf{R})$ applies $U_\mathsf{P}$ if the qubit in $\mathsf{R}$ is $|1\rangle$:
\begin{align*}
    C(U_\mathsf{P}, \mathsf{R}) = \begin{pmatrix} I_\mathsf{P} & 0 \\ 0 & U_\mathsf{P} \end{pmatrix}
\end{align*}
More generally, for a register $\mathsf{R}'$ of dimension $d$ and $i \in [d]$, the controlled unitary $C(U_\mathsf{P}, \mathsf{R}, i)$ applies $U_\mathsf{P}$ if the qubit in register $\mathsf{R}$ is $\ket i$:
\begin{align*}
    C(U_\mathsf{P}, \mathsf{R}, i) = \mathrm{diag}(\underbrace{I_\mathsf{P}, \ldots, I_\mathsf{P}}_{i-1}, U_\mathsf{P}, \underbrace{I_\mathsf{P}, \ldots, I_\mathsf{P}}_{d-i})
\end{align*}

Let $\mathsf{P}, \mathsf{R}$ be registers and $O_\mathsf{P}$ an observable decomposed as $O = \sum_{i=1}^r a_i P_i$, where each $P_i$ is an orthogonal projection and $I = \sum_i P_i$. The unitary that performs the purified measurement and stores the outcome in $\mathsf{R}$ is:
\begin{align*}
    P(O_\mathsf{P}, \mathsf{R}) = \sum_{i=1}^r P_{i, \mathsf{P}} \cdot (X(a_i))_\mathsf{R}
\end{align*}

\label{def:epr_basis}
Let $|\phi^+\rangle = \frac{1}{\sqrt{2}}(|00\rangle + |11\rangle)$. The EPR basis states are:
\begin{align*}
    \ket{E_{00}} &= \ketbra{\phi^+}{\phi^+}, \\
    \ket{E_{10}} &= (Z \otimes I) \ketbra{\phi^+}{\phi^+} (Z \otimes I), \\
    \ket{E_{01}} &= (X \otimes I) \ketbra{\phi^+}{\phi^+}( X \otimes I), \\
    \ket{E_{11}} &= (ZX \otimes I) \ketbra{\phi^+}{\phi^+} (XZ \otimes I).
\end{align*}

Let $n, m \in \mathbb{Z}_+$, $w \in \mathbb{F}_2^n$, $\mathsf{T} = (\mathsf{T}_i)_{i \in [n]}$, and $s = (s_1, \ldots, s_m) \in [n]^m$. Define:
\begin{align*}
    w(s) = (w_{s_1}, \ldots, w_{s_m}), \quad \mathsf{T}(s) = (\mathsf{T}_{s_j})_{j \in [m]}\;.
\end{align*}

For a positive semidefinite operator $\sigma$, define:
\begin{align*}
    \langle A, B \rangle_\sigma = \mathrm{Tr}(A^\dagger B \sigma), \quad \|A\|_\sigma^2 = \mathrm{Tr}(A^\dagger A \sigma)\;.
\end{align*}

A Hamiltonian (hermitian matrix) $H$ is a  Clifford-Hamiltonian projection iff $H$ acts non-trivially on a set $S$ of qubits as $C^\dagger \ketbra{0^{|S|}}{0^{|S|}} C$, where $C$ is an element of the $|S|$-fold Clifford group. More specifically,
\begin{align*}
H = (C^\dagger  |0^{|S|}\rangle\langle0^{|S|}| C)_{S} \otimes I_{[n]-S}.
\end{align*}

A Hamiltonian $H \in \C^{2^n} \otimes \C^{2^n}$ is a Clifford-Hamiltonian if it is the uniform average of a polynomial number $m=\poly(n)$ of Clifford-Hamiltonian projection terms $H_i$. That is,
\begin{align*}
H = \frac{1}{m} \sum_{i \in [m]} H_i\;.
\end{align*}

Moreover, $H$ is $k$-local if each $H_i$ acts non-trivially on at most $k$ qubits.

Let $k \in \Z^+$ and let $a,b:\Z^+ \rightarrow \R^+$ be non-decreasing functions such that $\forall n \in \Z^+,~ a(n) < b(n)$. The local Clifford-Hamiltonian problem $\mathcal{LCH}(k,a,b)$ is the promise problem $(S_{yes}, S_{no})$ defined by:
\begin{itemize}
    \item $S_{yes}$: the set of $k$-local Clifford-Hamiltonians $H\in \C^{2^n} \otimes \C^{2^n}$ such that $\lambda_{\min}(H) \leq a(n)$,
    \item $S_{no}$: the set of $k$-local Clifford-Hamiltonians $H\in \C^{2^n} \otimes \C^{2^n}$ such that $\lambda_{\min}(H) \geq b(n)$.
\end{itemize}

\label{lem:c_ham_amp}
Let $(S_{yes}, S_{no}) = \mathcal{LCH}(k, a, b)$ with $a, b \in (0, 0.1)$. Let $H \in S_{yes} \cup S_{no}$, and define $H' = (1 - 2H)^{\otimes N}$ for some odd $N \in \Z^+$. Then:
\begin{enumerate}
    \item If $H \in S_{yes}$, then $\lambda_{\max}(H') \geq (1 - 2a)^N$.
    \item If $H \in S_{no}$, then $\lambda_{\max}(H') \leq (1 - 2b)^N$.
\end{enumerate}

Furthermore, let $p, q$ be as in Theorem~\ref{thm:clifford_ham}. For $k=5$, $a=2^{-p(n)}$, $b=1/q(n)$, and $N=q^2(n)$, there exists a polynomial $s$ such that:
\begin{enumerate}
    \item If $H \in S_{yes}$, then $\lambda_{\max}(H') \geq 1 - 2^{-s(n)}$.
    \item If $H \in S_{no}$, then $\lambda_{\max}(H') \leq 2^{-s(n)}$.
\end{enumerate}

\label{def:pcpp}
Let $s, \delta: \mathbb{Z}^+ \rightarrow [0, 1]$ be functions. A verifier $V$ is said to be a probabilistically checkable proof of proximity (PCPP) system for a pair language $L$ with proximity parameter $\delta$ and soundness error $s$ if, for every pair of strings $(x, y)$, the following conditions hold:
\begin{itemize}
    \item \textnormal{Completeness:} If $(x, y) \in L$, then there exists a proof string $\pi$ such that $V(x)$ accepts the oracle $y \circ \pi$ with probability $1$.
    \item \textnormal{Soundness:} If $y$ is $\delta(|x|)$-far from $L(x)$, then for every $\pi$, the verifier $V(x)$ accepts the oracle $y \circ \pi$ with probability strictly less than $s(|x|)$.
\end{itemize}
If $s$ and $\delta$ are not explicitly specified, they are assumed to be constants in the interval $(0, 1)$.

\label{thm:pcpp}
There exists a constant $\delta_0 \in (0, 1)$ such that for all $n \in \mathbb{Z}^+$ and all $\delta < \delta_0$, the language \textsc{Circuit Value} has a PCP of proximity (for circuits of size $n$) with the following parameters:
\begin{itemize}
    \item randomness complexity $O(\log n)$,
    \item query complexity $O(1)$,
    \item perfect completeness, and
    \item soundness error $1 - \Omega(\delta)$ for proximity parameter $\delta$.
\end{itemize}

For a positive semidefinite operator $\sigma$, define:
\begin{align*}
    \langle A, B \rangle_\sigma = \mathrm{Tr}(A^\dagger B \sigma), \quad \|A\|_\sigma^2 = \mathrm{Tr}(A^\dagger A \sigma).
\end{align*}

\label{def:qpcp_sys}
A quantum probabilistically checkable proof system for a promise problem $(S_{yes}, S_{no})$ is
a quantum algorithm with queries $\texttt V$ such that:
\begin{enumerate}
\item \textnormal{Efficient:} $\texttt V$ has polynomial time complexity.  
\item \textnormal{Completeness:} For any $x\in S_{yes}$, there exists a quantum state $\rho$ such that $\Pr[\texttt  V(x)=1] \geq \frac{2}{3}$.   
\item \textnormal{Soundness:} For any $x\in S_{no} $ and any quantum state $\rho$, $\Pr[\texttt  V(x)=1] \leq \frac{1}{3}$.   
\end{enumerate}

\label{def:qip}
Let $m \in \mathbb{Z}_+$ be the total number of messages, and let $h = \lfloor m/2 + 1 \rfloor$. An $m$-message quantum interactive oracle proof system is defined by a tuple of quantum algorithms with queries $\texttt{V} = (\texttt{V}_1, \texttt{V}_2, \ldots, \texttt{V}_h)$.
The tuple $\mathbb{V}_x = (\mathbb{V}_{x,1}, \ldots, \mathbb{V}_{x,h})$ represents the quantum channels with queries produced by the algorithm $\texttt{V}_i$ on input $x$. Each quantum channel $\mathbb{V}_{x,i}$, for $i\in[h]$, acts on a (quantum) witness register $(\mathsf{W}_{i-1}, \mathsf{W}'_{i-1})$ and (quantum) reference register $\mathsf{R}$, and it returns a message register  $(\mathsf{J}_i,\mathsf{M}_i)$ where  $\mathsf{J}_i$ is classical and  $\mathsf{M}_i$ quantum, together with private registers $( \mathsf{W}'_{i}, \mathsf{R})$.\footnote{For the present definition the registers $\mathsf{W}'_{i}$ are not needed and can be assumed to be trivial without loss of generality. We include them for future consistency.} 
Summarizing, the verifier channel $\mathbb{V}_{x,i}$ acts on the registers as follows:
\begin{align*}
\big((\mathsf{W}_{i-1}, \mathsf{W}'_{i-1}), \mathsf{R} \big)
\longrightarrow 
\big((\mathsf{M}_{i}, \mathsf{J}_{    i}), (\mathsf{W}'_{i},\mathsf{R}) \big)\;.
\end{align*}
If $m$ is odd, define the index set $I = \{0, \ldots, h-1\}$; if $m$ is even, let $I = \{1, \ldots, h-1\}$.  
A prover strategy is specified by a collection of quantum channels $\{\mathbb{P}_i\}_{i \in I}$ and a quantum register $\mathsf{P}$, where each $\mathbb{P}_i$ acts on the registers as follows:
\[
((\mathsf{M}_i, \mathsf{J}_i), \mathsf{P}) \longrightarrow (\mathsf{W}_i, \mathsf{P}).
\]
Let the first (classical) bit of the register $\mathsf{J}_{    h}$ in the output of $\mathbb{V}_{x,h}$ represent the verifier's final decision to accept or reject.
Let $\omega(\mathbb{V}_x)$ denote the value of the interactive game defined by $\mathbb{V}_x$. That is, $\omega(\mathbb{V}_x)$ is the maximum acceptance probability of $\mathbb{V}_x$ over all possible prover strategies $\{\mathbb{P}_i\}_{i \in I}$.

The following properties must be satisfied:
\begin{itemize}
\item \textnormal{Consistent:} 
Unless otherwise specified, we initialize $\mathsf{W}_i$, $\mathsf{W}'_i$, $ \mathsf{R}$, $ \mathsf{M}_i$ to $\ket{0}$, whereas $\mathsf{P}$ may be initialized in an arbitrary quantum state.
The register $\mathsf{J}_i$ is initialized to the all-zero string.
\item \textnormal{Efficient:} Each verifier's algorithm $\texttt{V}_i$ must be implementable in polynomial time and have polynomial time complexity as defined in Definition \ref{def:qwq}. 
\end{itemize}

\label{def:sqiop}
An $m$-message \emph{strong quantum interactive oracle proof system} consists of an $m$-message quantum interactive oracle proof system satisfying that (using the notation in Definition \ref{def:qip} and Definition \ref{def:qiop}) 
for each $i \in [h]$, $\mathsf{M}'_i$ is trivial (no new quantum message sent by the verifier) and $\mathsf{N}_{i-1,i}=\mathsf{W}_{i-1}$ (all prover quantum messages are sent back to him). As a consequence, $\mathsf{M}_i=\mathsf{W}_{i-1}$, $\mathsf{W}'_{i-1}$ is always trivial, and $\mathbb{V}_{x,i}$ has witness register $ \mathsf{W}_{i-1}$ only.

\label{def:qiop_}
Let $m \in \mathbb{Z}_+$ be the total number of messages. 
An $m$-message restricted quantum interactive oracle proof system (resp. general quantum interactive oracle proof system, strong  quantum interactive oracle proof system) for a promise problem $(S_{\text{yes}}, S_{\text{no}})$  satisfies the following, where $\omega(\mathbb{V}_x)$ is defined as in Definition~\ref{def:qiop} (resp. Definition~\ref{def:gqiop}, Definition~\ref{def:sqiop}). 
\begin{itemize}
\item \textnormal{Completeness:} There exists a constant $c \in (0,1]$ such that for all $x \in S_{\text{yes}}$, the maximum acceptance probability $\omega(\mathbb{V}_x) \geq c$. That is, there exists an honest prover strategy under which the verifier accepts every yes-instance with probability at least $c$.

\item \textnormal{Soundness:} There exists a constant $s \in [0, c)$ such that for all $x \in S_{\text{no}}$, the maximum acceptance probability $\omega(\mathbb{V}_x) \leq s$. That is, no prover strategy can cause the verifier to accept a no-instance with probability greater than $s$.
\end{itemize}

\label{def:ioc}
An interactive oracle commitment scheme is specified by a classical probabilistic polynomial-time interactive machine $\texttt{V}$ and a function $D:\F_2^*\rightarrow \F_2^*$ satisfying the following:
\begin{enumerate}
\item The verifier's query complexity is a constant. 
\item There exists an honest polynomial time prover $\texttt{P}$, such that for any $n$, any $s\in \F_2^n$, for any circuit $C$ of size  $\poly(n)$ with a single-bit output, any $\eps\in (0, 1)$, at the end of the interaction between $ \texttt{P}(s)$ and $\texttt{V}({C}, \eps)$, the verifier outputs ${C}({s})$ with probability $1$. Moreover, the communication complexity between $\texttt{P}$ and $\texttt{V}$ is $\poly(n)$.
\item \textnormal{Soundness:} For any polynomial size circuit ${C}$ with a single bit output, any $\eps\in (0, 1)$, and any prover $\texttt{P}$, let $m$ be the prover's first message, at the end of the interaction, 
\begin{align*}
\Pr[\text{$\texttt{V}({C}, \eps)$ outputs ${C}({D(m)})$ or rejects}] \geq 1-\eps\;.
\end{align*} 
\end{enumerate}

\label{def:ioc_hp}
\hfill
\begin{itemize}
\item \textnormal{The prover's first step:} The prover sends the verifier a string $E(s)$, where $E$ is the encoding function of the code from Theorem~\ref{thm:ltc}.
\item \textnormal{The verifier's first step:} The verifier sends the prover a description of a Boolean circuit $C$.
\item \textnormal{The prover's second step:} The prover responds with a string $C(s) \circ w$, where $w$ is a witness such that the verifier in Theorem~\ref{thm:pcpp} accepts the oracle $E(s) \circ w$ when invoked on input $x = C(D(\cdot)) + C(s) + 1$.
\item \textnormal{The verifier's second step:} The verifier decides whether to accept, and if so, produces an output.
\end{itemize}

\label{def:ioc_verifier}
\hfill
\begin{itemize}
\item \textnormal{The prover's first step:} The prover sends the verifier a string $m$.
\item \textnormal{The verifier's first step:} The verifier sends the prover a description of a Boolean circuit $C$.
\item \textnormal{The prover's second step:} The prover sends the verifier a string $r \circ w$.
\item \textnormal{The verifier's second step:} The verifier accepts and outputs $r$ if and only if the verifier from Theorem~\ref{thm:pcpp}, when run a constant number of times, accepts each time on input
\[
x = \big(C(D(\cdot)) + r + 1\big) \wedge T(\cdot),
\]
with implicit input $y = m$ and proof $\pi = w$, where $D$ is the decoding circuit and $T$ is the  code tester  from Theorem~\ref{thm:ltc}
\end{itemize}

\label{lem:clifford_pauli}
For any $k\in\Z_+$ and any element of the $ k $-fold Clifford group $C$ there exists $ a,b,c\in \F_2^k, d\in \F_2$, such that 
\begin{align}
\label{eq:lem:clifford_pauli}
    C^\dagger 
(Z\otimes \underbrace{I \otimes I\otimes\cdots \otimes I }_{k-1}) C = (-1)^d X(a)Z(b)Y(c)
\end{align} and  $a \land b =b \land c = c \land a=0 $. We call $(-1)^d X(a)Z(b)Y(c)$ the \emph{Pauli representation} of $C^\dagger 
(Z\otimes \underbrace{I \otimes I\otimes\cdots \otimes I }_{k-1}) C$.

\label{lem:switch_XZ}
Let $A,B$ be matrices.
For $x\in \F_2$, $ \frac{I+(-1)^x A}{2} B = B\frac{I+(-1)^{x+1} A}{2}$ if $ \{A,B\}=0 $, $ \frac{I+(-1)^x A}{2} B = B\frac{I+(-1)^x A}{2}$ if $  [A,B]=0$.

\label{lem:otimes_obs_eq_sum_otimes_proj}
For any observable $O_i$ such that $ O_i^2 = I$, 
\begin{align*}
\frac{I+\bigotimes_{i\in [N]} O_i}{2} = \sum_{\bigoplus_{i\in [N]} r_i =0} \bigotimes_{i\in [N]} \frac{(I+(-1)^{r_i} O_i)}{2} 
\end{align*}

\label{lem:xor_r:tel_qiop}
Let $O_i$ for $i\in [m]$ be observables. Let $ H = \frac{1}{m}\sum_{i\in [m]}O_i$. Let $ \ket{\phi}$ be a quantum state. Let $l_i\in [m]$ for $i\in [N]$. 
Let $r'_i$ be the random variable that has the distribution of measuring $\ket{\phi}$ under $O_{l_i}$. Then,
\begin{align}
\Pr[\bigoplus_{i\in [N]} r'_i =0]
 = \Pr[\text{The outcome of measuring $ \ket{\phi}^{\otimes N}$ under $\bigotimes_{i\in [N]} O_{l_i}$  is $0$}] \label{eq:trivial_qcpcp:c:1}
\end{align}

\label{def:3c}
Let $\{C_n\}$ be the code defined in Theorem~\ref{thm:3c_code}.
\begin{itemize}
    \item Define $\texttt{L}^w(1^k; r)$ as the output of $\texttt{L}^w(1^k)$ when using randomness $r \in \mathbb{F}_2^{l_{\texttt{L}}}$, where $l_{\texttt{L}}$ is the randomness complexity of $\texttt{L}$.
    \item Define $\texttt{S}^w(1^k, p; r)$ as the output of $\texttt{S}^w(1^k, p)$ when using randomness $r \in \mathbb{F}_2^{l_{\texttt{S}}}$, where $l_{\texttt{S}}$ is the randomness complexity of $\texttt{S}$.
\end{itemize}

\label{def:mqt:honest_prover:block}
Let $k,n\in \Z_+$. 
Let $\mathsf{P}$ be a register of $k$ qubits, $\mathsf{R}=(\mathsf{R}_{j})_{j\in [n]}$ a register of $ n$ qubits. 
$\mathsf{P, R}$ are initially held by the prover. 
For $j\in[n]$, let $ O_{j}$ be observables on register $\mathsf{P}$. 
\begin{mdframed}
\begin{itemize}
\item \textnormal{The prover's first step:} 
The prover applies the following unitary 
\begin{align*}
\prod_{p\in[n]}P(O_{ p, \mathsf{P}}, \mathsf{R}_{p}). 
\end{align*}
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. The verifier sends the prover the register $\mathsf{R}$. 
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. The prover applies the following unitary 
\begin{align*}
(\prod_{p\in[n]} P(O_{p, \mathsf{P}}, \mathsf{R}_{p}))^{-1}.
\end{align*}
\end{itemize}
\end{mdframed}

\label{def:mqt:honest_prover:l_consist}
Let $k,n\in \Z_+$. 
Let $\mathsf{P}$ be a register of $k$ qubits, 
$\mathsf{R}=(\mathsf{R}_{j})_{j\in [n]}$ a register of $ n$ qubits. 
$\mathsf{P, R}$ are initially held by the prover. 
For $q'\in[2], j\in[n]$, let $ O_{q', j}$ be observables on register $\mathsf{P}$. 
\begin{mdframed}
\begin{itemize}
\item The verifier sends the prover $q' \in [2]$. 
\item The honest prover acts as in Definition \ref{def:mqt:honest_prover:block} with $ O_{p}=O_{q', p}$ for $p\in [n]$. 
\end{itemize}
\end{mdframed}

\label{def:mqt:honest_prover}

Let $k,n\in \Z_+$. 
Let $ G_k=[g_1, g_2,\cdots, g_n]^T \in \F_2^{n} \otimes \F_2^k$ be as in Definition \ref{def:3c}.
Let $\mathsf{P}$ be a register of $k$ qubits, $\mathsf{R}$ a register of $n$ qubits. $\mathsf{P, R}$ are initially held by the prover and initialized to $\ket{0}$. 

The honest prover's actions are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The honest prover prepares the witness in register $\mathsf{P}$.
\item The honest prover acts as in Definition \ref{def:mqt:honest_prover:block} with $ O_{p}=Z(g_p)$ for $p\in [n]$.
\item The honest prover acts as in Definition \ref{def:mqt:honest_prover:block} with $ O_{p}=X(g_p)$ for $p\in [n]$. 
\item The honest prover acts as in Definition \ref{def:mqt:honest_prover:l_consist} with $ O_{1, p}=Z(g_p), O_{2, p}=X(g_p)$ for $p\in [n]$.
\end{itemize}
\end{mdframed}

\label{def:mqt:read_self_corr}
Let $S_{p} $ be as in Definition \ref{def:self_corr}. 
Let $\mathsf{R}=(\mathsf{R}_{j})_{j\in [n]}$ be a register of $n$ qubits. 
Let $\mathsf{S}$ be a register. 
Define 
\begin{align*}
{\tilde O}_{p, \mathsf{SRT_S}} = 
S_{p, \mathsf{SRT_S}}^\dagger \cdot Z_{\mathsf{S}} \cdot 
S_{p, \mathsf{SRT_S}}.
\end{align*}

\label{def:mqt:verifier:block}
Let $\mathsf{R} =(\mathsf{R}_{j})_{j\in[n]}$ be a register. Let $ \mathsf{S}$ be a register held by the verifier and initialized with $ \ket{0}$. Let $ \mathsf{T_S} $ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{S}}} \ket{0}$, where $l_{\mathsf{S}} $ is defined as in Definition \ref{def:3c}. 
Let $M,F\in \{0,1\}, m, f\in [n]$. 
\begin{mdframed}
\begin{itemize}
\item \textnormal{The prover's first step:} 
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. 
If $F=1$, the verifier measures $\mathsf{T_S}$, then the verifier applies ${\tilde O}_{ f, \mathsf{SRT_S}}$. If $M=1$, the verifier measures $\mathsf{T_S}$. Then, the verifier
measures ${\tilde O}_{m,\mathsf{SRT_S}}$ and outputs the measurement result $r$. 
The verifier sends the prover the register $\mathsf{R}$. 
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. 
\end{itemize}
\end{mdframed}

\label{def:mqt:verifier:last}
Let $q'\in[2], m\in [n]$. 
\begin{mdframed}
\begin{itemize}
\item  
The verifier sends $q'$ to the prover.
\item The verifier acts as in Definition \ref{def:mqt:verifier:block} with $M=1,F=0,m=m,f=0$. 
\end{itemize}
\end{mdframed}

\label{def:mqt:verifier:c} 
Let $ D$ be a distribution over $[n]$. 
Let $\mathsf{R} =(\mathsf{R}_{j})_{j\in[n]}$ be a register. Let $ \mathsf{S}$ be a register held by the verifier and initialized with $ \ket{0}$. Let $ \mathsf{T_{S, i}} $ for $i\in [3]$ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{S}}} \ket{0}$. 
The verifier's actions are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The verifier samples $u\in_R [2]$, sets $M_u=1$, and sets $ M_i =0$ for $i \neq u, i\in [2]$. 
\item If $M_1=1$, the verifier sets $F_i = 0$ for $i\in [2]$. If $M_2=1$, the verifier sets $F_1 \in_R \F_2$, $F_2 = 0$.
\item The verifier samples $f_1,f_2\sim D$. 
\item The verifier repeats the verifier's actions in Definition \ref{def:mqt:verifier:block} twice. In the $i$-th time, the verifier acts as in Definition \ref{def:mqt:verifier:block} with $ M = M_i, F = F_i, m=f_i, f=f_i$; if $M_i=1$ he sets $r_i$ to be the output. 
\item In the end, the verifier acts as in Definition \ref{def:mqt:verifier:last} with $q'= u, m=f_u$. Let $r'$ be the output of the verifier.  
\item The verifier accepts iff $ r_u=r'$.
\end{itemize}
\end{mdframed}

\label{def:mqt:verifier:a}
Let $ D$ be a distribution over $[n]$. 
Let $ G_k=[g_1, g_2,\cdots, g_n]^T \in \F_2^{n} \otimes \F_2^k$ be defined as in Definition \ref{def:3c}.
Let $\mathsf{R} =(\mathsf{R}_{j})_{j\in[n]}$ be a register. Let $ \mathsf{S}$ be a register held by the verifier and initialized with $ \ket{0}$. Let $ \mathsf{T_{S, i}} $ for $i\in [3]$ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{S}}} \ket{0}$. 
The verifier's action are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The verifier sets $M_1=1, F_1=0, M_2=0, F_2=1$.  
\item The verifier samples $ (f_1,f_2)\sim D$. 
\item The verifier repeats the verifier's action in Definition \ref{def:mqt:verifier:block} for $2$ times. In the $i$-th time, the verifier acts as in Definition \ref{def:mqt:verifier:block} with $ M = M_i, F = F_i, m=f_i, f=f_i$, if $M_i=1$, sets $r_i$ be the output. 
\item In the end, the verifier acts as in Definition \ref{def:mqt:verifier:last} with $q'= 1, m=f_1$. Let $r'$ be the output of the verifier. 
\item The verifier accepts iff $ r_1=r' \oplus (g_{f_1}\cdot  g_{f_2})$.
\end{itemize}
\end{mdframed}

\label{def:mqt:verifier:b_code}
Let $\mathsf{R} =(\mathsf{R}_{j})_{j\in[n]}$ be a register. Let $ \mathsf{L}$ be a register held by the verifier and initialized with $ \ket{0}$. Let $ \mathsf{T_L} $ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{L}}} \ket{0}$. 
Let $ \mathsf{T_S} $ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{S}}} \ket{0}$. Let $t\in \{0,1\}, F\in\{0,1\},f\in[n]$. 
\begin{mdframed}
\begin{itemize}
\item \textnormal{The prover's first step:} 
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. 
If $F=1$, the verifier measures $\mathsf{T_S}$, then applies ${\tilde O}_{ f, \mathsf{SRT_S}}$.
\begin{itemize}
\item If $t=0$, the verifier sends the prover the register $\mathsf{R}$. 
\item If $t=1$, the verifier measures $\mathsf{T_L}$, then the verifier applies ${L}_{\mathsf{LRT_L}}$ and measures $Z_{\mathsf{L}}$ and outputs the measurement result $ r$. 
The verifier sends the prover the register $\mathsf{R}$. 
\end{itemize}
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. 
\end{itemize}
\end{mdframed}

\label{def:mqt:verifier:l_code}
Let $t\in \{0,1\}$. Let $q'\in [2]$. 
\begin{mdframed}
\begin{itemize}
\item  
The verifier sends $q'$ to the prover.
\item The verifier acts as in Definition \ref{def:mqt:verifier:b_code} with $t=t, F=0, f=0$. 
\end{itemize} 
\end{mdframed}

\label{def:mqt:verifier:v} 
Let $ D$ be a distribution over $[n]$. 
Let $\mathsf{R} =(\mathsf{R}_{j})_{j\in[n]}$ be a register. Let $ \mathsf{S}, \mathsf{L}$ be registers held by the verifier and initialized with $ \ket{0}$. Let $ \mathsf{T_{S, i}} $ for $i\in [3]$ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{S}}} \ket{0}$.
Let $ \mathsf{T_{L, i}} $ for $i\in [3]$ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{L}}} \ket{0}$.
The verifier's actions are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The verifier samples $u\in_R [3]$. The verifier sets $t_u=1$ and $t_i=0$ for $i\neq u, i\in [3]$.
\item The verifier samples $F_i\in_R \{0, 1\}$ for $i\in [u-1]$. The verifier sets $F_i=0$ for $i\geq u$. 
\item The verifier samples $f_1,f_2\sim D$. 
\item The verifier samples $q'\in_R [2]$. 
\item The verifier repeats the verifier's actions in Definition \ref{def:mqt:verifier:b_code} twice. In the $i$-th time, the verifier acts as in Definition \ref{def:mqt:verifier:b_code} with $t=t_i, F=F_i, f=f_i$ and if $t_i=1$ sets $r_i$ to be the output. 
\item In the end, the verifier acts as in Definition \ref{def:mqt:verifier:l_code} with $t=t_3,q'=q'$ and if $t_3=1$ sets $r_3$ to be the output.  
\item The verifier accepts iff $ r_u=1$.
\end{itemize}
\end{mdframed}

\label{def:mqt:verifier} 
Let $\mathsf{R} $ be a register.  

The verifier's actions are defined as follows: 
\begin{mdframed}
\begin{enumerate}
\item With probability $1/6$, the verifier acts as in Definition \ref{def:mqt:verifier:c} with $D=\mu_1$,
\item With probability $1/6$, the verifier acts as in Definition \ref{def:mqt:verifier:a} with $D=\mu_1$,
\item With probability $1/6$, the verifier acts as in Definition \ref{def:mqt:verifier:v} with $D=\mu_1$,
\item With probability $1/6$, the verifier acts as in Definition \ref{def:mqt:verifier:c} with $D=\mu_2$,
\item With probability $1/6$, the verifier acts as in Definition \ref{def:mqt:verifier:a} with $D=\mu_2$,
\item With probability $1/6$, the verifier acts as in Definition \ref{def:mqt:verifier:v} with $D=\mu_2$,
\end{enumerate}
\end{mdframed}

\label{def:mqt:canonical_prover}
Let $\mathsf{P}$ be a register, $\mathsf{R}$ be a register of $n$ qubits. 
$\mathsf{P, R}$ are initially hold by the prover and initialized by $\ket{0}$. 
For $q'\in [2]$, let $ U'_{q'}$ be a unitary. 
For $i\in [2]$, let $ U_i$ be a unitary. 
\begin{mdframed}
\hfill 

The canonical prover's actions in the first two rounds are defined as follows: At round $i$, 
\begin{itemize}
\item \textnormal{The prover's first step:} 
The prover applies a unitary $ {U}_{i,\mathsf{PR}}$. 
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. The verifier sends the prover the register $\mathsf{R}$. 
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. 
\end{itemize}

The canonical prover's actions in the last round  are defined as follows: 
\begin{itemize}
\item \textnormal{The verifier's first step:} 
The verifier sends $q'\in [2]$ to the prover.
\item \textnormal{The prover's first step:} 
The prover applies a unitary $ {U}'_{q',\mathsf{PR}}$. 
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. The verifier sends the prover the register $\mathsf{R}$. 
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. 
\end{itemize}
\end{mdframed}

[The prover's purified forms]
\label{def:pure_prover}
Let $\mathsf{P}, \mathsf{S}, \mathsf{T_S}$ be a register, $\mathsf{R}$ be a register of $n$ qubits. 
For $q'\in [2]$, let $ U'_{q'}$ be a unitary. 
For $a\in \F_2^k$, define the prover's hermitian forms in the last round as:
\begin{align*}
{\tilde O}'_{q',j,\mathsf{SPRT_S}} = ({U}'_{q', \mathsf{PR}})^{\dagger} \cdot {\tilde O}_{ j, \mathsf{SRT_S}}\cdot {U}'_{q', \mathsf{PR}}.
\end{align*}

[The verifier's clean forms]
\label{def:hermitian_verifier}
Let $\mathsf{P}, \mathsf{D}$ be a register, $\mathsf{R}$ be a register of $n$ qubits. 
Let $D_C$ be defined as in Definition \ref{def:decode}.
For $a\in \F_2^k$, define the verifier's hermitian forms in the first two rounds as:
\begin{align*}
{O}_\mathsf{DR}(a) = D_{C, \mathsf{DR}}^\dagger Z_{\mathsf{D}}(a) D_{C, \mathsf{DR}} .
\end{align*}

[The prover's clean forms]
\label{def:hermitian_prover}
Let $\mathsf{P}, \mathsf{D}$ be a register, $\mathsf{R}$ be a register of $n$ qubits. 
For $q'\in [2]$, let $ U'_{q'}$ be a unitary. 
For $a\in \F_2^k$, define the prover's hermitian forms in the last round as:
\begin{align*}
{O}'_{q',\mathsf{DPR}}(a) = ( U'_{q', \mathsf{PR}})^\dagger O_{\mathsf{DR}}(a)  U'_{q', \mathsf{PR}}.
\end{align*}

\label{def:trans}
Let $ {U}_{i}$ for $i\in[2]$ be defined as in Definition \ref{def:mqt:canonical_prover}. 
For $i<j$, define the transition action from $i$ to $j$ as:
\begin{align*}
{U}_{i\rightarrow j} ={U}_{j} \cdots {U}_{i+2}{U}_{i+1}.
\end{align*}

\label{def:trans_f}
Let $ {U}_{i}$ for $i\in[2]$ be defined as in Definition \ref{def:mqt:canonical_prover}.
For $F\in \{0, 1\}^2, f\in [n]^2$, define the transition action with flips in the purified forms as:
\begin{align*}
{\tilde U}_{1, F, f, \mathsf{SPRT_S}} =&~ {\tilde O}_{f_1, \mathsf{SRT_S}}^{F_1} 
{U}_{1}, \\
{\tilde U}_{2, F, f, \mathsf{SPRT_S}}=&~ {\tilde O}_{f_2,\mathsf{SPRT_S}}^{F_2} {U}_{2}\cdot  {\tilde U}_{1, F, f, \mathsf{SPRT_S}} .
\end{align*}

\label{def:trans_f_herm}
Let $ G_k=[g_1, g_2,\cdots, g_n]^T \in \F_2^{n} \otimes \F_2^k$ be defined as in Definition \ref{def:3c}. 
Let $ {U}_{i}$ for $i\in[2]$ be defined as in Definition \ref{def:mqt:canonical_prover}.
For $F\in \{0, 1\}^2, f\in [n]^2$, define the transition action with flips in the clean forms as:
\begin{align*}
{U}_{1, F, f} =&~  O(g_{f_1})^{F_1} {U}_{1}, \\
{U}_{2, F, f} =&~  O(g_{f_2})^{F_2} {U}_{2} \cdot {U}_{1, F, f}.
\end{align*}

\label{lem:mqt:prob}
Let $\texttt{V},\texttt{P}$ be defined as in Theorem \ref{thm:mqt}. 
Let $D_c$ be the distribution of $ M,F$ in Definition \ref{def:mqt:verifier:c}.
Let $D_v$ be the distribution of $ u$ in Definition \ref{def:mqt:verifier:v}.


Then
$$ \Pr[\text{ \texttt{V} accepts \texttt{P} } ] \geq 1-\Theta(\delta),$$  
if and only if
\begin{itemize}
\item For any $u\in[3], F\in \{0,1\}^2,q'\in[2]$ in the support of $D_v$,
\begin{align*}
\Pr[\text{ validity check passes }~|~F,q',u, D~] \geq 1- \Theta(\delta).
\end{align*}
\item For any $M,F\in\{0, 1\}^2$ in the support of $D_c$,
\begin{align*}
\Pr[\text{ consistency check passes }~|~M,F, D~] \geq 1- \Theta(\delta).
\end{align*}
\item Moreover, 
\begin{align*}
\Pr[\text{ anti-commuting test passes }~|~ D] \geq 1- \Theta(\delta).
\end{align*}
\end{itemize}

\label{lem:7.38}
Let
\begin{align*}
\ket\psi=\ket{\phi}_{\mathsf{PR}}\otimes \ket{0}_{\mathsf{L}} \otimes H^{\otimes l_{\mathsf{L}}}\ket{0}_{\mathsf{T_L}}\;,
