\begin{align*}
\ket\phi=\ket{0}_{\mathsf{PRDS}}\otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S,1}}\otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S,2}}\cdots \otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S, u}},
