\label{lem:mqt:v2:0}
Let $ G_k=[g_1, g_2,\cdots, g_n]^T \in \F_2^{n} \otimes \F_2^k$ be defined as in Definition \ref{def:3c}. 
Let 
\begin{align*}
\ket\phi=\ket{0}_{\mathsf{PRDS}}\otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S,1}}\otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S,2}}\cdots \otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S, u}}\;.
\end{align*}
Then for $q'\in[2]$, 
\begin{align*}
&~ \E_{(f_1, f_2)\sim D}[\|{\tilde O}'_{q', {f_{q'}}}{\tilde U}_{2, F, f}\ket\phi -  {O}'_{q' }(g_{f_{q'}}){\tilde U}_{2, F, f}\ket\phi\|^2]\\
\leq&~ \Theta(\eps)+ \Theta\Big(1- \Pr[\text{ validity check passes }~|~F, q',u=3, D~]  \Big)
\end{align*}

\label{lem:mqt:v2}

Let 
\begin{align*}
\ket\phi=\ket{0}_{\mathsf{PRDS}}\otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S,1}}\otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S,2}}\cdots \otimes H^{\otimes l_\mathsf{S}}\ket{0}_\mathsf{T_{S, u}},
\end{align*}
then for $q'\in[2]$, 
\begin{align*}
&~ \E_{(f_1, f_2)\sim D}[\|{\tilde O}'_{q', {f_{q'}}}{\tilde U}_{2, F, f}\ket\phi -  {O}'_{q' }(g_{f_{q'}}){U}_{2, F, f}\ket\phi\|^2]\\
\leq&~ \Theta(\eps)+ \sum_{u\in[3]}\Theta\Big(1- \Pr[\text{ validity check passes }~|~F, q',u, D~]  \Big).
\end{align*}

\label{lem:mqt:c}
Let $ {U}_{i}$ for $i\in[2]$ be defined as in Definition \ref{def:mqt:canonical_prover}.
Let $\mathsf{P},\mathsf{R}$ be defined as in Definition \ref{def:mqt:canonical_prover}. 
Let $D$ be the sampling distribution of $ M,F$ in Definition \ref{def:mqt:verifier:c}. For any $M,F\in\{0, 1\}^2$ in the support of $D$. Let $ M_u=1$. 

Then
\begin{align*}
&~\E_{(f_1, f_2)\sim D}\|(U_{u\rightarrow 2, \mathsf{PR}} {O}_{\mathsf{DR}}(g_{f_u}) {U}_{u, F, f, \mathsf{DPR}}-{O}'_{u, \mathsf{DPR}}(g_{f_u}) {U}_{2, F, f, \mathsf{DPR}})\ket{0}_\mathsf{DPR}\|^2\\
\leq &~ \Theta(1-\Pr[\text{ consistency check passes }~|~M,F, D])\\
&~\quad+\sum_{ F,q',u}\Theta(1- \Pr[\text{ validity check passes }~|~F, q',u, D~])+\Theta(\eps).
\end{align*}

\label{lem:mqt:a}
Let $ {U}_{i}$ for $i\in[2]$ be defined as in Definition \ref{def:mqt:canonical_prover}.
Let $\mathsf{P},\mathsf{R}$ be defined as in Definition \ref{def:mqt:canonical_prover}. 

Then,
\begin{align*}
&~\E_{(m_1,m_2)\sim D}\|{O}'_{1}(m_1) {O}(m_2) U_{0 \rightarrow 2}\ket{0}-(-1)^{g_{m_1}\cdot g_{m_2}}{ O}(m_2)  U_{2} { O}(m_1) U_{1}\ket{0}\|^2 \\
\leq &~ \Theta(1-\Pr[\text{ anti-commuting test passes }~|~D])\\
&~\quad+\sum_{ F,q',u}\Theta(1- \Pr[\text{ validity check passes }~|~F, q',u, D~])+\Theta(\eps).
\end{align*}

\label{lem:mqt:anti}

Let \begin{align*}
    \rho = U_{0\rightarrow 2}\ket{00}_{\mathsf{PRD}}\bra{00}_{\mathsf{PRD}} U_{0\rightarrow 2}^\dagger.
\end{align*}

Then
\begin{align*}
&~ \E_{(a, b)\sim D}\| O'_{1}(a)O'_{2}(b)-(-1)^{a\cdot b}O'_{2}(b)O'_{1}(a)\|^2_\rho  \\
\leq &~  \sum_{ M,F} \Theta(1-\Pr[\text{ consistency check passes }~|~M,F, D])\\
&~\quad+\Theta(1-\Pr[\text{ anti-commuting test passes }~|~D])\\
&~\quad+\sum_{ F,q',u}\Theta(1- \Pr[\text{ validity check passes }~|~F, q',u,D~])+\Theta(\eps).
\end{align*}

\label{lem:mqt:hp_cp}
Let 
$$ R_1 = \prod_{p\in[n]}P((Z(g_p))_{\mathsf{P}}, \mathsf{R}_p), R_2 = \prod_{p\in[n]}P((X(g_p))_{\mathsf{P}}, \mathsf{R}_p). $$


The prover in Definition \ref{def:mqt:honest_prover} is the prover in Definition \ref{def:mqt:canonical_prover} with:
\begin{align*}
U_1 =&~ R_1,\\
U_2 =&~ R_2\cdot R_{1}^{-1},\\
U'_{1}=&~ R_1\cdot R_{2}^{-1},\\
U'_{2}=&~ I.
\end{align*}

\label{lem:mqt:hp_properties}
For $i\in [2]$, let $ U_i$ be defined as in Lemma \ref{lem:mqt:hp_cp}. For $q'\in [2]$, let $ U'_{q'}$ be defined as in Lemma \ref{lem:mqt:hp_cp}. 
Then:

\begin{itemize}
\item For any $u\in[2]$,
\begin{align*}
{\tilde O}'_{u, j} U_{u\rightarrow 2} = U_{u\rightarrow 2} {\tilde O}_{j}.
\end{align*}
\item Moreover, 
\begin{align*}
{\tilde O}'_{1, j_1} {\tilde O}_{j_2} U_{2} = (-1)^{g_{j_1}\cdot g_{j_2}} {\tilde O}_{j_2} U_{2} {\tilde O}_{j_1}
\end{align*}
\end{itemize}

\label{def:mqt:verifier:m}
Let $\mathsf{R} =(\mathsf{R}_{j})_{j\in[n]}$ be a register. Let $ \mathsf{S}$ be a register held by the verifier and initialized with $ \ket{0}$. Let $ \mathsf{M}$ be a register held by the verifier. Let $ \mathsf{T_S} $ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{S}}} \ket{0}$. Let $m\in [n]$. Let $\tilde{O}_{m,\mathsf{SRT_S}}$ be defined as in Definition~\ref{def:mqt:read_self_corr}.
\begin{mdframed}
\begin{itemize}
\item \textnormal{The prover's first step:} 
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. 
The verifier measures $\mathsf{T_S}$. Then, the verifier
applies $C({\tilde O}_{m,\mathsf{SRT_S}}, \mathsf{M})$. 
The verifier sends the prover the register $\mathsf{R}$. 
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. 
\end{itemize}
\end{mdframed}

\label{def:mqt:verifier:measure} 
Let $ a,b,c\in \{0, 1\}^k$ such that $ a\cap b = b\cap c = c\cap a = \emptyset $. 
Let $\mathsf{R} =(\mathsf{R}_{j})_{j\in[n]}$ be a register. Let $ \mathsf{S}$ be a register held by the verifier and initialized with $ \ket{0}$. Let $ \mathsf{M}$ be a register held by the verifier and initialized with $\ket{+}$. 
Let $ \mathsf{T_{S, i}} $ for $i\in [3]$ be a register held by the verifier and initialized with $H^{\otimes l_{\mathsf{S}}} \ket{0}$. 
The verifier's actions are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The verifier sets $m_1 = b+c, m_2 = a+c$.
\item The verifier repeats the verifier's actions in Definition \ref{def:mqt:verifier:block} twice. In the $i$-th time, the verifier acts as in Definition \ref{def:mqt:verifier:block} with $m=m_i$.
\item In the end, the verifier applies the phase gate $|c|$ times as $S^{|c|}_{\mathsf{M}}$. Then, the verifier applies $ H_{\mathsf{M}}$, measures the register $\mathsf{M}$ under $Z_\mathsf{M}$, and outputs the measurement result. 
\end{itemize}

\end{mdframed}

\label{def:mqt:hp_last_energy}
Let $\mathsf{P}$ be a register of $k$
qubits. 
Let $p,q$ be as in Theorem \ref{thm:clifford_ham}, $s,N$ be as in Lemma \ref{lem:c_ham_amp}. 
Use the notation for $H$, $O_{i,j}$,  and $a_{i,j}, b_{i,j}, c_{i,j}$ from Definition~\ref{def:mqdef}
Let $$ C(x) = \bigoplus_{i\in [N]} \big(1 \oplus \bigvee_{j\in [5]} x_{i,j} \big) ,$$ 
where $x=(x_{i,j})_{i \in [N], j\in[5]}$. Let $E$ be the encoding circuit of the codes in Theorem \ref{thm:ltc}, $D$ the decoding circuit of the codes in Theorem \ref{thm:ltc}, and $T$ the  code tester 
circuit of the codes in Theorem \ref{thm:ltc}.

\begin{mdframed}
\begin{itemize}
\item The verifier sends the prover $l_i\in[m]$ for $i\in[N]$.
\item For $i\in [N],j\in [5]$, the honest prover measures $\mathsf{P}$ under observable 
\begin{align*}
\underbrace{I\otimes I \otimes \cdots \otimes I}_{i-1} \otimes O_{l_i, j} \otimes \underbrace{I\otimes I \otimes \cdots \otimes I}_{N-i},
\end{align*}
and stores the  measurement result in $r_{i,j}$. Let \begin{align*}
    r=(r_{i,j})_{i\in [N], j\in [5]}.
\end{align*}
\item The honest prover sends the verifier $E(r)$, $C(r)$, and $w$, where $w$ is a witness such that the verifier in Theorem \ref{thm:pcpp} with explicit input the circuit $C(D(\cdot)) + C(r) + 1$ and implicit input the input of the circuit $E(r)$ accepts the PCPP witness $w$.
\item The verifier sends the prover $ t\in_R\F_2^{5N}$.
\item Let $ C'(r)=r\cdot t$. The prover sends the verifier $C'(r)$ and $w'$, where $w'$ is a witness such that the verifier in Theorem \ref{thm:pcpp} with explicit input $V(C'(D(\cdot )) + C'(r) + 1)$ and implicit input $E(r)$ accepts the witness $w'$.
\end{itemize}

\end{mdframed}

\label{def:mqt:hp_energy} 
The honest prover's actions are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The honest prover acts as in Definition \ref{def:mqt:honest_prover} for the first two rounds. 
\item The verifier sends the prover a symbol ``EnergyTests" or ``QubitsTests". 
\item If the symbol is ``QubitsTests", the honest prover continues as in Definition \ref{def:mqt:honest_prover}. If the symbol is ``EnergyTests", the honest prover acts as in Definition \ref{def:mqt:hp_last_energy}.
\end{itemize}

\end{mdframed}

\label{def:mqt:verifier_e_last}
Let $ c,e\in \{0, 1\}$. Let $ t\in\F_2^{5N}$. Let $ l_i\in [m]$ for $i\in [N]$. 
Let $E$ be the encoding circuit of the codes in Theorem \ref{thm:ltc}, $D$ be the decoding circuit of the codes in Theorem \ref{thm:ltc}, $T$ be the  code tester 
circuit of the codes in Theorem \ref{thm:ltc}.

\begin{mdframed}
\begin{itemize}
\item The verifier sends $l_i\in[m]$ for $i\in[N]$ to the prover. 
\item The prover sends the verifier $M, o, w$: the implicit input of the PCPP, the value supposed to be $C(D(M))$ (which is also used to build the explicit input of the PCPP), and the witness of the PCPP.
\item The verifier sets $a_1=1$ if and only if $o=0$ and the verifier in Theorem \ref{thm:pcpp}, when run a constant number of times, accepts each time with the following parameters:
explicit input $x = C(D(\cdot)) + o + 1 \wedge T(\cdot)$, implicit input $ y = M$, PCPP proof  $\pi= w$.
\item The verifier sends $t$ to the prover.
\item The prover sends the verifier $o',w' $.  The verifier sets $a_2=1$ if and only if $o'=e$ and the verifier in Theorem \ref{thm:pcpp}, when run a constant number of times, accepts each time with the following parameters:
$x = C'(D(\cdot)) + o' + 1 \wedge T(\cdot)$, $y = M$, $\pi= w'$. 
\item If $c=0$, the verifier accepts iff $a_1=1$. If $ c=1$, the verifier accepts iff $a_2=1$.
\end{itemize}
\end{mdframed}

\label{def:mqt:verifier_energy} 
Let $p,q$ be as in Theorem \ref{thm:clifford_ham}, $s,N$ be as in Lemma \ref{lem:c_ham_amp}. Let $H$, $H_i$, and $O_{i,j}$ be as in Definition~\ref{def:mqt:hp_last_energy}.

The verifier's actions are defined as follows: 

\begin{mdframed}
\begin{enumerate}
\item The verifier samples $ t\in_R\F_2^{5N}$ and samples $l_i\in_R[m]$ for $i\in [N]$. Let
\begin{align*}
O = \prod_{i\in [N], j\in [5]} O_{l_i,j}^{t_{i,j}}\;, 
\end{align*}
with Pauli representation
\begin{align*}
O =  (-1)^{d} X(a) Z(b) Y(c)\;.  
\end{align*}
\item \textnormal{ (Qubits tests:)} With probability $1/3$, the verifier acts as in Definition \ref{def:mqt:verifier} and sends the prover a symbol ``QubitsTests'' after the end of the first two rounds. 
\item \textnormal{ (Energy tests:)} With probability $1/3$, the verifier repeats the verifier’s action in Definition \ref{def:mqt:verifier:block} for $2$ times. Each time, the verifier acts as in Definition \ref{def:mqt:verifier:block} 
with $M = 0, F = 0, m = 0, f = 0$. In the end, the verifier sends the prover a symbol ``EnergyTests'' and acts as in Definition \ref{def:mqt:verifier_e_last} with $ c=0,e=0$. 
\item \textnormal{ (Energy consistency tests:)} With probability $1/3$, the verifier acts as in Definition \ref{def:mqt:verifier:measure} with $a=a, b=b,c=c$. Let $e$ be the output. In the end, the verifier sends the prover a symbol ``EnergyTests'' and acts as in Definition \ref{def:mqt:verifier_e_last} with $ c=1, e=e+d, t=t, l_i=l_i$ for $i\in [N]$. 
\end{enumerate}
\end{mdframed}

\label{def:mqt:canonical_prover_e}
Let $\mathsf{P}$ be a register. 
Let $h = |E(1^{5N})|$ be
the output length of the encoding circuit of the codes in Theorem \ref{thm:ltc}. 
Let $g$ denote the length of the witness used by the verifier in Theorem \ref{thm:pcpp}, where the circuit has input size $h$.
For $l\in [m]^N$, let $P_{l}=\{P_{l,M,o,w}\}_{M\in \F_2^h,o\in\F_2,w\in\F_2^{g}}$ be a projective measurement acting on $\mathsf{P}$. 
\begin{mdframed}
\hfill 

The canonical prover's actions in the last round  of the energy tests are defined as follows: 
\begin{itemize}
\item \textnormal{The verifier's first step:} 
The verifier sends $l_i\in [m]$ for $i\in[N]$ to the prover.
\item \textnormal{The prover's first step:} 
The prover measures according to $ {P}_{l,\mathsf{P}}$. 
The prover sends the verifier the measurement result $M$ and $o,w$.
\item \textnormal{The verifier's second step:} 
The verifier sends the prover $t\in \F_2^{5N}$. 
\item \textnormal{The prover's second step:} 
The prover sends verifier $o',w'$. 
\end{itemize}
\end{mdframed}

\label{lem:mqt:ec}





Let 
\begin{align*}
P'_{l,t}=\sum_{M,o,w} 1_{D(M)\cdot t=0} P_{l,M,o,w} - \sum_{M,o,w} 1_{D(M)\cdot t=1} P_{l,M,o,w}.
\end{align*}


If for any $ M,F,D,u,q'$,
\begin{align*}
\Pr[\text{ consistency check passes }~|~M,F, D]\geq&~ 1- \eps'\\
\Pr[\text{ validity check passes }~|~F, q',u, D~] \geq&~ 1-\eps'\\
 \Pr[\text{ anti-commuting test passes }~|~D]\geq&~ 1-\eps'.
\end{align*}

Then 
\begin{align*}
&~ \E_{l\in [m]^N, t\in \F_2^{5N}}
\|(
P'_{l,t}-
V^\dagger ((-1)^{d}\cdot  X(a)Z(b)Y(c)\otimes I) V
)U_{0\rightarrow 2}\ket{0} \|^2\\
\leq &~\Theta(\eps+\delta+\eps'),
\end{align*}
where $a,b,c,d$ are defined as in Definition \ref{def:mqt:verifier_energy}, $\eps$ is the self-correction parameter from Theorem~\ref{thm:3c_code} and $\delta$ is the PCPP proximity parameter from Theorem~\ref{thm:pcpp}.

\label{lem:q_sound_had}
Let $ d' > d$. Let $ \{P_s\}_{s\in \F_2^n}$ be an orthogonal projective measurement on $ \C^{d}$.
Let $ O_i$ be observables 
on $\C^{d'}$ for $i\in [n]$. Let $ V:\C^{d}\rightarrow\C^{d'}$ be an isometry. 
For $t\in \F_2^n$, let
\begin{align*}
O^{(t)} = \prod O^{t_i}_i.
\end{align*}
Moreover, let 
\begin{align*}
P^{(t)}=\sum_s (-1)^{st}\cdot P_s.
\end{align*}
Then
\begin{align*}
\sum_s \Big\|P_s - V^\dagger \prod_{i\in [n]} \frac{I+(-1)^{s_i}O_i}{2} V\Big\|_\rho^2 \leq 
\E_t \|P^{(t)}- V^\dagger O^{(t)} V\|_\rho^2 +1 - \E_t \|V^\dagger O^{(t)} V\|_\rho^2. 
\end{align*}

\label{lem:8.13}
\begin{align*}
\E_l\sum_s \Big\|\sum_{M,o,w} 1_{D(M)=s} P_{l,M,o,w}- V^\dagger \prod_{i\in [n]} \frac{I+(-1)^{s_i}O_{i,j}}{2} V\Big\|_\rho^2 
\leq 
\Theta(\sqrt{\eps+\eps'+\delta})\;. 
\end{align*}

\label{lem:e_imply}

\begin{align*}
\Pr[\text{energy test passes}]\leq  \eps + \E_{l\in_R [m]^N} 
 \Big\|  \sum_{M,o,w} 
1_{C(D(M))=0} 
\cdot P_{l,M,o,w} U_{0\rightarrow 2}\ket{0}\Big\|^2.
\end{align*}

\label{lem:ec_in_e}
\begin{align*}
&~ \E_{l\in_R [m]^N} 
 \Big\| \sum_{M,o,w} 
1_{C(D(M))=0} 
\cdot P_{l,M,o,w} U_{0\rightarrow 2}\ket{0}\Big\|^2 \\
\leq  &~
\Theta(\sqrt{\eps+\eps'+\delta})+ 1.01\cdot \E_{l\in_R [m]^N} 
 \sum_{s} 1_{C(s)=0}\Big\| V^\dagger \prod_{i\in [N], j\in [5]} \frac{I+(-1)^{s_{i,j}}O_{l_i,j}}{2} V  U_{0\rightarrow 2}\ket{0}\Big\|^2\;.
\end{align*}

\label{lem:measP2e}
Let $H$, $H_i$, $O_{i,j}$ and $C$ be as in Definition~\ref{def:mqt:hp_last_energy}.
Then,
\begin{align*}
&~\E_{l\in_R [m]^N} 
 \sum_{s} 1_{C(s)=0}\Big\| \prod_{i\in [N], j\in [5]}\underbrace{I\otimes I \cdots \otimes I}_{i-1} \otimes\frac{I+(-1)^{s_{i,j}}O_{l_i,j}}{2}\otimes \underbrace{I\otimes I \cdots \otimes I}_{N-i} \ket{\phi}\Big\|^2\\
=&~ \bra{\phi} \frac{1+(1-2H)^{\otimes N} }{2}\ket{\phi} \;.
