\label{def:s:honest_prover_sqt:block}
Let $\mathsf{P}$ be a register of $1$ qubit, $\mathsf{R}$ be a register of $1$ qubit. 
$\mathsf{P, R}$ are initially hold by the prover. 
Let $ O_1,O_2$ be observables on register $\mathsf{P}$. 
\begin{mdframed}
\begin{itemize}
\item \textnormal{The prover's first step:} 
The prover applies the following unitary 
\begin{align*}
P(O_{\mathsf{P}}, \mathsf{R}). 
\end{align*}
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. The verifier sends the prover the register $\mathsf{R}$. 
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. The prover applies the following unitary 
\begin{align*}
(P(O_{\mathsf{P}}, \mathsf{R}))^{-1}. 
\end{align*}
\end{itemize}

\end{mdframed}

\label{def:s:honest_prover_sqt:last}
Let $\mathsf{P}$ be a register of $1$ qubits. 
$\mathsf{P}$ is initially hold by the prover.  
\begin{mdframed}
\begin{itemize}
\item \textnormal{The verifier's first step:} The verifier sends the prover $q'\in [2]$.
\item \textnormal{The prover's first step:} 
The prover measures $\mathsf{P}$ under observable $ Z$ if $q'=1$, under observable $X$ if $q'=2$ and returns the measurement result. 
\end{itemize}
\end{mdframed}

\label{def:s:sqt:honest_prover} 
Let $\mathsf{P}$ be a register of $1$ qubits, $\mathsf{R}$ be a register of $1$ qubits. $\mathsf{P, R}$ are initially hold by the prover and initialized by $\ket{0}$. 

The honest prover's actions are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The honest prover acts as in Definition \ref{def:s:honest_prover_sqt:block} with $ O=Z$. 
\item The honest prover acts as in Definition \ref{def:s:honest_prover_sqt:block} with $ O=X$. 
\item In the end, the honest prover acts as in Definition \ref{def:s:honest_prover_sqt:last}.  
\end{itemize}
\end{mdframed}

\label{def:s:verifier_sqt:block}
Let $\mathsf{R} $ be a register. Let $M,F\in \{0,1\}$. 
\begin{mdframed}
\begin{itemize}
\item \textnormal{The prover's first step:} 
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. 
If $F=1$, verifier applies $Z_{\mathsf{R}}$. If $M=1$, verifier
measures $Z_{\mathsf{R}}$ and outputs the measurement result. 
The verifier sends the prover the register $\mathsf{R}$. 
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. 
\end{itemize}
\end{mdframed}

\label{def:s:verifier_sqt:last}
Let $q'\in [2]$. 
\begin{mdframed}
\begin{itemize}
\item \textnormal{The verifier's first step:} 
The verifier sends $q'$ to the prover.
\item \textnormal{The prover's first step:} 
The prover returns a single bit $r'$.  
\end{itemize}
\end{mdframed}

\label{def:s:sqt:verifier:c} 
Let $\mathsf{R} $ be a register.  
The verifier's action are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The verifier samples $u\in_R [2]$, sets $M_u=1$, and sets $ M_i =0$ for $i \neq u, i\in [2]$. 
\item If $M_1=1$, the verifier sets $F_i = 0$ for $i\in [2]$. If $M_2=1$, the verifier sets $F_1 \in_R \F_2$, $F_2 = 0$. 
\item The verifier repeats the verifier's action in Definition \ref{def:s:verifier_sqt:block} for $2$ times. In the $i$-th time, the verifier acts as in Definition \ref{def:s:verifier_sqt:block} with $ M = M_i, F = F_i$, if $M_i=1$, sets $r_i$ be the output. 
\item In the end, the verifier acts as in Definition \ref{def:s:verifier_sqt:last} with $q'= u$. Let $r'$ denote the bit that the verifier received from the prover.  
\item The verifier accepts iff $ r_u=r'$.
\end{itemize}
\end{mdframed}

\label{def:s:sqt:verifier:a} 
Let $\mathsf{R} $ be a register.  
The verifier's action are defined as follows: 
\begin{mdframed}
\begin{itemize}
\item The verifier sets $M_1=1, F_1=0, M_2=0, F_2=1$.  
\item The verifier repeats the verifier's action in Definition \ref{def:s:verifier_sqt:block} for $2$ times. In the $i$-th time, the verifier acts as in Definition \ref{def:s:verifier_sqt:block} with $ M = M_i, F = F_i$, if $M_i=1$, sets $r_i$ be the output. 
\item In the end, the verifier acts as in Definition \ref{def:s:verifier_sqt:last} with $q'= 1$ (corresponding to the symbol ``Z"). Let $r'$ denote the bit that the verifier received from the prover.  
\item The verifier accepts iff $ r_1=r'\oplus 1$.
\end{itemize}
\end{mdframed}

\label{def:s:sqt:verifier} 
Let $\mathsf{R} $ be a register.  

The verifier's action are defined as follows: 
\begin{mdframed}
\begin{enumerate}
    \item With probability $1/2$, the verifier acts as in Definition \ref{def:s:sqt:verifier:c},
    \item With probability $1/2$, the verifier acts as in Definition \ref{def:s:sqt:verifier:a}.
\end{enumerate}
\end{mdframed}

\label{def:s:sqt:canonical_prover}
Let $\mathsf{P}$ be a register, $\mathsf{R}$ be a register of $1$ qubits. 
$\mathsf{P, R}$ are initially hold by the prover and initialized by $\ket{0}$. For $q'\in [2]$, let $O'_{q'}$ be an observable such that $ (O'_{q'})^2=I$. 
For $i\in [2]$, let $ U_i$ be a unitary. 
\begin{mdframed}
\hfill 

The canonical prover's actions in the first two rounds are defined as follows: At round $i$, 
\begin{itemize}
\item \textnormal{The prover's first step:} 
The prover applies a unitary $ {U}_{i,\mathsf{PR}}$. 
The prover sends the verifier the register $\mathsf{R}$.
\item \textnormal{The verifier's first step:} 
The verifier receives the register $\mathsf{R}$ from the prover. The verifier sends the prover the register $\mathsf{R}$. 
\item \textnormal{The prover's second step:} 
The prover receives the register $\mathsf{R}$ from the verifier. 
\end{itemize}

The canonical prover's actions in the last round  are defined as follows: 
\begin{itemize}
\item \textnormal{The verifier's first step:} 
