Since $\tree$ is a path, the only elimination ordering of $\var{\textsc{QParity}_2}$ that agrees with $\tree$ is $\V=(x_1, z_1,x_2, z_2, u)$. We initialize $\Q^{(0)}=\exists x_1 x_2 \forall u \exists z_1 z_2$ and $\mathcal{F}^{(0)}=\{\{\phi\}\}$ with $\phi=(x_1 \lor \overline{z_1}) \land (\overline{x_1} \lor z_1)  \land (u \lor \overline{z_2}) \land (\overline{u} \lor z_2)  \land  (\overline{z_{2}} \lor x_{2} \lor z_1) \land (z_{2} \lor \overline{x_{2}} \lor z_1) \land (z_{2} \lor x_{2} \lor \overline{z_1}) \land (\overline{z_{2}} \lor \overline{x_{2}} \lor \overline{z_1})$.

Now observe that $x_1$, the first variable that is eliminated in $\V$, is existential but does not satisfy Rule~\ref{itm:R2} since $z_1 \in \rchi(\forget{x_1})$ and $x_1\preceq_{\D_{\mathrm{trv}}}z_1$. Therefore, Rule~\ref{itm:R4} is applied, which means that $\mathcal{F}^{(1)}$ is computed as $\strext{\{\phi\}}{x_1}$ via strategy extension. Since $x_1$ does not depend on any universal variable, the only two strategies for $x_1$ are setting it to constant 0 or 1. Therefore, we have $\strext{\{\phi\}}{x_1}=\{\{\psi_{x_1=0}\}, \{\psi_{x_1=1}\}\}$ with $\psi_{x_1=0}=(\overline{z_1}) \land (u \lor \overline{z_2}) \land (\overline{u} \lor z_2) \land \mathrm{xor}(z_2, x_2, z_1)$ and $ \psi_{x_1=1}= (z_1)  \land (u \lor \overline{z_2}) \land (\overline{u} \lor z_2) \land \mathrm{xor}(z_2, x_2, z_1)$, where $\mathrm{xor}(z_2, x_2, z_1)=(\overline{z_{2}} \lor x_{2} \lor z_1) \land (z_{2} \lor \overline{x_{2}} \lor z_1) \land (z_{2} \lor x_{2} \lor \overline{z_1}) \land (\overline{z_{2}} \lor \overline{x_{2}} \lor \overline{z_1})$.
The updated prefix is $\Q^{(1)}=\exists x_2 \forall u \exists z_1 z_2$.

Next, $z_1$ is eliminated. Observe that the node in which $z_1$ is forgotten does not contain any variable that depends on $z_1$. Hence, we apply \ref{itm:R2}, that is, we separately resolve over $z_1$ in all matrices. As a result, we obtain $\mathcal{F}^{(2)}=\{\pi_1=\{\res{\psi_{x_1=0}}{z_1}\}, \pi_2=\{\res{\psi_{x_1=1}}{z_1}\}\}$ with $\res{\psi_{x_1=0}}{z_1}=(u \lor \overline{z_2}) \land (\overline{u} \lor z_2)  \land  (\overline{z_{2}} \lor x_{2}) \land (z_{2} \lor \overline{x_{2}})$ and $\res{\psi_{x_1=1}}{z_1}=(u \lor \overline{z_2}) \land (\overline{u} \lor z_2)  \land (z_{2} \lor x_{2} ) \land (\overline{z_{2}} \lor \overline{x_{2}})$. The new prefix is $\Q^{(2)}=\exists x_2 \forall u \exists z_2$.

Now we eliminate $x_2$ via \ref{itm:R4}. This gives rise to $\mathcal{F}^{(3)}=\strext{\pi_1}{x_2}\cup \strext{\pi_2}{x_2}$. Note that again, the only possible strategies for $x_2$ are setting it to constant 0 or 1, and we account for both with respect to each set of $\mathcal{F}^{(2)}$. More specifically, we obtain 
 $\strext{\pi_1}{x_2}=\{\{\psi^{\pi_1}_{x_2=0}, \psi^{\pi_1}_{x_2=1}\}\}$ and $\strext{\psi_2}{x_2}=\{\{\psi^{\pi_2}_{x_2=0}, \psi^{\pi_2}_{x_2=1}\}\}$, where $\psi^{\pi_1}_{x_2=0}=(u \lor \overline{z_2}) \land (\overline{u} \lor z_2)  \land  \overline{z_{2}}$, $\psi^{\pi_1}_{x_2=1}=(u \lor \overline{z_2}) \land (\overline{u} \lor z_2)  \land z_{2} $, $\psi^{\pi_2}_{x_2=0}=(u \lor \overline{z_2}) \land (\overline{u} \lor z_2)  \land z_{2} $, and $\psi^{\pi_2}_{x_2=1}=(u \lor \overline{z_2}) \land (\overline{u} \lor z_2)  \land \overline{z_{2}}$. In particular, this would amount to $\mathcal{F}^{(3)}=\{\{\psi^{\pi_1}_{x_2=0}, \psi^{\pi_1}_{x_2=1}\} , \{\psi^{\pi_2}_{x_2=0}, \psi^{\pi_2}_{x_2=1}\}\}$. However, since $\psi^{\pi_1}_{x_2=0}=\psi^{\pi_2}_{x_2=1}$ and $\psi^{\pi_1}_{ x_2=1}=\psi^{\pi_2}_{x_2=0}$, the set $\mathcal{F}^{(3)}$ simplifies to $\{\{\psi^{\pi_1}_{x_2=0}, \psi^{\pi_1}_{x_2=1}\}\}$. The new matrix is $\Q^{(3)}=\forall u \exists z_2$.

As a penultimate step, we eliminate $z_2$ by Rule~\ref{itm:R2}, which creates $\mathcal{F}^{(4)}=\{\{\overline{u}, u\}\}$ and $\Q^{(4)}=\forall u$.
Finally, $u$ is eliminated by Rule~\ref{itm:R3}, which performs reduction separately on the remaining matrices $\overline{u}$ and $u$. This results in $\mathcal{F}^{(5)}=\{\{\bot, \bot\}\}$ and an empty prefix. Since each set in $\mathcal{F}^{(5)}$ contains only matrices that in turn contain the empty clause, the derivation sequence witnesses the fact that $\textsc{QParity}_2$ is false.

\label{def:structuredtd}
A trunk-aligned tree decomposition $\mathcal{T}=(\mathbf{T},\rchi)$ of $(\Phi, \D)$ is \emph{structured} if each of its leaves $w'$ satisfies $|\rchi(w')|=k+1$, and each bag $X\in \{\rchi(w)~|~w\in V(\mathbf{T})\}$ that is a separator of $G_\Phi$ satisfies the following conditions:
\begin{enumerate}
\item There exists a designated connected component of $G_{\Phi}-X$ denoted $C^X_\downarrow$, and possibly also a second designated connected component of $G_{\Phi}-X$ denoted $C^X_\uparrow$. Let $C^X_1,\dots,C^X_u$ be all remaining connected components of $G_{\Phi}-X$ ordered according to $\prec^*$;
 \item There exists a \emph{guiding sequence} of nodes $z_0,\dots,z_{u}$ in $\rchi^{-1}(X)$ which all occur on a single leaf-to-root path of $\mathbf{T}$ and every node in $\rchi^{-1}(X)$ is either in the guiding sequence or a child of a node in the guiding sequence;
\item For each $i\in [u]$, the vertices of $C^X_i$ occur solely in bags of nodes whose path to $\rt$ contains $z_{i}$ but not $z_{i-1}$;
\item  The vertices of $C^X_\uparrow$ occur solely in bags of nodes whose path to $\rt$ does not contain $z_u$ and the vertices of $C^X_\downarrow$ occur solely in bags of nodes whose path to $\rt$ contains~$z_0$.\todo{If time, add a picture to illustrate this definition.}
   \end{enumerate}

\label{lem:classify}
Let $\mathcal{T}=(\mathbf{T},\rchi)$ be a structured trunk-aligned tree decomposition of $(\Phi,\D)$ with width $k$, and let $X$ be a set of at most $k+1$ variables in $V(G_{\Phi})$. If $X$ is not a separator of~$G_\Phi$, then $|\rchi^{-1}(X)|\leq 1$. Otherwise, every node $w\in \rchi^{-1}(X)$ is:
\begin{itemize}
\item an element $z_i$ in the guiding sequence, or
\item a child of an element $z_i$ in the guiding sequence.
\end{itemize}
In the former case, $w$ is the root of a subtree of $\mathbf{T}$ whose bags span $C^X_\downarrow$, $C^X_1,\dots, C^X_i$ but no other connected component of $G_\Phi-\rchi(w)$. In the latter case, $w$ is the root of a subtree of~$\mathbf{T}$ whose bags span only $C^X_i$ but no other connected component of $G_\Phi-\rchi(w)$.

\label{thm: mld_main}
    Assuming $\ETH$, there exist constants $\gamma > 1$ and $\delta>0$, such that for any algorithm that takes as input a matrix $\vec{H}\in \F_q^{d \times N}$, a vector $\vec{u}\in\F_q^{d}$ and a parameter $k\in\N$, it must take $ N^{\delta k}$ time to distinguish the following two cases:
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec x\in\F_q^{N}$ with $\|\vec x\|_0\le k$ such that $\vec H\vec x=\vec u$.
        \item $\no$ Case: For every $\vec x\in\F_q^{N}$ with $\|\vec x\|_0\le \gamma k$, we have $\vec H\vec x\neq\vec u$.
    \end{itemize}

\label{thm: mld_main_2}
    Assuming randomized $\ETH$, there exist constants $\gamma > 1$ and $\delta,\varepsilon>0$, such that for any algorithm that takes as input a matrix $\vec{H}\in \F_q^{d \times N}$, a vector $\vec{u}\in\F_q^{d}$ and an integer $k\in\N$ such that $2\le k\le N^\varepsilon$, it must take $N^{\delta k}$ time to distinguish the following two cases:
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec x\in\F_q^{N}$ with $\|\vec x\|_0\le k$ such that $\vec H\vec x=\vec u$.
        \item $\no$ Case: For every $\vec x\in\F_q^{N}$ with $\|\vec x\|_0\le \gamma k$, we have $\vec H\vec x\neq\vec u$.
    \end{itemize}

A $\gapmaxlinq$ instance $(\vec A,\vec b)$ consists of an $m \times n$ matrix $\vec A \in \F_q^{m \times n}$ and a vector $\vec{b} \in \F_q^m$.
The objective of the problem is to distinguish between the following cases.
\begin{itemize}
    \item $\yes$ Case: There exists $\vec{x}\in \F_q^n$ such that $\|\vec A\vec x-\vec b\|_0\le (1-c)m$.
    \item $\no$ Case: For every $\vec{x}\in \F_q^n$, $\|\vec A\vec x-\vec b\|_0> (1-s)m$.
\end{itemize}

\label{def:gmld}
    A $\gapmldq$ instance $(\vec H,\vec u,\ell)$ consists of a $d\times n$ matrix $\vec H \in \F_q^{d\times n}$, a target vector $\vec u \in \F_q^d$ and a value $\ell$. The goal is to distinguish between the following cases.
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec x\in\F_q^{n}$ with $\|\vec x\|_0\le \ell$ such that $\vec H\vec x=\vec u$.
        \item $\no$ Case: For every $\vec x\in\F_q^{n}$ with $\|\vec x\|_0\le \gamma\ell$, we have $\vec H\vec x\neq\vec u$.
    \end{itemize}

\label{def:gap-MLD}\label{def:gapkmld}
    A $\gapkmldq$ instance $(\vec H,\vec u)$ consists of a $d\times n$ matrix $\vec H \in \F_q^{d\times n}$, a target vector $\vec u \in \F_q^d$ and a parameter $k\in\mathbb{N}$. The goal is to distinguish between the following cases.
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec x\in\F_q^{n}$ with $\|\vec x\|_0\le k$ such that $\vec H\vec x=\vec u$.
        \item $\no$ Case: For every $\vec x\in\F_q^{n}$ with $\|\vec x\|_0\le \gamma k$, we have $\vec H\vec x\neq\vec u$.

    \end{itemize}

\label{def:gap-NCP}
    A $\gapkncpq$ instance $(\vec A,\vec t)$ consists of a $n\times d$ matrix $\vec A \in \F_q^{n\times d}$, a target vector $\vec t \in \F_q^n$ and a parameter $k\in\mathbb{N}$. The goal is to distinguish between the following cases.
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec{x}\in \F_q^d$ such that $\|\vec A\vec x-\vec t\|_0\le k$.
        \item $\no$ Case: For every $\vec{x}\in \F_q^d$, $\|\vec A\vec x-\vec t\|_0> \gamma k$.
    \end{itemize}

\label{def:gap-CVP}
    A $\gapkcvpp$ instance $(\vec A,\vec t)$ consists of a $n\times d$ matrix $\vec A \in \Z^{n\times d}$, a target vector $\vec t \in \Z^n$ and a parameter $k\in\mathbb{N}$. The goal is to distinguish between the following cases.
    \begin{itemize}
        \item $\yes$ Case: There exists $\vec{x}\in \Z^d$ such that $\|\vec A\vec x-\vec t\|_p\le k$.
        \item $\no$ Case: For every $\vec{x}\in \Z^d$, $\|\vec A\vec x-\vec t\|_p> \gamma k$.
    \end{itemize}

\label{lem:maxlin2mld}
    There exists a polynomial-time reduction that takes as input a $\gapmaxlin$ instance $(\vec A,\vec b)$ where $\vec{A} \in \mathbb{F}_q^{m \times n}$, $\vec{b} \in \mathbb{F}_q^m$ and $0<s<c<1$. The reduction outputs a $\gapmldq$ instance $(\vec H,\vec u,\ell)$ where $\vec{H}\in \mathbb{F}_q^{d\times m}\ (d\le m)$, $\vec{u} \in \mathbb{F}_q^d$, $\ell = (1-c)m$ and $\gamma = \frac{1-s}{1-c}$. This reduction satisfies the following properties:
    \begin{itemize}
        \item \textbf{Completeness:} If there exist $\vec{x} \in \mathbb{F}_q^n$ and $\vec{e} \in \mathbb{F}_q^m$ such that $\|\vec{e}\|_0 \le (1-c)m$ and $\vec{A}\vec{x} + \vec{e} = \vec{b}$, then there exists $\vec x'\in\F_q^m$ with $\|\vec x'\|_0\le\ell$ such that $\vec H\vec x'=\vec{u}$.

        \item \textbf{Soundness:} If for every $\vec{x} \in \mathbb{F}_q^n$ and $\vec{e} \in \mathbb{F}_q^m$ satisfying $\vec{A}\vec{x} + \vec{e} = \vec{b}$, we have $\|\vec{e}\|_0 > (1-s)m$, then there is no $\vec x'\in\F_q^m$ with $\|\vec x'\|_0\le\gamma\ell$ such that $\vec H\vec x'=\vec{u}$.
    \end{itemize}

\label{lem:naive_group}
    For every $\varepsilon>0$, there exists a reduction that takes as input an integer $k\in\N$, a $\gapmldq$ instance $(\vec M,\vec u,\ell)$ where $\vec M\in \mathbb{F}_q^{d\times m}$, $\vec{u} \in \mathbb{F}_q^d$, and $\frac{k}{\varepsilon}<\ell<\frac{m}{\gamma}$. The reduction outputs a new matrix $\vec{M}_k\in\F_q^{d\times m'}$ in $(m')^{O(1)}$ time, which satisfies the following properties:
    \begin{itemize}
        \item \textbf{Size:} $m'= 2^{O(\frac{m \log k}{k})}$.

        \item \textbf{Completeness:}
        If there exists $\vec{x}\in\F_q^{m}$ with $\|\vec x\|_0\le\ell$ such that $\vec M\vec x=\vec{u}$, then there exists $\vec y\in\F_q^{m'}$ with $\|\vec y\|_0\le k$ such that $\vec M_k\vec y=\vec{u}$.

        \item \textbf{Soundness:}
        If there is no $\vec{x}\in\F_q^{m}$ with $\|\vec x\|_0\le\gamma\ell$ such that $\vec M\vec x=\vec{u}$, then for $\gamma' = \gamma-\varepsilon$, there is no $\vec{y}\in\F_q^{m'}$ with $\|\vec y\|_0\le\gamma' k$ such that $\vec M_k\vec y=\vec{u}$.
    \end{itemize}

A $(U,k,\alpha,\varepsilon)$-cover family  is a collection $\Scal\subseteq 2^{U}$ of subsets of $U$, such that
\begin{itemize}
    \item (C1) For every $S\in\Scal$, $|S|\le\frac{(1+\varepsilon)\alpha |U|}{k}$.
    \item (C2) For every $\tilde{S}\subseteq U$ with $|\tilde{S}|\le\alpha |U|$, there exists $\{T_1,\dots,T_k\}\subseteq\Scal$ such that $\bigcup_{i\in[k]}T_i=\tilde{S}$. Moreover, $T_i\cap T_j=\emptyset$ for every $i\neq j\in[k]$.
\end{itemize}

\label{lem:cover_group}
    There exists a reduction that takes as input an integer $k\in\N$, an $([m],k,\alpha,\varepsilon)$-cover family $\Scal\subseteq 2^{[m]}$, and a $\gapmldq$ instance $(\vec M,\vec u,\alpha m)$ where $\vec M\in \mathbb{F}_q^{d\times m}$, $\vec{u} \in \mathbb{F}_q^d$. The reduction outputs a new matrix $\vec{M}_k\in\F_q^{d\times m'}$ in $(m')^{O(1)}$ time, which satisfies the following properties:
    \begin{itemize}
        \item \textbf{Size:} $m'= |\Scal|\cdot q^{\frac{(1+\varepsilon)\alpha m}{k}}$.

        \item \textbf{Completeness:}
        If there exists $\vec{x}\in\F_q^{m}$ with $\|\vec x\|_0\le\alpha m$ such that $\vec M\vec x=\vec{u}$, then there exists $\vec y\in\F_q^{m'}$ with $\|\vec y\|_0\le k$ such that $\vec M_k\vec y=\vec{u}$.

        \item \textbf{Soundness:}
        If there is no $\vec{x}\in\F_q^{m}$ with $\|\vec x\|_0\le\gamma\alpha m$ such that $\vec M\vec x=\vec{u}$, then there is no $\vec{y}\in\F_q^{m'}$ with $\|\vec y\|_0\le\frac{\gamma}{1+\varepsilon} k$ such that $\vec M_k\vec y=\vec{u}$.
    \end{itemize}

\label{thm:mld_main_restate}
   Assuming $\ETH$, there exist constants $\gamma > 1$ and $\delta>0$, such that  for any algorithm that takes as input a matrix $\vec{H}\in \F_q^{d \times N}$, a vector $\vec{u}\in\F_q^{d}$ and a parameter $k\in\N$, it must take $ N^{\delta k}$ time to distinguish the following two cases:
   \begin{itemize}
       \item $\yes$ Case: There exists $\vec x\in\F_q^{N}$ with $\|\vec x\|_0\le k$ such that $\vec H\vec x=\vec u$.
       \item $\no$ Case: For every $\vec x\in\F_q^{N}$ with $\|\vec x\|_0\le \gamma k$, we have $\vec H\vec x\neq\vec u$.
   \end{itemize}


Assuming randomized $\ETH$, there exist constants $\gamma > 1$ and $\delta,\varepsilon'>0$, such that for any algorithm that takes as input a matrix $\vec{H}\in \F_q^{d \times N}$, a vector $\vec{u}\in\F_q^{d}$ and an integer $k\in\N$ such that $2\le k\le N^{\varepsilon'}$, it must take $N^{\delta k}$ time to distinguish the following two cases:
\begin{itemize}
    \item $\yes$ Case: There exists $\vec x\in\F_q^{d}$ with $\|\vec x\|_0\le k$ such that $\vec H\vec x=\vec u$.
    \item $\no$ Case: For every $\vec x\in\F_q^{d}$ with $\|\vec x\|_0\le \gamma k$, we have $\vec H\vec x\neq\vec u$.
\end{itemize}

A $(U,k,\alpha,\varepsilon,c)$-balanced partition family is a family $\Fcal\subseteq[k]^{U}$ of functions from $U$ to $[k]$, such that
\begin{itemize}
    \item (P1) For every $f\in\Fcal$ and $j\in[k]$, $|f^{-1}(j)|\le \frac{c|U|}{k}$.
    \item (P2) For every $S\subseteq U$ with $|S|=\alpha |U|$, there exists $f\in\Fcal$ such that $|S\cap f^{-1}(j)|\le\frac{(1+\varepsilon)|S|}{k}$ for every $j\in[k]$.
\end{itemize}

\label{thm:rand_par}
    For every $m,k\in\N$ and $0<\alpha,\varepsilon<1$ such that $m\ge\frac{6k\ln 2k}{\varepsilon^2\alpha}$,
    there exists an $([m],k,\alpha,\varepsilon,1+\varepsilon)$-balanced partition family $\Fcal$ with $|\Fcal|=\frac{12k}{\varepsilon^2\alpha}$.

\label{thm:old_collapses}
