\label{layeredconfgrph}
Let \( k \in \mathbb{N} \). We define the layered configuration graph with \( k \) layers associated with \( \gmx \) as follows:
\begin{itemize}
\item Its vertex set consists of pairs $\conf{v}{i}$ for every \( v \in V(\gmx) \) and \( i \in [k] \cup \{0\}\).
\item For every directed edge \((v,v') \) in \(\gmx\) with label \( b \in \{0,1\} \) and \( i \in [k] \), the layered graph contains a directed edge from $\conf{v}{i}$ to $\conf{v'}{i-1}$, carrying the same label \( b \).
\item Additionally, for every halt configuration \( v \in V(\gmx) \) and \( i \in [k] \), the layered graph includes a directed edge from $\conf{v}{i}$ to $\conf{v}{i-1}$ that is labeled with both \(0\) and \(1\).
\end{itemize}
One can imagine the layers arranged from left to right, numbered from $k$ to $0$. Note that the vertices in the last layer (layer $0$) have no outgoing edges.

\label{avbvdefn}
   Let $\conf{v}{i}$ and $\conf{z}{i+1}$ be two \textit{arbitrary} vertices/configurations in layers $i$ and $i+1$, respectively, of the layered configuration graph of $\gmx$. We introduce the following sets:
\begin{itemize}
    \item $A_{v}^{acc}=\{\text{seeds in } \{0,1\}^m \text{ for which $y$-DFS from $\accz$ visits $\conf{v}{i}$, for $y\leftarrow$ PRG$_i$(seed)}\}$. We similarly define $A_{v}^{rej}$, where the definition uses $\rejz$ instead of $\accz$.
    \item $B_{vz}= \{t\in \{0,1\}^m\ \mid \text{ there is an edge with label } t_1 \text { \textup{(}first bit of $t$\textup{)} from } \conf{z}{i+1} \text{ to } \conf{v}{i}\}$. Thus, $|B_{vz}|$ is either $0$, $2^{m-1}$, or $2^m$.
\end{itemize}

\label{goodnesslemma}
Let $\mathcal{H}=\{h:\{0,1\}^m \rightarrow \{0,1\}^m\}$ be a pairwise independent hash family, and let $A,B \subseteq \{0,1\}^m$. A hash function $h:\{0,1\}^m \rightarrow \{0,1\}^m$ is called $(A,B,\alpha)$-independent if 
$$\big|\Pr_{x\in \{0,1\}^m}[x\in A \text{ and } h(x) \in B]-\rho(A)\rho(B)\big| \le \alpha$$ Here $\rho(A)=\frac{|A|}{2^m}$, and $\rho(B)=\frac{|B|}{2^m}$.

\label{goodnessofhashfn}
A hash function from the hash family is considered \emph{good} if it is 
\begin{enumerate}
    \item $(A_v^{acc},B_{vz}, \alpha)$-independent for every $\conf{v}{i} \in S_i$ and $\conf{z}{i+1} \in N_{i+1}(\conf{v}{i})$.
    \item $(A_v^{rej},B_{vz}, \alpha)$-independent for every $\conf{v}{i} \in S_i$ and $\conf{z}{i+1} \in N_{i+1}(\conf{v}{i})$.
\end{enumerate}
where $\pmb{\alpha}$ is a parameter whose value will be set later.

 \label{thm:main}
Let $\epsilon_0 > 0$ be a sufficiently small constant.
Any randomized streaming algorithm that returns a $(1-\epsilon)$-approximate maximum cut in a graph with $n$ vertices with probability at least $0.51$, where $\epsilon(n) \in [\omega(1/\sqrt{n}), \epsilon_0]$, requires $\Omega(\epsilon^{-2} n \log(n \epsilon^2))$ bits of space.

\label{lemma:prelim:hamming sum}
    Let $n \in \N$ and $0 \le k \le n/2$. Then
$\sum_{i=0}^{k} \binom{n}{i} \le 2^{n \cdot \entropy(k/n)}.$

\label{lem:nsa implies small adv}
    For every pair of bipartite graphs $\vecG = (G_1,G_2)$ and left-assignment $x \in \{\pm1\}^L$,
    if $\Cgood{G_1}{x}{\tau} \cap \Cgood{G_2}{x}{\tau} \neq \emptyset$,
    then $\sum_{v \in R} \adv{\vecG}{x}{v} \le 4\tau$.

\label{lem:adv lower bound}
    For every pair of bipartite graphs $\vecG = (G_1,G_2)$, left-assignment $x \in \{\pm1\}^L$, and right-vertex $v \in R$: \[
    \adv{\vecG}{x}{v} \ge \slack \parens*{ \xA{\vecG}{x}{v}, \xB{\vecG}{x}{v}} - 4|\xCom{\vecG}{x}{v}|. \]

 \label{lem:lipschitz}
The function $\slack : \R \times \R \to \R$ is 2-Lipschitz with respect to the $1$-norm:
$|\slack(a', b') - \slack(a, b)| \le 2(|a' - a| + |b' - b|)$.

 \label{lem:hard_family}
For every $\etaOverlap,\etaTail > 0$ and $\Cdeg > 1$, there exist $\Csize, \Cstretch > 0$ such that the following holds: 
for every sufficiently large $k \in \N$ and $n \ge \Cstretch k \in \N$,
there exists a family $\calF \subset \GRR{n}{k}$ of simple bipartite graphs satisfying:
\begin{enumerate}
    \item \emph{Right-regularity}:
    for every $G \in \calF$ and $v \in R$, it holds that $\deg{G}{v} = k$.
    \item \emph{Bounded sum of squared left-degrees:}
    for every $G \in \calF$, it holds that $\sum_{u \in L} \deg{G}{u}^2 \le \Cdeg n k^2$.
    \item \emph{Light left-degree tail:}
    for every $G \in \calF$, it holds that $\TailDeg{G}{2k} \le \etaTail n\sqrt{k}$.
    \item \emph{Low overlap:} for every $G_1 \ne G_2 \in \calF$, it holds that $|E(G_1) \cap E(G_2)| \le \etaOverlap nk$.
    \item \emph{Large size:} $\log |\calF| \ge \Csize nk \log(n/k)$.
\end{enumerate}

 \label{lem:equiv}
Let $\bX, \bY$ be independent, symmetrically distributed random variables.
Then $\Exp[\slack(\bX,\bY)] = \Exp[\min(|\bX|, |\bY|)]$.

 \label{lem:rademacher}
Let $\bX,\bY$ be independent Rademacher sums of lengths $m_X, m_Y \ge m \ge 1$. Let $\bW \coloneqq \min(|\bX|,|\bY|)$.
Then $\Exp[\bW] \ge \Csep \sqrt{m}$, where $\Csep \coloneqq 9/512 \approx 0.0175$.

\label{def:maxcut:dense hard:disjoint}
    Let $\gamma \in [0,1]$.
    Two graphs $G,G'$ on $[n]$ are \emph{$(1-\gamma)$-disjoint} if $\Good{\gamma}{G} \cap \Good{\gamma}{G'} = \emptyset$.

\label{thm:maxcut:dense hard:instances}
    There exists $\alpha, C > 0$ such that the following holds.
    For $\epsilon_0 \coloneqq \tfrac14$ and every $0 < \epsilon < \epsilon_0$, let $n \in \N$ be sufficiently large.
    Then there exists a set $\calG$ such that:
    \begin{enumerate}
        \item Each $G \in \calG$ is an undirected simple graph on $[n]$ with $\ge \alpha \binom{n}2$ edges.
        \item $|\calG| \ge 2^{Cn}$.
        \item Each $G \in \calG$ is \emph{bipartite}, i.e., $\maxval{G} = 1$.
        \item For every $G \ne G' \in \calG$, $G$ and $G'$ are $(1-\eps)$-disjoint (in the sense of \Cref{def:maxcut:dense hard:disjoint}).
    \end{enumerate}

\label{lemma:maxcut:dense hard:counting}
    For every $0 < \delta < 1/2$, there exists $C > 0$ such that for sufficiently large $n \in \N$, there exists a set $\calS \subseteq \{0,1\}^n$ such that:
    \begin{enumerate}
        \item $|\calS| \ge 2^{Cn}$.
        \item For every $x \in \calS$, $w(x) \in [1/3,2/3]$.
        \item For every $x \ne x' \in \calS$, $\HPMBall{\delta}{x} \cap \HPMBall{\delta}{x'} = \emptyset$.
    \end{enumerate}

\label{claim:maxcut:dense hard:eps}
    Let $0 < \eps < 1/4$.
    Then $\frac{\eps}{1-\sqrt{\eps}} \le 2 \eps$.

\label{claim:maxcut:dense hard:pq}
    Suppose $S,T \subseteq [n]$, $p = p(S,T)$ and $q = q(S,T)$ are as in \Cref{eq:maxcut:dense hard:p-q}, and $0 < \eps < 1/4$.
    If $\val{\bip{S}}{1_T} \ge 1-\eps$, then either $\max\{p,q\} \le 2\eps$ or $\min\{p,q\} \ge 1-2\eps$.

\label{lemma:maxcut:dense hard:hamming}
    Suppose $S,T \subseteq [n]$ and $0 < \eps < 1/4$.
    If $\val{\bip{S}}{1_T} \ge 1-\eps$, then either $d(1_S,1_T) \le 2\eps$ or $d(1_S,1_T) \ge 1-2\eps$.

\label{lemma:det:hard_family}
    For every $k \in \N$ and $\eta > 0$, there exists $\Csize > 0$ such that for sufficiently large $n$,
    there is a family $\calF$ of bipartite $k$-regular graphs on the same vertex-set $L \sqcup R$ with $|L| = |R| = k$ such that
    \begin{enumerate}
        \item \emph{Bipartite regularity:} Every $G \in \calF$ is a bipartite $k$-regular graph $L \sqcup R$.
        \item \emph{Mild differences between graphs:} 
        For every $G_1 \ne G_2 \in \calF$, $|E(G_1) \triangle E(G_2)| \ge \eta nk$.
        \item \emph{Size: $\log_2 |\calF| \ge \Csize nk \log n$.}
    \end{enumerate}

\label{lemma:det:value-gap}
    Let $A_1,A_2$ be two $k$-regular bipartite matchings on $L \sqcup R$.
    If $A_1, A_2$ differ in $\eta nk$ edges, then there exists a cut $z \in \{\pm1\}^{L \sqcup R}$ such that $|\val{A_1}{z} - \val{A_2}{z}| > \Omega(\eta n \sqrt{k})$.

 \label{thm:seExpander}
    For any prime $p \equiv 1 \mod 4$ and every sufficiently large $N$ there is a strongly explicit construction of an $(N, d, \lambda)$-graph where $d = p+2$ and $\lambda \le (1 + \sqrt{2})\sqrt{d-1}/d + o(1)$, and the $o(1)$ term tends to zero as $N$ tends to infinity.
(Strongly explicit means that the adjacency list of any vertex can be produced in time $\poly \log N$.)

\label{def:perm prob}
    Let $n \in \N$.
    In the $\PermProb$ problem, Alice receives a permutation $\pi : \{0,1\}^n \to \{0,1\}^n$ and Bob receives a pair $(x,i)$ for $x \in \{0,1\}^n$ and $i \in [n]$ and must output $(\pi(x))_i$.

\label{thm:perm prob}
     In any one-way protocol for $\PermProb$ with public randomness and constant advantage,
     Alice must send Bob $\Omega(2^n \cdot n)$ bits of information.

 \label{cl:denseSquare}
Let $n \in \N$, $\pi : \{0,1\}^n \to \{0,1\}^n$ be a permutation, and $x \in \{0,1\}^n$ and $i \in [n]$. Let $G$ be the graph created if Alice runs \Cref{alg:densub:sparse hard:alice-reduction} with input $\pi$ and Bob runs \Cref{alg:densub:sparse hard:bob-reduction} with input $(x,i)$. Then:
\begin{itemize}
    \item If $(\pi(x))_i = 1$, then $G$ contains exactly one square (i.e., a $4$-cycle), and the rest of the connected components are single edges and length-$3$ paths; hence, $\maxden{G} \ge 1$.
    \item If $(\pi(x))_i = 0$, then the connected components of $G$ are single edges and length-$3$ paths; hence, $\maxden{G} \le \frac34$.
\end{itemize}

\label{thm:densub:dense hard:instances}
    There exists $\alpha, C > 0$ such that the following holds.
    For $\epsilon_0 \coloneqq \tfrac14$ and every $0 < \epsilon < \epsilon_0$, let $n \in \N$ be sufficiently large.
    Then there exists a set $\calG$ such that:
    \begin{enumerate}
        \item Each $G \in \calG$ is an undirected simple graph on $[n]$ with $\ge \alpha \binom{n}2$ edges.
        \item $|\calG| \ge 2^{Cn/\eps}$.

        \item For every $G \ne G' \in \calG$, $G$ and $G'$ are $(1-\eps)$-disjoint (in the sense of \Cref{def:densub:dense hard:disjoint}).
    \end{enumerate}

\label{thm:maxcsp:dense alg}
Let $k,q \in \N$.
There exists an insertion-only streaming algorithm which, given an instance $\Phi$ on $n$ vertices with $m \ge \alpha n^k$ constraints and $\eps \in (0,1)$, outputs $x : V \to [q]$ which has $\val{\Phi}{x} \ge (1-\eps) \cdot \maxval{\Phi}$ in $O(\frac{n}{\eps^2\alpha^2})$ bits of space with probability at least $2/3$.

 \label{thm:altForCSP}
Let $k,q \in \N$.
There exists an insertion-only streaming algorithm which, given an instance $\Phi$ on $n$ vertices with $m \ge \alpha n^k$ constraints and $\eps \in (0,1)$, outputs $x : V \to [q]$ which has $\val{\Phi}{x} \ge (1-\eps) \cdot \maxval{\Phi}$ in $O(\frac{n}{\eps^2\alpha^2} \log \frac{1}{\eps \alpha})$ bits of space and $O(\log n)$ amortized update time with probability at least $2/3$.

\label{thm:rare-alg}
For every $\eps, \alpha > 0$ and $N,k \in \N$, there exists an insertion-only streaming algorithm which, given as input a sequence of insertions to a multiset $\calS \subseteq [N]$, letting $S_k$ denote the number of distinct elements in $\calS$ of multiplicity $k$ and $D$ the total number of distinct elements in $\calS$, assuming $D \ge \alpha N$, outputs \[ v \in \frac{S_k}{D} \pm \eps \] with probability at least $2/3$ in $O(\log k/(\alpha\eps^2) + \log N)$ bits of space and $O(1)$ time (in arithmetic operations) per update.
The multiplicity of an element can be unbounded.

We say a language $L$ is in $\AM$ if and only if for an input $z \in \{0,1\}^*$, there exists a single-prover one-round interactive proof system satisfying the following properties:
\begin{enumerate}
    \item Verifier's messages are sampled uniformly at random from $\{0,1\}^{p(|z|)}$ for some polynomial $p$.
    \item If $z \in L$, the verifier accepts with probability at least $\frac{2}{3}$. 
    \item If $z \notin L$, the verifier accepts with probability at most $\frac{1}{3}$.
\end{enumerate}

We say a language $L$ is in $\NEXP$ if and only if there exist polynomials $p,q$ and a deterministic classical algorithm $\mathcal{A}$ satisfying the following properties:
\begin{enumerate}
    \item For all $x,y$ the algorithm $\mathcal{A}$ runs in time $2^{p(x)}$ on input $(x,y)$.
    \item If $x \in L$, there exists a string $y$ of length $2^{q(|x|)}$ such that the algorithm $\mathcal{A}$ given $x$ and $y$ accepts.
    \item If $x \notin L$, then for all strings $y$ of length $2^{q(|x|)}$, the algorithm $\mathcal{A}$ given $x$ and $y$ rejects.
\end{enumerate}

\label{def:mip}
    We say a language $L$ is in $\MIP_{c,s}[q,a]$ if and only if, for $z \in \{0,1\}^*$, there exists a family of non-local games $G_z = (\pi, \cX \times \cY, \cA \times \cB, \mathsf{V})$ satisfying the following properties: 
    \begin{enumerate}
        \item The question size is $q$ and the answer size is $a$.
        \item There is an algorithm running in $\poly(|z|)$-time, given $z$, to sample questions $(x,y) \in \cX \times \cY$ from $\pi$.
        \item There is an algorithm running in $\poly(|z|)$-time, given $z$ and $(x,y,a,b) \in \cX \times \cY \times \cA \times \cB$, to output $\sV(a,b|x,y) \in \{0,1\}$.
        \item If $z \in L$, $\omega_c(G_z) = c$
        \item If $z \notin L$, $\omega_c(G_z) \leq s$.
    \end{enumerate}

\label{def:mip*}
    We say a language $L$ is in $\MIP^*$ if and only if, for an input $z \in \{0,1\}^*$, there exists a family of non-local games $G_z = (\pi, \cX \times \cY, \cA \times \cB, \mathsf{V})$ satisfying the following properties: 
    \begin{enumerate}
        \item There is an algorithm that runs in $\poly(|z|)$-time, given $z$, to sample questions $(x,y) \in \cX \times \cY$ from $\pi$.
        \item There is an algorithm that runs in $\poly(|z|)$-time, given $z$ and $(x,y,a,b) \in \cX \times \cY \times \cA \times \cB$, to output $\sV(a,b|x,y) \in \{0,1\}$.
        \item If $z \in L$, $\omega_q(G_z) = 1$.
        \item If $z \notin L$, $\omega_q(G_z) \leq \frac{1}{2}$.
    \end{enumerate}

\label{def:label-cover}
    An instance of label cover $\Psi = (G=(L\cup R,E), \Sigma_L, \Sigma_R, \Phi = \{\Phi_{e}\}_{e\in E})$ consists of a bipartite graph $G$, alphabets $\Sigma_L, \Sigma_R$ and constraints $\Phi_e\subseteq \Sigma_L\times \Sigma_R$, one for each edge.
    Each one of the constraints is a projection constraint, meaning that for every $e\in E$ there is a map $\phi_e\colon \Sigma_L\to\Sigma_R$ such that
    \begin{equation*}
