\label{def:mip-leakage}
    We say a language $L$ is in $\MIP_{c,s}[q,a, \ell]$ if and only if, for $z \in \{0,1\}^*$, there exists a family of non-local games $G_z = (\pi, \cX \times \cY, \cA \times \cB, \mathsf{V})$ satisfying the following properties: 
    \begin{enumerate}
        \item The question size is $q$ and the answer size is $a$.
        \item There is an algorithm running in $\poly(|z|)$-time, given $z$, to sample questions $(x,y) \in \cX \times \cY$ from $\pi$.
        \item There is an algorithm running in $\poly(|z|)$-time, given $z$ and $(x,y,a,b) \in \cX \times \cY \times \cA \times \cB$, to output $\sV(a,b|x,y) \in \{0,1\}$.
        \item If $z \in L$, $\omega_c(G_z) = c$.
        \item If $z \notin L$, and even if the provers are allowed to communicate at most $\ell$ bits, we must have $\omega_c(G_z) \leq s$.
    \end{enumerate}

\label{def:mip*-leakage}
    We say a language $L$ is in $\MIP^*[q,a,\ell]$ if and only if, for an input $z \in \{0,1\}^*$, there exists a family of non-local games $G_z = (\pi, \cX \times \cY, \cA \times \cB, \mathsf{V})$ satisfying the following properties: 
    \begin{enumerate}
        \item The question size is $q$ and the answer size is $a$.
        \item There is an algorithm running in $\poly(|z|)$-time, given $z$, to sample questions $(x,y) \in \cX \times \cY$ from $\pi$.
        \item There is an algorithm running in $\poly(|z|)$-time, given $z$ and $(x,y,a,b) \in \cX \times \cY \times \cA \times \cB$, to output $\sV(a,b|x,y) \in \{0,1\}$.
        \item If $z \in L$, $\omega_q(G_z) = 1$.
        \item If $z \notin L$, and even if the provers are allowed to communicate at most $\ell$ bits, $\omega_q(G_z) \leq \frac{1}{2}$.
    \end{enumerate}

\label{def:oneway-leakage}
    A language $L$ is in $\MIP^{\rightarrow}_{c,s}[q,a,\ell]$ if and only if there exists a two-prover one-round interactive proof for $L$, in which the verifier $V$ runs in time $\poly(|x|)$ for every instance $x\in\{0,1\}^*$ and satisfies the following properties:
    \begin{itemize}
        \item \emph{Completeness:} If $x\in L$, then after exchanging one round of messages first with $P_1$ and then with $P_2$, the verifier $V$ accepts with probability at least $c$.
        \item \emph{Soundness:} If $x\notin L$, for every set of malicious provers $P_1$ and $P_2$, in which $P_1$ is allowed to send $\ell$ bits to $P_2$ after receiving the question from $V$, the verifier will accept with probability at most $s$.
    \end{itemize}
    Additionally, the question size is $q$ bits, and the answer size is at most $a$ bits.

