\begin{enumerate}
    \item $R$ is \tbalanced.
    \item For every $f\in\{0,1\}^r\setminus R$, there exists a prime-power $q_f$ and a multilinear polynomial $p_f$ over $\mathbb Z/q_f\mathbb Z$ of degree at most $t$ such that $p_f$ captures $f$ with respect to $R$.
\end{enumerate}
Moreover, if $R$ is not \tbalanced, then there exists $f\in\{0,1\}^r\setminus R$ that is not captured by any degree-$\le t$ multilinear polynomial over any \ring.

\label{thm:carbonnel-lower-bound}
Let $R$ be a relation of arity $r$ over a finite domain $D$, and let $2\le k\le r$. If
$f^D_{P^u_k}\notin \pppol(\{R\})$, then $\nrdr=\Omega(n^k)$.

\label{def:balance}
A Boolean predicate $P \subseteq \{0,1\}^r$ is \emph{balanced} if for all~$k \in \mathbb{N}$ and all tuples $t_1, \hdots, t_{2k+1} \in P$ (some possibly equal), if we compute (over $\mathbb Z$) the $r$-tuple
\[
    t := t_1 - t_2 + t_3 - \cdots + t_{2k+1}
\]
and $t \in \{0,1\}^r$, then $t \in P$.

\label{def:projection}
Consider predicates $P \subsetneq Q \subseteq D_1^{r_1}$ and $R \subsetneq S \subseteq D_2^{r_2}$. Given a sequence $\mathcal I = (I_1, \hdots, I_{r_2})$ of subsets of $[r_1]$, we say that $P \mid Q$ is an \emph{$\mathcal I$-substructure} of $R \mid S$ if there exist maps $\{g_j : D_1^{I_j} \to D_2 \mid j \in [r_2]\}$ (called the \emph{witnessing maps}) such that  the following two conditions are true.
\begin{align}
  \forall x \in P &, (g_1(\pi_{I_1} x), g_2(\pi_{I_2} x), \hdots, g_{r_2}(\pi_{I_{r_2}} x)) \in R, \label{eq:P}\\
  \forall x \in Q \setminus P &, (g_1(\pi_{I_1} x), g_2(\pi_{I_2} x), \hdots, g_{r_2}(\pi_{I_{r_2}} x)) \in S \setminus R.\label{eq:Q-P}
\end{align}

\label{prop:projection-compact}
Consider predicates $P \subsetneq Q \subseteq D_1^{r_1}$ and $R \subsetneq S \subseteq D_2^{r_2}$. Given a sequence $\mathcal I = (I_1, \hdots, I_{r_2})$ of subsets of $[r_1]$, we have that that $P \mid Q$ is an $\mathcal I$-substructure of $R \mid S$ if and only if there exists a map $\Sigma : Q \to S$ subject to the following conditions
\begin{enumerate}
\item[(1)] $\Sigma(P) \subseteq R$ and $\Sigma(Q \setminus P) \subseteq S \setminus R$.
\item[(2)] For all $i \in [r_1]$ and $j \in [r_2]$, if $i \not\in I_j$ and $x, y \in Q$ differ only in coordinate $i$, then $\Sigma(x)_j = \Sigma(y)_j$.
\end{enumerate}

\label{thm:shrink-lb}
Consider predicates $P \subsetneq Q \subseteq D_1^{r_1}$ and $R \subsetneq S \subseteq D_2^{r_2}$. Given a sequence $\mathcal I = (I_1, \hdots, I_{r_2})$ of subsets of $[r_1]$, assume that that $P \mid Q$ is an $\mathcal I$-substructure of $R \mid S$. Further let $H_1 = (V_1, E_1), H_2 = (V_2, E_2), \hdots$ be an infinite sequence of non-redundant instances of $\CSP(P \mid Q)$ with the following properties. Assume there exists absolute constants $C_1, C_2, \eps > 0$ (with $\eps < 1$) such that the following conditions hold for all $i \ge 1$:
\begin{enumerate}
  \item $H_i$ is $(C_1 \cdot |E_i|^{-\eps}, \mathcal I)$-shrinking, and
  \item $1 \le |E_{i+1}| / |E_{i}| \le C_2$.
\end{enumerate}

Then, $\NRD(R \mid S, n) = \Omega(n^{\frac{1}{1-\eps}}),$ where $\Omega$ hides constant factors dependent on $|E_1|, C_1, C_2, r_1,r_2, \eps.$

\label{def:box-product}
Given predicates $P_1 \subsetneq Q_1 \subseteq D^{r_1}$ and $P_2 \subsetneq Q_2 \subseteq D^{r_2}$, we define their \emph{box product} $(P_1 \mid Q_1) \boxtimes (P_2 \mid Q_2) = (P_3 \mid Q_3)$ with $P_3 \subsetneq Q_3 \subseteq D^{r_1+r_2}$ as follows.
\begin{align*} 
  Q_3 &:= Q_1 \times Q_2 = \{(t_1, \hdots, t_{r_1}, t'_{1}, \hdots, t'_{r_2}) : t \in Q_1, t' \in Q_2\}\\
  P_3 &:= (P_1 \times Q_2) \cup (Q_1 \times P_2). 
\end{align*}

\label{thm:BoolBCK-projections}
For every $J \subsetneq [9]$ such that $\pi_J\BoolBCKp \neq \pi_J\BoolBCK$, we have that
\begin{align}
\NRD(\pi_J\BoolBCK \mid \pi_J\BoolBCKp, n) \ge \Omega(n^{6/5}).\label{eq:BoolBCK-proj-lb}
\end{align}

\label{lem:J-sym}
For every $J \subseteq [9]$ of size $8$, either
\begin{align*}
\NRD(\pi_J\BoolBCK \mid \pi_J\BoolBCKp, n) &= \NRD(\pi_{J_1}\BoolBCK \mid \pi_{J_1}\BoolBCKp, n), \text{or}\\
\NRD(\pi_J\BoolBCK \mid \pi_J\BoolBCKp, n) &= \NRD(\pi_{J_2}\BoolBCK \mid \pi_{J_2}\BoolBCKp, n),
\end{align*}
where $J_1 = [9] \setminus \{1\}$ and $J_2 = [9] \setminus \{2\}$.

\label{thm:catalan-cousins}
We following lower bounds hold.
\begin{align}
\NRD(P_1 \mid Q_1, n) &\ge \Omega(n^{4/3}) \label{eq:P1Q1}\\
\NRD(P_2 \mid Q_2, n) &\ge \Omega(n^{4/3}) \label{eq:P2Q2}\\
\NRD(P_3 \mid Q_3, n) &\ge \Omega(n^{6/5}) \label{eq:P3Q3}
\end{align}

\label{def:postbqp}
A language $L$ is in $\PostBQP$ if there exists a polynomial-time uniform family
of quantum circuits, each acting on $\ket{w}\ket{0^{m(|w|)}}$ and equipped with
a designated output qubit and a post-selection register, such that for every
input~$w$:
\begin{enumerate}[label=(\roman*)]
\item the probability of the post-selection register returning $\ket{0\cdots 0}$
      is nonzero;
\item if $w \in L$, the output qubit is~$1$ with probability at least $2/3$,
      conditioned on post-selection;
\item if $w \notin L$, the output qubit is~$0$ with probability at least $2/3$,
      conditioned on post-selection.
\end{enumerate}

\label{prop:gadget}
Suppose $r_0 r_1 \neq 0$.  Then $V = \lambda H$ if and only if
\begin{equation}\label{eq:gadget_sol}
w_{ab} = \frac{\lambda\,(-1)^{ab}}{r_b}.
\end{equation}
A unitary diagonal $W$ with this property exists if and only if $|r_0| = |r_1|$,
and is then unique up to global phase.

\label{prop:optimization}
The cost function~$C$ constructed in Theorem~\ref{thm:degree3} can be made
monotone and maximized at $x = 1^n$ without altering the QAOA circuit.

\label{def:cutwidth}
A gate on qubits~$S$ crosses cut~$i$ if there exist $j,j'\in S$ such that $j \le i < j'$.  Single-qubit gates cross no cut.  The \emph{cut width} of a
circuit on qubits~$[n]$ is the maximum number of gates crossing any single cut.

(Step (1))\label{lem:step1}
There are some universal constants $\eta_1$, $d$ and $\lambda<d$ such that, for a constraint graph $G$ with alphabet $\Sigma$ and constraints from a set $\mathcal{C}$, we can compute a $d$-regular constraint graph $G_1$ with alphabet $\Sigma$ and constraints from $\mathcal{C}\cap \{x=y, \Sigma^2\}$ such that:

\begin{itemize}
    \item $|E(G_1)|=\mathcal{O}(|E(G)|)$
    \item $\lambda(G_1)\le \lambda$
    \item if $\text{UNSAT}(G)=0$ then $\text{UNSAT}(G_1)=0$
    \item $\text{UNSAT}(G_1)\ge \eta_1\cdot \text{UNSAT}(G)$
\end{itemize}

(Step (2))\label{lem:step2}
Fix constants $d$ and $\lambda<d$. Then there is some constant $\eta_2$ such that, for each $t\in \mathbb{N}$, given a constraint $d$-regular constraint graph $G_1$ with alphabet $\Sigma$, constraint set $\mathcal{C}$ and $\lambda(G_1)\le \lambda$, we can in polynomial time construct a constraint graph $G_2$ with alphabet $\Sigma^{d^{t+1}}$ and constraint set $\mathcal{P}(\mathcal{C}_{\Sigma}^{2d^{t+1}})$ such that:

\begin{itemize}
    \item $|E(G_2)|=\mathcal{O}_t(|E(G_1)|)$
    \item if $\text{UNSAT}(G_1)=0$, then $\text{UNSAT}(G_2)=0$
    \item $\text{UNSAT}(G_2)\ge \eta_2t\cdot \text{min}(\text{UNSAT}(G_1), \frac1t)$
\end{itemize}

(Composition Lemma)\label{lem:composition}
Let $G_2$ be a constraint graph with alphabet $\Sigma$ and constraint set $\mathcal{C}$. Given an assignment tester for $\mathcal{C}$ with parameters as above, we can construct a new graph $G'$ with alphabet $\Gamma^\ell$ and constraint set $\mathcal{D}_{[\frac12, 2]}^{2\ell}$ such that:

\begin{itemize}
    \item if $\text{UNSAT}(G_2)=0$, then $\text{UNSAT}(G')=0$
    \item $\text{UNSAT}(G')\ge \frac{\zeta}{\ell+1}\cdot \text{UNSAT}(G)$
    \item $|E(G')|=(\ell+1)R|E(G)|$
\end{itemize}

(Step 3)\label{cor:step3}
Fix $n$. Let $G_2$ be a constraint graph with alphabet $[\frac12, 2]^{n}$ and constraint set $\mathcal{P}\left(\mathcal{C}(q)_{[\frac12, 2]}^{2n}\right)$. If $q$ is sufficiently small, then in polynomial time we can construct a constraint graph $G_3$ with alphabet $[\frac12, 2]^4$ and constraint set $\mathcal{C}(q)_{[\frac12, 2]}^{8}$ such that:

\begin{itemize}
    \item $|E(G_3)|=\mathcal{O}_n(|E(G_2)|)$
    \item if $\text{UNSAT}(G_2)=0$ then $\text{UNSAT}(G_3)=0$
    \item $\text{UNSAT}(G_3)\ge \eta_3\cdot \text{UNSAT}(G_2)$, where $\eta_3=\frac{1}{5000}$
\end{itemize}

\label{lem:gapamplification}
There is some $\alpha>0$ such that, for sufficiently small $q$, given a constraint graph $G$ with alphabet $[\frac12, 2]^4$ and constraint set $\mathcal{C}(q)_{[\frac12, 2]}^8$, we can construct in polynomial time a constraint graph $G'$ with the same alphabet and constraint set, such that:

\begin{itemize}
    \item $|E(G')|=\mathcal{O}(E(G))$
    \item if $\text{UNSAT}(G)=0$ then $\text{UNSAT}(G')=0$
    \item $\text{UNSAT}(G')\ge \text{min}(\alpha, 2\cdot \text{UNSAT}(G))$
\end{itemize}

\label{lem:constraintshrinking}
Let $V\subseteq \mathbb{R}^4$ be a constraint in $\mathcal{C}(q)$. Then there is a subset $V'$ of $\mathbb{R}^{74}$ such that:

\begin{itemize}
    \item $V'$ is cut out by constraints of form $x=q$, $x+y=z$, and $(1+x)(1+y)=(1+z)$, with at most $1$ constraint of form $x=q$, at most $52$ constraints of form $x+y=z$, and at most $18$ constraints of form $(1+x)(1+y)=1+z$
    \item if $x\in V$, then there is some $y\in [-6q, 6q]^{70}$ such that $(qx, y)\in V'$, and
    \item if $(x, y)\in V'$ with $x\in \mathbb{R}^4$ and $y\in \mathbb{R}^{70}$, then $q^{-1}x\in V$
\end{itemize}

\label{lem:threeconstraintconversion}
For each $n\in \mathbb{N}$ there is some $m\in \mathbb{N}$, such that for any $q\in (0, \frac12]$ and a constraint $V\in \mathcal{P}\left(\mathcal{C}(q)_{[\frac12, 2]}^{n}\right)$, we can construct a subset $V'$ of $\mathbb{R}^{n+m}$ such that:

\begin{itemize}
    \item $V'$ is cut out by constraints of form $x+y=z$, $(1+x)(1+y)=(1+z)$, and $x=q$, with exactly one constraint of form $x=q$,
    \item for any $x\in V$, there is a $y\in [-6q, 6q]^m$ such that $(qx, y)\in V'$, and
    \item if $(x, y)\in V'$ for some $x\in \mathbb{R}^n$, then $q^{-1}x\in V$
\end{itemize}

\label{lem:basisfinding}
Let $V$ be $d$-dimensional linear subspace of $\mathbb{R}^n$ given by the kernel of a matrix $B$ with integer entries, where each row $c$ of $B$ has $\Vert c\Vert_1\le k$ for some integer $k\ge 1$. 

Then there is a basis $b_1, \dots, b_d$ for $V$ where the entries of the $b_i$ are integers with absolute value at most $k^{n-1}$. Furthermore, there is some positive integer $D$ and some function $\rho:[d]\rightarrow [n]$ such that, for $\alpha\in V$, $\alpha=\frac{1}{D}\sum_{i=1}^d\alpha_{\rho(i)}b_i$.

\label{lem:constrainttestsatisfying}
There is some value of $q>0$ depending only on $n$ such that, for any $\alpha\in V'$, we can set $u_\sigma=\prod_{i=1}^{n+m}(1+\alpha_i)^{\sigma_i}$ for each $\sigma\in \{0, 1\}^{n+m}$ and assign values of $A_1$, $A_2$ such that:

\begin{itemize}
    \item each $u_\sigma$ and each entry of $A_1$ or $A_2$ is in $[\frac12, 2]$, and
    \item the constraint test passes with probability $1$
\end{itemize}

 \label{thm:dks}
Suppose that, for any $\lambda \geqs 1$, no polynomial time algorithm solves {\sc GapD$k$S}$(\lambda)$. Then, for any $\varepsilon > 0$, no polynomial time algorithm approximates {\sc DAL$k$S} to within a factor of $(3/2 - \varepsilon)$.


Moreover, if we assume further that, for any $\lambda \geqs 1$ and $f: \N \to \N$, no $f(k) \cdot n^{O(1)}$ time algorithm solves {\sc GapD$k$S}$(\lambda)$, then, for any $\varepsilon > 0$, no $f(k) \cdot n^{O(1)}$ time algorithm approximates {\sc DAL$k$S} to within a factor of $(3/2 - \varepsilon)$.

For any $\delta \in (0, 1]$ and $t \in \N$, the {\sc PolyGapDkS}$(\delta, t)$ problem is the following: given a graph $G$ and $k \in \N$, distinguish between 
\begin{itemize}
\item (Completeness) there exists $S \subseteq V_G$ of size $k$ s.t. $G[S]$ contains at least $k^{t - \delta}$ copies of $t$-cliques, and,
\item (Soundness) $\den_{\leqs k}(G) < k^\delta$.
\end{itemize}

 \label{thm:polydks}
Suppose that, for any $\delta > 0$ and any $t \in \N$, no polynomial time algorithm solves {\sc PolyGapD$k$S}$(\delta, t)$. Then, for any $\varepsilon > 0$, no polynomial time algorithm approximates {\sc DAL$k$S} to within a factor of $(2 - \varepsilon)$.


Moreover, if we assume further that, for any $\delta > 0, t \in \N$ and $f: \N \to \N$, no $f(k) \cdot n^{O(1)}$ time algorithm solves {\sc PolyGapD$k$S}$(\delta, t)$, then, for any $\varepsilon > 0$, no $f(k) \cdot n^{O(1)}$ time algorithm approximates {\sc DAL$k$S} to within a factor of $(2 - \varepsilon)$.

For any $\delta \in (0, 1]$, $\gamma \geqs 1$ and $t \in \N$, the {\sc PolyGapDkS}$(\delta, t, \gamma)$ problem is the following: given a graph $G$ and $k \in \N$, distinguish between 
\begin{itemize}
\item (Completeness) There exists $S \subseteq V_G$ of size $k$ s.t. $G[S]$ contains at least $k^{t - \delta}$ copies of $t$-cliques, and,
\item (Soundness) $\den_{\leqs \gamma \cdot k^t}(G) < k^\delta$.
\end{itemize}

For any $\lambda, \gamma \geqs 1$ and $t \in \N$, the $t$-uniform {\sc StrongGapD$k$SH$(\lambda, \gamma)$} problem is: given a universe $U$, a collection $\cS$ of $t$-element subsets of $U$ and $k, \ell \in \N$, distinguish between
\begin{itemize}
\item (Completeness) There exists $T \subseteq U$ of size $k$ such that $|\{S \in \cS \mid S \subseteq T\}| \geqs \ell$.
\item (Soundness) For any $T \subseteq U$ of size at most $\gamma \cdot k$, $|\{S \in \cS \mid |S \cap T| > 1\}| < \ell/\lambda$
\end{itemize}

\label{thm:intro-dictator}
In the instance described above, for any allocation $X$ that allocates all the large goods, the following holds:
\begin{description}[font=\normalfont]
    \item[\textsc{Completeness}] If $f_X$ is defined as $f_X(x) = \mathbbm{1}\{x_i > 0\}$ for all $x \in \{0, 1, 2\}^R$ for some $i \in [R]$, then there is an allocation of the small goods such that each agent not allocated a large good in $X$ receives a utility\footnote{The utility of an agent $i$ is their value for their allocated bundle $v_i(X_i)$.} of $3^{-(R-1)}$.
    \item[\textsc{Soundness}] If $f_X$ is `far' from a dictator, then the total utility of all the agents not allocated large goods is at most $\frac{65}{81}$. 
\end{description}

For a function $f:[q]_{0}^R \rightarrow \mathbb{R}$ and $i \in [R]$, we define the influence of the $i$-th coordinate (denoted $\Inf_i(f)$) as 
\begin{align*}
	\Inf_i(f) = \sum_{S: i \in S} \E_x[f_S(x)^2],
\end{align*}
where $f_S$ is given by the Efron-Stein decomposition.
We also define the degree $d$-influence of $f$ (denoted $\Inf_i^{\le d}(f)$) as the value $\Inf_i(f^{\le d})$. Note that $\Inf_i^{\le d}(f) = \sum_{S: i \in S, |S|\le d} \E_x[f_S(x)^2]$.

(\citet[Theorem 6.6]{mossel2010gaussian})\label{thm:mossel-pairwise}
For any positive integers $q$ and $k$, let $([q]^k_0, \eta)$ be a probability space such that 
\begin{enumerate}[(a)]
\item $\eta$ is pairwise independent and balanced, and
\item For all $w \in [q]^k_0$, $\eta(w) \ge \alpha > 0$ for some constant $\alpha$.
\end{enumerate}
Then, for all $\vare > 0$, there exists a $\tau > 0$ and $d > 0$ such that the following holds for all positive integers $R$. Let $f_1, f_2, \dots, f_k$ be functions such that $f_j: [q]^R_0 \rightarrow [0, 1]$ and for all $i \in [R]$, $\Inf_i^{\le d}(f_j) \le \tau$, then
\begin{align*}
\left | \E_{w^1, \dots, w^R} \left [\prod_{j = 1}^k f_j(w^1_{j}, \dots, w^R_{j}) \right ] - \prod_{j = 1}^k\left (\E_{w^1, \dots, w^R}\left [f_j(w^1_{j}, \dots, w^R_{j}) \right ] \right ) \right | \le \vare.
\end{align*}
Here, each $w^i$ is independent and distributed according to the probability space $([q]^k_0, \eta)$.

\label{claim:eta-properties}
The distribution $\eta$ satisfies the following properties:
\begin{enumerate}[(i)]
\item $\eta$ is balanced and pairwise independent
\item For $(a, b, c, d) \in \{0, 1, 2\}^4$ sampled according to the distribution $\eta$, at least one of $a, b, c$ and $d$ is $0$ with probability $1$. 
\end{enumerate}

\label{thm:dictator-test}
In an instance from Problem Instance Family \ref{prob:dictator-test}, let $X$ be an allocation where $2 \cdot 3^{R-1}$ agents receive a large good, and let $N'$ be the set of agents which do not receive any large goods. Then:
\begin{description}[font=\normalfont]
    \item[\textsc{Completeness.}] If $f_X$ is defined as $f_X(x) = \mathbbm{1}\{x_i > 0\}$ for some $i \in [R]$, then there is an allocation $X'$ with $f_X = f_{X'}$ such that for all agents in $u \in N'$, $v_u(X'_u) \ge \frac{1}{3^{R-1}}(1 - \vare)$.
    \item[\textsc{Soundness.}] There exists a $d > 0$ and $\tau > 0$ such that if $f_X$ has $\Inf^{\le d}_i(f_X) \le \tau$ for all $i \in [R]$, then $\sum_{u \in N'} v_u(X_u) \le \frac{65}{81} + \vare$. 
\end{description}

\label{thm:meta}
For every rational constant $\vare \in (0, 1)$, assuming the unique games conjecture is true, it is NP-hard to distinguish between the following two cases given an instance from Problem Instance Family \ref{prob:meta} (parameterized by $\vare$):
\begin{description}[font=\normalfont]
    \item[\textsc{YES Case:}] There is an allocation $X$ where $2n/3$ agents are allocated a large good they value at $\frac1{\vare}$ and all the agents who are not allocated a large good receive a utility of at least $\frac3n (1 - \vare)$.
    \item[\textsc{NO Case:}] For every allocation $X$ where $2n/3$ agents receive a large good they value at $\frac1{\vare}$, the total utility of agents who do {\em not} receive a large good is at most $\frac{65}{81} + 3\vare$. That is, $\sum_{u \in N'}v_u(X_u) \le \frac{65}{81} + 3\vare$ where $N'$ is the set of agents who do not receive a large good in $X$.
\end{description}

\label{thm:general-dictator-test}
In an instance from Problem Instance Family \ref{prob:general-dictator-test}, let $X$ be an allocation where $q \cdot (q+1)^{R-1}$ agents receive a large good, and let $N'$ be the set of agents which do not receive any large goods. Then:
\begin{description}[font=\normalfont]
    \item[\textsc{Completeness.}] If $f_X$ is defined as $f_X(x) = \mathbbm{1}\{x_i > 0\}$ for some $i \in [R]$, then there is an allocation $X'$ with $f_X = f_{X'}$ such that for all agents in $u \in N'$, $v_u(X'_u) \ge \frac{1}{(q + 1)^{R-1}}(1 - \vare)$.
    \item[\textsc{Soundness.}] There exists a $d > 0$ and $\tau > 0$ such that if $f_X$ has $\Inf^{\le d}_i(f_X) \le \tau$ for all $i \in [R]$, then $\sum_{u \in N'} v_u(X_u) \le 1 - \left ( \frac{q}{q+1} \right )^{q+2} + \vare$. 
\end{description}

