\label{def:streaming-kde}
    The algorithm receives keys $k_1, \ldots, k_n\in \R^d$ in a stream and at every point $j = 1,\ldots, n$, 


    given any fixed $q\in \R^d$,  outputs an estimate $\widehat \expker(K_{j}, q)$ of $\expker(K_{j}, q)$ that satisfies
    \begin{gather}
        \label{eq:streaming-kde}
        |\widehat{\expker}(K_{j}, q) - \expker(K_{j}, q)| \leq \eps \cdot \expker(K_{j}, q)
    \end{gather}
    with probability at least $1-\delta$ for some $\delta\in (0, 1)$ for any fixed query $q$.  Here $K_{j}=(k_1, \ldots, k_{j})$ is the sequence of keys received by time $j$.

\label{th:const_r_ub_lb}
