    \end{gather*}

\label{lem:weighted_embed_memory}
    Let $\gamma(k, q) := \sum_{l = 0}^{t} a_l \<k, q>^l$ for some $t$ and $a_l$. Then there exist embeddings $\psi_1, \psi_2$ such that for any $K \subset \R^d$  with $\|k\|_2  \leq r$ for all $k \in K$, any $q \in \R^d$ with $\|q\|_2 \leq r$ , and any weights $\{w(k)\}_{k \in K}$ with $|w(k)| \leq 1$ for all $k \in K$, we guarantee
    \[\qty|\Bigl \langle \sum_{k \in K} w(k) \psi_1(k), \psi_2(q) \Bigr \rangle - \sum_{k \in K}  w(k)\gamma(k, q)| < \delta,\] and the weighted aggregate $ \sum_{k \in K} w(k)\psi_1(k)$ can be stored in $O\Bigl(\frac{(d+t)^{t}}{t!}\log\frac{|K|\cdot (d+t)^{t} \cdot\max_l |a_l|\cdot \max\{r, 1\}^t}{\delta}\Bigr)$ bits of space.

Assume that $r = \log^{o(1)} n$, $\log n \leq d \leq \log^a n$ for some constant $a > 1$ and $\eps < n^{-c}$ for any constant $c > 0$. The Weighted Softmax KDE problem (\cref{def:weighted-kde}) can be solved using
    \begin{align*}
        \tilde{O}\qty(\qty(\frac{1}{\eps})^{1 - \frac{1}{a} + o(1)})
    \end{align*}
    memory. If, on the other hand, $r^2 = \Omega(\log n)$, equivalently
$e^{r^2} = n^{\Omega(1)}$, then the Weighted Softmax KDE problem
\eqref{eq:streaming-kde} can be solved using
    \begin{align*}
    \tilde{O}\qty(\frac{e^{r^2(1 + o(1))}}{\eps})
    \end{align*}
    memory.

\label{def:random-kde-instance}
Let $\bx \in \{0,1\}^{2n}$ be a binary vector with exactly $n$ ones. Let $K \subset \R^d$ be a set of $2n$ points drawn i.i.d.\ from a rotationally invariant distribution, independently of $\bx$. Let $K_\bx$ be the set of points indexed by the ones of $\bx$.
A \emph{random KDE instance} is an instance of the streaming KDE problem (\cref{def:streaming-kde}) in which the keys $k_1, \ldots, k_n$ are the points in $K$ and the query $q$ is chosen from $K$. Vector $q$ is chosen to be one of the keys $k_i \in K$; the position in the dataset $i$ is independent of the randomness of $K$.

\label{AdjacencyX_1}
Let $X_1,Y_1 \in \{A_1,B_1,C_1,D_1,E_1
\}$. Each $X_1$ is independent. Furthermore,  $X_1$ is complete to $Y_1$ if $X_1$ and $Y_1$ are not consecutive, otherwise, $X_1$ and $Y_1$ are independent.

\label{A1-D2-C2}
Suppose $X_1,Y_2,Z_2$ (say $A_1,D_2,C_2)$ are not empty where $X_1$ is not consecutive with $Y_1$ and not consecutive with $Z_1$($Y_1,Z_1$ consecutive). Then $Y_2=Y^2_2 \cup Y^1_2$, and $Z_2=Z^1_2 \cup Z^2_2$ so that :
\begin{itemize}
\item $X_1$ is complete to $Y^2_2$ and $Z^2_2$. 
\item $X_1$ is independent of $Y^1_2$ and $Z^1_2$.
\item $Z^1_2$ and $Y^2_2$ form  a complete bipartite graph.
\item $Y^1_2$ and $Z^2_2$ form a complete bipartite graph.

\end{itemize}

\label{A0-A2-B2}
If $X_0$, $X_2$, and $Y_2$ ($X_2,Y_2$ are consecutive) are not empty then the following hold. 
\begin{itemize}
    \item [(1)] For every two vertices $a_0,a'_0 \in X_0$ with a common neighbor in $X_2$, $N(a_0) \cap Y_2 = N(a'_0) \cap Y_2$. 
    \item [(2)] For every two vertices $a_0,a'_0 \in X_0$ with a common neighbor in $Y_2$, $N(a_0) \cap X_2 = N(a'_0) \cap X_2$. 
    \item [(3)] For every two vertices $a_2,a'_2 \in X_2$ with a common neighbor in $X_0$, $N(a_2) \cap Y_2 = N(a'_2) \cap Y_2$. 

\end{itemize}

\label{chain-switch}
Let $a_1, a_2 \in V_j$ and $b_1, b_2 \in V_{j+1}$. Suppose that $a_1b_1 \in E(H)$, $a_2b_2 \in E(H)$, and $b_1a_2 \in E(H)$, but $a_1b_2 \notin E(H)$ (a `Z' shape). Then:
\begin{enumerate}
    \item $N(b_2) \cap V_{j+2} \subseteq N(b_1) \cap V_{j+2}$,
    \item $N(a_1) \cap V_{j-1} \subseteq N(a_2) \cap V_{j-1}$.
\end{enumerate}

\label{lem:safe-branching}
Algorithm~1 is complete under its preference rule: for every instance $G$, at least one root-to-leaf branch explored by the algorithm
is consistent with an optimal OCT of $G$.

\label{lem:gen-chain-switch}
Let $a_1, a_2 \in V_j$ and $b_1, b_2 \in V_{j+1}$. Suppose $a_1b_1, a_2b_2, a_2b_1 \in E(H)$ but $a_1b_2 \notin E(H)$ (forming  induced `Z' structure). Then:
\begin{enumerate}
    \item $N(b_2) \cap V_{j+2} \subseteq N(b_1) \cap V_{j+2}$
    \item $N(a_1) \cap V_{j-1} \subseteq N(a_2) \cap V_{j-1}$
\end{enumerate}

\label{lem:gen-2K2}
Let $a_1, a_2 \in V_j$ and $b_1, b_2 \in V_{j+1}$. Suppose the edges $a_1b_1 \in E(H)$ and $a_2b_2 \in E(H)$ form an induced $2K_2$ (i.e., $a_1b_2 \notin E(H)$ and $a_2b_1 \notin E(H)$).
Then $N(a_1) \cap V_{j-1} = N(a_2) \cap V_{j-1}$ and $N(b_1) \cap V_{j+2} = N(b_2) \cap V_{j+2}$.

\label{def:local-tester}
Let $c \in \mathbb{Z}_+$. Let $C = \ker(H)$ be a classical locally testable code, where $H \in \mathbb{F}_2^{m \times n}$ is a parity-check matrix. Define the local tester $\texttt{T}$ for the code $C$ as the following procedure:
\begin{enumerate}
    \item Given input $w \in \mathbb{F}_2^n$,
    \item Randomly sample $i_1, \ldots, i_c \in_R [m]$,
    \item Compute
    \begin{align*}
        r =
        \begin{bmatrix}
    H_{i_1} \\
    \vdots \\
    H_{i_c}
    \end{bmatrix}
        \cdot w \in \mathbb{F}_2^c,
    \end{align*}
    \item Reject if \( \bigvee_{j \in [c]} r_j = 1 \) (i.e., any parity constraint is violated).
\end{enumerate}

\label{def:tester}
Let $\texttt{T}$ be the local tester algorithm for a classical LTC, as defined in Definition~\ref{def:local-tester}. Let $l_r$ denote the number of random bits used by $\texttt{T}$, and let $q$ denote the number of bits of $q$ that are queried by the tester. For $r \in \mathbb{F}_2^{l_r}$, let $\texttt{T}(w; r)$ denote the output of $\texttt{T}$ when the randomness is $r$ and the query results corresponding to that randomness are given by $w$.

Then, for $a \in \mathbb{F}_2$, $w \in \mathbb{F}_2^q$, and $r \in \mathbb{F}_2^{l_r}$, define the local tester operator as
\begin{align*}
L_r(\ket{a} \ket{w} ) = \ket{a \oplus \texttt{T}(w; r)} \ket{w}\;.
\end{align*}

\label{def:tensor_op}
Let $e \in \mathbb{F}_2^n$ and let $W$ be a single-qubit operator. Define
\begin{align*}
W(e) = W^{e_1} \otimes W^{e_2} \otimes \cdots \otimes W^{e_n},
\end{align*}
that is, $W(e)$ applies $W$ at each position $i$ where $e_i = 1$ and applies the identity operator otherwise.

\label{def:dist_mod}
Let $C$ be a quantum CSS code and $H_X$, $H_Z$ the associated parity check matrices, as in Definition~ \ref{def:css}. Define
\begin{align*}
d_{q,X} =&~ \min\big\{ |w| : w \in \ker(H_X) \setminus \Im(H_Z^T) \big\}\;,\\
d_{q,Z} =&~ \min\big\{ |w| : w \in \ker(H_Z) \setminus \Im(H_X^T) \big\}\;.
\end{align*}

\label{lem:logical_qltc}
Let $C$ be an $[M, B_q, d_q]$ CSS code. Then there exist $F, G \in \mathbb{F}_2^{B_q \times M}$ such that $$X(F_1), \ldots, X(F_{B_q})$$ are $B_q$ linearly independent logical operators composed only of $X$ and identity operators, and $$Z(G_1), \ldots, Z(G_{B_q})$$ are $B_q$ linearly independent logical operators composed only of $Z$ and identity operators. Moreover, for each $i, j \in \{1, \ldots, B_q\}$, these operators satisfy
\[
X(F_i) Z(G_j) = (-1)^{1(i=j)} Z(G_j) X(F_i).
\]
Finally, it holds that
\begin{equation}\label{eq:kfg}
F H_Z^T = G H_X^T = 0 \;.
\end{equation}

\label{def:e_qltc}
Let $C$ be an $[M, B_q, d_q]$ CSS code.
Let $ H_X,H_Z$ be defined as in Definition \ref{def:css}.
Let $G$ be defined as in Lemma~\ref{lem:logical_qltc}.

For each $a \in \F_2^{B_q}$, let
\begin{align*}
\ket{\phi_a} =  \prod_{j\in [k]} \frac{I+ (-1)^{a_j} Z(G_j)}{2} \cdot \prod_{j}\frac{I+ X((H_X)_j)}{2}\cdot \prod_{j}\frac{I+ Z((H_Z)_j)}{2} \ket{+}^{\otimes M}.
\end{align*}
Let the following unitary $E_q$ be the encoding unitary of $C$:
\begin{align*}
E_q(\ket{a}\ket{0}^{\otimes (M-B_q)})=&~ \frac{\ket{\phi_a}}{\|\ket{\phi_a}\|}\; .
\end{align*}
For convenience, we also write $E_q(\ket{\phi})$ to denote $E_q(\ket{\phi}\ket{0}^{\otimes (M-B_q)})$.

\label{thm:qltc}
There exists a polynomial-time algorithm that, given an integer $N$ (in unary), returns explicit descriptions of parity-check matrices $H_X$ and $H_Z$ on $\Theta(N)$ qubits such that the following properties hold:
\begin{enumerate}
    \item The weight of each row of $H_X$ and $H_Z$ is $\Theta(1)$;
    \item The code $C = \mathrm{CSS}(H_X, H_Z)$ has dimension $\Theta(N)$ and distance $\Theta(\frac{N}{(\log N)^3})$;
    \item $C$ is a quantum locally testable code (qLTC) with soundness parameter $\rho = \Omega(\frac{1}{(\log N)^3})$.
\end{enumerate}

\label{def:decode:comp_p}
Let $M, m \in \mathbb{Z}_+$ such that $m$ divides $M$.
Let $W \in \{X, Z\}$.
Let $C_W$ be the linear code with parity-check matrix $H_W$ from Theorem~\ref{thm:qltc}, with codeword length $M$, dimension $B_W$.
Let $\texttt{D}_W$ denote its decoding algorithm.

Let $x = (x_i)_{i \in [M/m]}$ and $w = (w_i)_{i \in [M/m]}$ be tuples of blocks, with each $x_i, w_i \in \mathbb{F}_2^m$.
Define the \emph{partial composite decoding function} as:
 \begin{align*}
\texttt{D}_{p,W,i}(x, w) = \texttt{D}_W(x_1, \ldots, x_i, w_{i+1}, \ldots, w_{M/m}).
\end{align*}
For $i \in \{0, \ldots, M/m\}$, $x \in \mathbb{F}_2^{M}$, $w \in \mathbb{F}_2^{M}$, and $r \in \mathbb{F}_2^{B_W}$, define the partial composite decoding operator as:
 \begin{align*}
D_{p,W,i}(\ket{r} \ket{x} \ket{w}) = \ket{r \oplus \texttt{D}_{p,W,i}(x, w)} \ket{x} \ket{w}.
\end{align*}
Moreover,
for $w \in \mathbb{F}_2^{M}$ and $r \in \mathbb{F}_2^{B_W}$, define the one-sided decoding operator:
 \[
D_{W}(\ket{r} \ket{w}) =
\ket{r \oplus \texttt{D}_{p,W,0}(0, w)} \ket{w}.
\]
For $x \in \mathbb{F}_2^{M}$ and $r \in \mathbb{F}_2^{B_W}$, define the composite decoding operator:

 \begin{align*}
D_{c, W}(\ket{r} \ket{x}) =
\ket{r \oplus \texttt{D}_{p,W,M/m}(x, 0)} \ket{x}.
\end{align*}

Let $s, \delta: \mathbb{Z}^+ \rightarrow [0, 1]$ be functions. A verifier $V$ is said to be a probabilistically checkable proof of proximity (PCPP) system for a pair language $L$ with proximity parameter $\delta$ and soundness error $s$ if, for every pair of strings $(x, y)$, the following conditions hold:
\begin{itemize}
    \item \textnormal{Completeness:} If $(x, y) \in L$, then there exists a proof string $\pi$ such that $V(x)$ accepts the oracle $y \circ \pi$ with probability $1$.
    \item \textnormal{Soundness:} If $y$ is $\delta(|x|)$-far from $L(x)$, then for every $\pi$, the verifier $V(x)$ accepts the oracle $y \circ \pi$ with probability strictly less than $s(|x|)$.
\end{itemize}
If $s$ and $\delta$ are not explicitly specified, they are assumed to be constants in the interval $(0, 1)$.

\label{thm:pcpp_}
There exists a constant $\delta_0 \in (0, 1)$ such that for all $n \in \mathbb{Z}^+$ and all $\delta < \delta_0$, the language \textsc{Circuit Value} has a PCP of proximity (for circuits of size $n$) with the following parameters:
\begin{itemize}
    \item randomness complexity $O(\log n)$,
    \item query complexity $O(1)$,
    \item perfect completeness, and
    \item soundness error $1 - \Omega(\delta)$ for proximity parameter $\delta$.
\end{itemize}

\label{lem:pcpp_amp}
There exists a constant $\delta_0 \in (0, 1)$ such that for all $n \in \mathbb{Z}^+$ and all $\delta < \delta_0$, the language \textsc{Circuit Value} has a PCP of proximity (for circuits of size $n$) with the following parameters:
\begin{itemize}
\item randomness complexity $O(\log n)$,
\item query complexity $O(\log(s)/\log(1-\Omega(\delta)))$,
\item perfect completeness, and
\item soundness error $s$ for proximity parameter $\delta$.
\end{itemize}

\label{def:pcpp_generate}
Let $ s,l_x,l_y\in\Z_+$. Let $f : \F_2^{l_x}\times \F_2^{l_y} \to \F_2$ be classical circuits of size $s$. For each $ x\in \F_2^{l_x}, y\in \F_2^{l_y}$, let $f_x(y) = f(x,y)$.
Let $\texttt{N}$ be the classical algorithm that generates the proof for inputs to \textsc{CktVal} from Lemma~\ref{lem:pcpp_amp}. Suppose the output length of $\texttt{N}$ on input of size $ \Theta(s) $ is bounded by $ l_w(s)$.
For $a \in \mathbb{F}_2^{l_w(s)}$, $x \in \mathbb{F}_2^{l_x}$, $y \in \mathbb{F}_2^{l_y}$,  define the operator
\begin{align*}
N_f(\ket{a} \ket{x} \ket{y}) = \ket{a \oplus \texttt{N}(f_x, y)} \ket{x} \ket{y}.
\end{align*}

\label{def:pcpp_check}
Use the same notation as Definition \ref{def:pcpp_generate}.
Let $\texttt{T}$ be the verifier's algorithm from Lemma~\ref{lem:pcpp_amp}.
Let the randomness complexity of $\texttt{T}$ on instance size of $\Theta(n) $ be bounded by $l_r(n)$.

For $a \in \mathbb{F}_2$, $x \in \mathbb{F}_2^{l_x}$, $y \in \mathbb{F}_2^{l_y}$, $w \in \mathbb{F}_2^{l_w(n)}$, and $r \in \mathbb{F}_2^{l_r(n)}$, define
\begin{align*}
T_f( \ket{a} \ket{x} \ket{y} \ket{w} \ket{r} ) = \ket{a \oplus \texttt{T}(f_x, y, w; r)} \ket{x} \ket{y} \ket{w} \ket{r}.
\end{align*}

\label{def:qiop_}
A quantum interactive probabilistically checkable proof system for a promise problem $(S_{\text{yes}}, S_{\text{no}})$ satisfies the following:

Let $\omega(\texttt{V}, \ket{\phi}_{\mathsf{WP}})$ be defined as in Definition~\ref{def:qiop}. The system must satisfy:

\begin{itemize}
\item \textnormal{Completeness:} There exists a constant $c \in (0,1]$ such that for all $x \in S_{\text{yes}}$, the maximum acceptance probability satisfies ${\max}_{\ket{\psi}}\,\omega(\texttt{V}, \ket{\psi}_{\mathsf{W}}\ket{0}_{\mathsf{P}}) \geq c$. That is, there exists a quantum witness $\ket{\psi}$ and an honest prover strategy under which the verifier accepts with probability at least $c$.

\item \textnormal{Soundness:} There exists a constant $s \in [0, c)$ such that for all $x \in S_{\text{no}}$, the maximum acceptance probability satisfies ${\max}_{\ket{\phi}}\,\omega(\texttt{V}, \ket{\phi}_{\mathsf{WP}}) \leq s$. That is, no combination of prover strategy, prover's initial state, and jointly entangled quantum witness can cause the verifier to accept a no-instance with probability greater than $s$.
\end{itemize}

For $W\in\{X,Z\}$ we say that a Hamiltonian (hermitian matrix) $H$ is a $W$ projection if and only if $H$ acts non-trivially on a quantum register $\mathsf{S}$ of $k$ qubits as ${I + W_f}/{2}$, where $f: \F_2^{k} \rightarrow \F_2$ is a boolean function.\footnote{Recall the notation $W_f = \sum_x (-1)^{f(x)}S_W\proj{x}S_W$, with $S_W$ a tensor product of $I$ ($W=Z$) or $H$ ($W=X$).} More specifically,
\begin{align*}
H = \Big(\frac{I + W_f}{2}\Big)_{\mathsf{S}}\;.
\end{align*}

\label{def:d_ham}
A Hamiltonian $H \in \C^{2^n} \otimes \C^{2^n}$ is a dual-basis projector Hamiltonian if it is the uniform average of a polynomial number $m=\poly(n)$ of $X$  projection or $Z$  projection terms $H_i$. That is,
\begin{align*}
H = \frac{1}{m} \sum_{i \in [m]} H_i\;.
\end{align*}

Moreover, $H$ is $k$-local if each $H_i$ acts non-trivially on at most $k$ qubits.

\label{def:dlh}
Let $k \in \Z^+$ and let $a,b:\Z^+ \rightarrow \R^+$ be non-decreasing functions such that $\forall n \in \Z^+,~ a(n) < b(n)$. The local dual-basis projector Hamiltonian problem $\mathcal{DLH}(k,a,b)$ is the promise problem $(S_{yes}, S_{no})$ where
\begin{itemize}
\item $S_{yes}(n)$ is the set of $k$-local dual-basis projector Hamiltonians $H\in \C^{2^n} \otimes \C^{2^n}$ such that $\lambda_{\min}(H) \leq a(n)$,
\item $S_{no}(n)$ is the set of $k$-local dual-basis projector Hamiltonians $H\in \C^{2^n} \otimes \C^{2^n}$ such that $\lambda_{\min}(H) \geq b(n)$.
\end{itemize}

\label{def:qltc-local-testing}
Let $C=CSS(H_X, H_Z)$ be a stabilizer code on $n$ qubits, and let $\ket{\phi}$ be a quantum state. The verifier performs the following steps $c$ times:
\begin{itemize}
\item The verifier randomly samples $W \in \{X, Z\}$.
\item The verifier randomly samples a row $r_W$ from $H_W$.
\item The verifier measures the observable $W(r_W)$ on the state $\ket{\phi}$ and rejects if the measurement outcome is $-1$.
\end{itemize}
If none of the tests reject, the verifier accepts.

\label{lem:DO2Dq_beta}
Recall the notations introduced in Section~\ref{sec:notation}.
Let
\begin{align*}
\ket{\beta} = \sum_{(a,b)\in {\cal S}} 1(wt_{\text{cent}}(X(a)Z(b)) < \eta_q d_q )\cdot \alpha_{a,b} X(a)Z(b) \ket{\eta_{a,b}}
\end{align*}
be a quantum state, where $\{\ket{\eta_{a,b}}\}$ are codewords.
Then, for any Boolean function $f : \{0, 1\}^{B_q} \rightarrow \{0, 1\}$,
\begin{align*}
W''_{\Tilde{f}, W}\ket{\beta } =  W'_{f, W} \ket{\beta}.
\end{align*}

\label{lem:DO2Dq}
Recall the notations introduced in Section~\ref{sec:notation}.
Let
\[
\ket{\psi} = \sum_{(a,b)\in {\cal S}} \alpha_{a,b} X(a)Z(b) \ket{\eta_{a,b}}
\]
be a quantum state, where $\{\ket{\eta_{a,b}}\}$ are a family of codewords. Then, for any boolean function $f :\mathbb{F}_2^{B_q}\rightarrow \mathbb{F}_2$,
\begin{align*}
\|W''_{\Tilde{f} }\ket{\psi } -  W'_f \ket{\psi}\|^2 \leq \Theta(1)\cdot \sum_{(a,b)\in {\cal S}} 1(wt_{\text{cent}}(X(a)Z(b)) \geq \eta_q d_q)\cdot |\alpha_{a,b}|^2\;.
\end{align*}

\label{def:pcpp:hp}
Recall the notations introduced in Section~\ref{sec:notation}.

Let $C_P$ be a classical error-correcting code with dimension $k$, codeword length $n_P(k)$, decoder $\texttt{D}_P$, and code tester $\texttt{T}_P$.

Let
$\mathsf{U}$ be an $l_x$-qubit register denoting the output, $\mathsf{E}$ an $l_y$-qubit register denoting the encoded input, let $f:\F_2^{n_P^{-1}(l_y)} \rightarrow \F_2^{l_x}$ represent the verification of the computation.
Let $g:\F_2^{l_x}\times \F_2^{l_y} \rightarrow \F_2$ be defined as
\begin{align*}
g(x,y) = 1(f(\texttt{D}_P(y))=x) \wedge \texttt{T}_P(y)\;.
\end{align*}
Let $s$ be the size of the circuit $ g $.
Let $\mathsf{B}$ be a quantum register of  $l_{w}(s) $ qubits.
The honest prover performs the following steps:
\begin{itemize}
\item The prover computes an $l_{w}(s)$-bit long PCPP proof for a statement regarding the content of register $\mathsf{E}$. This proof is stored in register $\mathsf{B}$.
Formally,
the prover applies the following unitary:
\begin{align*}
N_{g, \mathsf{B} \mathsf{U} \mathsf{E}}\;.
\end{align*}

\item The prover sends the verifier the quantum registers $\mathsf{B}$.
\end{itemize}

\label{def:pcpp:v}
Use
the notation in Definition \ref{def:pcpp:hp}.
The verifier performs the following steps:
\begin{itemize}
\item The verifier executes the PCPP verifier on input $(g_x,y)$ and stores the verification result in a single qubit register $\mathsf{C}$, where $x$ is the contents of register $\mathsf{U}$, $y$ is the contents of register $\mathsf{E}$ and the proof is in register $\mathsf{B}$. The randomness is stored in register $\mathsf{R}$.
Formally, the verifier initialize $\mathsf{C}$ to $\ket{0}$ and $\mathsf{R}$ to $l_r(s)$  classical randomness bits, then the verifier applies $$T_{g, \mathsf{C}\mathsf{U}\mathsf{E}\mathsf{B}\mathsf{R}}.$$
\item The verifier rejects if the PCPP verifier rejects. Formally, the verifier  measures $\mathsf{C}$ and rejects if the outcome is $0$.
\end{itemize}

\label{lem:pcpp}
Let $ s,\delta$ be defined as in Notation \ref{not:pcpp}. Use the notation introduced in Definition \ref{def:pcpp:v}.

Let $\mathsf{O}$ be a quantum register representing all registers in the system except for $\mathsf{U}$, $\mathsf{E}$, and $\mathsf{B}$.
Let $\ket{\phi}_{\mathsf{O}\mathsf{U}\mathsf{E}\mathsf{B}}$ be the quantum state of the system before the prover returns the quantum registers $\mathsf{B}$.
Let the state be written as
\begin{align*}
\ket{\phi} = \sum_{o,u,e,b} \alpha_{o,u,e,b} \ket{o}_{\mathsf{O}}\ket{u}_{\mathsf{U}}\ket{e}_{\mathsf{E}}\ket{b}_{\mathsf{B}}.
\end{align*}

For $u\in\F_2^{l_x}$, let $S_u=\{e\in\F_2^{l_y}\mid 1(f(\texttt{D}_P(e))=u) \wedge \texttt{T}_P(e)=1\}$. If $f(\texttt{D}_P(e))=u$ for every $u\in\F_2^{l_x}$ and every $e\in\F_2^{l_y}$ with $\text{dist}(e,S_u)\le\delta$,
then
\begin{itemize}
\item The acceptance probability of the verifier is upper bounded by
\begin{align*}
\Pr[\text{PCPP test accepts}] \leq  \max\Big\{s , \sum |\alpha_{o,u,e,b}|^2 \cdot 1\Big( f(\texttt{D}_P(e))=u \Big)  \Big\} .
\end{align*}
\item The rejection probability of the verifier is lower bounded by
\begin{align*}
\Pr[\text{PCPP test rejects}] \geq  - s + \sum |\alpha_{o,u,e,b}|^2 \cdot 1\Big(f(\texttt{D}_P(e)) \neq u \Big) .
\end{align*}
\end{itemize}

Let $\mathsf{P}$ be a register and $U_\mathsf{P}$ a unitary acting on it. Let $\mathsf{R}$ be a one-qubit register.
The controlled unitary $C(U_\mathsf{P}, \mathsf{R})$ applies $U_\mathsf{P}$ if the qubit in $\mathsf{R}$ is $|1\rangle$:
\begin{align*}
    C(U_\mathsf{P}, \mathsf{R}) = \begin{pmatrix} I_\mathsf{P} & 0 \\ 0 & U_\mathsf{P} \end{pmatrix}\;.
\end{align*}

Let $\mathsf{P}, \mathsf{R}$ be registers and $O_\mathsf{P}$ an observable decomposed as $O = \sum_{i=1}^r a_i P_i$, where each $P_i$ is an orthogonal projection and $I = \sum_i P_i$. The unitary that performs the purified measurement and stores the outcome in $\mathsf{R}$ is:
\begin{align*}
