 \label{def:value_function}
Let $(T,\{X_t\}_{t\in V(T)})$ be a tree decomposition of $G({\cal F})$. For $t\in V(T)$, let $C_t$ be the set of its children. If $s\in C_t$, let $\forget(s\to t) \triangleq X_s\setminus X_t$, and let $\forget_t^{\downarrow} \triangleq X_{t}^{\downarrow}\setminus X_t$. 
We define its value function $\Potential$ as follows: for $t\in V(T)$ and a consistent assignment $\sigma=(x,u)$,
\begin{equation}\label{eqn:potential_dynamic_program}
\Potential[t,\sigma] = \bigoplus_{y\in \{0,1\}^{I_t^{\downarrow}}:\, y|_{I_t}=x} \quad \bigotimes_{
f\in {\cal F}\cap \fforget_t^{\downarrow}} \psi(z_f \cdot f(y)).
\end{equation}
If $\sigma$ is inconsistent, then $\Potential[t,\sigma]=\zero$.

\label{prop:dynamic_program_consistent_assignment}
   Let $(T,\{X_t\}_{t\in V(T)}$ be a tree decomposition of $G$.  
   If $\sigma$ is consistent, then
   \begin{equation} \label{eqn:dyn_prog_rec}
   \Potential[t,\sigma] = \bigotimes_{s\in C_t} \bigoplus_{\sigma^s\in\{0,1\}^{X_s}: \sigma^s|_{X_s\cap X_t}=\sigma|_{X_s\cap X_t}}\local(s\to t,\sigma^s)\otimes \Potential[s,\sigma^s]. 
   \end{equation}
   Moreover, the value function \eqref{eqn:potential_dynamic_program} is uniquely determined by recursion \eqref{eqn:dyn_prog_rec}, with value $\one$ at the leaves.

\label{prop:Laplace_mech}
For any function $f:\domain\mapsto\mathbb{R}$ such that for any $X\simeq X'$ satisfies $|f(X)-f(X')|\leq \Delta$, the mechanism that returns $\hat f(X) =  f(X)+\mathrm{Lap}\big(\frac{\Delta}{\varepsilon}\big),$\footnote{Recall the Laplace distribution $\mbox{Lap}(b)$ has density function $p(x)=\frac{1}{2b}\exp(-|x|/b)$.} satisfies $\varepsilon$-DP. Furthermore, this mechanism enjoys the following error bounds:
\begin{align*} 
\mathbb{P}[|\hat f(X)-f(X)|>\tau] &= \exp(-\varepsilon\tau/\Delta) \qquad(\forall \tau>0), \\
\mathbb{E}[|\hat f(X)-f(X)|] &\leq \frac{\Delta}{\varepsilon}.
\end{align*}
For high dimensions, where $F:\domain\mapsto\mathbb{R}^k$, considering the $\ell_1$-sensitivity, $\Delta=\sup_{X\simeq X'}\|F(X)-F(X')\|_1$, the mechanism that adds Laplace noise $\hat F(X)=F(X)+\mathrm{Lap}\big(\frac{\Delta}{\varepsilon}\big)^k$, and satisfies
\begin{align*} 
\mathbb{P}[\|\hat F(X)-F(X)\|_{\infty}<\tau] &\leq |{\cal F}|\exp(-\varepsilon \tau/\Delta),  \\
\mathbb{E}[\|\hat F(X)-F(X)\|_{\infty}] &\leq \frac{\Delta}{\varepsilon}(1+\ln k).
\end{align*}

{\bf \cite[Theorems 3.10 and 3.11]{DworkR14}}
 \label{prop:exp_mech}
 Let $\score:{\cal Y}\times\domain^{\ast}\mapsto\mathbb{R}$ be a function of a decision variable $y\in {\cal Y}$ and a private input $X\in \domain^{\ast}$. If 
 \[\Delta \triangleq \sup_{X\simeq X'} \max_{y\in {\cal Y}} |\score(y,X)-\score(y,X')|<+\infty,\] 
 then \Cref{alg:exp_mech}  
 is $\varepsilon$-DP, and satisfies
 \[\mathbb{P}\Big[ \score(Y,X)\leq \max_{w\in {\cal Y}}\score(w,X)-\frac{2\Delta}{\varepsilon}\Big(\ln(|{\cal Y}|)+\tau\Big) \Big]\leq \exp(-\tau) \qquad(\forall \tau>0).\]

