{theorem}{StatDistTrans}
\label{thm:stat-dist-trans}
    Let $\cF$ be a VC dimension $d$ class, and let $\dist^\star$ be an arbitrary distribution in $\Delta(\cX^T)$. Let $N \in\bbN$ be arbitrary. Then, there exists an algorithm that makes at most $N$ oracle calls to $\oracle_{\dist}$, at most $N^{O(d)}$ calls to a realizable ERM oracle w.r.t. $\cF$, and achieves regret \[
        \En \reg \lesssim d \log T + \frac{dT}{N} + d \cdot \KL{\dist^\star}{\dist} + \frac{T}{\log\left(1 + N/T\right)} \cdot \KL{\dist^\star}{\dist}.
    \]

{lemma}{CoverAnalysis}
\label{lemma:cover-analysis}
    Let $\seq Z  =\left(Z_1,\ldots,Z_N\right) \sim \bar \dist^{\otimes N}$, and $\cG(\seq Z)$ be an improper cover of $\cF$ constructed as follows
    \begin{equation}
    \label{eq:cg-ell}
    \cG(\seq Z) := \left\{\Alg_{\mathsf{M3}}\left((Z_i,y_i)_{i \in [N]}\right) \colon \left(y_i\right)_{i \in [N]} \in \left.\cF\right\vert_{\seq Z}\right\}.
    \end{equation}
        Then, for any $f\in\cF$, we have
      \[ \En_{\seq Z} \En_{\seq X \sim \dist}  \min_{g \in \cG(\seq Z)} \norm{f-g}_{\seq X} \lesssim\frac{d}{N}.\]

{theorem}{RealizableLB}
    \label{thm:realizable-lb}
    For any $d \in \bbN$, $N \ge 2$, and $D \in \bbN \cup \{0\}$, there exists a class $\cF$ of VC dimension $d$, such that, for any learning algorithm that draws at most $N$ unconditional samples from $\oracle_\dist$, there exists a choice of distributions $(\dist, \dist^\star)$ with $\KL{\dist^\star}{\dist} \le D$ and $f^\star \in \cF$ such that
    \[
    \En \reg(\cF, T) \gtrsim \left(d + \frac{d T}{N} + D + D  \frac{T}{\log N} \right)\land T
    \]

{theorem}{RealizableERMOracleLB}
\label{thm:realizable-erm-oracle-lb}
There is a sufficiently small constant $c$ so that the following holds. For any $d, N, T\in \bbN$ satisfying $TN \leq 2^{cd}$, and any learning algorithm $\Alg$ that draws at most $N$ unconditional samples from $\dist^\star$ and makes at most $N$ agnostic ERM oracle queries, there exists a class $\cF$ of VC dimension at most $d$ and a distribution $\dist^\star$ so that $\Alg$ suffers regret $\En \reg(\cF, T) \gtrsim T$.

{theorem}{AgnosticImpossibility}
\label{thm:agnostic-impossibility}
    Let $\cF$ be the class of thresholds on the $[0,1]$ interval. For any $N \ge 1$, and for any learning algorithm that draws at most $N$ unconditional samples from $\dist^\star$, there exists a choice of a distribution $\dist^\star$ and $f^\star \not \in \cF$ such that $\En \reg(\cF,T) \gtrsim T.$

{theorem}{CondOracleEff}
    \label{thm:cond-oracle-eff}
    Let $\cF$ be a VC dimension $d$ class. Then, there exists an algorithm that runs in $\poly(T)$ time and, given access to an agnostic ERM oracle over $\cF$ and a conditional sampling oracle $\condoracle_{\dist}$, achieves the following expected regret bound in the agnostic setting:
    \[
    \En \reg(\cF,T) \lesssim \sqrt{dT (1 + \KL{\dist^\star}{\dist})}.
    \]

{lemma}{IdealizedRegret}
    \label{lemma:idealized-regret}
    Let $\cF$ be a VC dimension $d$ class. Then, for every $\eta > 0$, an algorithm that plays according to~\cref{eq:relaxation-mgf-strategy} achieves the following expected regret bound in the agnostic setting:
\[
\En_{\dist^\star} \reg(\cF,T) \lesssim \sqrt{dT} + \frac{1}{\eta} \KL{\dist^\star}{\dist} + \eta T.
\]

{proposition}{ClosedFormStrategy}
    \label{prop:closed-form}
    For a history $\seq S_{1:t}$ and a covariate $X_t$, let
    \begin{equation}
        \label{eq:ayw}
    \off{y}(\seq W^t) :=
    \sup_{f\in \cF}\left[ \sum_{s=t+1}^T \varepsilon_s \frac{2f(X_s)-1}{2} - L_{t-1}(f) - \ind \{f(X_t) \neq y\} \right].
    \end{equation}
    Then, $q_t$ as in~\cref{eq:relaxation-mgf-strategy} can be written as
    \[
    q_t(\seq S_{1:t-1}, X_t) = \frac{1}{2} + \frac{1}{2\eta} \log \left(\frac{\En \exp(\eta \off{1}(\seq W^t))}{\En \exp(\eta \off{0}(\seq W^t))}\right)
    \]

{lemma}{RegMGFIntermediate}
\label{lemma:reg-mgf-intermediate}
Let $\cF$ be a VC dimension $d$ class. Then, an algorithm that plays according to~\cref{eq:plug-in} with $N$ samples per step and inverse temperature $\eta$ achieves the following regret bound
\begin{align*}
\En_{\dist^\star} \reg(\cF,T) \lesssim \sqrt{dT} + \eta T + \frac{1}{\eta} \KL{\dist^\star}{\dist} + T \sqrt{\frac{\exp(O(\eta \sqrt{dT} + \eta^2 T))}{N}}.
\end{align*}

{corollary}{LearnabilitySublinearKL}
\label{cor:sim-families}
Let $\cP$ be a family of processes with $\cR(\cP) \le o(T)$, and $\cF$ a bounded VC dimension class. Then, there exists a (possibly inefficient) algorithm that achieves sublinear agnostic regret for every $\dist^\star \in \cP$. Moreover, for every $D \in \bbN$, there exists $\cP$ with $\cR(\cP) \le D \land T$ and a VC class of dimension $1$, such that any algorithm suffers regret $\Omega(D \land T)$ even in the realizable setting.

{theorem}{UniversalDist}
\label{thm:universal-dist}
    Let $p \colon \mathbb N \to \mathbb N$ be a time-constructible bound. There exists a time bound $p'(t) =\poly(p(t))$ and a sequence of measures $\{\mu^t\}_{t \ge 1}$, with each $\mu^t \in \Delta (\Sigma^*)$ samplable in time $p'(t)$ that satisfy the following. For any $p$-time samplable distribution $P$ and any $\seq x \in \cX^t$ we have
    \[
    \log \frac{P_{1:t}(\langle \seq x \rangle)}{\mu^t(\langle \seq x\rangle)} \le K^p(P) + 2\log K^p(P) + O(1).
    \]

{theorem}{SamplableNature}
\label{thm:samplable-nature}
    Suppose the distribution $\dist^\star$ of nature is $p$-time samplable (as per~\Cref{def:samplable}). Let $\cF$ be any class of VC dimension $d$. Then, there exists an algorithm that, given access to a realizable ERM oracle w.r.t. $\cF$, runs in time $\poly(T^d, p(T))$ and for any $f^\star \in \cF$, achieves regret
    \[
    \En \reg (\cF, T ) \lesssim d \log(T) + d \cdot 2^{K^p(\dist^\star) + 2\log K^p(\dist^\star)}.
    \]

