    \begin{itemize}
        \item For every $S\subset [n]$ with $|S|=k$, there exists $X\in\mathcal{S}$ such that $X\subset S$;
        \item $\mathcal{S}$ contains at most $\frac{\binom{n}{t}}{\binom{k}{t}}\cdot 2^{o(n)}$ sets;
    \end{itemize}
    $\mathcal{S}$ is called $(n,k,t)$-set-inclusion family and the algorithm works in $|\mathcal{S}|\cdot 2^{o(n)}$ time.

\label{lemma:modified-local-search-bound}
    Let $c_1>c_2\ge 1$ be two constants and $n\ge k\ge t$ be three non-negative integers.
    Then $$\frac{\binom{n}{k}\cdot c_1^{k-t}}{\binom{n-t}{k-t}\cdot c_2^{k}}\le \left(1+\frac{1}{c_2}-\frac{1}{c_1}\right)^n\cdot \polyn.$$

\label{lemma:m(n)=pairs}
For every positive integer $n$, $m(n)$ is the largest integer $m$ for which there exists a collection $\{(A_i,B_i)\}_{i \in [m]}$ of $m$ pairs of subsets of $[n]$ such that for every $i \in [m]$, there exists a permutation \mbox{$\pi_i:[n] \to [n]$} such that for all $j \in [m]$, it holds that
\[ \pi_i(A_j) = B_j ~~~\mbox{if and only if}~~~ i=j.\]

\label{thm:pairs}
Let $k$ and $n$ be positive integers, such that $2k$ divides $n$.
Then there exists a collection $\{(A_i,B_i)\}_{i \in [m]}$ of \[m = {\binom{2k}{k}}^{n/k-1}\] pairs of subsets of $[n]$, each of size $n/2$, such that
\begin{enumerate}
  \item\label{itm:1} for every permutation $\pi:[n] \to [n]$ there exists an $i \in [m]$ such that $\pi(A_i) = B_i$, and
  \item\label{itm:2} for every $i \in [m]$ there exists a permutation $\pi_i:[n] \to [n]$ such that for all $j \in [m]$, it holds that
  \[\pi_i(A_j) = B_j ~~\mbox{ if and only if}~~ i = j.\]
\end{enumerate}

\label{cor:lower_m(n)}
For all positive integers $k$ and $n$ with $n \geq 2k$, it holds that
\[ m(n) \geq {\binom{2k}{k}}^{2 \cdot \lfloor n/(2k) \rfloor -1}.\]

\label{thm:final_m(n)}
There exists a constant $c > 0$ such that for all positive integers $n$, it holds that
\[ 2^{2n-c \cdot (n \log n)^{1/2}} \leq m(n) \leq 2^{2n-(\log n)/2}.\]

\label{thm:NO_split}
For all positive integers $k$ and $q$ with $q \geq 2k$, there exists an irreducible $\NO$ instance $(G,L)$ of $\qListCol$, where $G$ is a split graph on at least \[{\binom{2k}{k}}^{2 \cdot \lfloor q/(2k) \rfloor-1}\]
vertices. Therefore, there exists a constant $c>0$ such that for all positive integers $q$, there exists such an instance on at least $2^{2q-c \cdot (q \log q)^{1/2}}$ vertices.

\label{lem:decode-from-regret}
Let $\mathcal{B}$ be any online algorithm (quantum or classical) run on the
decoding game~\eqref{eq:masking-loss}, and let
$R_{\mathcal{B}}(|\mathcal{W}|)$ denote its expected regret against the best
fixed action. Define the epoch-$k$ estimator $\hat{z}_k$ to be the empirical
mode of the actions $\mathcal{B}$ plays during epoch $k$. Then
\begin{equation}
\frac1K\sum_{k=1}^{K}\Pr[\hat{z}_k\neq z_k]
\;\le\;\frac{R_{\mathcal{B}}(|\mathcal{W}|)}
{(1-2\varepsilon_{\mathrm{prep}})\,|\mathcal{W}|}\;+\;\frac1B .
\label{eq:decode-bound}
\end{equation}

\label{thm:separation}
Suppose Assumptions~\ref{ass:gibbs-mapping} and~\ref{ass:bcl-realizable} hold,
and that the BCL hardness assumption holds: no polynomial-time classical
algorithm samples a distribution within constant total-variation distance of
$\mu^\star$, on pain of collapsing the polynomial hierarchy. Run the decoding
game~\eqref{eq:masking-loss} with epoch length $B=\Theta(\log d)=\Theta(n)$. Then
the following hold.
\begin{enumerate}[label=(\roman*),leftmargin=*]
\item \emph{Quantum achievability.} DQMW-Sample attains
\begin{equation}
R_{\mathrm{DQMW}}(|\mathcal{W}|)
\;=\;O\!\bigl(\sqrt{|\mathcal{W}|\,\log d}\bigr)
\;=\;O\!\bigl(\sqrt{n\,|\mathcal{W}|}\bigr).
\label{eq:sep-upper}
\end{equation}
Its engineered Davies dissipator~\eqref{eq:davies-generator} prepares
$\rGibbs\approx\rho^\star$ each epoch, so its computational-basis sample is
distributed within $\varepsilon_{\mathrm{prep}}$ of $\mu^\star$; concentrating on
the epoch mode over $B=\Theta(n)$ rounds recovers $z_k$ with error
$O(1/\mathrm{poly}(n))$, and the residual regret is the standard
multiplicative-weights rate over $d$ experts.
\item \emph{Classical lower bound.} Every efficient (per-round
$\mathrm{poly}(n)$-time) classical online learner $\mathcal{C}$ incurs
\begin{equation}
R_{\mathcal{C}}(|\mathcal{W}|)\;=\;\Omega\!\bigl(|\mathcal{W}|\bigr),
\label{eq:sep-lower}
\end{equation}
i.e.\ non-vanishing average regret.
\item \emph{Separation.} Consequently, under standard complexity assumptions
there is an online-learning instance on which DQMW-Sample is asymptotically
no-regret while every efficient classical learner suffers $\Omega(1)$ average
regret, with
\begin{equation}
\frac{R_{\mathcal{C}}(|\mathcal{W}|)}{R_{\mathrm{DQMW}}(|\mathcal{W}|)}
\;=\;\Omega\!\Bigl(\sqrt{|\mathcal{W}|/n}\Bigr).
\label{eq:sep-ratio}
\end{equation}
\end{enumerate}

\label{lem:transcript-marginal}
Under Assumptions~\ref{ass:gibbs-mapping}--\ref{ass:bcl-realizable}
and~\ref{ass:reachability}, the marginal of $\mathcal{P}_T$ on the
round-$t_\star$ coordinate, restricted to and reweighted by the good-prefix event
$\mathcal{G}$, is within total-variation distance $\varepsilon_{\mathrm{prep}}$ of
$\mu^\star$. Concretely, the conditional law
\begin{equation}
\nu\;:=\;\mathrm{law}\bigl(i_{t_\star}\,\big|\,(i_1,\dots,i_{t_\star-1})\in\mathcal{G}\bigr)
\quad\text{satisfies}\quad
\TV(\nu,\mu^\star)\le\varepsilon_{\mathrm{prep}}.
\label{eq:cond-marginal}
\end{equation}

Let $N = 2^k$ be a positive integer. 
The problem $\iter_N^{dt}$ is defined as follows.
As input, for each element $u \in [N]$, we are given a \emph{successor} $s_u \in [N]$, interpreted as naming the successor node of $u$, and which we can think of as being encoded by a string of $k$ bits.
The goal of the search problem is to output any of the following
\begin{enumerate}
\item $1$ if $s_1 = 1$ \hfill \emph{(inactive distinguished source)}
\item $u \neq 1$, if $s_u < u$, \hfill \emph{(decreasing successor)}
\item $u$, if $u$ is active and $s_u$ is a proper sink. \hfill \emph{(proper sink)}
\end{enumerate}

\label{def:non-uniform mapping reduction}
    Let $R \in \TFNP$ and let $F(x_1, \dots, x_n) = C_1 \land \cdots \land C_m$ be an unsatisfiable CNF formula.
    Let $\ell(n)$ denote the polynomial upper bound on the length of any solution to $R$ on inputs of length $n$.
    A \emph{non-uniform mapping reduction} from $\search_F$ to $R$ is given by two circuits $C : \{0,1\}^n \rightarrow \{0,1\}^s, D : \bits^n \times \bits^{\ell(s)} \rightarrow \bits^m$, such that
    \begin{equation}\label{eq:nu-reduction}
        R(C(x), y) \implies \unsat_F(x, D(x, y)).
    \end{equation}

\label{def:imp_proof}
The formula $\mathrm{ImpProof}_{\Res}(n, m, s, C, P, N)$ is the conjunction of the following formulas:
\begin{itemize}
    \item $\isCkt(n, C)$
    \item $\mathrm{Active}(n, s, C, 1^s) \land \mathrm{Empty}(n, s, C, 1^s)$
    \item $\forall Y < s: \mathrm{Active}(n, s, C, Y) \rightarrow \mathrm{isWeaken}(n, s, C, Y) \lor \mathrm{isResolve}(n, s, C, Y) \lor \exists i < m: \mathrm{isAxiomW}(n, m, s, i, P, N, C, Y)$.
\end{itemize}

\label{def:reduction-v1vpv}
    Let $\iter$ denote the polynomial-time function symbol encoding the polynomial-time verifier for the $\iterlong$ problem.
    The formula $\Reduction_\iter(n, m, s, C, D, P, N)$ is defined to be the conjunction of the formulas:
    \begin{itemize}
        \item $\isCkt(n, C)$,
        \item $\isCkt(n+s, D)$,
        \item and the formula
        \begin{multline*}
            \forall X < n, Y < s: \iter(s, \Eval(n, s, C, X), Y) \rightarrow\\
            \unsat(n, m, P, N, X, \Eval(n+s, m, D, X \circ Y))
        \end{multline*} 
        where $\circ$ denotes string concatenation.
    \end{itemize}

\label{thm:formalizationPLSResConv}
    There is a polynomial-time algorithm $R$ and a number term $t$ such that $\V^1(\VPV)$ proves
    \[ \mathrm{Reduction}_\iter(n, m, s, C, D, P, N) \rightarrow \ImpProof_{\Res}(n, m, t(\vec y, \vec Y), R(\vec y, \vec Y), P, N), \] where $\vec y = (n, m, s)$ and $\vec Y = (C, D, P, N)$.

\label{lem:conv_to_exists}
 Let $F = \bigwedge_{i=1}^m C_i$ be an unsatisfiable CNF, and suppose $G_1 \vdash \lnot F$. Then \[G_1 \vdash \exists i \, \Big(\llbracket i = 1 \rrbracket \lor \cdots \lor \llbracket i = m \rrbracket\big) \land \big( (\llbracket i = 1 \rrbracket \rightarrow \lnot C_1) \land \cdots \land ( \llbracket i = m \rrbracket \rightarrow \lnot C_m)\Big).\]
    This is the quantified version of the $\unsat_F$ formula of Definition \Cref{def:unsat-cnf}, and it is near identical to the first-order formula $\unsat_F$ used to define $\mathsf{Reduction}_\iter$. We will denote this as $\unsat^q_F$.

 $\WrongProof_P:= \{\WrongProof_{P,n,m,s}\}_{n,m,s}$ is the false clause search problem associated with the unsatisfiable formula $\neg \refl_P$, which asserts that a formula has both a $P$-proof and a falsifying assignment. Formally, \begin{align}
    \WrongProof_{P,n,m,s}(x,z) :&= \unsat_{\neg \refl_{P,n,m,s}}(x,z) \nonumber \\
    &=\unsat_{\Proof_{P,n,m,s}}(x,z_1) \lor \unsat_{\neg \mathrm{SAT}_{n,m}}(x,z_2),
\end{align}
Recalling that we use a one-hot encoding in $\unsat$, $z_1$ are the bits that represent the clauses of $\Proof$, while $z_2$ are those belonging to $\mathrm{SAT}$. As well, $x=(\alpha,F,\Pi)$ is a tuple encoding an assignment, a formula (claimed to be a tautology), and a proof $\Pi$.
Recall from \Cref{def:unsat-cnf} that this is a problem in $\TFNP$.

\label{clm:EF_properties}
    For any CNF formula $F$ on $n$ variables, the following hold:
    \begin{enumerate}
        \item Extended Frege has $\poly(|F|)$-size proofs of $\neg  F(x) \rightarrow \unsat_F(x,y)$, for new variables $y$, and $\unsat_F(x,y) \rightarrow \neg F(x)$.
        \item For any circuit $C: \{0,1\}^t \rightarrow \{0,1\}^n$, if Extended Frege can prove $F$ then it also has $\poly(|C|)$-size proofs of  $\Eval(C,x',x) \wedge F(x)$.
    \end{enumerate}

\label{lem:forwardGeneral}
    Let $P,Q$ be proof systems such that $EF \leq_p P \leq_p Q$
    and $Q$ proves the reflection principle for $P$. If $\langle EF,\WrongProof_{P}\rangle$ has a size $s$ refutation of $F$, then $Q$ has a size $\poly(s)$ refutation of $F$.

\label{def:pk}
Let all formulas be propositional and under the DeMorgan basis. A \emph{PK proof} uses the following rules. 

\[
\begin{array}{l l}

\text{(Ax)}\;
\inferrule*[right=Ax]{ }{A \rightarrow A}
&
\text{(Cut)}\;
\inferrule*[right=Cut]{\Gamma \rightarrow A \\ \Delta, A \rightarrow B}{\Gamma, \Delta \rightarrow B}
\\

\text{(WL)}\;
\inferrule*[right=WL]{\Gamma \rightarrow A}{\Gamma, B \rightarrow A}
&
\text{(WR)}\;
\inferrule*[right=WR]{\Gamma \rightarrow A}{\Gamma \rightarrow A, B}
\\

\text{(CL)}\;
\inferrule*[right=CL]{\Gamma, A, A \rightarrow B}{\Gamma, A \rightarrow B}
&
\text{(CR)}\;
\inferrule*[right=CR]{\Gamma \rightarrow A, A}{\Gamma \rightarrow A}
\\

\text{(EL)}\;
\inferrule*[right=EL]{\Gamma, A, B, \Delta \rightarrow C}{\Gamma, B, A, \Delta \rightarrow C}
&
\text{(ER)}\;
\inferrule*[right=ER]{\Gamma \rightarrow A, B, \Delta}{\Gamma \rightarrow B, A, \Delta}
\\

\text{(neg L)}\;
\inferrule*[right=neg L]{\Gamma \rightarrow A, \Delta}{\Gamma, \neg A \rightarrow \Delta}
&
\text{(neg R)}\;
\inferrule*[right=neg R]{\Gamma, A \rightarrow \Delta}{\Gamma \rightarrow \neg A, \Delta}
\\

\text{(and L)}\;
\inferrule*[right=and L]{\Gamma, A, B \rightarrow \Delta}{\Gamma, A \wedge B \rightarrow \Delta}
&
\text{(and R)}\;
\inferrule*[right=and R]{\Gamma \rightarrow A, \Delta \\ \Gamma \rightarrow B, \Delta}{\Gamma \rightarrow A \wedge B, \Delta}
\\

\text{(or L)}\;
\inferrule*[right=or L]{\Gamma, A \rightarrow \Delta \\ \Gamma, B \rightarrow \Delta}{\Gamma, A \vee B \rightarrow \Delta}
&
\text{(or R)}\;
\inferrule*[right=or R]{\Gamma \rightarrow A, B, \Delta}{\Gamma \rightarrow A \vee B, \Delta}

\end{array}
\]

\label{def:G}
	We adapt Frege to allow quantified formulas introduced by the following rules:

	\[
\begin{array}{l l}

(\forall\text{-left})\;
\inferrule*{A(B),\, \Gamma \rightarrow \Delta }{\forall x A(x), \Gamma \rightarrow \Delta}
&
(\forall\text{-right})\;
\inferrule*{\Gamma \rightarrow \Delta, A(p)}{\Gamma \rightarrow \Delta, \,\forall x\, A(x)}
\\

(\exists\text{-left})\;
\inferrule*{A(p), \,\Gamma \rightarrow \Delta }{\exists x A(x),\, \Gamma \rightarrow \Delta}
&
(\exists\text{-right})\;
\inferrule*{\Gamma \rightarrow \Delta, A(p)}{\Gamma \rightarrow \Delta, \,\exists x\, A(x)}


\end{array}
\]


For the $\forall$-right and $\exists$-left rules, the variable $p$ is called an \emph{eigenvariable} and cannot appear in the bottom sequent. The $G$ proof system is simply $PK$ with these additional rules. For $i\geq 0$, $G_i$ is a restriction of $G$ to only allow cuts on $\left(\Sigma^q_i \cup \Pi^q_i\right)$-formulas. (That is, the cut rule for $G_i$ can only be applied to formulas with at most $i$ alternations of $\forall$ and $\exists$ quantifiers.) 

While the $G$ systems can prove validity of  general QBF formulas, it is also interesting to understand their strength with respect to Boolean formulas.
Since $G$ (and even $G_1$) has all of EF rules plus additional rules, $G$ can trivially p-simulate EF (with respect to Boolean formulas). 
And it is known that the tree-like version of $G_1$, called $G_1^*$ is p-equivalent to EF. On the other hand, it is unknown whether or not $G_1$ is  stronger than EF (with respect to Boolean formulas), and it is generally conjectured to be more powerful wrt p-simulations.

\label{thm:v1_witnessing}
	Let $\phi(\vec x, \vec y, \vec X, \vec Y)$ be a $\Sigma^B_0$ formula.
	If \[V^1 \vdash \forall \vec x, \vec X \exists \vec y, \vec Y \phi(\vec x, \vec y, \vec X, \vec Y),\] then there are polynomial-time functions $f_1, \dots, f_k$, $F_1, \dots, F_m$ such that \[V^1(\vec f, \vec F) \vdash \forall \vec x, \vec X \phi(\vec x, \vec f(\vec x, \vec X), \vec X, \vec F(\vec x, \vec X)).\]

\label{thm:tv1_witnessing}
    Let $\phi(\vec x, \vec y, \vec X, \vec Y)$ be a $\Sigma^B_0(VPV)$ formula.
	If \[\mathsf{TV}^1 \vdash \forall \vec x, \vec X \exists \vec y, \vec Y \phi(\vec x, \vec y, \vec X, \vec Y),\] then there is a polynomial-time function $F$, and an $\Iter$ instance with graph $G_\phi(x, X, Z)$ such that \[\mathsf{V}^1(\mathsf{VPV})  \vdash  G_\phi(\vec x, \vec X) \longrightarrow \phi(\vec x, \vec X, F(\vec x, \vec X, Z)).\]

\label{lem:performance-difference-deviation-policy}
Fix a stationary joint policy $\Policy$ and a deviation
policy $\DeviationPolicy{i}$ for player $i$.  
Then
\begin{equation}
\Value{i}{\DeviationProfile{i}}{\State{0}}-\Value{i}{\Policy}{\State{0}}
=
\frac{1}{1-\Discount}
\sum_{s\in\StateSpace}
\VisitDist{\State{0}}{\DeviationProfile{i}}{s}
\CoarseAdvantage{i}{\Policy}{\DeviationPolicy{i}}{s}.
\label{eq:coarse-perf-diff}
\end{equation}

\label{lem:controller-value}
For every variable state $\State{u}$,
\begin{equation}
(1-\Discount)(1-\lambda)\RewMarg{u}
\le
\Value{\Controller}{\Policy}{\State{u}}
\le
(1-\Discount)\bigl((1-\lambda)\RewMarg{u}+\lambda\bigr)+\Discount.
\label{eq:controller-value-interval}
\end{equation}
In particular, when $\Discount=1/16$, the following hold:
\begin{align}
\RewMarg{u}\le\frac14&\Rightarrow \Value{\Controller}{\Policy}{\State{u}}\le \frac{19}{64}+\frac{45\lambda}{64},
\label{eq:read-low-lambda}\\
\RewMarg{u}\ge\frac34&\Rightarrow \Value{\Controller}{\Policy}{\State{u}}\ge \frac{45}{64}-\frac{45\lambda}{64},
\label{eq:read-high-lambda}\\
\RewMarg{u}\le\frac23&\Rightarrow \Value{\Controller}{\Policy}{\State{u}}\le \frac{88}{128}+\frac{40\lambda}{128},
\label{eq:read-two-thirds-lambda}\\
\RewMarg{u}\ge\frac13&\Rightarrow \Value{\Controller}{\Policy}{\State{u}}\ge \frac{40}{128}-\frac{40\lambda}{128}.
\label{eq:read-one-third-lambda}
\end{align}

\label{lem:decorrelation-identity}
Let $\Policy$ be any stationary joint policy of $G_\lambda(I)$.  Let $\Policy_{\RewardPlayer}^{\mathrm{br}}$ be the stationary reward-player deviation that, at each variable state $\State{u}$, plays action $1$ if $\CtrlMarg{u}\ge1/2$ and plays action $0$ otherwise.  Let $\Policy_{\Controller}^{\mathrm{dec}}$ be the stationary controller deviation that, at each variable state $\State{u}$, plays action $1$ with probability $\CtrlMarg{u}$ and action $0$ with probability $1-\CtrlMarg{u}$ independently of the reward player's action.  At sinks the deviations play uniformly.  Define
\[
\Delta_{\RewardPlayer}:=\Value{\RewardPlayer}{\Policy_{\Controller}\times\Policy_{\RewardPlayer}^{\mathrm{br}}}{\InitialDist}-\Value{\RewardPlayer}{\Policy}{\InitialDist}
\quad \text{and} \quad
\Delta_{\Controller}^{\mathrm{dec}}:=\Value{\Controller}{\Policy_{\Controller}^{\mathrm{dec}}\times\Policy_{\RewardPlayer}}{\InitialDist}-\Value{\Controller}{\Policy}{\InitialDist}.
\]
Then
\begin{equation}
\Delta_{\RewardPlayer}+\lambda^{-1}\Delta_{\Controller}^{\mathrm{dec}}
=
\sum_{u\in\NodeSet}\VisitDist{\InitialDist}{\Policy}{\State{u}}
\left(B(\CtrlMarg{u})-\ProdMatch{u}\right).
\label{eq:decorrelation-identity}
\end{equation}
Moreover, every summand on the right-hand side of \eqref{eq:decorrelation-identity} is nonnegative.

\label{thm:nonperfect-unconditional}
There exists a universal constant $\kappa>0$ such that computing a non-perfect Markov $\varepsilon$-CCE of a discounted two-player single-controller Markov game is \PPAD-hard whenever $\varepsilon<\frac{\kappa}{|\StateSpace|^2}$.
The hardness holds with fixed discount factor $\Discount=1/16$, rewards in $[0,1]$, and binary actions at all states.

Fix a stationary joint policy $\Policy$ and a deviation
policy $\DeviationPolicy{i}$ for player $i$.  
Then
\begin{equation}
\Value{i}{\DeviationProfile{i}}{\State{0}}-\Value{i}{\Policy}{\State{0}}
=
\frac{1}{1-\Discount}
\sum_{s\in\StateSpace}
\VisitDist{\State{0}}{\DeviationProfile{i}}{s}
\CoarseAdvantage{i}{\Policy}{\DeviationPolicy{i}}{s}.
\label{eq:coarse-perf-diff_}
