\label{conj:PACC}
    There exists a polynomial $p$, such that for all $n$ and $\delta >0$,
    \begin{equation}
        \Pr_{M \sim \calG^{n \times n}} \left( |\Per(M)| < \frac{\sqrt{n!}}{p(n,1/\delta)} \right) < \delta \, .
    \end{equation}

\label{thm:weakPACC}
Let $M \sim \calG^{n \times n}$ be a random Gaussian matrix.
Then, there exists a constant $c > 0$ such that for all $\alpha > 0$ and $n$ sufficiently large depending on $\alpha$,
\begin{equation}
\Pr_{M \sim \calG^{n \times n}} \left( | \Per (M) | < \frac{\sqrt{n!}}{n^{\alpha n}} \right) =
O \left( \frac{1}{n^c} \right) \, .
\end{equation}

\label{coro:typicalvalue}
    For a random matrix $M \sim \calG^{n \times n}$, we have 
    \begin{equation}
        | \Per (M) | = n^{( \frac{1}{2} + o (1) ) n} \, ,
    \end{equation}
    asymptotically almost surely, i.e., with probability $1 - o (1)$.

\label{maintainingmanylargeminors_main}
    Let $1 \le k \le (1 - \epsilon)n$ for some $\epsilon > 0$, $N \ge 1$, and $\lambda > 0$. Then
    \begin{equation}
        \Pr(E_{k+1,\, \epsilon N/6,\, \lambda} \mid E_{k,N,\lambda}) \ge 1 - 2\exp(-\Omega(\epsilon n)) \, .
    \end{equation}

\label{lemma:growingmanylargeminors_main}
    Under the same conditions as \cref{maintainingmanylargeminors_main}, with an additional parameter $0 < c < 1$, we can partition $E_{k,N,\lambda}$ into two exclusive events $E'_{k,N,\lambda,c}$ and $E''_{k,N,\lambda,c}$ (depending only on the first $k$ rows) such that
    \begin{equation}
        \Pr(E_{k+1,\, n^c N,\, \lambda} \mid E'_{k,N,\lambda,c}) \ge \frac{1}{3}
    \end{equation}
    and
    \begin{equation}
        \Pr(E_{k+1,\, \epsilon N/4,\, n^{1/2-c}\lambda} \mid E''_{k,N,\lambda,c}) \ge 1 - n^{-c/4} \, .
    \end{equation}

The probability density function for $z \sim \CC \calN (\mu, \sigma^2)$ is given by
\begin{align}
    p(z) = \frac{1}{\pi \sigma^2} \exp(- \frac{|z - \mu|^2}{\sigma^2}) \ .
\end{align}

\label{prop:prob_z_circle}
Let $z \sim \CC \calN(\mu, \sigma^2)$ be a complex Gaussian random variable with mean $\mu$ and variance $\sigma^2$. Then,
\begin{align}
    \Pr (|z - \mu| \leq R) = 1 - e^{-\frac{R^2}{\sigma^2}} \ .
\end{align}
In particular, when $z \sim \calG$, we have $\Pr(|z| \leq 1) = 1 - e^{-1}$.

\label{lemma:first_moment}Let $E_1, \ldots, E_m$ be arbitrary events (not
necessarily independent) such that $\Pr (E_i) \ge 1 - \delta$ for all
$1 \leq i \leq m$ and some $\delta > 0$, and let $0 < c < 1$. Then,
\begin{equation}
    \Pr ( \text{At most $c m$ among $E_1, \ldots, E_m$ are false} ) \ge 1 - \frac{\delta}{c} \, .
\end{equation}

\label{lemma:McDiarmid}Let $X_1, X_2, \ldots, X_n$ be independent random variables
such that $X_i \in \mathfrak{X}_i$ for some measurable sets
$\mathfrak{X}_i$. Suppose that $f : \prod_{i = 1}^n \mathfrak{X}_i
\rightarrow \mathbb{R}$ is ``Lipschitz'' in the following sense:   For each $k \le n$, and any two sequences $\vb{x}, \vb{x}' \in \prod_{i = 1}^n
\mathfrak{X}_i$ that differ only in the $k$-th coordinate, we have
\begin{equation}
  | f (\vb{x}) - f (\vb{x}') | \le \sigma_k \, .
\end{equation}
Let $Y = f (X_1, X_2, \ldots, X_n)$.  Then for any $\alpha > 0$,
\begin{equation}
  \Pr \{ | Y - \Ex [Y] | \ge \alpha \} \le 2 \exp \left\{ -
  \frac{2 \alpha^2}{\sum_{i = 1}^n \sigma_i^2} \right\} \, .
\end{equation}

\label{lemma:supermartingale}
Let $\mathcal{F}_0 \subset \mathcal{F}_1 \subset \cdots \subset \mathcal{F}_m$ be a filtration, and let $W_0, W_1, \ldots, W_m$ be $\mathcal{F}_i$-measurable real-valued random variables satisfying the supermartingale property $\Ex[W_i \mid \mathcal{F}_{i-1}] \leq W_{i-1}$ for all $1 \leq i \leq m$. Assume also that $|W_i - W_{i-1}| \leq c$ for all $1 \leq i \leq m$. Then for any $\lambda \geq 0$,
\begin{equation}
  \Pr(W_m - W_0 \geq \lambda) \leq \exp\left(-\frac{\lambda^2}{2 c^2 m}\right) \, .
\end{equation}

\label{lemma:large_parent_has_large_child}
Suppose that $M \sim \calG^{n \times n}$ is sampled.
Let $A \in \binom{[n]}{k}$ for some $1 \le k < n$, and let $i \not\in A$. 
Assume that the submatrix $M^{(k)}$ is fixed and we expose a random row $\vec{X}_{k+1} \sim \calG^n$. Then
\begin{equation}
\Pr\left( | \Per ( M_{A \cup \{ i \}} ) | \ge \left| \Per (M_A) \right| \right) \ge \frac{1}{e} \, .
\end{equation}

\label{maintainingasinglelargeminor}
    Suppose $M \sim \calG^{n \times n}$ is sampled, $A \in \binom{[n]}{k}$ for some $1 \le k < n$, and $I \subseteq [n] - A$. Let
    \begin{equation}
        \nu(A, I) := \#\{i \in I : |\Per(M_{A\cup\{i\}})| \ge |\Per(M_A)|\} \, .
    \end{equation}
    Conditioning on $M^{(k)}$ fixed and exposing the random row $k+1$,
    \begin{equation}
        \Pr(\nu(A, I) \ge 1) \ge 1 - \eta^{-|I|} \, ,
    \end{equation}
    where $\eta := e/(e-1)$. This implies $\Pr(E_{k+1, 1, \lambda} \mid E_{k, 1, \lambda}) \ge 1 - \eta^{-(n-k)}$.

\label{lemma:growing_many_large_minors}
    Under the assumptions of \cref{maintainingasinglelargeminor} with $k < (1-\epsilon)n$,
    \begin{equation}\label{eq12}
        \Pr(\nu(A, I) \ge |I|/3) \ge 1 - \exp(-\Omega(|I|)) \, ,
    \end{equation}
    which implies $\Pr(E_{k+1, \epsilon n/3, \lambda} \mid E_{k,1,\lambda}) \ge 1 - \exp(-\Omega(\epsilon n))$.

\label{maintainingmanylargeminors}
    Let $1 \le k \le ( 1 - \epsilon ) n$ for some $\epsilon > 0$, let $N \ge 1$ and let $\lambda > 0$. 
    Then we have
    \begin{equation}
        \Pr ( E_{k + 1, \epsilon N / 6, \lambda} | E_{k, N, \lambda} ) \ge 1 - 2\exp ( - \Omega ( \epsilon n ) ) \ .
    \end{equation}

\label{prop:growingmanylargeminors}
    Let $1 \le k \le ( 1 -  \epsilon ) n$ for some $ \epsilon > 0$, let $N \ge 1$, let $0 < c < 1$, and let $\lambda > 0$. 
    We can partition the event $E_{k, N, \lambda}$ as $E_{k, N, \lambda, c}' \vee E''_{k, N, \lambda, c}$, where the events $E_{k, N, \lambda, c}'$ and $E''_{k, N, \lambda, c}$ depend only on the first $k$ rows of $M$.
    Then, we have
    \begin{equation}
    \Pr ( E_{k + 1, n^c N, \lambda}  | E'_{k, N, \lambda, c}
    ) \ge \frac{1}{3}
    \end{equation}
    and
    \begin{equation}
    \Pr ( E_{k + 1,  \epsilon N / 4, n^{1 / 2 - c} \lambda}  |
    E''_{k, N, \lambda, c} ) \ge 1 - n^{- c / 4} \ .
    \end{equation}

\label{proposition:second_step}
Fix a desired $\alpha > 0$ and choose $\epsilon > 0$ sufficiently smaller than $\alpha$. Let $k_1 = \floor{(1 - \epsilon) n}$. Then, we have
    \begin{equation}
        \Pr(E_{k_1,1, n ^{(1/2 - \alpha)n}}) \geq 1 - \exp(-\Omega(\epsilon' n)) \, ,
    \end{equation}
where $\epsilon' > 0$ is sufficiently small compared to $\epsilon$.

\label{endgame}Let $1 \le k \le ( 1 -  \epsilon )
n$ for some $ \epsilon > 0$, and let $\lambda > 0$. Then
\begin{equation}
  \Pr ( E_{n, 1, n^{- \log n}  \lambda}  | E_{k, 1, \lambda}
  ) \ge 1 - n^{- \Omega (1)} \, .
\end{equation}

We have
\begin{equation}
  \Pr ( F_{L, \left\lfloor  \epsilon n / 10 L \right\rfloor, \lambda}
  ) = 1 - \exp ( - \Omega (L) ) = 1 - n^{- \Omega (1)} \, .
\end{equation}

\label{iteration}Let $1 < j \le L$, $N \ge n^{0.5}$ (say), and
$\lambda' > 0$. Then
\begin{equation}
  \Pr ( F_{j - 1, \lfloor N / 12 \rfloor, \lambda' / n^2}  |
  F_{j, N, \lambda'} ) \ge 1 - n^{- \Omega (1)}
\end{equation}

\label{lem:ratio}
Let $1\le q\le k$.  Prescribing $q$ vertices inside a row and $q$
vertices outside it retains a definite fraction of the slice:
\[
 \frac{\binom{n-2q}{\ell-q}}{\binom n\ell}
 \ \ge\ \frac9{10}\Bigl(\frac2e\Bigr)^{q}
 \Bigl(\frac\ell n\Bigr)^{q}.
\]

\label{lem:even-density}
The Kikuchi graph converts hyperedges into degree according to
\[
        \bd\ge\frac9{20\sqrt r}\Bigl(\frac8e\Bigr)^{r}
        \Bigl(\frac\ell n\Bigr)^{r}|\cH| .
\]

\label{lem:even-trace}
If $\cH$ has no even cover of size at most $2s$, then
\[
 \Tr K^{2s}
 =\sum_{S\in\Om_\ell}
 \bigl\langle(S,\varnothing)\bigr|\,\Lop^{2s}\,
 \bigl|(S,\varnothing)\bigr\rangle.
\]

\label{lem:even-indegree}
Suppose $\cH$ has no even cover of size at most
$\max\{2s,\ \ell+ks+1\}$.  Then every lifted state has in-degree at
most $2\ell$ under the above orientation, and
\begin{equation}\label{eq:even-spectral}
        \norm K\ \le\ 2\sqrt{\frac{2\ell}{\bd}}\;N^{1/(2s)} .
\end{equation}

\label{def:spread}
For $1\le q\le k-1$, put
$h_q:=\max\{2,\lceil(n/\ell)^{\,q-k/2}\rceil\}$.
A \emph{spread bundle of residual size} $q$ is a family $\cB\subseteq\cH$
of $h_q$ hyperedges through a common $(k-q)$-set $U_\cB$, so that every
$F\in\cB$ decomposes as $F=U_\cB\mathbin{\dot\cup}R_F$ with
\emph{residual} $R_F$ of size $q$, such that
\begin{equation}\label{eq:spread}
        \#\{J\in\cB: T\subseteq R_J\}<h_{q-t}
\end{equation}
for every $F\in\cB$ and every $T\subseteq R_F$ with
$1\le t:=|T|<q$.

\label{lem:odd-contention}
If $q\le r$, then $c(z)\le1$ for every port $z$.  If $q\ge r+1$, then
the total excess contention obeys
\begin{equation}\label{eq:odd-contention}
        \sum_zc(z)\bigl(c(z)-1\bigr)\le\Xi_q\,\mu_q,
        \qquad
        \Xi_q:=8\,B_q\,(2.031)^{a}\,\Bigl(\frac n\ell\Bigr)^{b-k/2}.
\end{equation}

\label{lem:odd-gain}
With the weights \eqref{eq:odd-weights}, the graph $Y$ converts
hyperedges into degree according to
\begin{equation}\label{eq:odd-gain}
        \bd\ \ge\ \frac{(1.0324)^k}{74\,k^3}\,
        m_+\Bigl(\frac\ell n\Bigr)^{k/2}.
\end{equation}

\label{prop:odd-trace}
Let $s\ge1$.  If $\cH$ has no even cover of size
at most $\max\{4s,\ 2\ell+4ks+2\}$, then $\bd\le32\,\ell\,N^{1/s}$.

\label{thm:main-inference}
There are constants $C_{k,\delta},c_k>0$ such that, for every level satisfying
\cref{eq:range},
\begin{equation}\label{eq:inference-threshold}
 m\ge C_{k,\delta}\frac{\Dkl}{\rho^2}
\end{equation}
suffices for a spectral algorithm running in $n^{\ell+O_k(1)}$ time to
achieve strong detection and to output, under planting, an assignment
$\widehat x$ with
\[
 \begin{cases}
 |\ip{\widehat x}{\xstar}|\ge c_kn,&k\text{ even},\\[1mm]
 \ip{\widehat x}{\xstar}\ge c_kn,&k\text{ odd},
 \end{cases}
\]
with probability $1-o(1)$.

\label{lem:poisson-insertion}\label{lem:fixed-deletion}
Let $F\ge0$ be insertion-nonincreasing: adjoining a further marked
label never increases $F$.
\begin{enumerate}
\item If $\Xi$ is a marked Poisson process with finite intensity
measure $\nu$, then for every nonnegative measurable $g$ and $s\ge1$,
\begin{equation}\label{eq:poisson-insertion}
 \E\!\sum_{(z_1,\ldots,z_s)\in\Xi_{\ne}^{s}}
 F(\Xi)g(z_1,\ldots,z_s)
 \le
 \int\!\cdots\!\int
 \E F(\Xi)g(z_1,\ldots,z_s)
 \,d\nu(z_1)\cdots d\nu(z_s).
\end{equation}
\item If instead $\Xi$ consists of $m$ i.i.d.\ marked labels
$Z_1,\ldots,Z_m$ and $F$ is a function of the unordered sample, then
for $1\le s\le m$,
\begin{equation}\label{eq:fixed-deletion}
 \E\sum_{\substack{i_1,\ldots,i_s\le m\\ \text{distinct}}}
 F(Z_1,\ldots,Z_m)\,g(Z_{i_1},\ldots,Z_{i_s})
 \ \le\
 (m)_s\,\E\bigl[F(Z_{s+1},\ldots,Z_m)\,g(Z_1,\ldots,Z_s)\bigr],
\end{equation}
where $(m)_s:=m(m-1)\cdots(m-s+1)$.
\end{enumerate}
Both parts hold conditionally after any finite set of labels has been
exposed explicitly, with the intensity, respectively the number of
unexposed labels, adjusted accordingly.

\label{lem:copy-transfer}
Let $A'$ be an independent copy of a random object $A$ and suppose
$X(A)=\E_{A'}S(A,A')$, where $S(A,A')$ is self-adjoint.  Let
$R(A,A')\succ0$ satisfy $|v^{\mathsf T}Sv|\le v^{\mathsf T}Rv$ for all
$v$.  Suppose that, on an event $\cG$ depending only on $A$,
\begin{equation}\label{eq:copy-mean}
 \E_{A'}R(A,A')\preceq C\,\Gamma(A),
\end{equation}
that there is a pair event $\cH$ with
\begin{equation}\label{eq:copy-pointwise}
 R(A,A')\preceq M\,\Gamma(A)\quad\text{on }\cG\cap\cH,
 \qquad
 \E_{A'}\bigl[\1_{\cH^c}R(A,A')\bigr]\preceq\zeta\,\Gamma(A)
 \quad\text{on }\cG,
\end{equation}
and that jointly
$\bbP\{\|R^{-1/2}SR^{-1/2}\|>\lambda_0\}\le p_0$.  Then, outside an event
of probability at most $\bbP(\cG^c)+\sqrt{p_0}$,
\begin{equation}\label{eq:copy-conclusion}
 \|\Gamma^{-1/2}X\,\Gamma^{-1/2}\|
 \le C\lambda_0+M\sqrt{p_0}+\zeta.
\end{equation}

\label{lem:down-identities}
With $J_0:=I$,
\begin{align}
 \partial_\ell^{\mathsf T}\partial_\ell&=\ell I+J_1,
 \label{eq:down-one}\\
 (\partial_\ell^{[s]})^{\mathsf T}\partial_\ell^{[s]}
 &=\sum_{j=0}^s\binom{\ell-j}{s-j}J_j,
 \label{eq:down-s}\\
 \|\partial_j\|^2&=j(n-j+1).
 \label{eq:down-norm}
\end{align}

\label{lem:rdm-identity}
For every $u\in\mathbb R^{\Omega_\ell}$ and
$\bar x:=\xstar/\sqrt n$,
\begin{equation}\label{eq:rdm-identity}
 \bar x^{\mathsf T}\rhoone(Zu)\bar x
 =\frac{\|\partial_\ell u\|^2}{n\ell}.
\end{equation}

\label{thm:transfer}
Fix $s\ge1$ and $0<c\le1$.  There are $c_{s,c}>0$ and $n_0(s,c)$ such
that, for every $s\le\ell\le n/3$ and $n\ge n_0(s,c)$, every unit vector
$u\in\mathbb R^{\Omega_\ell}$ satisfying
\begin{equation}\label{eq:johnson-energy}
 u^{\mathsf T}J_su\ge c\,b_{s,\ell}
\end{equation}
obeys
\begin{equation}\label{eq:transfer}
 \bar x^{\mathsf T}\rhoone(Zu)\bar x\ge c_{s,c}.
\end{equation}

\label{lem:active}
At every prefix, with $S$ the current row and $\chi$ the current excess,
\begin{equation}\label{eq:active}
 \#\{a\in\cO:|C_a\cap S|=r\}\le\frac{\ell+2\chi}{r}.
\end{equation}

\label{lem:chronology}
Fix $r\ge1$, $t\ge1$, and $\chi\ge0$.
\begin{enumerate}
\item For single-label words of length $2t$ with exactly $t$ openings,
the chronologies with final excess $\chi$ number at most $C_r^t2^\chi$.
\item For pair words of length $2t$, in which each step uses an
unordered pair of disjoint residual labels and every label has even
total multiplicity, the chronologies with final excess $\chi$ number at
most $C_r^t2^\chi$.
\end{enumerate}

\label{thm:single-trace}
Fix $r\ge1$ and $\delta>0$, and let $\ell$ satisfy \cref{eq:range}.  Let
$\{C_a\}$ be either a Poisson family or a deterministic number of
independent uniform residual supports in $\binom{[n]}{2r}$.  Let
$\sigma_a$ be independent Rademacher signs and let $u_a\in[-1,1]$ be
coefficients independent of the signs and, conditional on any auxiliary
marks, independent of the supports.  Define
\begin{equation}\label{eq:single-operator}
 \cS:=\sum_a u_a\sigma_aA_{C_a},
 \qquad
 G:=\sum_a|u_a|P_{C_a},
 \qquad
 \Gamma:=G+dI,
\end{equation}
where $d>0$ is deterministic.  Assume that, after every fixed branch
prefix of a $2t$-step trace and for every $h\ge0$, the conditional expected
weighted mass of labels that are new on that branch, legal at its current
row, and recycle exactly $h$ previously exposed exterior vertices is at
most
\begin{equation}\label{eq:single-mass}
 d\left(\frac{C_rt}{n}\right)^h.
\end{equation}
Then, for $t=\lfloor c\ell\log n\rfloor$ with
$c=c(r,\delta)>0$ sufficiently small,
\begin{equation}\label{eq:single-moment}
 \E\Tr(\Gamma^{-1/2}\cS\Gamma^{-1/2})^{2t}
 \le N\left(\frac{C_r\ell}{rd+\ell}\right)^t
 \sum_{\chi\ge0}
 \left(\frac{C_rt}{n}\right)^\chi
 \left(1+\frac{2\chi}{\ell}\right)^t,
\end{equation}
and, for every fixed $B>0$,
\begin{equation}\label{eq:single-tail}
 \bbP\left\{
 \|\Gamma^{-1/2}\cS\Gamma^{-1/2}\|
 >C_{r,\delta,B}\sqrt{\frac{\ell}{rd+\ell}}
 \right\}\le n^{-B\ell}.
\end{equation}
The same conclusion holds for a fixed finite superposition of independent
families, with their masses and diagonal degrees added.

\label{thm:packet-trace}
Fix $r\ge1$, $\delta>0$, and $C_0\ge1$, and let $\ell$ satisfy
\cref{eq:range}.  Let $\Xi$ be a single family of marked labels, each
label $a$ carrying a residual $C_a\in\binom{[n]}{2r}$: either a marked
Poisson process of finite intensity, or a deterministic number of
i.i.d.\ marked labels.  An unordered pair $p=\{a,b\}$ of distinct labels
with disjoint residuals carries the symmetric partial matching
$B_{C_a,C_b}$; write $\mathcal E(p)$ for its undirected row edges, and
for $e=(p,\{S,T\})\in\mathcal E(p)$ put $A_e:=E_{S,T}+E_{T,S}$, so that
$S\sd T=C_a\sd C_b$.  Given the full unsigned marked configuration
$\xi$, let $\omega_e(\xi)\in[0,C_0]$ be the retained amplitude of the
row edge $e$, and let $G_\xi\succeq0$ be diagonal.  Assume:
\begin{enumerate}[label=\textup{(P\arabic*)}]
\item\label{P-monotone} For every row edge already exposed on the
current branch, $\omega_e(\xi)$ is insertion-nonincreasing, and $G_\xi$
is insertion-nondecreasing.
\item\label{P-diagonal} Pointwise, for every row $S$,
\begin{equation}\label{eq:packet-diagonal}
 G_\xi(S,S)\ge
 \sum_{e:S\in e}\omega_e(\xi).
\end{equation}
\item\label{P-port} For every row $S$ and physical label $a$,
\begin{equation}\label{eq:packet-port}
 \sum_{e:S\in e,\,a\in p(e)}\omega_e(\xi)\le C_0.
\end{equation}
\item\label{P-mass} After any fixed chronological branch prefix of a
$2t$-step trace, the deletion masses obtained after dropping the
insertion-nonincreasing retention factors of the fresh edges satisfy,
for total first-use excess $h$,
\begin{align}
 \text{two new labels:}&\quad C_0d(C_0t/n)^h,\label{eq:packet-mass-two}\\
 \text{exactly one new label, the partner among at most $4t$ exposed:}
 &\quad C_0t\beta(C_0t/n)^h,\label{eq:packet-mass-one}\\
 \text{a new partner of one fixed exposed label:}
 &\quad C_0\beta(C_0t/n)^h,\label{eq:packet-mass-partner}
\end{align}
where $d>0$ is a deterministic floor and $0<\beta\le C_0$ satisfies
$\beta^2\le C_0d/n$ and $t\beta\le c_0d$ for a sufficiently small
$c_0=c_0(r,C_0)$.  In the Poisson case these are the deletion masses
of \cref{eq:poisson-insertion}; in the
fixed-sample case they are those of
\cref{eq:fixed-deletion}, with the floor $d$ held fixed throughout.
\end{enumerate}
Let the physical labels carry signs $\sigma_a$ that, conditional on the
unsigned configuration $\xi$, are independent Rademacher variables, and
define
\begin{equation}\label{eq:packet-operator}
 \cS_\xi:=\sum_p\sum_{e\in\mathcal E(p)}
 \omega_e(\xi)\,\sigma_{a(p)}\sigma_{b(p)}A_e,
 \qquad
 \cR_\xi:=dI+G_\xi.
\end{equation}
Then, for $t=\lfloor c\ell\log n\rfloor$ with
$c=c(r,\delta,C_0)>0$ sufficiently small,
\begin{equation}\label{eq:packet-moment}
 \E\Tr(\cR_\xi^{-1/2}\cS_\xi\cR_\xi^{-1/2})^{2t}
 \le N\left(\frac{C_{r,C_0}\ell}{d}\right)^t
 \sum_{\chi\ge0}
 \left(\frac{C_{r,C_0}t}{n}\right)^{\chi/2}
 \left(1+\frac{2\chi}{\ell}\right)^t,
\end{equation}
and, for every fixed $B>0$,
\begin{equation}\label{eq:packet-tail}
 \bbP\left\{
 \|\cR_\xi^{-1/2}\cS_\xi\cR_\xi^{-1/2}\|
 >C_{r,\delta,B,C_0}\sqrt{\frac\ell d}
 \right\}\le n^{-B\ell}.
\end{equation}

\label{prop:even-null}
Let the clause family be either a Poisson pool of mean $\bar m$ or
exactly $\bar m$ i.i.d.\ clauses; in particular, the full fixed-$m$ input
is allowed.  For every fixed $B>0$, under the null,
\begin{equation}\label{eq:even-null}
 \bbP\left\{
 \|K\|>C_{r,\delta,B}\sqrt{\frac{\ell}{r\bd+\ell}}
 \right\}\le n^{-B\ell}.
\end{equation}

\label{lem:even-witness}
Under the planted law, for the spectral pool, with probability $1-o(1)$,
\begin{equation}\label{eq:even-witness}
 \lambda_{\max}(K)\ \ge\ \frac\rho2-o(\rho),
\end{equation}
uniformly over the levels in \cref{eq:range}.

\label{prop:even-comparison}
Assume $\bd\ge C_{r,\delta}\ell$.  With
probability $1-o(1)$,
\begin{equation}\label{eq:even-comparison}
 \left\|\Gamma^{-1/2}\bigl(ZAZ-\rho\tau J_r\bigr)\Gamma^{-1/2}\right\|
 \ \le\ C_{r,\delta}\sqrt{\frac\ell\bd}.
\end{equation}

\label{lem:odd-uniqueness}
For every candidate and mark realization:
\begin{enumerate}
\item for every root $u$, the retained graph
$K_u:=\sum_{g:u(g)=u}A_g$ is a partial matching; in particular, at most
one retained edge is incident with a given cell $(u,S)$, and for every
fixed candidate $e$ the subgraph $L_e:=\sum_{g:e\in g}A_g$ is a partial
matching as well;
\item if a retained edge $g=(u;\{e,f\};\{S,T\})$ has
$\theta_e\theta_f=1$, then $g_u(S)=g_u(T)=1$; irrespective of the
marks, $g_u(S)\ge\alpha^2$ and $g_u(T)\ge\alpha^2$;
\item $\|H_{\rm o}\|\le1$ and
$\|\Gamma_{\rm o}^{-1/2}\cP_{\rm o}\,\Gamma_{\rm o}^{-1/2}\|\le1$.
\end{enumerate}

\label{lem:odd-palm-degree}
There are constants $0<c_r<C_r<\infty$ such that
\begin{equation}\label{eq:odd-dcirc}
 c_rd\le d_\circ\le C_rd,
 \qquad
 \E\cP_{\rm o}=\frac{d_\circ}{b_{2r,\ell}}J_{2r}.
\end{equation}

\label{prop:odd-population}
For every fixed $B>0$, the population estimate
\begin{equation}\label{eq:odd-pop-conc}
 \left\|\cP_{\rm o}-\frac{d_\circ}{b_{2r,\ell}}J_{2r}\right\|
 \le C_{r,B}\alpha^2(\sqrt{n\log N}+\log N)=o(d)
\end{equation}
holds with probability at least $1-2N^{-B}$.  Independently of $B$,
with probability $1-o(1)$,
\begin{equation}\label{eq:odd-raw-trace}
 \Tr\Gamma_{\rm o}\le C_rdN
\end{equation}
and
\begin{equation}\label{eq:odd-max-diagonal}
 \max_{S\in\Omega_\ell}\Gamma_{\rm o}(S,S)\le C_r(d+\log N).
\end{equation}

\label{prop:odd-null}
For every fixed $B>0$, under the null,
\begin{equation}\label{eq:odd-null}
 \bbP\left\{\|H_{\rm o}\|>
 C_{r,\delta,B}\sqrt{\frac\ell d}\right\}\le n^{-B\ell}.
\end{equation}

\label{prop:odd-comparison}
Assume $m\ge C_{k,\delta}\rho^{-2}\Dkl$, with the leading constant
sufficiently large.  Then, with probability $1-o(1)$,
\begin{equation}\label{eq:odd-comparison}
 \left\|\Gamma_{\rm o}^{-1/2}
 \bigl(Z\cC_{\rm o}Z-\rho^2\cP_{\rm o}\bigr)
 \Gamma_{\rm o}^{-1/2}\right\|
 \le C_{r,\delta}\sqrt{\frac\ell d}.
\end{equation}

\label{prop:odd-witness}
There is a constant $c_r^{\rm sig}>0$, depending only on $r$, such that
under the planted law, with probability $1-o(1)$,
\begin{equation}\label{eq:odd-witness}
 \lambda_{\max}(H_{\rm o})\ge c_r^{\rm sig}\rho^2.
\end{equation}

\label{prop:odd-recovery}
Under the hypotheses of \cref{thm:odd-detection}, the high-Rayleigh vector
for $H_{\rm o}$, followed by \cref{thm:transfer,lem:rounding,lem:validation},
outputs $\widehat x\in\{\pm1\}^n$ with
$\ip{\widehat x}{\xstar}\ge c_kn$ with probability $1-o(1)$, in
$n^{\ell+O_k(1)}$ time.

\label{lem:odd-cert}
Set $\bar g:=N^{-1}\Tr G_{\rm ref}$.  For every input, every rooting,
and every $x\in\{\pm1\}^n$,
\begin{equation}\label{eq:odd-pair-upper}
 P_0(x)\le
 \frac{2N(\bar g+d_*)}{\Delta_{r,\ell}}
 \max\{0,\lambda_{\max}(H_{\rm ref})\}
 +\frac{4\Def}{\Delta_{r,\ell}}.
\end{equation}
Consequently, for every certified
$U\ge\max\{0,\lambda_{\max}(H_{\rm ref})\}$,
\begin{equation}\label{eq:odd-cert-value}
 \Cert_{\rm odd}(I):=\frac1m\left\{n\left[
 m+\frac{2N(\bar g+d_*)}{\Delta_{r,\ell}}U
 +\frac{4\Def}{\Delta_{r,\ell}}+N_{\rm int}
 \right]\right\}^{1/2}
\end{equation}
is an upper bound on $\sup_x|V_I(x)|$.

\label{prop:iso-null}
Let $t=\lfloor c\ell\log n\rfloor$ and assume
\begin{equation}\label{eq:iso-conditions}
 d_*\ge C_r\ell,
 \qquad
 \mu_0\le c_r,
 \qquad
 t\mu_0\le c_rd_*.
\end{equation}
Then the fixed-$m$ null model satisfies
\begin{equation}\label{eq:iso-null}
 \|H_{\rm ref}\|\le C_{r,\delta}\sqrt{\frac\ell{d_*}}
\end{equation}
with failure probability $n^{-\Omega_r(\ell)}$.

\label{def:sign-degree}
For $D\ge0$, let $\cH_D\subseteq L^2(Q_m)$ be the closed subspace of
functions
\begin{equation}\label{eq:sign-degree}
 g(F,y)=\sum_{|A|\le D}g_A(F)\,y_A ,
\end{equation}
where each coefficient $g_A$ may be an arbitrary square-integrable
function of the \emph{entire} support sequence.  Write $\Pi_{\le D}$ for
the orthogonal projection onto $\cH_D$.

\label{lem:class-containment}
Each of the following lies in $\cH_D$:
\begin{enumerate}
\item every polynomial of degree at most $D$ in the signed one-hot
variables $X_{a,\alpha}:=y_a\1\{F_a=\alpha\}$,
$\alpha\in\binom{[n]}k$;
\item every polynomial of degree at most $D$ in the aggregated signed
counts $Z_\alpha:=\sum_{a}y_a\1\{F_a=\alpha\}$;
\item every function of Efron--Stein degree at most $D$ in the
independent observations $(F_a,y_a)_{a\le m}$.
\end{enumerate}
Moreover, an independent random seed may be adjoined to the support-side
data, so the lower bounds below also cover randomized procedures of sign
degree $D$.

\label{lem:boundary-lr}
For every $B\subseteq[n]$,
\begin{equation}\label{eq:boundary-expansion}
 L_B(F,y)=\sum_{A\subseteq[m]:\ \partial_FA=B}\rho^{|A|}\,y_A,
 \qquad
 \Pi_{\le D}L_B=\sum_{\substack{|A|\le D\\ \partial_FA=B}}
 \rho^{|A|}\,y_A,
\end{equation}
and consequently
\begin{equation}\label{eq:projection-norm}
 \bigl\|\Pi_{\le D}L_B\bigr\|_{L^2(Q_m)}^2
 =\sum_{t=0}^{\min\{D,m\}}\binom mt\rho^{2t}\,q_{t,B},
 \qquad
 q_{t,B}:=\bbP\{F_1\sd\cdots\sd F_t=B\},
\end{equation}
where $F_1,\ldots,F_t$ are independent uniform $k$-sets.

\label{lem:boundary-count}
Let $B\subseteq[n]$ with $b:=|B|$, and let $F_1,\ldots,F_t$ be
independent uniform $k$-subsets of $[n]$.  If $kt-b$ is negative or odd
then $q_{t,B}=0$.  Otherwise, for $n\ge2k$,
\begin{equation}\label{eq:boundary-count}
 q_{t,B}\ \le\ \left(\frac{2kt}n\right)^{(kt+b)/2} .
\end{equation}

\label{thm:master}
Assume $D\le n/(2k)$ and $\Lambda_D\le1/2$.
\begin{enumerate}
\item For every nonempty $B\subseteq[n]$ of fixed size $b$,
\begin{equation}\label{eq:master-B}
 \bigl\|\Pi_{\le D}L_B\bigr\|_2^2
 \ \le\ \frac{\Lambda_D}{1-\Lambda_D}
 \left(\frac{2kD}n\right)^{b/2}
 \ \le\ C_{k,b}\left(\frac Dn\right)^{b/2}.
\end{equation}
\item For the planted mixture,
\begin{equation}\label{eq:master-empty}
 \bigl\|\Pi_{\le D}(L_\varnothing-1)\bigr\|_2^2
 \ \le\ \frac{\Lambda_D^2}{1-\Lambda_D}\ \le\ 2\Lambda_D^2 .
\end{equation}
\end{enumerate}

\label{thm:ld-recovery}
Let $d\le n/(4k)$ and suppose
$e(2k)^{k/2}\rho^2m(2d)^{k/2-1}/n^{k/2}\le1/2$.  Then every estimator
$f=(f_1,\ldots,f_n)$ with $f_i\in\cH_d$ and $|f_i|\le1$ pointwise obeys
\begin{equation}\label{eq:ld-recovery}
 \E_{x,\,I\sim P_{m,x}}
 \Bigl(\frac1n\sum_{i=1}^nx_if_i(I)\Bigr)^{2}
 \ \le\ \frac1n+C_k\sqrt{\frac dn},
\end{equation}
the expectation being over a uniform hidden assignment and the planted
instance.  Consequently, if $d=o(n)$, no such estimator attains
nonvanishing absolute overlap below
$m\asymp_kn^{k/2}/(\rho^2d^{k/2-1})$.  The statement is
parity-independent and already respects the global sign ambiguity for
even $k$.

\label{thm:minimax}
Even with unlimited computation,
\begin{equation}\label{eq:minimax}
 \inf_{\widehat x}\ \sup_{\xstar\in\{\pm1\}^n}
 \E_{I\sim P_{m,\xstar},\,U}
 \bigl[\err_k\bigl(\widehat x(I,U),\xstar\bigr)\bigr]
 \ \ge\ c_k\exp\bigl(-C_k\rho^2m/n\bigr),
\end{equation}
where $U$ denotes the estimator's internal randomness.  Consequently,
minimax expected error $\vartheta$ requires
$m=\Omega_k(n\rho^{-2}\log(1/\vartheta))$.  Moreover, by a separate
argument, exact recovery with probability $1-o(1)$ requires
$m=\Omega_k(n\rho^{-2}\log n)$.

\label{thm:ld-refutation}
Fix $0<\eps\le1/4$ and $D\le n/(2k)$, and let
\begin{equation}\label{eq:ld-ref-threshold}
 m\ \le\ c_k\,\frac{n^{k/2}}{\eps^2D^{k/2-1}}
\end{equation}
for a sufficiently small $c_k$.  Then there is no statistic
$C\in\cH_D$ (randomized seeds allowed) satisfying all of:
$0\le C\le1$ pointwise; soundness
$C(I)\ge\sup_x|V_I(x)|$ on every input; and
$Q_m\{C\le\eps\}\ge1-\delta_n$ with $\delta_n=o(\eps^2)$.
For fixed $\eps$ the last condition is ordinary null success with
probability $1-o(1)$.

\label{lem:parity-free-guide}
Let $L=ck$ with $c\in\mathbb N$, let $n\ge kL$, and let $\mathcal A$ be the
normalized degree-$k$ planted polynomial of
\cite[Definition~36 and equation~(C6)]{SOKB}.  Write $G$ for its guiding
vector, $\bar z=N_L^{-1/2}((x^\star)^S)_{|S|=L}$, and $\mu_{\rm g}$ for
the mean of one normalized coefficient, whose variance is one.  Assume
\begin{equation}\label{eq:guide-mean-window}
 \frac{L}{\sqrt{\binom nk}}\le\mu_{\rm g}\le\frac1{10L^{k/2}}.
\end{equation}
Then every deterministic unit vector $a$, independent of the guide
polynomial and satisfying $\langle a,\bar z\rangle>0$, obeys
\begin{equation}\label{eq:raw-guide-overlap}
 \langle a,G\rangle
 \ge \frac12\sqrt{\operatorname{Part}_k(L)}\,\mu_{\rm g}^c
       \langle a,\bar z\rangle
\end{equation}
except with probability at most
$C_kc^2/\bigl(\binom nk\,\mu_{\rm g}^2|\langle a,\bar z\rangle|^2\bigr)$;
moreover,
\begin{equation}\label{eq:guide-norm-mean}
 \mathbb E\|G\|^2\le1.0202.
\end{equation}
Suppose in addition that the guide instance is a Poisson pool of mean
$m_{\rm g}$ with
$n\le m_{\rm g}=O(n^{k/2})$ and $L^2\log n=o(n)$.
Except with probability $O(m_{\rm g}^{-1/2})$ over that pool, there is a
quantum circuit of $O(m_{\rm g}L\log n)$ gates which prepares
\begin{equation}\label{eq:raw-guide-preparation}
 \beta_{\rm g}\,\frac{G}{\|G\|}\,|0\rangle+|\perp\rangle|1\rangle,
 \qquad
 \beta_{\rm g}\ge c_kL^{-L/2}.
\end{equation}
The statement holds for both parities of $k$.

\label{prop:quantum-odd-normalization}
Fix odd $k=2r+1$ and fixed $\rho>0$.  At level $L$ and with a main
pool of mean $A_k\rho^{-2}\mathsf D_{k,L}$, choose $A_k$ sufficiently
large.  Then, for all sufficiently large $n$, the following hold.
\begin{enumerate}
\item Deterministically,
\begin{equation}\label{eq:quantum-odd-domination}
 \|H_{\rm o}\|\le1,
 \qquad
 \left\|\Gamma_{\rm o}^{-1/2}
 \cP_{\rm o}\,\Gamma_{\rm o}^{-1/2}\right\|\le1.
\end{equation}
\item Under either the null or planted support law, with probability
$1-o(1)$,
\begin{equation}\label{eq:quantum-odd-diagonal-bounds}
 \Tr\Gamma_{\rm o}\le C_kdN_L,
 \qquad
 \max_S\Gamma_{\rm o}(S,S)
 \le C_k(d+\log N_L).
\end{equation}
\item Under the null, for every fixed $B>0$,
\begin{equation}\label{eq:quantum-odd-null}
 \Pr\left\{\|H_{\rm o}\|>
 C_{k,B}\sqrt{L/d}\right\}\le n^{-BL}.
\end{equation}
Under planting, with probability $1-o(1)$,
\begin{equation}\label{eq:quantum-odd-comparison}
 \left\|\Gamma_{\rm o}^{-1/2}
 \bigl(Z\cC_{\rm o}Z-\rho^2\cP_{\rm o}\bigr)
 \Gamma_{\rm o}^{-1/2}\right\|
 \le C_k\sqrt{L/d}.
\end{equation}
\end{enumerate}

\label{lem:quantum-condition-number}
Let $d=\bd$ in the even case and $d=n\alpha^2$ in the odd case, and put
$B_\Gamma:=C_k(d+\log N_L)$.  With probability $1-o(1)$ under either
model,
\begin{equation}\label{eq:quantum-condition-number}
 d\le\Gamma(S,S)\le B_\Gamma\quad\text{for every }S,
 \qquad
 \chi_\Gamma:=\frac{B_\Gamma}d\le C_k\log n.
\end{equation}

\label{prop:quantum-cutoff-recovery}
On the high-probability planted event, let $\sigma$ be any density operator
supported on $\operatorname{Ran}\Pi_-$.  Apply the trace-nonincreasing
filter with Kraus operator $\sqrt d\,\Gamma^{-1/2}$ and condition on
success; equivalently, the normalized post-filter state is
\begin{equation}\label{eq:quantum-filtered-state}
 \widetilde\sigma
 :=\frac{\Gamma^{-1/2}\sigma\Gamma^{-1/2}}
 {\Tr(\Gamma^{-1}\sigma)}.
\end{equation}
Then apply the isometry
$|S\rangle\mapsto L^{-1/2}\sum_{i\in S}|i\rangle|S\setminus\{i\}\rangle$
and trace out the second register.  The resulting one-particle state
$\varrho$ satisfies
\begin{equation}\label{eq:quantum-rdm-mass}
 \left\langle\frac{\xstar}{\sqrt n},
 \varrho\frac{\xstar}{\sqrt n}\right\rangle\ge c_k>0.
\end{equation}
For even $k$, the conclusion is understood modulo the unavoidable global
sign.

\label{thm:quantum-inference}
Fix $k\ge2$ and a bias $\rho\in(0,1]$, independently of $n$.
Let $\ell\ge k$, let $L$ be as in
\cref{eq:quantum-divisible-level}, and assume
\begin{equation}\label{eq:quantum-range}
 L^2\log n=o(n).
\end{equation}
For a sufficiently large constant $C_k$,
\begin{equation}\label{eq:quantum-sample}
 m\ge C_k\rho^{-2}
       \frac{n^{k/2}}{\ell^{k/2-1}}
\end{equation}
suffices for quantum strong detection and weak recovery, with success
probability $1-o(1)$ uniformly in the planted assignment.  For even $k$,
recovery is understood modulo the unavoidable global sign.  In the reversible
read-only input model, the gate complexity is
\begin{equation}\label{eq:quantum-runtime}
 \widetilde O\!\left(
 N_L^{1/4}L^{O_k(L)}n^{O_k(1)}
 \right),
\end{equation}
and the coherent workspace is $\widetilde O(L\log n)$ qubits, excluding
polynomial-size read-only storage for the input and auxiliary classical
data.

\label{lem:exact-csp-channel}
If $\mu_S\ne0$, then
\begin{equation}\label{eq:csp-derived-label}
 b_a^S:=\sign(\mu_S)\prod_{j\in S}Y_{aj}
\end{equation}
is exactly a planted noisy $|S|$XOR label of bias $|\mu_S|$ on support
$\{i_{aj}:j\in S\}$.  Under the null it is exactly an unbiased XOR label.

\label{thm:linear_converg_informal}
For any diffuse instance (Ass.~\ref{ass:dist_regular}) of the autobidding equilibrium problem (Prob.~\ref{prob:Bayesian_SPTE} \& ~\ref{prob:Bayesian_SPPE}), with suitable parameters, our algorithm (Alg.~\ref{alg:prime_alg}) converges linearly: for all $t \geq 1$,
\begin{align*}
    \sum_{i} \|\alpha_i^{(t)} - \alpha_{i}^{*}(\alpha_{-i}^{(t)})\|_2 \leq \frac{3}{4} \sum_i \|\alpha_i^{(t-1)} - \alpha_i^{*}(\alpha_{-i}^{(t-1)})\|_2,
\end{align*}
where $\alpha^{(t)}$ denotes the pacing multipliers at iteration $t$ and $\alpha_i^{*}(\alpha_{-i})$ is bidder $i$'s best response.

\label{def:PL_condition}
A differentiable function $f:\mathbb{R}^n \to \mathbb{R}$ satisfies the PL condition if there exists $\mu > 0$ such that:
\begin{align*}
\frac{1}{2}\|\nabla f(x)\|^2 \geq \mu (f(x) - f^*),
\end{align*}
where $f^*$ is the minimum value of $f$.

\label{def:moreau_envelope}
    Let $f:\X_x \to (-\infty,+\infty]$ be a proper, lower semicontinuous function, for $\X_x$ is a convex set and let \(\eta>0\). 
    The \emph{Moreau envelope} of \(f\) with parameter \(\eta\) is defined by 
    \[
f_\eta(x)\;:=\;\min_{y\in \X_x}
\{
f(y) + \frac{\eta}{2}\|x-y\|^2
\}   
    \],  for $x\in \X_x$, where $x_{+}$ denotes the proximal point, defined as the minimizer of the inner problem. In addition, when $f$ is $L$-smooth, for $\eta  > L$, the gradient of the Moreau envelope satisfies $$\nabla f_\eta(x)= \eta(x - x_+)$$, with $$\|\nabla f(x_+)\| \;\ge\; \eta\,\|x - x_+\| $$.

\label{prob:Bayesian_SPPE}
Consider a set of $n$ bidders, where each bidder $i$ with per-iteration budget constraint as $\rho_i$, and value distribution $v_i \sim \D_i$. 
The ex-ante SPPE for the value-maximizing bidder setting is a strategy profile $\alpha^*$ such that, each bidder $i \in [n]$'s strategy (i.e., $\alpha^*_i$) obtain the minimum of their respective optimization problem given other's strategy $\alpha^{*}_{-i}$, i.e.,  
\begin{align*}
    & & l_i (\alpha) & := \min_{\alpha_i \in [0,1]} \E_{v \sim \pD} [- x_i(\alpha) v_i] & \\
    \text{s.t.}& & g_i(\alpha) &:= \E_{v \sim \pD}[x_i(\alpha) \max_{j \neq i} \alpha_j v_j] - \rho_i  \leq 0 &~~~ \text{   budget constraint}
\end{align*}
where $x_i (\alpha) := \mathbbm{1} \{ \alpha_i v_i \geq \max \alpha_j v_j \}$, $\alpha = (\alpha_1, \ldots, \alpha_n)$, $\mathsf{D} = \Pi_{i \in [n]} \D_i$ denotes the (independent) product Gaussian distribution over bidders’ values.

\label{ass:exist_active_Eq}
For every autobidding auction instance considered in this paper, there exists an equilibrium $\alpha^* \in \mathcal{X}$ such that
$\alpha_i^* \geq \underline{\alpha}$ for all $ i\in[n]$, where $\underline{\alpha}\in(0,1]$ is a sufficiently small constant.

\label{def:saddle_point}
Given the Lagrangian function $ \mathcal{L}_i $ defined in Def.~\ref{def:aug_lagrangian}, a point $ (\alpha^*_i, \alpha^*_{-i}, \lambda^*_i) $ is said to be a (local) saddle point of $ \mathcal{L}_i $ if, for every $ \alpha_i \in [0,1], \lambda_i \geq 0$,
\begin{align*}
\mathcal{L}_i (\alpha^*_i, \alpha^*_{-i}, \lambda_i) \leq \mathcal{L}_i (\alpha^*_i, \alpha^*_{-i}, \lambda^*_i) \leq \mathcal{L}_i (\alpha_i, \alpha^*_{-i}, \lambda^*_i).
\end{align*}
, where $ \alpha^*_{-i} $ is a fixed parameter, not a decision variable subject to optimization. Furthermore, a point $(\alpha^*, \lambda^*_1, \ldots, \lambda^*_n)$ is said to be a \emph{global} saddle point of a GNE (Def.~\ref{def:GNE}) if the above condition holds simultaneously for all $l_i, i \in [n] $.

\label{thm:convergence_PRIME}
Under the setting of separately monotone GNE (Def.~\ref{def:SM_GNE}), there exists parameters $\eta_1, \ldots, \eta_n, \tilde{\eta_1},\ldots, \tilde{\eta_n}, \tau_1^{1}, \ldots, \tau_1^{n}, k_1,\ldots, k_n$, and bounded, convex set $\X_\lambda$ such that running our algorithm \textsc{PRIME} (Alg.~\ref{alg:prime_alg}) obtains linear convergence to a GNE point $(\alpha^*, \lambda^*)$:
\begin{align*}
        \sum_{i} \|\alpha_i^{(t)} - \alpha_{i}^{*} (\alpha_{-i}^{(t)})\|_2 \leq \frac{3}{4} \sum_i \|\alpha_i^{(t-1)} -\alpha_i^{*} (\alpha_{-i}^{(t-1)}) \|_2
\end{align*}
, where $\eta_1$ is the parameters of the Moreau envelope, $\tau_1^i$ denote the step sizes of bidder $i$ for gradient descent.

\label{def:app:GNE}
Given a set of $n$ players where each player $i \in [n]$ deploys strategy $\alpha_i$ and optimizes the objective function $l_i$ subject to the constraints $g_i$ below:
\begin{align*}
 \min_{\alpha_i \in \X_i} l_i (\alpha_i, \alpha_{-i})  \quad \text{s.t.}\quad&\quad  g_i (\alpha_i, \alpha_{-i}) \leq 0 
\end{align*}
where $\X_i$ is a nonempty, convex, closed and bounded "private" strategy set of player $i$. A strategy vector $\alpha^* = (\alpha^*_1, \ldots, \alpha^*_n)$ is a generalized Nash equilibrium if for every player $i = 1, \ldots, n$,
\begin{align*}
    l_i (\alpha^*_i, \alpha^*_{-i}) \leq l_i (\alpha^i, \alpha^*_{-i}), \text{~~~for every~~~} \alpha_i \in \Fe_i(\alpha^*_{-i})
\end{align*}
where the feasible set function is defined as $\Fe_i (\alpha^*_{-i}) := \{ \alpha_i \in \X_i |   g_i (\alpha_i, \alpha_{-i}) \leq 0\}$.

\label{def:2_sided_PL}
A function $f(x,y)$ satisfies the two-sided PL condition if there exist constants $\mu_1, \mu_2 > 0$ such that, for any $x \in \X_x, y \in \X_y$, where $\X_x, \X_y$ are convex, 
 \begin{align*}
    \frac{1}{2}\|\nabla_x f(x, y)\|^2 \geq \mu_1\left[ f(x,y) - \min_{x'} f(x', y)\right], \frac{1}{2}\|\nabla_y f(x, y)\|^2 \geq \mu_2\left[ \max_{y'} f(x,y') - f(x, y)\right].
\end{align*}
where the first condition is the primal side P\L{} and the second condition is the dual side P\L{}.

\label{def:log_concave}
A distribution $\D$ on domain $D$ is log-concave if its probability density function $f(\cdot) = e^{ - \psi}$, and $\psi$ is a convex function defined from domain $D$ to $(-\infty, +\infty]$. 
\iffalse Equivalently, a probability measure $P$ defined on domain $D$ is log-concave if for all nonempty sets $A, B \in D$, and for all $\theta \in [0,1]$, we have:
\begin{align*}
    P(\theta A + (1 - \theta)B ) \geq P(A)^\theta P(B)^{(1-\theta)}
\end{align*}
\fi 
In addition, log concave distribution will have a finite mean.

\label{cor:log_concave_lip}
    The underlying convex function $\psi_i$ of a log concave distribution defined in Ass.~\ref{ass:app:log_concave} has the following property: 
    \begin{align*}
        |\psi'_i (x)| \leq  |\psi'_i(0)| + \beta_i |x| := C_i + \beta_i |x|
    \end{align*}
    where $\beta_i$ is the smoothness factor of function $\psi_i$.

\label{prop:log_concave}
Let $p = \exp (- \psi)$ be a probability density function. Then the following are equivalent: 
\squishlist
    \item $ \psi = - \log p$ is convex.
    \item $\nabla \psi = - \nabla p / p$ is monotone: For all $x_1, x_2$,
    \begin{align*}
        \langle \nabla \psi (x_2) - \nabla \psi (x_1) , x_2 - x_1 \rangle \geq 0 
    \end{align*}
    \item $\nabla^2 \psi \geq 0$.  
\squishend

\label{lem:mom_lg_concave}
If a random variable $X$ follows a log concave distribution :
\begin{align*}
    \E[\|X\|^p]^{1/p} \leq C p \E[\|X\|]
\end{align*}
where $C>0 $ is an absolute constant. Moreover, when $X \in \R$, $E[X]$ is finite.

\label{lem:var_lg_concave}
Let $X$ be a random variable following a log-concave distribution with density $f$, then:
\begin{align*}
    \frac{1}{12\var(X)} \leq \sup_{x \in \R} f(x)^2 \leq \frac{1}{\var (X)}
\end{align*}

\label{def:gamma}
The Gamma function, denoted as $\Gamma(s)$, is defined for all complex numbers $v$ except non-positive integers as:
\begin{align}
\Gamma(s) &= \int_0^\infty e^{-v} v^{s-1} dv.
\end{align}
For positive integers $n$, the Gamma function coincides with the factorial:
\begin{align}
\Gamma(n) &= (n-1)!.
\end{align}

\label{def:beta}

The Beta function, denoted by $B(a,b)$, is defined for all $a,b>0$ as
\begin{align*}
B(a,b)
&=
\int_0^1 t^{a-1}(1-t)^{b-1}\,dt.
\end{align*}

The Beta function is related to the Gamma function through the identity
\begin{align*}
B(a,b)
&=
\frac{\Gamma(a)\Gamma(b)}{\Gamma(a+b)}.
\end{align*}

\label{lem:cf_cd_i_SPPE}
For every \(i\), \(g_i\) is continuously differentiable in \(\alpha_i\), and
\(\partial_{\alpha_i}g_i\) is positive and bounded on \(\A\).

\label{lem:cf_cd_j_SPPE}
For every \(i\) and \(j\ne i\), \(g_i\) is continuously differentiable in
\(\alpha_j\), and \(\partial_{\alpha_j}g_i\) is bounded on \(\A\).

\label{lem:obj_cd_i_SPPE}
For every \(i\), \(l_i\) is continuously differentiable in \(\alpha_i\), and
\(\partial_{\alpha_i}l_i\) is negative and bounded on \(\A\).

\label{lem:obj_cd_j_SPPE}
For every \(i\) and \(j\ne i\), \(l_i\) is continuously differentiable in
\(\alpha_j\), and \(\partial_{\alpha_j}l_i\) is bounded on \(\A\).

\label{thm:cf_lip_grad_i_SPPE}
The derivative \(\partial_{\alpha_i}g_i\) is Lipschitz in \(\alpha_i\) on
\(\A\), uniformly over the other coordinates.

\label{thm:cf_lip_grad_j_SPPE}
For every \(j\ne i\), the derivative \(\partial_{\alpha_j}g_i\) is Lipschitz
in \(\alpha_j\) on \(\A\), uniformly over the other coordinates.

\label{thm:cf_lip_grad_j_k_SPPE}
For distinct \(j,k\ne i\), the derivative \(\partial_{\alpha_j}g_i\) is
Lipschitz in \(\alpha_k\) on \(\A\), uniformly over the other coordinates.

\label{thm:cf_lip_grad_i_j_SPPE}
For every \(j\ne i\), the derivative \(\partial_{\alpha_i}g_i\) is Lipschitz
in \(\alpha_j\) on \(\A\), uniformly over the other coordinates.

\label{thm:obj_lip_grad_i_SPPE}
The derivative \(\partial_{\alpha_i}l_i\) is Lipschitz in \(\alpha_i\) on
\(\A\), uniformly over the other coordinates.

\label{thm:obj_lip_grad_j_SPPE}
For every \(j\ne i\), the derivative \(\partial_{\alpha_j}l_i\) is Lipschitz
in \(\alpha_j\) on \(\A\), uniformly over the other coordinates.

\label{thm:obj_lip_grad_j_k_SPPE}
For distinct \(j,k\ne i\), the derivative \(\partial_{\alpha_j}l_i\) is
Lipschitz in \(\alpha_k\) on \(\A\), uniformly over the other coordinates.

\label{thm:obj_lip_grad_i_j_SPPE}
For every \(j\ne i\), the derivative \(\partial_{\alpha_i}l_i\) is Lipschitz
in \(\alpha_j\) on \(\A\), uniformly over the other coordinates.

\label{cor:sppe-global-lipschitz}
For each \(i\), the functions \(l_i\) and \(g_i\) are Lipschitz on \(\A\), and
their gradients are Lipschitz on \(\A\).

\label{def:app:moreau_envelope}
    Let $f:\mathbb{R}^d \to (-\infty,+\infty]$ be a proper, lower semicontinuous function and let \(\eta>0\). 
    The \emph{Moreau envelope} of \(f\) with parameter \(\eta\) is defined by
    \[
    f_\eta(x)
\;:=\;
\inf_{y\in\mathbb{R}^d}
\Big\{
f(y) + \frac{\eta}{2}\|x-y\|^2
\Big\},
\qquad x\in\mathbb{R}^d.
\]

The associated \emph{proximal operator} is well-defined and unique, as defined below:
\[
\operatorname{prox}_{\eta f}(x)
\;:=\;
\arg\min_{y\in\mathbb{R}^d}
\Big\{
f(y) + \frac{\eta}{2}\|x-y\|^2
\Big\}.
\]

\label{lem:app:grad_moreau}
Let $f:\mathbb{R}^n \to \mathbb{R}$ be $\rho_\textsc{wc}$-weakly convex and let $\eta > \rho_\textsc{wc}$.
Let 
\[
x_+ = \arg\min_{u} \left\{ f(u) + \frac{\eta}{2}\|u - x\|^2 \right\}
\]
be the proximal point. Then
\begin{align*}
\nabla f_\eta(x)
= \eta(x - x_+)
= \nabla f(x_+).
\end{align*}

Moreover, if $f$ is twice differentiable, then the Hessian of the Moreau envelope is
\begin{align*}
\nabla^2 f_\eta(x)
&= \eta I - \eta^2 \big(\eta I + \nabla^2 f(x_+)\big)^{-1}.
\end{align*}

\label{def:saddle_env}
Given a saddle point optimization problem $\min_{x \in \X_x} \max_{y \in \X_y} \lag(x, y)$, with $\X_x, \X_y$ convex, its saddle envelope is defined as:
\begin{align*}
     \lag_{\eta} (x,y) = \min_{u \in \X_x} \max_{v \in \X_y} \Lsaddle(u,v):= \lag(u, v) + \eta_1/2 \|u - x\|^2 - \eta_2/2 \|v - y\|^2
\end{align*}

\label{lem:app:saddle_env_grad}
Let $z = (x, y)$, and let $z_{+} = (x_{+}, y_{+}) = \operatorname{prox}_\eta(z)$ denote the proximal update. Then the gradient of the saddle envelope $\mathcal{L}_\eta(x, y)$ satisfies:
\begin{align*}
\|\nabla_x \mathcal{L}(z_{+})\|_2 \geq \eta_1 \|x - x_{+}\|_2, \quad
\|\nabla_y \mathcal{L}(z_{+})\|_2 \geq \eta_2 \|y_{+} - y\|_2. \\
\nabla_x \lag_\eta(x) = \eta_1 (x - x_{+}), \quad \nabla_y \lag_\eta(y) = -\eta_2 (y - y_{+})
\end{align*}
where the first (resp., second) equality holds if and only if $x_{+}$ (resp., $y_{+}$) is not on the boundary of $\X_x$ (resp., $\X_y$).

\label{lem:hessian_saddle_envelope}

Consider the saddle envelope $ L_\eta(z) $, where  $z = (\alpha, \lambda) $. Its Hessian satisfies the following:
\begin{align*}
\nabla_{\lambda \lambda}^2 L_\eta(z) &= -\eta_2 I + \eta_2^2 \left( \eta_2 I + \nabla_{\lambda \lambda}^2 L(z_+) + \nabla_{\lambda \alpha}^2 L(z_+) \left( \eta_1 I + \nabla_{\alpha \alpha}^2 L(z_+) \right)^{-1} \nabla_{\alpha \lambda}^2 L(z_+) \right)^{-1}.
\end{align*}

\label{lem:all_lags}
The maximizer over $\lambda$ for $\lag_\eta$ is:
\begin{align*}
    \lambda_{+} = \proj_{\X_\lambda}[ \lambda + \frac{1}{2 \eta_2} (g(\alpha_{+}) + |g(\alpha_{+})|)]. 
\end{align*}
\begin{enumerate}[(i)]
\item Conditioned on $g(\alpha_{+}) = 0$:
\begin{align*}
    \lag_\eta (\alpha, \lambda) = \min_{\alpha_{+}} \lag_l (\alpha_{+}, \lambda ; \alpha) = \min_{\alpha_{+}} l(\alpha_{+}) + \frac{\eta_1}{2} \|\alpha - \alpha_{+}\|_2^2
\end{align*}
\item Conditioned on $\lambda_{+} = C_\lambda$, $g(\alpha_{+}) >0$:
\begin{align*}
    \lag_\eta (\alpha, \lambda) = \min_{\alpha_{+}} \lag_\lambda (\alpha_{+}, \lambda ; \alpha)  := \min_{\alpha_{+}} l(\alpha_{+})+ C_\lambda \proj_{+}[g(\alpha_{+})] - \frac{\eta_2}{2} \|C_\lambda - \lambda\|_2^2 + \frac{\eta_1}{2} \|\alpha - \alpha_{+} \|_2^2
\end{align*}

\item Conditioned on $\lambda_{+} = \lambda + \frac{1}{2 \eta_2} (g(\alpha_{+}) + |g(\alpha_{+})|)$ (the projection is not active), and $g(\alpha_{+}) >0$: 
\begin{align*}
     \lag_\eta (\alpha, \lambda) = \min_{\alpha_{+}} \lag_{+} (\alpha_{+}, \lambda ; \alpha)  := \min_{\alpha_{+}} l(\alpha_{+}) + \lambda \proj_{+}[g(\alpha_{+})] + \frac{1}{2 \eta_2} \proj_{+}[g(\alpha_{+})]^2 + \frac{\eta_1}{2} \| \alpha_{+} - \alpha\|_2^2
\end{align*}
\end{enumerate}

\label{lem:local_lambda_min}

Fixed $\lambda$, we define $\alpha_\lambda^* \in [\alpha^*, 1]$ such that $g (\alpha_\lambda^*) = \eta_2 (C_\lambda - \lambda) $. If no such $\alpha_\lambda^*$ exists, $\alpha_\lambda^* = 1$. Then the $\lag_\eta(\cdot, \lambda)$ is : 
\squishlist
    \item monotonically decreasing over $[0,\alpha^*]$, with local minimizer $\alpha^*$.
    \item possibly not monotonic over $[\alpha^*, \alpha_\lambda^*]$, with $\alpha_{+}^*$ satisfies either the following condition:\footnote{This is a necessary but not sufficient condition.}
    \begin{align*}
        \lambda + \frac{1}{\eta_2} g(\alpha_{+}^*) = -\frac{\frac{d}{d \alpha} l (\alpha_{+}^*)}{\frac{d}{d \alpha} g (\alpha_{+}^*)}.
    \end{align*}
    If no such $\alpha_{+}^*$ exists, $\alpha_{+}^*= \arg \min_{\alpha} \{ \lag_l (\alpha^*, \lambda ), \lag_\lambda (\alpha_{\lambda}^*, \lambda) \}$.
    \item monotonically increasing over $[\alpha_\lambda^*, 1]$, with local minimizer $\alpha_\lambda^*$. Moreover, for $\alpha_\lambda^* \neq 1$, the local minimum is $l(\alpha^*_\lambda) + \frac{\eta}{2} [C_\lambda^* - \lambda^*]^2$.
\squishend

\label{thm:dual_side_properties}
For the inner maximization over $\lambda$ in $\Lsaddle(\alpha,\lambda)$, the following holds:
\begin{itemize}
    \item For \textnormal{case (i)} and \textnormal{case (ii)}, the dual P\L{} condition holds with parameter $\eta_2$.
    \item For \textnormal{case (iii)}, the gradient with respect to $\lambda$ is $g(\alpha_{+})$.
\end{itemize}

\label{lem:app:control_rival}

Suppose $m(\alpha_i, \alpha_{-i}) := \min_{\alpha_{+}} \tilde{m} (\alpha_i, \alpha_{-i}) = \min_{\alpha_{+}} l(\alpha_{+},\alpha_{-i}) + C_\lambda \proj_{+} [g (\alpha_{+},\alpha_{-i})] + \frac{\eta_1}{2} \|\alpha_{+} - \alpha\|_2^2$ is $L_m$ smooth in $\alpha_i$, and the largest eigenvalue $\sigma (\nabla_{\alpha_i, \alpha_{-i}}m) \leq L^{\textsc{SM}}_{i,j}$, then applying another Moreau envelope over $\alpha$ with $\tilde{\eta} > \eta_1$, i.e., $\hat{m}(\alpha_i, \alpha_{-i}) = \min_{\tilde{\alpha}_i}  {m} (\tilde{\alpha}_{i}, \alpha_{-i}) + \frac{\tilde{\eta}}{2} \|\tilde{\alpha}_i - \alpha_i\|_2^2$, we have:
\begin{align*}
   \| \frac{\partial \alpha^{*}}{\partial \alpha_{-i}} \| \leq \frac{1}{\tilde{\eta} - L_m} L^{\textsc{SM}}_{i,j}
\end{align*}
, where $\alpha^* = \arg\min_{\alpha_i } \hat{m}(\alpha_i, \alpha_{-i}) $and $\alpha^*= \min_{\alpha_i } m(\alpha_i, \alpha_{-i})$.

\label{lem:global_conv_alpha}
Under the assumptions (Ass.~\ref{def:SM_GNE}, Prob.~\ref{def:SM_GNE}), After $k$ steps, the alternating descent algorithm (Alg.~\ref{alg:prime_alg}) will have the following guarantee:

\begin{align*}
    \|\alpha_i^{t+k} - \alpha_i^*(\alpha_{-i}^{t}) \|_2 \leq 1/2 \|\alpha_i^{t} - \alpha_i^*(\alpha_{-i}^{t})\|_2
\end{align*}
for $k \geq \log (\nicefrac{\mu_1}{\tilde{\eta}}) / (\log (1 - \tau_1 \tilde{\mu}))$, and $\tilde{\eta} \geq 4 L_m$.

\label{thm:app:convergence_PRIME}
Under the setting of separately monotone GNE (Def.~\ref{def:SM_GNE}), there exists parameters $\eta_1, \ldots, \eta_n, \tilde{\eta_1},\ldots, \tilde{\eta_n}, \tau_1^{1}, \ldots, \tau_1^{n}, k_1,\ldots, k_n$, and bounded, convex set $\X_\lambda$ such that running our algorithm \textsc{PRIME} (Alg.~\ref{alg:prime_alg}) obtains linear convergence to a GNE point $(\alpha^*, \lambda^*)$:
\begin{align*}
        \sum_{i} \|\alpha_i^{(t)} - \alpha_{i}^{*} (\alpha_{-i}^{(t)})\|_2 \leq \frac{3}{4} \sum_i \|\alpha_i^{(t-1)} -\alpha_i^{*} (\alpha_{-i}^{(t-1)}) \|_2
\end{align*}
, where $\eta_1$ is the parameters of the Moreau envelope, $\tau_1^i$ denote the step sizes of bidder $i$ for gradient descent, and $c$ depends on these parameters.

\label{thm:app:informal_gda}
Fix a single bidder and let $(\alpha^*, \lambda^*)$ be a saddle point of $f$. Run alternating gradient descent ascent on $f$ with sufficiently small step sizes. Then the iterates converge linearly to the saddle point:
\begin{align*}
    \|\alpha_t - \alpha^*\|_2 + \|\lambda_t - \lambda^*\|_2
    \;\le\; C \,\rho^{\,t}\, \|\alpha_0 - \alpha^*\|_2 ,
\end{align*}
where $\rho \in (0,1)$ and $C > 0$ depend only on the problem parameters.

\label{thm:lineaar_conv_local}
Consider the PDA-M, then there exist step sizes $\tau_1, \tau_2$, $\eta = (\eta_1, \eta_2)$ such that 
\begin{align*}
