    + \|\lambda_t - \lambda_{t-1}\|_2^2 \le C (1 - \frac{1}{2} \mu_m \tau_1)^t [\|\alpha_0 - \alpha^*\|_2^2]
\end{align*}
, where $\tau_1 = (\tau_1^1, \ldots, \tau_1^n)$ and $\tau_2 = (\tau_2^1, \ldots, \tau_2^n)$ denote the vectors of per-bidder step sizes (i.e., $\tau_1^i, \tau_2^i$ are bidder $i$'s scalar step sizes), $\alpha^*$ is one GNE, and $C$ is a constant dependent on the parameters in a separately monotone GNE.

\label{lem:hessian_Lipshitz}
Let $ f: \mathbb{R}^d \to \mathbb{R} $ be a twice differentiable function. Then the following statements are equivalent:
\begin{enumerate}
    \item The gradient $ \nabla f(x) $ is Lipschitz continuous (Def.~\ref{def:lipschitz_gradient}) with constant $ L $, i.e., for all $ x, y \in \mathbb{R}^d $,
    \begin{align}
        \|\nabla f(x) - \nabla f(y)\| \leq L \|x - y\|.
    \end{align}
    \item The Hessian $ \nabla^2 f(x) $ is uniformly bounded in operator norm:
    \begin{align}
        \|\nabla^2 f(x)\|_2 \leq L, \quad \forall x \in \mathbb{R}^d.
    \end{align}
    \item The function $ f(x) $ is $L$-smooth, and hence it satisfies the quadratic upper bound:
    \begin{align}
        f(y) \leq f(x) + \nabla f(x)^T (y - x) + \frac{L}{2} \|y - x\|^2, \quad \forall x, y \in \mathbb{R}^d.
    \end{align}
\end{enumerate}

\label{lem:PL_partial_gradient}
Consider the minimax problem 
\begin{equation}
    \min_{\alpha} \max_{\lambda} f(\alpha, \lambda). \label{line:app:minimax}
\end{equation}

Suppose that the function \(f\) has an \(L_g\)-Lipschitz continuous gradient (see Definition~\ref{def:lipschitz_gradient}), and that \(-f(\alpha, \cdot)\) satisfies the Polyak--Łojasiewicz (PL) condition with constant \(\mu_2\). Then the value function
$m(\alpha) := \max_{\lambda} f(\alpha, \lambda)$ is \(L_m\)-smooth, where
$L_m = L_g + \frac{L_g^2}{\mu_2}$.
Moreover, its gradient is given by
\[
\nabla m(\alpha) = \frac{\partial}{\partial \alpha} f(\alpha, \lambda^*(\alpha)),
\quad \text{for any } 
\lambda^*(\alpha) \in \arg\max_{\lambda} f(\alpha, \lambda).
\]

\label{lem:progress_1_PL}
Consider the optimization problem $\min_{\alpha} m(\alpha)$, where $m$ is $L_m$-smooth and satisfies the PL condition with constant $\mu_1$. 
Let the iterates be updated according to gradient descent:
\begin{align*}
    \alpha_{t+1} = \alpha_{t} - \tau \nabla m(\alpha_t),
    \quad \text{with} \quad \tau \leq \frac{1}{L_m}.
\end{align*}
Then, the function value decreases geometrically:
\begin{align*}
    m(\alpha_{t+1}) - m^* 
    \leq (1 - \mu_1 \tau)\, [m(\alpha_t) - m^*].
\end{align*}

\label{lem:young}
    Given $A,B$, and $\beta>0$, we have:
    \begin{align*}
        \|A\|_2^2 \leq  (1 + \beta) \|B\|_2^2 + (1 + \frac{1}{\beta}) \|A-B\|_2^2. 
    \end{align*}

\label{lem:prop_m}
For the saddle envelope function as described in Lem.~\ref{lem:all_lags}, the following properties are satisfied:  
\begin{enumerate}[(a)]
\item $m$ only takes the form of case (i) and case (ii).
\item $m$ is $L_m$-smooth. 
\end{enumerate}

\label{prop:QG_PL}

Given convex set $\X$, for $\mu$-P\L{} function $f$ with input $x \in \mathcal{X}$, we have:
\begin{align*}
    f(x) - f^* \geq \frac{\mu}{2} \|\proj_{\X^*}[x] - x\|_2^2
\end{align*}
where $f^*$ denote the minimum of $f$ over set $\X$ and $\proj_{{\X}^*} [x]$ denote the projection of $x$ onto the minimizer set ${\X}^* \subseteq \X $.

\label{lem:descent}
Let $f:\X_x \to \mathbb{R}$ be differentiable and $L$-smooth, where set $\X_x$ is convex. Consider the gradient descent update $x_{t+1} = x_t - \tau \nabla f(x_t)$, with stepsize $0 < \tau \le \frac{1}{L}$. Then the following descent guarantee holds:
\begin{align*}
    f(x_{t+1}) \le f(x_t) - \frac{\tau}{2}\|\nabla f(x_t)\|^2.
\end{align*}

\label{lem:app:saddle_gradient_ub}
    Under the formulation of Ass.~\ref{def:SM_GNE}, we have, under $g (\alpha^{+}(\alpha_0, \lambda)) > 0$,we have:
