\label{lem:pot_conv_w_PL}
Define 
$a_t := m(\alpha_t) - m^* = m(\alpha_t) - \min_{\alpha} m(\alpha)$, 
where $m(\alpha_t) = \max_{\lambda} f(\alpha_t, \lambda)$. 
Also define $b_t := m(\alpha_t) - f(\alpha_t, \lambda_t)$. Consider the alternating gradient updates as follows:
\begin{align*}
    \alpha_{t+1} &\gets \alpha_t - \tau_1 \frac{\partial f(\alpha_t, \lambda_t)}{\partial \alpha}, \\
    \lambda_{t+1} &\gets \lambda_t + \tau_2 \frac{\partial f(\alpha_{t+1}, \lambda_t)}{\partial \lambda},
\end{align*}
with step sizes $\tau_1 \le \frac{1}{L_m}$ and $\tau_2 \le \frac{1}{L_g}$. Let the potential function be defined as $P_t := a_t + \pw b_t$. Then we have
\begin{align*}
    P_{t+1} \le \max\{k_1, k_2\} \, P_t,
\end{align*}
, where
\begin{align*}
    k_1 &:= 1 - \mu_m \Big[ \tau_1 
    - \pw (1 - \mu_2 \tau_2) \tau_1 \big( (1+\beta)(2+L_g \tau_1 ) - 1 \big) \Big], \\
    k_2 &:= 1 - \mu_2 \tau_2 
    + \frac{L_g^2 \tau_1}{\mu_2 \pw} 
    + (1 - \mu_2 \tau_2) \frac{L_g^2 \tau_1}{\mu_2} 
