\label{thm:general}
There exists a constant $C>0$ such that the following holds.
Let $\Sigma$ be a finite set, let $n\geq 1$ be an integer,
and let $S\subseteq\Sigma^n$ and $S'$ be sets.
Let $f:S\rightarrow S'$.
Let $A$ be an algorithm that for all $x\in S$ computes $f$,
with bounded error $\eps$ and at most $T$ queries to the input.

Then for every $x,y\in S$ with $f(x)\neq f(y)$:
\begin{enumerate}
\item If $A$ is a quantum algorithm then
$$T \geq C\times
      \frac{1-2\sqrt{\eps(1-\eps)}}{\sum_{i:x_i \neq y_i}
                            \sqrt{2^{-\K(i \given x,A)-\K(i \given y,A)}}};$$
\item If $A$ is a randomized algorithm then
$$T \geq C\times
\frac{1-2\eps} 
{\sum_{i:x_i \neq y_i} 
\min\left(2^{-\K(i \given x,A)},2^{-\K(i \given y,A)}
\right)}.$$
\end{enumerate}

\label{prop:knowing}
There exists a constant $c\geq 0$ such that
for every finite string $\sigma$,
$$\K(x \given \sigma)\leq \K(x)+c, \text{ and }$$
$$ \K(x) \leq \K(\sigma) + K(x \given \sigma) + c.$$

\label{prop:kraft}
Let $S$ be any prefix-free set of finite strings.
Then $\sum_{x\in S}2^{-\abs{x}} \leq 1.$

 \label{prop:k-inequality}
 There is a constant $c\geq 0$ such that for any three strings $x,y,z$,
$$\K(z \given x) \geq \K(x,y) - \K(x)  - \K(y \given z,x) + \K(z \given x,y,\K(x,y))-c.$$

~
\label{lemma:qdivergence}
For every input $x,y\in S$ such that $f(x)\neq f(y)$ the following holds.
\begin{enumerate}
