$$2T\sum_{i:x_{i}\neq y_{i}}  \sqrt{\overline{p}^{x}(i)   \overline{p}^{y}(i)       }
\geq 1-2\sqrt{\eps(1-\eps)}.$$
\item For randomized algorithms:
$$2T  \sum_{i:x_{i}\neq y_{i}} \min\left(\overline{p}^{x}(i),\overline{p}^{y}(i)
\right) \geq 1-2\eps.$$
\end{enumerate}

