Let $f: \{0,1\}^n \rightarrow \{0,1\}$ be a Boolean function, 
$X{=}f^{-1}(0)$, and $Y{=}f^{-1}(1)$.  For $i \in [n]$ let $D_i$ be 
$|X| {\times} |Y|$ be defined by $D_i[x,y] = 1-\delta_{x_i,y_i}$. We call the 
set of $n$ Boolean ($0-1$) matrices $\{P_i\}_{i\in n}$ {\em index selection 
functions} if 
\begin{enumerate}
\addtolength{\itemsep}{-0.5\baselineskip} 
  \item{$\sum_{i} P_{i} = E$, where $E[x,y]=1$ for every $x\in X$, $y\in Y$. (informally: for every $x\in X$, $y\in Y$
we select a unique
index)}
  \item{$P_{i} \le D_{i}$ (informally: for every $x\in X$, $y\in Y$ 
the index we select is an
$i$ such that $x_{i}\neq y_{i}$).}
\end{enumerate}

A function $\mu:2^{X{\times} Y}\rightarrow \Reals^{+}$
is called a {\em rectangle measure} if the following properties hold. 
\begin{enumerate}
\addtolength{\itemsep}{-0.5\baselineskip} 
\item (Subadditivity) For any rectangle partition
$\R$ of $X{\times} Y$, $\mu(X{\times} Y) \leq \sum_{R\in \R} \mu(R)$.
\item (Monotonicity) For any rectangle $R \subseteq X{\times} Y$, and
subset $S \subseteq X{\times} Y$, if $R\subseteq S$ then
$\mu(R) \leq \mu(S)$.
\end{enumerate}

