\label{thm:main-result}
  There is a parallel oracle-algorithm for Problem \ref{problem:lambda} (Approximation of $\lambda(\bA,\bP)$) with run time bounded by a polynomial in $k$, $1/\delta$, and $\log (mn)$.
  This algorithm is efficient if $k,1/\delta$ are promised to scale as a polynomial in $\log (mn)$.

\label{prop:angle-tnorm}
  For all density matrices $\rho,\xi$ it holds that
  \[ \frac{1}{2}\tnorm{\rho-\xi} \leq A(\rho,\xi) \leq \sqrt{\frac{\pi}{2}\tnorm{\rho-\xi}}. \]

\label{thm:lambda}
  For any $\varepsilon>0$ it holds that
  \( \lambda(\bA,\bP) \geq \mu_\varepsilon(\bA,\bP) > \lambda(\bA,\bP)-\varepsilon. \)

\label{cor:angle-bound}
  For any $\varepsilon>0$ and any states $\rho_1,\dots,\rho_k\in\bbM_{mn}$ there exists $(\rho_1',\dots,\rho_k')\in\bA$ such that
  \[
    \frac{1}{2}\tnorm{\rho_k-\rho_k'}
    < \varepsilon + \frac{k}{\varepsilon} \sum_{i=1}^{k-1} \frac{1}{2}
    \tnorm{\ptr{\bbM_n}{\rho_{i+1}}-\Phi_i(\rho_i)}.
  \]
  Moreover, $\rho_1',\dots,\rho_k'$ can be computed efficiently in parallel given $\rho_1,\dots,\rho_k$.

\label{cor:lambda}
  The following hold for
  any $\delta,\varepsilon>0$:
  \begin{enumerate}

  \item \label{item:lambda:rho}

  If $(\rho_1,\dots,\rho_k)$ is $\delta$-optimal for $\mu_\varepsilon(\bA,\bP)$ then there is an efficient parallel algorithm to compute $(\rho_1',\dots,\rho_k')\in\bA$ that is $(\delta+\varepsilon)$-optimal for $\lambda(\bA,\bP)$.

  \item \label{item:lambda:P}

  If $(P,\Pi_1,\dots,\Pi_{k-1})$ is $\delta$-optimal for $\mu_\varepsilon(\bA,\bP)$ then $P$ is also $(\delta+\varepsilon)$-optimal for $\lambda(\bA,\bP)$.

  \end{enumerate}

\label{prop:consistency}
  Let $V=(\ket{\psi},V_1,\dots,V_{a+b-1},\Pi)$ be a verifier and let $\bY(V)$ be the set of admissible states for the yes-prover.
  A given state $\rho$ is an element of $\bY(V)$ if and only if there exist density matrices $\rho_1,\dots,\rho_a\in\bbM_{\cM\cV}$ with $\rho_a=\rho$ and
  \begin{alignat*}{2}
    \ptr{\cM}{\rho_i} &= \ptr{\cM}{V_{i-1}\rho_{i-1}V_{i-1}^*} \quad & \textrm{for $i=1,\dots,a$}
  \end{alignat*}
  where we have written $V_0=I$ and $\rho_0=\ket{\psi}\bra{\psi}$ for convenience.

