 \label{t:spanprogramalgorithm}
Fix a function $f : \{0,1\}^n \rightarrow \{0,1\}$.  For $k \in \N$, define $f^k : \{0,1\}^{n^k} \rightarrow \{0,1\}$ as follows: $f^1 = f$ and $f^k(x) = f \big(f^{k-1}(x_1,\ldots, x_{n^{k-1}}), \ldots, f^{k-1}(x_{n^k-n^{k-1}+1}, \ldots, x_{n^k}) \big)$ for $k > 1$.  If span program $P$ computes $f$, then 
\begin{equation}
Q(f^k) = O(\wsize{P}^k)
 \enspace ,
\end{equation}
where $Q(f^k)$ is the bounded-error quantum query complexity of $f^k$.

 \label{t:spanprogramSDPintro}
For any function $f : \{0,1\}^n \rightarrow \{0,1\}$,
\begin{equation} 
\inf_{P} \wsize P  = \ADVpm(f)
 \enspace ,
\end{equation}
where the infimum is over span programs $P$ computing $f$.  Moreover, this infimum is achieved.

 \label{t:generalspanprogramalgorithmintro}
Let $P$ be a span program computing $f: \{ 0, 1\}^n \rightarrow \{0, 1\}$.  Then
\begin{equation}
Q(f) = O\bigg( \wsize P \frac{\log \wsize P}{\log \log \wsize P} \bigg)
 \enspace .
\end{equation}

 \label{t:querycomplexitytightintro}
For any function $f : \{0,1\}^n \rightarrow \{0,1\}$, the quantum query complexity of $f$ satisfies 
\begin{equation}
Q(f) = \Omega(\ADVpm(f)) \quad \text{and} \quad Q(f) = O\bigg(\ADVpm(f) \, \frac{\log \ADVpm(f)}{\log \log \ADVpm(f)}\bigg)
 \enspace .
\end{equation}

 \label{t:spanprogramdef}
Let $n \in \N$.  A span program $P$ consists of a ``target" vector $\ket t$ in a finite-dimensional inner-product space $V$ over $\C$, together with ``input" vectors $\ket{ v_i } \in V$ for $i \in I$.  Here the index set $I$ is a disjoint union $I = \Ifree \sqcup \bigsqcup_{j \in [n], b \in \B} I_{j,b}$.  

To $P$ corresponds a function $f_P : \B^n \rightarrow \B$, defined by 
\begin{equation} \label{e:spanprogramdef}
f_P(x) = \begin{cases}
1 & \text{if $\ket t \in \Span(\{ \ket{ v_i } : i \in \Ifree \cup \bigcup_{j \in [n]} I_{j, x_j} \})$} \\ 
0 & \text{otherwise}
\end{cases}
\end{equation}

 \label{t:wsizedef}
Consider a span program $P$, and a vector $s \in [0, \infty)^n$ of nonnegative ``costs."  Let $S = \sum_{j \in [n], b \in \B, i \in I_{j,b}} \sqrt{s_j} \ketbra i i$.  For each input $x \in \B^n$, define the witness size of $P$ on $x$ with costs $s$, $\wsizexS P x s$, as follows: 
\begin{itemize}
\item If $f_P(x) = 1$, then $\ket{t} \in \Range(A \Pi(x))$, so there is a witness $\ket{w} \in \C^{\abs I}$ satisfying $A \Pi(x) \ket{w} = \ket{t}$.  Then $\wsizexS P x s$ is the minimum squared length of any such witness, weighted by the costs $s$: 
\begin{equation} \label{e:wsizetrue}
\wsizexS P x s 
= \min_{\ket w : \, A \Pi(x) \ket w = \ket t} \norm{S \ket w}^2
 \enspace .
\end{equation}
\item If $f_P(x) = 0$, then $\ket t \notin \Range(A \Pi(x))$.
Therefore there is a witness $\ket{w'} \in V$ satisfying $\braket{t}{w'} = 1$ and $\Pi(x) A^\adjoint \ket{w'} = 0$.  Then 
\begin{equation} \label{e:wsizefalse}
\wsizexS P x s 
= \min_{\substack{\ket{w'} : \, \braket{t}{w'} = 1 \\ \Pi(x) A^\adjoint \ket{w'} = 0}} \norm{S A^\adjoint \ket{w'}}{}^2
 \enspace .
\end{equation}
\end{itemize}

The witness size of $P$ with costs $s$, restricted to domain $\D \subseteq \B^n$, is 
\begin{equation}
\wsizeSD P s =  \max_{x \in \D} \wsizexS P x s
 \enspace .
\end{equation}

 \label{t:adversarydef}
For finite sets $C$ and $E$, and $\D \subseteq C^n$, let $f: \D \rightarrow E$ and let $s \in [0, \infty)^n$ be a vector of nonnegative costs.  An adversary matrix for $f$ is a nonzero, $\abs{\D} \times \abs{\D}$ real, symmetric matrix $\Gamma$ that satisfies $\bra x \Gamma \ket y = 0$ for all $x, y \in \D$ with $f(x) = f(y)$.  

Define the nonnegative-weight adversary bound for $f$, with costs $s$, as 
\begin{equation} \label{e:adversarydef}
\ADV_s(f) = \max_{\large \substack{\text{adversary matrices $\Gamma$:} \\
\forall x, y \in \D, \, \bra x \Gamma \ket y \geq 0 \\
\forall j \in [n], \, \norm{\Gamma \circ \Delta_j} \leq s_j}} \norm{\Gamma}
 \enspace ,
\end{equation}
where $\Gamma \circ \Delta_j$ denotes the entry-wise matrix product between $\Gamma$ and $\Delta_j = \sum_{x, y \in \D : x_j \neq y_j} \ketbra x y$, and the norm is the operator norm.  

The general adversary bound for $f$, with costs $s$, is 
\begin{equation}
\ADVpm_s(f) = \max_{\large \substack{\text{adversary matrices $\Gamma$:} \\
\forall j \in [n], \, \norm{\Gamma \circ \Delta_j} \leq s_j}} \norm{\Gamma}
 \enspace .
\end{equation}
In this maximization, the entries of $\Gamma$ need not be nonnegative.  In particular, $\ADVpm_s(f) \geq \ADV_s(f)$.  

Letting $\vec{1} = (1, 1, \ldots, 1)$, the nonnegative-weight adversary bound for $f$ is $\ADV(f) = \ADV_{\vec 1}(f)$ and the general adversary bound for $f$ is $\ADVpm(f) = \ADVpm_{\vec 1}(f)$.

 \label{t:advquerycomplexity}
For any function $f : \D \rightarrow E$,  with $\D \subseteq C^n$, the $\epsilon$-bounded-error quantum query complexity of $f$ is lower-bounded as 
\begin{equation}\begin{split}
Q_\epsilon(f) 
&\geq \frac{1 - 2\sqrt{\epsilon(1-\epsilon)}}{2} \ADV(f) \\
Q_\epsilon(f) 
&\geq \frac{1 - 2\sqrt{\epsilon(1-\epsilon)} - 2 \epsilon}{2} \ADVpm(f)
 \enspace .
\end{split}\end{equation}
In particular, $Q(f) = \Omega(\ADVpm(f))$.  
Moreover, if $D = \{0,1\}$, then 
\begin{equation}
Q_\epsilon(f) 
\geq \frac{1 - 2\sqrt{\epsilon(1-\epsilon)}}{2} \ADVpm(f)
 \enspace .
\end{equation}

 \label{t:weakadversarycomposition}
Let $f : \{0,1\}^n \rightarrow \{0,1\}$ and, for $j \in [n]$, let $f_j : \{0,1\}^{m_j} \rightarrow \{0,1\}$.  Define $g : \{0,1\}^{m_1} \times \cdots \times \{0,1\}^{m_n} \rightarrow \{0,1\}$ by 
\begin{equation}
g(x) = f\big(f_1(x_1), \ldots, f_n(x_n)\big)
 \enspace .
\end{equation} 
Let $s \in [0, \infty)^{m_1} \times \cdots \times [0, \infty)^{m_n}$, and let $\alpha_j = \ADV_{s_j}(f_j)$ and $\beta_j = \ADVpm_{s_j}(f_j)$ for $j \in [n]$.  Then 
\begin{align}
\ADV_s(g) &= \ADV_\alpha(f) \\
\ADVpm_s(g) &\geq \ADVpm_\beta(f) \label{e:weakadversarycomposition}
 \enspace .
\end{align}
In particular, if $\ADV_{s_1}(f_1) = \cdots = \ADV_{s_n}(f_n) = \alpha$, then $\ADV_s(g) = \alpha \, \ADV(f)$, and if $\ADVpm_{s_1}(f_1) = \cdots = \ADVpm_{s_n}(f_n) = \beta$, then $\ADVpm_s(g) \geq \beta \, \ADVpm(f)$.

 \label{t:wsizeadvbound}
For any span program $P$ computing $f_P : \{0,1\}^n \rightarrow \{0,1\}$, 
\begin{equation}
\wsize{P} \geq \ADVpm(f_P) \geq \ADV(f_P)
 \enspace .
\end{equation}

 \label{t:spanprogramuniversal}
Consider a quantum query algorithm $\algorithm$ that evaluates $f: \{0,1\}^n \rightarrow \{0,1\}$, with bounded one-sided error on false inputs, using $q$ queries.  Then there exists a span program $P$ computing $f_P = f$, with 
\begin{equation}
\wsize{P} = O(q)
 \enspace .
\end{equation}
In particular, $\inf_{P : f_P = f} \wsize{P} = O(Q^1(f))$.

The dual span program $P^\dagger$, with target vector $\ket{t'}$ and input vectors $\ket{v_k'}$ for $k \in I' = \Ifree' \sqcup \bigsqcup_{j \in [n], b \in \B} I_{j, b}'$ in the inner product space $V'$, is defined by: 
\begin{itemize}
\item
$V' = \C^{1 + \abs{I}}$, with orthonormal basis $\{ \ket 0 \} \sqcup \{ \ket i : i \in I \}$.  
\item 
$\ket{t'} = \ket 0$.  
\item
$\Ifree' = [d]$, with free input vectors, for $k \in \Ifree'$, 
\begin{equation}
\ket{v_k'} = (\ketbra 0 t + A^\dagger) \ket k = \ket 0 \!\braket{t}{k} + \sum_{i \in I} \ket i \!\braket{v_i}{k}
 \enspace .
\end{equation}  
\item
For $j \in [n]$ and $b \in \B$, $I_{j, b}' = I_{j, \bar b}$ with $\ket{v_i'} = \ket i$ for $i \in I_{j, b}'$.  
\end{itemize}

 \label{t:spanprogramcomposition}
Consider functions $f : \B^n \rightarrow \B$ and, for $j \in [n]$, $f_j : \B^m \rightarrow \B$.  Let $g : \B^m \rightarrow \B$ be defined by 
\begin{equation}
g(x) = f\big( f_1(x), f_2(x), \ldots, f_n(x) \big)
 \enspace .
\end{equation}
Let $P$ be a span program computing $f_P = f$ and, for $j \in [n]$, let $P_j$ be a span program computing $f_{P_j} = f_j$.  

Then there exists a span program $Q$ computing $f_Q = g$, and such that, for any $s \in [0, \infty)^m$ and $r_j = \wsizeS{P_j}{s}$, 
\begin{equation} \label{e:spanprogramcomposition}
\wsizeS Q s \leq \wsizeS P r
 \enspace .
\end{equation}
In particular, $\wsizeS Q s \leq \wsize P \max_{j \in [n]} \wsizeS{P_j}{s}$.

 \label{t:tensorproductcomposedef}
The tensor-product-composed span program $Q^\tensor$ is defined by: 
\begin{itemize}
\item
The inner product space is $V^\tensor = V \otimes \bigotimes_{j \in [n], c \in \B} V^{jc}$.  
\item
The target vector is $\ket{t^\tensor} = \ket{t}_V \otimes \bigotimes_{j \in [n], c \in \B} \ket{t^{jc}}_{V^{jc}}$.  
\item
The free input vectors are indexed by $\Ifree^\tensor = \Ifree \sqcup \bigsqcup_{j \in [n], c \in \B} (I_{jc} \times \Ifree^{jc})$ with, for $i \in \Ifree^\tensor$, 
\begin{equation}
\ket{v^\tensor_i} = \begin{cases}
\ket{v_i}_V \otimes \bigotimes_{j \in [n], c \in \B} \ket{t^{jc}}_{V^{jc}} & \text{if $i \in \Ifree$} \\
\ket{v_{i'}}_V \otimes \ket{v_{i''}}_{V^{jc}} \otimes \bigotimes_{\substack{j' \in [n], c' \in \B : \\ (j',c') \neq (j,c)}} \ket{t^{j'c'}}_{V^{j'c'}} & \text{if $i = (i', i'') \in I_{jc} \times \Ifree^{jc}$} 
\end{cases}
\end{equation}
\item
The other input vectors are indexed by $I^\tensor_{kb} = \sqcup_{j \in [n], c \in \B} (I_{jc} \times I^{jc}_{kb})$ for $k \in [m]$, $b \in \B$.  For $i \in I_{jc}$, $i' \in I^{jc}_{kb}$, let 
\begin{equation}
\ket{v^\tensor_{ii'}} = \ket{v_i}_V \otimes \ket{v_{i'}}_{V^{jc}} \otimes \bigotimes_{\substack{j' \in [n], c' \in \B : \\ (j',c') \neq (j,c)}} \ket{t^{j'c'}}_{V^{j'c'}}
 \enspace .
\end{equation}
\end{itemize}

 \label{t:directsumcomposedef}
The direct-sum-composed span program $Q^\oplus$ is defined by: 
\begin{itemize}
\item
The inner product space is $V^\oplus = V \oplus \bigoplus_{j \in [n], c \in \B} (\C^{I_{jc}} \otimes V^{jc})$.  Any vector in $V^\oplus$ can be uniquely expressed as $\ket{u}_V + \sum_{i \in I \smallsetminus \Ifree} \ket i \otimes \ket{u_i}$, where $\ket u \in V$ and $\ket{u_i} \in V^{\jc(i)}$.  
\item
The target vector is $\ket{t^\oplus} = \ket{t}_V$.  
\item
The free input vectors are indexed by $\Ifree^\oplus = I \sqcup \bigsqcup_{j \in [n], c \in \B} (I_{jc} \times \Ifree^{jc})$ with, for $i \in \Ifree^\oplus$, 
\begin{equation}
\ket{v^\oplus_i} = \begin{cases}
\ket{v_i}_V & \text{if $i \in \Ifree$} \\
\ket{v_i}_V - \ket i \otimes \ket{t^{jc}} & \text{if $i \in I_{jc}$} \\
\ket{i'} \otimes \ket{v_{i''}} & \text{if $i = (i', i'') \in I_{jc} \times \Ifree^{jc}$} 
\end{cases}
\end{equation}
\item
The other input vectors are indexed by $I^\oplus_{kb}
= \sqcup_{j \in [n], c \in \B} (I_{jc} \times I^{jc}_{kb})$ for $k \in [m]$, $b \in \B$.  For $i \in I_{jc}$, $i' \in I^{jc}_{kb}$, let 
\begin{equation}
\ket{v^\oplus_{ii'}} = \ket{i} \otimes \ket{v_{i'}}
 \enspace .
\end{equation}
\end{itemize}

 \label{t:reducedtensorproductcomposedef}
The tensor-product-composed span program, reduced with respect to the basis $\{ \ket l : l \in [d] \}$, is $Q^\rtensor$, defined by: 
\begin{itemize}
\item
For $l \in [d]$, let $Z_l = \{ (j, c) \in [n] \times \B : \forall \, i \in I_{jc}, \braket{l}{v_i} = 0 \}$, and let $\pi_l = \prod_{(j,c) \in Z_l} \norm{\ket{t^{jc}}}$.
\item
The inner product space of $Q^\rtensor$ is $V^\rtensor = \bigoplus_{l \in [d]} \big( \bigotimes_{(j,c) \notin Z_l} V^{jc} \big)$.  Any vector $\ket v \in V^\rtensor$ can be uniquely expressed as $\sum_{l \in [d]} \ket l \otimes \ket{v_l}$, where $\ket{v_l} \in \bigotimes_{(j,c) \notin Z_l} V^{jc}$.  
\item
The target vector is 
\begin{equation}
\ket{t^\rtensor} = \sum_{l \in [d]} \braket l t \ket l \pi_l \otimes \bigotimes_{(j,c) \notin Z_l} \ket{t^{jc}}_{V^{jc}}
 \enspace .
\end{equation}
\item
The free input vectors are indexed by $\Ifree^\rtensor = \Ifree^\tensor = \Ifree \sqcup \bigsqcup_{j \in [n], c \in \B} (I_{jc} \times \Ifree^{jc})$ with, for $i \in \Ifree^\rtensor$, 
\begin{equation}
\ket{v^\rtensor_i} = \begin{cases}
\sum_{l \in [d]} \braket{l}{v_i} \ket l \pi_l \otimes \bigotimes_{(j,c) \notin Z_l} \ket{t^{jc}}_{V^{jc}} & \text{if $i \in \Ifree$} \\
\sum_{l \in [d]} \braket{l}{v_{i'}} \ket l \pi_l \otimes \ket{v_{i''}}_{V^{jc}} \otimes \bigotimes_{\substack{(j',c') \notin Z_l : \\ (j',c') \neq (j,c)}} \ket{t^{j'c'}}_{V^{j'c'}} & \text{if $i = (i', i'') \in I_{jc} \times \Ifree^{jc}$}
\end{cases}
\end{equation}
\item
The other input vectors are indexed by $I^\rtensor_{kb} = I^\tensor_{kb} = \sqcup_{j \in [n], c \in \B} (I_{jc} \times I^{jc}_{kb})$ for $k \in [m]$, $b \in \B$.  For $i \in I_{jc}$, $i' \in I^{jc}_{kb}$, let 
\begin{equation}
\ket{v^\rtensor_{ii'}} = 
\sum_{l \in [d]} \braket{l}{v_i} \ket l \pi_l \otimes \ket{v_{i'}}_{V^{jc}} \otimes \bigotimes_{\substack{(j',c') \notin Z_l : \\ (j', c') \neq (j,c)}} \ket{t^{j'c'}}_{V^{j'c'}}
 \enspace .
\end{equation}
\end{itemize}

 \label{t:reducedtensorproductcompose}
The span program $Q^\rtensor$ computes $f_{Q^\rtensor} = g$, and, for any $s \in [0, \infty)^m$, 
\begin{equation}
\wsizeS {Q^\rtensor} s \leq \wsizeS P \sigma
 \enspace ,
\end{equation}
where $\sigma_j = \wsizeS{P_j}{s}$ for $j \in [n]$.  In particular, $\wsizeS {Q^\rtensor} s \leq \wsize P \max_{j \in [n]} \wsizeS{P_j}{s}$.

 \label{t:spanprogramcompositiontight}
In \thmref{t:spanprogramcomposition}, assume that the functions $f_j$, $j \in [n]$, depend on disjoint sets of the input bits.  Assume also that the span programs $P_j$ have witness sizes $r_j = \wsizeS{P_j}{s} = \ADVpm_s(f_j)$ and that $P$ has witness size $\wsizeS P r = \ADVpm_r(f)$.  (By \thmref{t:wsizeadvbound}, these witness sizes are optimal.)   Then the composed span program $Q$ satisfies 
\begin{equation} \label{e:spanprogramcompositiontight}
\wsizeS Q s = \ADVpm_s(g) = \ADVpm_r(f)
 \enspace ,
\end{equation}
which is optimal.

 \label{t:strictmonotonerealdef}
Let $P$ be a span program.  
\begin{itemize}
\item
$P$ is \emph{strict} if it has no free input vectors, i.e., $\Ifree = \emptyset$.  
\item
$P$ is \emph{real} if in a basis for $V$ the coefficients of the input and target vectors are all real numbers.  
\item
$P$ is \emph{monotone} if $I_{j,0} = \emptyset$ for all $j \in [n]$.  
\end{itemize}

 \label{t:spanprogramSDP}
For any function $f : \D \rightarrow \B$, with $\D \subseteq \B^n$, and any cost vector $s \in [0, \infty)^n$, 
\begin{equation} \label{e:spanprogramSDP}
\inf_{\large\substack{P : \, f_P\vert_\D = f}} \wsizeSD P s = \ADVpm_s(f)
 \enspace ,
\end{equation}
where the infimum is over span programs $P$ that compute a function agreeing with $f$ on $\D$.  Moreover, this infimum is achieved.

 \label{t:adversarydual}
For finite sets $\D \subseteq C^n$, and $E$, let $f: \D \rightarrow E$, and let $s \in [0, \infty)^n$ be a vector of nonnegative costs.  
If either $C = \{0,1\}$ or $E = \{0,1\}$, then the general adversary bound for $f$, with costs $s$, equals 
\begin{equation} \label{e:generaladversarydual}
\ADVpm_s(f) = 
\min_{\large \substack{X \succeq 0 : \\ \forall (x,y) \in F, \,  \sum_{j \in [n] : x_j \neq y_j} \bra{x,j} X \ket{y,j} = 1}}
\max_{\large \substack{x \in \D}} \sum_{j \in [n]} s_j \bra{x,j} X \ket{x,j} 
 \enspace .
\end{equation}
Here $X$ is required to be a positive semi-definite, $(n \abs{\D}) \times (n \abs{\D})$ matrix, with coordinates labeled by $\D \times [n]$, and $F = \{ (x, y) \in \D \times \D : f(x) \neq f(y) \}$.  
The optimum is achieved.

 \label{t:adversarydualgeneral}
For finite sets $\D \subseteq C^n$, and $E$, let $f: \D \rightarrow E$, and let $s \in [0, \infty)^n$.  Let $F = \sum_{x, y \in \D : \, f(x) \neq f(y)} \ketbra x y$.  As in \defref{t:adversarydef}, let $\Delta_j = \sum_{x, y \in \D : x_j \neq y_j} \ketbra x y$ for $j \in [n]$, and let $\circ$ denote entry-wise matrix multiplication.  

Then the nonnegative-weight adversary bound for $f$, with costs $s$, equals
\begin{equation} \label{e:adversarydual}
\ADV_s(f) 
= 
\min_{\large \substack{X_j \succeq 0 : \\ \sum_j X_j \circ \Delta_j \circ F \geq F}} \max_{x \in \D} \sum_{j \in [n]} s_j \bra x X_j \ket x
 \enspace .
\end{equation}
The minimization is over $\abs \D \times \abs \D$ positive semi-definite matrices $X_j$, $j \in [n]$, that satisfy the entry-wise inequality $\sum_j X_j \circ \Delta_j \circ F \geq F$.  (Note that Eq.~\eqnref{e:generaladversarydual} has the same form, except with the requirement that $\sum_j X_j \circ \Delta_j \circ F = F$.)  

The general adversary bound for $f$, with costs $s$, equals 
\begin{equation} \label{e:generaladversarydualgeneral}
\ADVpm_s(f) = 
\min_{\large \substack{X_j, Y_j \succeq 0 : \\ \sum_j (X_j - Y_j) \circ \Delta_j \circ F = F}}
\max_{\large \substack{x \in \D}} \sum_{j \in [n]} s_j \bra{x} (X_j+Y_j) \ket{x} 
 \enspace .
\end{equation}

 \label{t:spanprogramSDPconstruction}
Let $f : \D \rightarrow \B$, with $\D \subseteq \B^n$, be a partial boolean function.  For $b \in \B$, let $F_b = \{ x \in \D : f(x) = b \}$.  Then for any cost vector $s \in [0, \infty)^n$, 
\begin{equation}\begin{split} \label{e:spanprogramSDPCholesky}
\inf_{\large\substack{P : \, f_P\vert_\D = f}} \wsizeSD P s
&=
\inf_{\large \substack{m \in \N, \\ \{ \ket{v_{x j}} \in \R^m : \, x \in \D, j \in [n] \} \,: \\ \forall (x,y) \in F_0 \times F_1, \, \sum_{j \in [n] : x_j \neq y_j} \braket{v_{x j}}{v_{y j}} = 1}} \max_{\large \substack{x \in \D}} \; \sum_{j \in [n]} s_j \norm{ \ket{v_{x j}} }^2
 \enspace .
\end{split}\end{equation}

 \label{t:spanprogramuniversalboundederror}
For any function $f : \D \rightarrow \{0,1\}$, with $\D \subseteq \{0,1\}^n$, there exists a span program $P$ computing $f_P\vert_\D = f$ with witness size upper-bounded by the bounded-error quantum query complexity of~$f$, 
\begin{equation}
\wsizeD P = O(Q(f))
 \enspace .
\end{equation}

 \label{t:advpmcomposition}
Let $f : \{0,1\}^n \rightarrow \{0,1\}$ and, for $j \in [n]$, let $f_j : \{0,1\}^{m_j} \rightarrow \{0,1\}$.  
Define $g : \{0,1\}^{m_1} \times \cdots \times \{0,1\}^{m_n} \rightarrow \{0,1\}$ by $g(x) = f\big(f_1(x_1), \ldots, f_n(x_n)\big)$.  Let $s \in [0, \infty)^{m_1} \times \cdots \times [0, \infty)^{m_n}$, and let $\beta_j = \ADVpm_{s_j}(f_j)$ for $j \in [n]$.  Then 
\begin{equation}
\ADVpm_s(g) = \ADVpm_\beta(f)
 \enspace .
\end{equation}
In particular, if $\ADVpm_{s_1}(f_1) = \cdots = \ADVpm_{s_n}(f_n) = \beta$, then $\ADVpm_s(g) = \beta \, \ADVpm(f)$.

 \label{t:querycomplexitylimit}
For any function $f : \{0,1\}^n \rightarrow \{0,1\}$, define $f^{k} : \{0,1\}^{n^k} \rightarrow \{0,1\}$ as the function $f$ composed on itself repeatedly to a depth of $k$, as in \thmref{t:spanprogramalgorithm}.  Then 
\begin{equation}
\lim_{k \rightarrow \infty} Q(f^{k})^{1/k} = \ADVpm(f)
 \enspace .
\end{equation}

 \label{t:signdegree}
For any function $f : \{0,1\}^n \rightarrow \{0,1\}$, 
\begin{equation}
\underset{k \rightarrow \infty}{{\lim \sup}} \, \signdegree(f^{k})^{1/k} \le \lim_{k \rightarrow \infty} Q(f^k)^{1/k}= \ADVpm(f)
 \enspace .
\end{equation}

A finite, weighted, bipartite graph $G$ is specified by finite sets $T$ and $U$, and $\biadj_G \in \L(\C^U, \C^T)$ the ``biadjacency matrix."  $G$ has vertices $\{ \tau_i : i \in T \} \sqcup \{ \mu_j : j \in U \}$.  For each $i \in T$ and $j \in U$ with $\bra i \biadj_G \ket j \neq 0$, $G$ has an edge $(\tau_i, \mu_j)$ weighted by $\bra i \biadj_G \ket j$.  The weighted adjacency matrix of $G$, $A_G \in \L(\C^T \oplus \C^U)$, is 
\begin{equation}
A_G = \left( \begin{matrix} 0 & \biadj_G \\ \biadj_G^\dagger & 0 \end{matrix} \right)
\place{{\small T}}{-74mu}{18pt}
\place{{\small U}}{-30mu}{18pt}
\place{{\small T}}{0mu}{8pt}
\place{{\small U}}{0mu}{-6pt}
\end{equation}

 \label{t:spanprogramadjacencymatrix}
Let $P$ be a span program with target vector $\ket t$ and input vectors $\ket{v_i}$ for $i \in I = \Ifree \cup \bigcup_{j \in [n], b \in \B} I_{j,b}$, in inner product space $V$.  Fix an arbitrary orthonormal basis $\{ \ket k : k \in [\dim(V)] \}$ for $V$.  

Let $G_P$ be the weighted bipartite graph with $T = [\dim(V)] \sqcup I$, $U = \{ 0 \} \sqcup I$ and the biadjacency matrix
\begin{equation}
\biadj_{G_P} = \left( \begin{matrix} \ket t & A \\ 0 & \identity \end{matrix} \right)
\place{{\small $0$}}{-58mu}{18pt}
\place{{\small I}}{-23mu}{18pt}
\place{{\small V}}{0mu}{8pt}
\place{{\small I}}{0mu}{-6pt}
\end{equation}
The vertex $\mu_0$ is called the ``output vertex."

Note that for each input vector index $i \in I$, $G_P$ has two corresponding vertices, with a weight-one edge between them.  For $x \in \B^n$, let $G_P(x)$ be the same as $G_P$ except with these weight-one edges deleted for all $i \in I(x)$.  That is, $G_P(x)$ has the biadjacency matrix 
\begin{equation} \label{e:spanprogramadjacencymatrix}
\biadj_{G_P(x)} = \left( \begin{matrix} \ket t & A \\ 0 & \Pim(x) \end{matrix} \right)
\place{{\small $0$}}{-81mu}{18pt}
\place{{\small I}}{-35mu}{18pt}
\place{{\small V}}{0mu}{8pt}
\place{{\small I}}{0mu}{-6pt}
\end{equation}

 \label{t:spanprogramspectralanalysis}
Let $P$ be a span program and $\D \subseteq \B^n$.  Then a span program $P'$ can be constructed such that $f_{P'} = f_P$ and, for all $x \in \D$, 
\begin{itemize}
\item
If $f_P(x) = 1$, then there is an eigenvalue-zero eigenvector $\ket \psi$ of $A_{G_{P'}(x)}$ with 
\begin{equation} \label{e:spanprogramspectralanalysistrue}
\frac{\abs{ \braket 0 \psi }^2}{\norm{\ket \psi}^2}
\geq 
\frac{1}{2}
 \enspace .
\end{equation}
\item
If $f_P(x) = 0$, let $\{ \ket \alpha \}$ be a complete set of orthonormal eigenvectors of $A_{G_{P'}(x)}$, with corresponding eigenvalues $\rho(\alpha)$.  Then for any $c \geq 0$, the squared length of the projection of $\ket 0$ onto the span of the eigenvectors $\alpha$ with $\abs{\rho(\alpha)} \leq c / \wsizeD P$ satisfies 
\begin{equation} \label{e:spanprogramspectralanalysisfalse}
\sum_{\alpha : \, \abs{\rho(\alpha)} \leq c / \wsizeD P} \abs{\braket \alpha 0}^2 \leq 8 c^2 \Big(1 + \frac{1}{\wsizeD P}\Big) \leq 16 c^2
 \enspace .
\end{equation}
\end{itemize}

 \label{t:spanprogramspectralanalysisnonblackbox}
Let $P$ be a span program, and for $x \in \B^n$ let $G_P(x)$ be the weighted bipartite graph from \defref{t:spanprogramadjacencymatrix}.  Then for $x \in \B^n$: 
\begin{itemize}
\item
If $f_P(x) = 1$, let $\ket w \in \C^I$ be a witness, i.e., $A \Pi(x) \ket w = \ket t$.  Then $A_{G_P(x)}$ has an eigenvalue-zero eigenvector $\ket \psi$ with 
\begin{equation} \label{e:spanprogramspectralanalysisnonblackboxtrue}
\frac{\abs{ \braket 0 \psi }^2}{\norm{\ket \psi}^2} \geq \frac{1}{1 + \norm{\ket w}^2}
 \enspace .
\end{equation}
\item
If $f_P(x) = 0$, let $\ket{w'} \in V$ be a witness, i.e., $\braket{t}{w'} = 1$ and $\Pi(x) A^\dagger \ket{w'} = 0$.  Let $\{ \ket \alpha \}$ be a complete set of orthonormal eigenvectors of $A_{G_P(x)}$, with corresponding eigenvalues $\rho(\alpha)$.  Then for any $\Upsilon \geq 0$, 
\begin{equation} \label{e:spanprogramspectralanalysisnonblackboxfalse}
\sum_{\alpha : \, \abs{\rho(\alpha)} \leq \Upsilon} \abs{\braket \alpha 0}^2 \leq 8 \Upsilon^2 \Big( \norm{\ket{w'}}^2 + \norm{A^\dagger \ket{w'}}^2 \Big)
 \enspace .
\end{equation}
\end{itemize}

 \label{t:zeroenergy}
For a span program $P$ and input $x \in \B^n$, consider all the eigenvalue-zero eigenvector equations of the weighted adjacency matrix $A_{G_P(x)}$, except for the constraint at the output vertex $\mu_0$, i.e., Eqs.~(\ref{e:zeroenergyequations}) except (\ref{e:zeroenergyequationsaO}) at $\rho = 0$.  

These equations have a solution $\ket \psi$ with $\psi_{U,0} \neq 0$ if and only if $f_P(x) = 1$, and have a solution $\ket \psi$ with $\braket{t}{\psi_{T,V}} \neq 0$ if and only if $f_P(x) = 0$.  More quantitatively, let $s \in [0, \infty)^n$ be a vector of nonnegative costs, and recall from \defref{t:wsizedef} that $S = \sum_{j \in [n], b \in \B, i \in I_{j,b}} \sqrt{s_j} \ketbra i i$.  Then 
\begin{itemize}
\item 
If $f_P(x) = 1$, $A_{G_P(x)}$ has an eigenvalue-zero eigenvector $\ket \psi = (0, \psi_{U,0}, \ket{\psi_{U,I}}) \in \C^T \oplus \C^{\{0\}} \oplus \C^I$ with 
\begin{equation} \label{e:zeroenergytrue}
\frac{\abs{\psi_{U,0}}^2}{ \abs{\psi_{U,0}}^2 + \norm{S \ket {\psi_{U,I}}}^2}
\geq 
\frac{1}{1 + \wsizexS P x s}
 \enspace .
\end{equation}
\item 
If $f_P(x) = 0$, let $\ket{w'} \in V$ be an optimal witness, i.e., $\braket{t}{w'} = 1$, $\Pi(x) A^\dagger \ket{w'} = 0$ and $\norm{S A^\dagger \ket{w'}}^2 = \wsizexS P x s$ (see \defref{t:wsizedef}).  Then there is a solution $\ket \psi = (\ket{\psi_{T,V}}, \ket{\psi_{T,I}}, 0) \in V \oplus \C^I \oplus \C^U$ to Eqs.~(\ref{e:zeroenergyequations}a,b,d) at $\rho = 0$, with  
\begin{equation} \label{e:zeroenergyfalse}
\frac{ \abs{\braket{t}{\psi_{T,V}}}^2 } { \norm{\ket{\psi_{T,V}}}^2 + \norm{S \ket{\psi_{T,I}}}^2 } \geq \frac 1 {\norm{\ket{w'}}^2 + \wsizexS P x s}
 \enspace .
\end{equation}
\end{itemize}

 \label{t:zeroenergyuniformcosts}
Let $P$ be a span program.  Then there exists a span program $\hat P$ that computes $f_{\hat P} = f_P$, and such that, for all $x \in \B^n$, 
\begin{itemize}
\item
If $f_P(x) = 1$, then there is an eigenvalue-zero eigenvector $\ket \psi$ of $A_{G_{\hat P}(x)}$ with 
\begin{equation} \label{e:zeroenergyuniformcoststrue}
\frac{\abs{\psi_{U,0}}^2}{\norm{\ket \psi}^2}
\geq 
\frac{1}{1 + \wsizex P x}
 \enspace .
\end{equation}
\item
If $f_P(x) = 0$, then there is a solution $\ket \psi$ to all the eigenvalue-zero eigenvector equations of $A_{G_{\hat P}(x)}$, except for the constraint at vertex $\mu_0$, with  
\begin{equation} \label{e:zeroenergyuniformcostsfalse}
\frac{\abs{\braket{t}{\psi_{T,V}}}^2}{\norm{\ket \psi}^2}
\geq 
\frac{1}{1 + \wsizex P x}
 \enspace .
\end{equation}
\end{itemize}

 \label{t:bipartitepsdreduction}
Let $G$ be a weighted bipartite graph with biadjacency matrix $\biadj_G \in \L(\C^U, \C^T)$.  Assume that for some $\delta > 0$ and $\ket t \in \C^T$, the weighted adjacency matrix $A_G$ has an eigenvalue-zero eigenvector $\ket{\psi}$ with 
\begin{equation}
\abs{\braket{t}{\psi_T}}^2 \geq \delta \norm{\ket \psi}^2
 \enspace .
\end{equation}
Let $G'$ be the same as $G$ except with a new vertex, $\mu_0$, added to the $U$ side, and for $i \in T$ the new edge $(\tau_i, \mu_0)$ weighted by $\braket i t$.  That is, the biadjacency matrix of $G'$ is 
\begin{equation}
\biadj_{G'} = \left( \begin{matrix} \ket t & \biadj_G \end{matrix} \right)
\place{{\small $0$}}{-65mu}{12pt}
\place{{\small U}}{-27mu}{12pt}
\place{{\small T}}{3mu}{0pt}
\end{equation}

Recall that $\ket 0 = (0, 1, 0) \in \C^T \oplus \C^{\{0\}} \oplus \C^U$.  Let $\{ \ket \alpha \}$ be a complete set of orthonormal eigenvectors of $A_{G'}$, with corresponding eigenvalues $\rho(\alpha)$.  Then for all $\Upsilon \geq 0$, the squared length of the projection of $\ket 0$ onto the span of the eigenvectors $\alpha$ with $\abs{\rho(\alpha)} \leq \Upsilon$ satisfies 
\begin{equation} \label{e:bipartitepsdreduction}
\sum_{\alpha : \, \abs{\rho(\alpha)} \leq \Upsilon} \abs{\braket \alpha 0}^2 \leq 8 \Upsilon^2 / \delta
 \enspace .
\end{equation}

 \label{t:psdsquaredsupport}
Let $X \in \L(V)$ be a positive semi-definite matrix, $\ket t \in V$ a vector, and let $X' = X + \ketbra t t$.  Let $\{ \ket \beta \}$ be a complete set of orthonormal eigenvectors of $X'$, with corresponding eigenvalues $\lambda(\beta) \geq 0$.  Assume that there exists a $\ket \varphi \in \Kernel(X)$ with $\abs{\braket t \varphi}^2 \geq \delta \norm{\ket \varphi}^2$.  Then for any $\Lambda \geq 0$, 
\begin{equation} \label{e:psdsquaredsupport}
\delta \sum_{\substack{\beta : \, \lambda(\beta) \leq \Lambda \\ \braket t \beta \neq 0}} \frac{1}{\lambda(\beta)} \abs{\braket t \beta}^2 \leq 4 \Lambda
 \enspace .
\end{equation}

 \label{t:psdsquaredsupportmaximize}
Under the conditions of \thmref{t:psdsquaredsupport}, for any $\ket \xi \in V$, 
\begin{equation} \label{e:psdsquaredsupportmaximize}
\delta \abs{\braket t \xi}^2 \leq \norm{X' \ket \xi}{}^2
 \enspace .
\end{equation}
Moreover, if $\ket \xi$ is a linear combination of eigenvectors with corresponding eigenvalues at most $\kappa$, i.e., $\ket \xi = \sum_{\beta : \lambda(\beta) \leq \kappa} \braket \beta \xi \ket \beta$, then 
\begin{equation} \label{e:psdsquaredsupportmaximizeplugin}
\delta \abs{\braket t \xi}^2 \leq \kappa^2 \norm{\ket \xi}^2
 \enspace .
\end{equation}

\begin{equation}
\min_{\ket \xi : \, \braket t \xi = \norm{\ket t}} \norm{X' \ket \xi}^2 = \frac{ \norm{\ket t}^4 }{ 1 + \sum_j \big(\frac{b_j}{a_j}\big)^2 } \geq \delta \norm{\ket t}^2
 \enspace .
\end{equation}

 \label{t:phaseestimationalgorithm}
Let $G = (V,E)$ be a complex-weighted graph with Hermitian weighted adjacency matrix $A_G \in \L(\C^V)$ satisfying $\bra v A_G \ket v \geq 0$ for all $v \in V$.  Let $V_{\text{input}}$ be a subset of degree-one vertices of $G$ whose incident edges have weight one, and partition $V_{\text{input}}$ as $V_{\text{input}} = \bigsqcup_{j \in [n], b \in \B} V_{j,b}$.  For $x \in \B^n$, define $G(x)$ from $G$ by deleting all edges to vertices in $\cup_{j \in [n]} V_{j, x_j}$.  Let $A_{G(x)} \in \L(\C^V)$ be the weighted adjacency of matrix of $G(x)$.  

Let $f : \D \rightarrow \B$, with $\D \subseteq \B^n$, $\mu \in V \smallsetminus V_{\text{input}}$, $\epsilon = \Omega(1)$ and $\Lambda > 0$.  Assume that for all $x \in \D$ the graphs $G(x)$ satisfy:
\begin{itemize}
\item
If $f(x) = 1$, then $A_{G(x)}$ has an eigenvalue-zero eigenvector $\ket \psi \in \C^V$ with 
\begin{equation} \label{e:phaseestimationalgorithmtrue}
\frac{\abs{\braket \mu \psi}^2}{\norm{\ket \psi}} \geq \epsilon
 \enspace .
\end{equation}
\item 
If $f(x) = 0$, let $\{ \ket \alpha \}$ be a complete set of orthonormal eigenvectors of $A_{G(x)}$, with corresponding eigenvalues $\rho(\alpha)$.  Assume that 
the squared length of the projection of $\ket \mu$ onto the span of the eigenvectors $\alpha$ with $\abs{\rho(\alpha)} \leq \Lambda$ satisfies 
\begin{equation} \label{e:phaseestimationalgorithmfalse}
\sum_{\alpha : \, \abs{\rho(\alpha)} \leq \Lambda} \abs{\braket \alpha \mu}^2 \leq \epsilon / 2
 \enspace .
\end{equation}
\end{itemize}

Let $\abst(A_G)$ be the entry-wise absolute value of $A_G$, and let $\norm{\abst(A_G)}$ be its operator norm.  Then $f$ can be evaluated with error probability at most $1/3$ using at most 
\begin{equation} \label{e:phaseestimationalgorithm}
O\left( \min \bigg\{ \frac{\norm{\abst(A_G)}}{\Lambda}, \; \frac{1}{\Lambda} \frac{\log \frac{1}{\Lambda}}{\log \log \frac{1}{\Lambda}} \bigg\} \right)
\end{equation}
quantum queries.

 \label{t:generalspanprogramalgorithm}
Let $P$ be a span program and $\D \subseteq \B^n$.  Then the quantum query complexity of $f_P$ restricted to $\D$ satisfies
\begin{equation}
Q(f_P\vert_\D) = 
O\bigg( \wsizeD P \frac{\log \wsizeD P}{\log \log \wsizeD P} \bigg)
 \enspace .
\end{equation}

 \label{t:generalspanprogramalgorithmnonblackbox}
Let $P$ be a span program with target vector $\ket t$ and input vectors $\ket{v_i}$ for $i \in I = \Ifree \cup \bigcup_{j \in [n], b \in \B} I_{j,b}$, in inner product space $V$.  Let $\D \subseteq \B^n$ and assume that for some $W_1, W_2 \geq 1$, 
\begin{equation}\begin{split}
\max_{x \in \D : f_P(x) = 1} \min_{\substack{\ket w \in \C^I : \\ A \Pi(x) \ket w = \ket t}} \norm{\ket w}^2 
&\leq W_1 \\
\max_{x \in \D : f_P(x) = 0} \min_{\substack{\ket{w'} \in V : \, \braket{t}{w'} = 1, \\ \Pi(x) A^\dagger \ket{w'} = 0}}(\norm{\ket{w'}}^2 + \norm{A^\dagger \ket{w'}}^2) &\leq W_2
 \enspace .
\end{split}\end{equation}

Let $P'$ be the same as $P$, except with the target vector $\ket t / \sqrt{W_1}$.  Then $f_P$ can be evaluated on inputs in $\D$ using 
\begin{equation}
O\big( \sqrt{W_1 W_2} \norm{\abst(A_{G_{P'}})} \big)
= 
O\big( \sqrt{W_1 W_2} \norm{\abst(A_{G_P})} \big)
\end{equation}
quantum queries, with error probability at most $1/3$.

 \label{t:szegedization}
Let $V$ be a finite set.  For each $v \in V$, let $\ket{\varphi_v} \in \C^V$ be a length-one vector.  Define $T \in \L(\C^V, \C^V \otimes \C^V)$, $S, U \in \L(\C^V \otimes \C^V)$ and $M \in \L(\C^V)$ by 
\begin{align}
T &= \sum_{v \in V} (\ket v \otimes \ket{\varphi_v}) \bra v &
S &= \sum_{v,w \in V} \ketbra{v,w}{w,v} \label{e:szegedizationTS} \\
U &= (2 T T^\dagger - \identity) S &
M &= T^\adjoint S T = \sum_{v, w \in V} \braket{\varphi_v}{w} \braket{v}{\varphi_w} \ketbra v w \label{e:szegedizationUM}
\end{align}
Since $T^\dagger T = \identity$, $U$ is a unitary.  ($U$ is a swap followed by the reflection about the span of the vectors $\{ \ket v \otimes \ket{\varphi_v} : v \in V \}$.)  $M$ is a Hermitian matrix with $\norm M \leq 1$.  Let $\{\ket \alpha\}$ be a complete set of orthonormal eigenvectors of $M$ with respective eigenvalues $\rho(\alpha)$.  

Then the spectral decomposition of $U$ corresponds to that of $M$ as follows: Let $R_\alpha = \Span\{T \ket \alpha, S T \ket \alpha\}$.  Then $R_\alpha \perp R_{\alpha'}$ for $\alpha \neq \alpha'$; let $R = \oplus_\alpha R_\alpha$.  $U$ is $-S$ on $R^\perp$, and $U$ preserves each subspace $R_\alpha$.  

If $\abs{\rho(\alpha)} < 1$, then $R_\alpha$ is two-dimensional, and within it the eigenvectors and corresponding eigenvalues of $U$ are given by 
\begin{equation}\begin{split} \label{e:szegedizationeigenvectors}
\ket{\alpha, \pm} &= \Big(\identity - \big(\rho(\alpha) \mp i \sqrt{1 - \rho(\alpha)^2}\big) S \Big) T \ket \alpha \\
\lambda(\alpha, \pm) &= \rho(\alpha) \pm i \sqrt{1 - \rho(\alpha)^2}
 \enspace .
\end{split}\end{equation}
If $\rho(\alpha) \in \{1, -1\}$, then $S T \ket \alpha = \rho(\alpha) T \ket \alpha$, so $R_\alpha$ is one-dimensional; let $\ket{\alpha, +} = T \ket \alpha$ and $\lambda(\alpha, +) = \rho(\alpha)$ be the corresponding eigenvalue of $U$.

 \label{t:szegedizationnormalization}
With the setup of \thmref{t:szegedization}, for any $\ket \psi \in \C^V$, the eigenvectors $\ket{\alpha, \pm}$ with $\abs{\rho(\alpha)} < 1$ satisfy $\norm{\ket{\alpha, \pm}} = \sqrt{2 (1 - \rho(\alpha)^2)}$ and 
\begin{equation} \label{e:szegedizationnormalization}
\frac{\abs{ \bra \psi T^\dagger \ket{\alpha, \pm}}^2}{\norm{\ket{\alpha, \pm}}^2} = \frac{1}{2} \abs{ \braket \psi \alpha }^2
 \enspace .
\end{equation}
When $\abs{\rho(\alpha)} = 1$, $\norm{\ket{\alpha, +}} = 1$ and $\bra \psi T^\dagger \ket{\alpha, +} = \braket \mu \alpha$.

 \label{t:CGMSYization}
Suppose we are given a continuous-time query algorithm with any driving Hamiltonian $D(t)$ whose operator norm $\norm{D(t)}$ is bounded above by any $L_1$ function with respect to $t$.  (The size of $\norm{D(t)}$ as a function of the input size $N$ does not matter.)  Then there exists a discrete-time query algorithm that makes 
\begin{equation}
O \bigg( \frac{T \log \frac T \delta}{\delta \log \log \frac T \delta} \bigg)
\end{equation}
full queries and whose answer has fidelity $1-\delta$ with the output of the continuous-time algorithm.

When run with input $x \in \D$, the above procedure satisfies: 
\begin{itemize}
\item If $f(x) = 1$, then it outputs $1$ with probability at least $\epsilon$.  
\item If $f(x) = 0$, then it outputs $1$ with probability at most $3 \epsilon / 4$.  
\end{itemize}

 \label{t:querycomplexitytight}
For any function $f : \D \rightarrow \{0,1\}$, with $\D \subseteq \{0,1\}^n$, the bounded-error quantum query complexity of $f$, $Q(f)$, satisfies 
\begin{align}
Q(f) &= \Omega(\ADVpm(f)) \\
\intertext{and}
Q(f) &= O\bigg(\ADVpm(f) \, \frac{\log \ADVpm(f)}{\log \log \ADVpm(f)}\bigg)
 \enspace .
\end{align}

 \label{t:querycomplexitytightnonbinary}
For any function $f : \D \rightarrow [m]$, with $\D \subseteq \{0,1\}^n$, $Q(f)$ satisfies
\begin{align}
Q(f) &= \Omega(\ADVpm(f)) \\
\intertext{and}
Q(f) &= O\bigg(\ADVpm(f) \, \frac{\log \ADVpm(f)}{\log \log \ADVpm(f)} \log(m) \log \log m \bigg)
 \enspace .
\end{align}

 \label{t:adversaryprojection}
For finite sets $\D \subseteq C^n$, $E$ and $F$, let $f: \D \rightarrow E$ and $g : E \rightarrow F$.  Let $s \in [0, \infty)^n$.  Then 
\begin{align}
\ADV_s(g \circ f) &\leq \ADV_s(f) \\
\ADVpm_s(g \circ f) &\leq \ADVpm_s(f)
 \enspace .
\end{align}

 \label{t:advboundtight}
For any function $f : \D \rightarrow \{0,1\}$, with $\D \subseteq \{0,1\}^n$, the general quantum adversary bound is tight: 
\begin{equation}
Q(f) = \Theta(\ADVpm(f))
 \enspace .
\end{equation}

The Hamming-weight threshold function $\threshold{l}{n} : \{0, 1\}^n \rightarrow \{0,1\}$ is defined by 
\begin{equation}
\threshold{l}{n}(x) = \begin{cases}
1 & \text{if $\abs{x} \geq l$} \\
0 & \text{otherwise}
\end{cases}
\end{equation}
where $\abs{x} = \sum_{i=1}^{n} x_i$ is the Hamming weight of $x$.  

The Hamming-weight interval function $\interval{l}{m}{n} : \{0,1\}^n \rightarrow \{0,1\}$ is defined by 
\begin{equation}
\interval{l}{m}{n}(x) = \begin{cases}
1 & \text{if $l \leq \abs{x} \leq m$} \\
0 & \text{otherwise}
\end{cases}
\end{equation}

 \label{t:maintheorem}
For the interval function $\interval{l}{m}{n}$, assume that $\abs{\frac{n}{2} - m} \leq \abs{\frac{n}{2} - l}$.  Then  
\begin{equation}
\ADV(\interval{l}{m}{n}) = \begin{cases}
\sqrt{ (m+1)(n-m) + \frac{m(n-l+1)}{(m-l+1)^2} } & \text{if $l > 0$} \\
\sqrt{ (m+1)(n-m) } & \text{if $l = 0$}
\end{cases}
 \enspace .
\end{equation}
If $l \in \{0, 1, m \}$, then $\ADVpm(\interval{l}{m}{n}) = \ADV(\interval{l}{m}{n})$; otherwise $\ADVpm(\interval{l}{m}{n}) > \ADV(\interval{l}{m}{n})$.  

There exists a span program $P_{l,m}^{n}$ computing $f_{P_{l,m}^{n}} = \interval{l}{m}{n}$, with witness size 
\begin{equation} \label{e:maintheoremwsize}
\wsize{P_{l,m}^n} \leq \sqrt{ (m+1)(n-m) + \frac{l(n-l+1)}{m-l+1} }
 \enspace .
\end{equation}
This witness size matches $\ADV(\interval{l}{m}{n})$, and hence is optimal, for $l \in \{0, 1, m \}$, i.e., in those cases where $\ADVpm(\interval{l}{m}{n}) = \ADV(\interval{l}{m}{n})$.

 \label{t:dualadversarydef}
Let $f: \{0,1\}^n \rightarrow \{0,1\}$.  Then 
\begin{equation} \label{e:dualadversarydef}
\ADV(f) = \min_{\{p_x\}} \max_{x, y : f(x) \neq f(y)} \frac{1}{ \sum_{i : x_i \neq y_i} \sqrt{p_x(i) p_y(i)} }
 \enspace ,
\end{equation}
where the first minimization is over distributions $p_x$ on $[n]$ for each $x \in \{0,1\}^n$.

 \label{t:thresholdspanprogram}
For $l \in [n]$, there exists a span program $P_{l}^{n}$ computing $f_{P_{l}^{n}} = \threshold{l}{n}$, with witness size 
\begin{equation} \label{e:thresholdspanprogram}
\wsize{P_{l}^{n}} \leq \sqrt{ l (n-l+1) }
 \enspace .
\end{equation}

 \label{t:thresholdspanprogramwsizetrue}
On an input $x$ of Hamming weight $\abs{x} = j \geq l$, the span program $P_{l}^{n}$ constructed in \propref{t:thresholdspanprogram} satisfies
\begin{equation} \label{e:thresholdspanprogramwsizetrue}
\wsizex{P_{l}^{n}}{x} \leq \frac{1}{j-l+1}
 \enspace .
\end{equation}

 \label{t:intervalspanprogram}
There exists a span program $P_{l,m}^{n}$ computing $f_{P_{l,m}^{n}} = \interval{l}{m}{n}$, with witness size 
\begin{equation} \label{e:intervalspanprogram}
\wsize{P_{l,m}^n} \leq \sqrt{ (m+1)(n-m) + \frac{l(n-l+1)}{m-l+1} }
\end{equation}
when $\abs{\frac{n}{2} - m} \leq \abs{\frac{n}{2} - l}$.

 \label{t:intervaladversary}
For the interval function $\interval{l}{m}{n}$ with $\abs{\frac{n}{2} - m} \leq \abs{\frac{n}{2} - l}$,   
\begin{equation}
\ADV(\interval{l}{m}{n}) = 
\begin{cases}
\sqrt{ (m+1)(n-m) + \frac{m(n-l+1)}{(m-l+1)^2} } & \text{if $l > 0$} \\
\sqrt{ (m+1)(n-m) } & \text{if $l = 0$}
\end{cases}
\end{equation}
In particular, $\ADV(\threshold{l}{n}) = \sqrt{l(n-l+1)}$.

 \label{t:andorspanprogramdef}
Define span programs $P_{\AND}$ and $P_{\OR}$ computing $\AND$ and $\OR$, $\B^2 \rightarrow \B$, respectively, by 
\begin{align}
P_{\AND}: &&
\ket t &= \left( \begin{matrix} \alpha_1 \\ \alpha_2 \end{matrix} \right) ,\; 
&\ket{v_1} &= \left( \begin{matrix} \beta_1 \\ 0 \end{matrix} \right) ,\; &\ket{v_2} &= \left( \begin{matrix} 0 \\ \beta_2 \end{matrix} \right) \\
P_{\OR}: &&
\ket t &= \delta ,\; &\ket{v_1} &= \epsilon_1 ,\;& \ket{v_2} &= \epsilon_2 
\end{align}
for parameters $\alpha_j, \beta_j, \delta, \epsilon_j > 0$, $j \in \{1,2\}$.  
Both span programs have $I_{1,1} = \{1\}$, $I_{2,1} = \{2\}$ and $\Ifree = I_{1,0} = I_{2,0} = \emptyset$.  
Let $\alpha = \sqrt{\alpha_1^2 + \alpha_2^2}$.

 \label{t:andorspanprogramwsize}
With the parameters in \defref{t:andorspanprogramdef} set to 
\begin{align}
\alpha_j &= (s_j / s_p)^{1/4} & \beta_j &= 1 \\
\delta &= 1 & \epsilon_j &= (s_j / s_p)^{1/4}
 \enspace ,
\end{align}
where $s_p = s_1 + s_2$, the span programs $P_{\AND}$ and $P_{\OR}$ satisfy: 
\begin{align}\begin{split}
\wsizexS{P_{\AND}}{x}{(\sqrt{s_1}, \sqrt{s_2})}
&=
\begin{cases}
\sqrt{s_p} & \text{if $x \in \{11, 10, 01\}$} \\
\frac{\sqrt{s_p}}{2} & \text{if $x = 00$}
\end{cases} \\
\wsizexS{P_{\OR}}{x}{(\sqrt{s_1}, \sqrt{s_2})}
&=
\begin{cases}
\sqrt{s_p} & \text{if $x \in \{00, 10, 01\}$} \\
\frac{\sqrt{s_p}}{2} & \text{if $x = 11$}
\end{cases}
\end{split}\end{align}

\label{def:relaxed-prt}
The distributional relaxed partition bound $\bprt^\mu_\eps(f)$ is the
value of the following linear program.  (The value of $z$ ranges over
$\setout$ and $R$ over all rectangles, including the empty rectangle.)
\begin{align}
\bprt_\eps^\mu(f)& =  \min_{\eta,p_{R,z}\geq 0}  \; \frac{1}{\eta}
\quad \text{ subject to:} \nonumber \\
 & \sum_{(x,y)\in \setin}\mu_{x,y}\sum_{R:(x,y)\in R} p_{R,f(x,y)} + \sum_{(x,y)\notin \setin}\mu_{x,y}\sum_{z,R:(x,y)\in R} p_{R,z}\geq (1-\eps)\eta \label{eq:partfirst}\\
& \forall (x,y)\in\calX\times\calY,\quad \sum_{z,R:(x,y)\in R} p_{R,z}
\leq \eta \label{eq:partsecond}\\
&\sum_{R,z} p_{R,z}=1.\label{eq:prt-operational}
\end{align}
