\label{def:proj-tree}
Let $G : \zo^{A\times [w]}\to\zo$ be a DNF over $\calX$,  where we assume a fixed but arbitrary ordering on its terms, and likewise on the literals within each term. The \emph{canonical projection decision tree} $\Tree(G) : \zo^A\to\zo$ associated with $G$ is defined recursively as follows:
\begin{enumerate}
\item If $G \equiv 1$ (i.e.~if $G(X) = 1$ for all $X\in\zo^{A \times [w]}$) output the trivial decision tree $\Tree(G) \equiv 1$, and likewise, if $G \equiv 0$ output $\Tree(G) \equiv 0$.
\item Otherwise, let $T$ be the first term in $G$ such that $T \not\equiv 0$, and let
\[ \eta = \big\{ y_a \colon x_{a,i} \text{ occurs in $T$ for some $i\in [w]$}\big\} \sse \calY \]
\item $\Tree(G)$ queries all the variables in $\eta$ in its first $|\eta|$ levels.
\item For each path $\pi \in \zo^{\eta}$, recurse on $G \uhr (\eta\mapsto\pi)$.
\end{enumerate}

\label{fact:weights}
Fix $\tau \in \{0,1,\ast\}^{A_k}$, and  write $S_a = S_a(\tau)$ to denote $\tau_a^{-1}(\ast) = \{ i \in [w_{k-1}] \colon \tau_{a,i} = \ast\}$.  Then $\Prx_{\brho\leftarrow\calR(\tau)}[\brho = \rho] = \xi(\rho)$ for all $\rho\in \{0,1,\ast\}^{A_k}$, where $\xi : \{0,1,\ast\}^{A_k} \to [0,1]$ is the probability mass function:
\[  \xi(\rho) = \mathop{\prod_{a\in A_{k-1}}}_{S_a \ne \emptyset} \zeta_a(\rho(S_a)), \]
and $\rho(S_a)$ denotes the substring of $\rho_a$ with coordinates in $S_a$, and $\zeta_a : \{0,1,\ast\}^{S_a} \to [0,1]$ is the probability mass function:
\begin{align*}
  \zeta_a(\varrho)
  &=
  \begin{cases}
       \ds
     \lambda
     &\text{if } \varrho = \{1\}^{S_a},\\
     \ds
     q_a \cdot \frac{{t_k}^{|\varrho^{-1}(\ast)|}(1-t_k)^{|\varrho^{-1}(1)|}}{1-(1-t_k)^{|S_a|}}
     &\text{if } \varrho \in \{\ast,1\}^{S_a} \setminus \{1\}^{S_a},\\
     \ds
(1-\lambda-q_a) \cdot  \frac{{t_k}^{|\varrho^{-1}(0)|}(1-t_k)^{|\varrho^{-1}(1)|}}{1-(1-t_k)^{|S_a|}}
     &\text{if } \varrho \in \{0,1\}^{S_a} \setminus \{1\}^{S_a}.
  \end{cases}
\end{align*}

\label{fact:init-weights}
$\Prx_{\brho\leftarrow\calR_\init} [\brho = \rho] = \xi(\rho)$ for all $\rho\in \{0,1,\ast\}^{A_{d-1}\times [m]}$ (recall that $w_{d-1} = m$), where $\xi : \{0,1,\ast\}^{A_{d-1} \times [m]} \to [0,1]$ is the probability mass function:
\[  \xi(\rho) = \prod_{a\in A_{d-1}}\zeta(\rho_a), \]
and $\zeta : \{0,1,\ast\}^{m} \to [0,1]$ is the probability mass function:
\begin{align*}
  \zeta(\varrho)
  &=
  \begin{cases}
       \ds
     \lambda
     &\text{if } \varrho = \{1\}^{m},\\
     \ds
     q \cdot \frac{p}{1-p}
     &\text{if } \varrho \in \{\ast,1\}^{m} \setminus \{1\}^{m},\\
     \ds
(1-\lambda-q) \cdot  \frac{p}{1-p}
     &\text{if } \varrho \in \{0,1\}^{m} \setminus \{1\}^{m}.
  \end{cases}
\end{align*}

\label{thm:different-alternation} For $2\leq d \leq  {\frac {c\sqrt{\log n}}{\log \log n}}$, let $C : \zo^{n} \to \zo$ be a depth-$d$ circuit of size $S \le 2^{{\frac 1 2}n^{{\frac 1 {6(d-1)}}}}$ and unbounded bottom fan-in.
\begin{enumerate}
\item If the top gate of $C$ is an $\AND$, then $\mathbf{\Psi}(C)$ is $(1/S)$-close (with respect to the uniform distribution on $\{0,1\}^n$) to a width-$n^{{\frac 1 {4(d-1)}}}$ CNF with probability $1-\exp\big(-\Omega\big(n^{\frac 1 {{6}(d-1)}}\big)\big)$.
\item If the top gate of $C$ is an $\OR$, then $\mathbf{\Psi}(C)$ is $(1/S)$-close to a width-$n^{{\frac 1 {4(d-1)}}}$ DNF with probability  $1-\exp\big(-\Omega\big(n^{\frac 1 {{6}(d-1)}}\big)\big)$.
\end{enumerate}

\label{lem:combine}
Suppose that $3 \leq d \leq {\frac {c\log w}{\log \log w}}$.
For $2 \le k \le d-1$ and $\ell\in \N$, let $C : \zo^{A_{k+1}} \to\zo$ be a size-$S$ depth-$\ell$ circuit with bottom fan-in $w^{1/5}$.\ignore{ Let $\tau \in \{\bullet,\circ,\ast\}^{A_{k+1}}$ be typical.} For any $\tau \in \{\bullet,\circ,\ast\}^{A_{k+1}}$, with probability at least $1-S\cdot 4^{-w^{1/5}}\ignore{ - e^{-\Omega(w^{1/6})}}$ over $\brho\leftarrow\calR(\tau)$, we have that $\proj_{\brho}\,C$ is a depth-$(\ell-1)$ circuit with  bottom fan-in $w^{1/5}$, and has the same number of gates at distance at least two from the input variables as~$C$.

\label{prop:bounded-bottom-fan-in}
For $2 \leq d \leq {\frac {c\sqrt{\log n}}{\log \log n}}$,
let $C : \zo^{A_{d}} \to \zo$ be a depth-$d$ circuit with bottom fan-in $\frac1{5} m$ and size $S \le 2^{w^{1/5}}$.  Then $\mathbf{\Psi}(C)$ is computed by a depth-$(w^{1/5})$ decision tree with probability $1-e^{-\Omega(w^{1/{5}})}$.

\label{lem:truncate}
Let $C : \zo^n \to \zo$ be a circuit and let $\eps > 0$. There exists a circuit $C' : \zo^n\to\zo$ such that
\begin{enumerate}
