 \label{def:typical}
Let $\tau \in \{\bullet,\circ,\ast\}^{A_k}$ where $2\le k \le d-1$.  We say that $\tau$ is \emph{typical} if it satisfies:
\begin{enumerate}
\item For every $a\in A_{k-1}$ the set $\tau^{-1}_a(\ast) \sse [w_{k-1}]$ is $k$-acceptable, where we recall from Definition~\ref{def:acceptable} that this means
\[ |\tau^{-1}_a(\ast)| = qw \pm w^{\gradual(k,d)} \quad \text{where $\gradual(k,d) := \frac1{3} + \frac{d-k-1}{12d}$}. \] (Note  that $\frac1{3} \le \gradual(k,d) \le \frac{5}{12} < \frac1{2}$ for all $d\in \N$ and $2\le k \le d-1$.) We observe that by Definition \ref{def:lift}, this condition implies that for every $\alpha \in A_{k-2}$, we have
\begin{equation}
\hat{\tau}_\alpha \in \{ \ast, \circ \}^{w_{k-2}}.  \label{eq:old-prop-2-of-typicality}
\end{equation}
\item For every $\alpha \in A_{k-2}$,
\[ |(\hat{\tau}_\alpha)^{-1}(\ast)| \ge w_{k-2}- w^{4/5}. \]
\end{enumerate}
We note that (\ref{eq:old-prop-2-of-typicality}) and Condition (2)  together imply that
\[ \hat{\hat{\tau}}_\alpha  = \ast  \quad \text{for all $\alpha\in A_{k-2}$.} \]

 [Condition (1) of typicality] \label{lemma:condition1-initial}
Fix $a\in A_{d-2}$. Then
\[ \Pr\big[|\btau_a^{-1}(\ast)| = qw \pm  w^{1/3}\big] \ge 1- e^{-{\tilde{\Omega}}(w^{1/6})}. \]

 \label{lemma:condition2-initial}
Fix $\alpha \in A_{d-3}$. Then
\[ \Pr\big[\hat\btau_\alpha \in \{ \ast,1\}^{w_{d-3}} \big] \ge \ignore{1- w e^{-qw} = }1- e^{-{\Omega}(\sqrt{w})}. \]

 \label{lemma:condition3-initial}
Fix $\alpha \in A_{d-3}$.  Then
\[ \Pr\big[|(\hat\btau_\alpha)^{-1}(\ast)| <  w_{d-3}-w^{4/5} \big] \le e^{-\Omega(\sqrt{w})}.\]

\label{lemma:haha}
Fix $2 \le k \le d-2$ and let $\tau \in \{\bullet,\circ,\ast\}^{A_{k+1}}$ be typical.  For each $a\in A_{k-1}$ we write $S_a = S_a(\tau)$ to denote $(\hat\tau_a)^{-1}(\ast)$ (note that this is a subset of $[w]$).  Then for $\brho\leftarrow \calR(\tau)$,  we have that $\hat\brho_a$ (which is a string in $\{\bullet,\circ,\ast\}^{w}$) satisfies:
\[  \left\{
\begin{array}{ll}
 \hat\brho_a = \{\circ\}^{w} & \text{with probability~$\prod_{i\in S_a} (1-\lambda-q_{a,i})$}  \\
 (\hat\brho_a)^{-1}(\bullet) \ne \emptyset & \text{with probability~$1-(1-\lambda)^{|S_a|}$}  \\
 \hat\brho_a \in \{ \circ,\ast\}^{w} \setminus \{\circ\}^{w} & \text{otherwise,}
\end{array}
\right.
\]
 independently for all $a \in A_{k-1}$. (Recall that $\hat\tau_a \in \{\ast,\circ\}^{w} \setminus \{\circ\}^{w}$ for all $a\in A_{k-1}$ since $\tau$ is typical.) This implies that
\[ \hat{\hat\brho}_a = \left\{
\begin{array}{ll}
 \bullet & \text{with probability~$\prod_{i\in S_a} (1-\lambda-q_{a,i})$}  \\
\circ& \text{with probability~$1-(1-\lambda)^{|S_a|}$}  \\
\ast & \text{otherwise}
\end{array}
\right.
\]
 independently for all $a \in A_{k-1}$. (Recall that $\hat{\hat\tau}_a = \ast$ for all $a\in A_{k-1}$ since $\tau$ is typical.)

 [Condition ({2}) of typicality] \label{lemma:condition3-yields}
For $2\le k \le d-2$  let $\tau \in \{ \bullet,\circ,\ast\}^{A_{k+1}}$ be typical and fix $\alpha \in A_{k-2}$. Then
\[ \Prx_{\brho\leftarrow\calR(\tau)}\big[ \big|\big(\hat{\hat\brho}_\alpha\big)^{-1}(\ast)\big| \geq  w_{k-2} - w^{4/5} \big] = 1- e^{-\Omega(\sqrt{w})}.  \]

\label{fact:project-sipser}
For $2\le k \le d$ we have that
\[ \proj\,\BalancedSipser_d^{(k)} \equiv \BalancedSipser_d^{(k-1)}. \]

\label{prop:base-case}
Let $F: \zo^{w_0} \to \zo$ be a width-$r$ CNF and $\tau \in \{0,\ast\}^{w_0} \setminus \{0\}^{w_0}$.    Then for $\bY \leftarrow \{0_{1-{t_1}},1_{t_1}\}^{w_0}$,
\[ \Pr [(\OR_{w_0} \uhr \tau)(\bY) \ne F(\bY)]\big] \ge \bias(\OR_{w_0} \uhr \tau,\bY) - r{t_1}. \]

\label{thm:lch}
The $5$-local Clifford-Hamiltonian problem is \class{QMA}-complete
with respect to Karp reductions. Moreover, for any choice of
promise problem $A = (A_{\yes},A_{\no}) \in \class{QMA}$ and a
polynomially bounded function $p$, there exists a Karp reduction $f$
from $A$ to $5$-LCH having the form
\begin{equation}
  f(x) = \Bigl\langle H_1,\ldots,H_m,1^{p(\abs{x})},1^q\Bigr\rangle
\end{equation}
for every $x\in A_{\yes}\cup A_{\no}$.

Suppose that $S\subseteq\{0,1\}^{\ast}$ is an infinite set of binary strings,
$r$ is a polynomially bounded function, and $\rho_x$ and $\xi_x$ are states on
$r(\abs{x})$ qubits for each $x\in S$.
The collections $\{\rho_x\,:\,x\in S\}$ and
$\{\xi_x\,:\,x\in S\}$ are \emph{statistically indistinguishable} if
\begin{equation}
  \frac{1}{2} \norm{\rho_x - \xi_x}_1 \leq \varepsilon(|x|) \,
\end{equation}
for all $x\in S$, for a negligible function $\varepsilon$.
\label{def_sind_states}

A \emph{quantum computationally secure commitment scheme} for an alphabet
$\Gamma$ is a collection of polynomial-time computable functions
$\{f_n\,:\,n\in\natural\}$ taking the form
\begin{equation}
  f_n:\Gamma\times\{0,1\}^{p(n)} \rightarrow \{0,1\}^{q(n)},
\end{equation}
for polynomially bounded functions $p$ and $q$, such that the following
conditions hold:
\begin{mylist}{\parindent}
\item[1.]
  \emph{Unconditionally binding property.}
  For every choice of $n\in\natural$, $a,b\in\Gamma$, and
  $r,s\in\{0,1\}^{p(n)}$, one has that $f_n(a,r) = f_n(b,s)$ implies $a=b$.
\item[2.]
  \emph{Quantum computationally concealing property.}
  For every $a\in\Gamma$ and $n\in\natural$, define
  \begin{equation}
    \rho_{a,n} = \frac{1}{2^{p(n)}}\sum_{r\in\{0,1\}^{p(n)}}
    \ket{f_n(a,r)}\bra{f_n(a,r)}.
  \end{equation}
  For every choice of $a,b\in\Gamma$ the ensembles
  $\{\rho_{a,n}\,:\,n\in\natural\}$ and $\{\rho_{b,n}\,:\,n\in\natural\}$
  are quantum computationally indistinguishable.
\end{mylist}

Let $P$ and $Q$ be probability distributions over $S$. We define the following distance measures between distributions.
\begin{align*}
\text{Total variation distance:}& \quad \VR(P,Q) \defeq \max_{T \subseteq S}  \sum_{s \in T}\big(P(s) - Q(s)\big) = \frac{1}{2}\sum_{s\in S} |P(s) - Q(s)|.  \\
\text{Hellinger distance:}& \quad \h(P,Q) \defeq 
\frac{1}{\sqrt{2}} \sqrt{\sum_{s \in S}\left(\sqrt{P(s)}-\sqrt{Q(s)}\right)^2 } . 
\end{align*}

\label{fact:relation-inf}
Let $P$ and $Q$ be probability distributions. Then
\begin{align*}
&\quad \frac{1}{\sqrt{2}}\VR(P,Q) \leq \h(P,Q) \leq \sqrt{ \VR(P,Q)}. 
\end{align*}

\label{fact:prod} 
$\VR(P\otimes Q, P' \otimes Q')   \leq  \VR(P, P') + \VR(Q, Q').$
Additionally, if $Q= Q'$ then $\VR(P\otimes Q, P' \otimes Q')  = \VR(P, P')$.

\label{def:entropy}
Let $XYZ \in \X \times \Y \times \Z$ be correlated random variables. We define the following measures, where $\log(\cdot)$ denotes the base $2$ logarithm.
\begin{align*}
\text{Mutual information:}& \quad  \I(X:Y) \defeq \sum_{xy} \Pr(XY=(x,y)) \log \(\frac{\Pr(XY=(x,y))}{\Pr(X=x)\Pr(Y=y)}\) .\\
\text{Conditional mutual information:}& \quad   \I(X:Y~|~Z) \defeq \E_{z\leftarrow Z} \I(X : Y ~|~ Z=z) = \E_{z\leftarrow Z} \I(X^z : Y^z).
\end{align*}

 \label{fact:ID}
Let $XY \in \X \times \Y$ be correlated random variables. Then
$$\I(X:Y) \geq \VR^2(XY,X\otimes Y) \qquad \textrm{and} \qquad \I(X:Y) \geq \E_{x \leftarrow X} \VR^2(Y^x,Y).$$

\label{fact:I2}
	Let $AB$ be correlated random variables with $A \in \B$. Let $p \defeq \Pr(A=0)$,  $B^0 := (B~|~A=0)$, and $B^1 := (B~|~A=1)$. Then
	\[\I(A:B)\leq  2\log e \enspace  \VR(pB^0,(1-p)B^1).\]

 \label{fact:boost}
Let $0 < \delta < \eps < 1/2$. Let $\Pi$ be a protocol for $F$ with $\err(\Pi) \leq \eps$. There exists protocol $\Pi'$ for $F$ such that $\err(\Pi') \leq \delta$ and   
\begin{align*}
\IC(\Pi') \leq O\left(\frac{\log(1/\delta)}{\big(\frac{1}{2}-\eps\big)^2}\cdot  \IC(\Pi)\right) \quad \textrm{and} \quad 
\CC(\Pi') \leq O\left(\frac{\log(1/\delta)}{\big(\frac{1}{2}-\eps\big)^2}\cdot  \CC(\Pi)\right). 
\end{align*}

 \label{fact:indep}
Let $\Pi$ be a communication protocol on input $X \otimes Y$.  Then $X\leftrightarrow \Pi \leftrightarrow Y$ forms a Markov chain, or equivalently, for each $\pi$ in the support of $\Pi$, we have
\[(XY)^\pi  \sim X^\pi \otimes Y^\pi .\]

 \label{fact:pyth} 
Let $(x,y)$ and $(x',y')$ be two inputs to a protocol $\Pi$. Then
$$ \h^2(\Pi(x,y), \Pi(x',y)) +  \h^2(\Pi(x,y'), \Pi(x',y'))  \leq 2 \cdot \h^2(\Pi(x,y), \Pi(x',y')).$$

 \label{clm:lowinf}
Let $F\colon\X \times \Y \rightarrow \{0,1,*\}$ be a partial function and $\mu$ be a distribution over $\dom(F)$. Let $XY \sim \mu$ and define the random variable $F \defeq F(X,Y)$. Let $\Pi$ be a communication protocol with input $(X,Y)$ to Alice and Bob respectively. There exists a communication protocol  $\Pi'$ for $F$, with input $(X,Y)$ to Alice and Bob respectively, such that 
$$\IC^\mu(\Pi') \leq \IC^\mu(\Pi) + 1,\quad \CC(\Pi') = \CC(\Pi) + 1, \quad\text{and}\quad \err^\mu(\Pi') < \frac{1}{2} - \frac{\I(F:\Pi~|~X)}{3} . $$

 \label{clm:biasmu}
Let $F\colon\X \times \Y \rightarrow \{0,1,*\}$ be a partial function and let $\mu$ be a distribution over $\dom(F)$.  Let $\epsilon \in (0,1/2)$ and $c \geq 1$ be a positive integer.    For $i \in [c]$, let $X_iY_i \sim \mu$ be i.i.d.\  and define $L_i \defeq F(X_i,Y_i)$. Define $X \defeq (X_1,\ldots,X_c)$, $Y \defeq (Y_1,\ldots,Y_c)$, and $L \defeq (L_1,\ldots,L_c)$. Then 
either
\begin{enumerate}
\item[(a)] There exists a protocol $\Pi$ for $F$ such that $\CC(\Pi) = 1$, $\IC^\mu(\Pi) \leq 1$, and $\err^\mu(\Pi) \leq \frac{1}{2} - \epsilon$, or
\item[(b)] $\VR(XL, X \otimes W^{\otimes c})  \leq c\epsilon $,
where $W$ is the uniform distribution over $\B$.
\end{enumerate}

\label{thm:lookup_upper}
Let $F\colon \X \times \Y \to \{0,1,*\}$ be a (partial) function and $\mathcal{G}=\{G_0, \ldots, G_{2^c-1}\}$ a 
family of communication functions, where each $G_i \colon (\X^c \times \{0,1\}^m) \times (\Y^c \times \{0,1\}^m) \to \B$.  If 
$\G$ is consistent outside $F$ (\defn{consistency}) then 
\begin{align*}
\Q(F_\G) &=  O(\Q(F) \cdot c \log c) + \max_{i \in [2^c]} O(\Q(G_i)) \\
\Q_E(F_\G) &= \Q_E(F) \cdot c + \max_{i \in [2^c]} \Q_E(G_i)
\end{align*}
where $F_\G$ is the $(F,\G)$-lookup function.

\label{clm:X}
Assume the following conditions hold.
\begin{equation*}
\IC(\Pi) < \delta^2 2^c \tag{\ref{eq:assumption1}}
\end{equation*}
\begin{equation*}
\VR(XL, X \otimes W)  \leq c \delta/3 \tag{\ref{eq:assumption2}}
