 \Pr_{(x,\ell) \leftarrow XL} (\VR((\Pi U_\ell)^{x,\ell} , (\Pi U_\ell)^x  ) > 100  \sqrt{c \delta})\leq 0.01.  \tag{\ref{eq:Y}}
