 \label{thm:lifted-lb}
Let $m \le n$ and let $b \ge t \log n$ for a sufficiently large constant $t$.  Then 
\begin{align*}
\R(\STR\circ \IP_b) = \tOmega(n^{2.5}) \qquad \textrm{and} \qquad 
\R(\pTR_{n,m} \circ \IP_b) = \Omega(nm).
\end{align*}

 \label{thm:junta_deg}
Let $\STR$ and $\pTR_{n,m}$ denote the partial functions defined in \eq{str} and \eq{ptr}. Then
\begin{align*}
\deg_{1/(64\sqrt{n})}(\STR) = \Omega(n^{2.5}) \qquad \textrm{and} \qquad 
