\label{lem:simon_balanced} 
Let $\alpha\coloneqq\sqrt{n}/2$. There exists a pair of distributions $(D_1,D_0)$ where $D_i$ is supported on $\SIMON_n^{-1}(i)$ such that for every conjunction $C$ with $|C|$ literals,
\begin{equation} \label{eq:simon-lb}
\Pr_{z \leftarrow D_0}[C(z)=1] \geq (1- |C|/\alpha)\cdot\Pr_{z \leftarrow D_1}[C(z)=1].
\end{equation}

\label{lem:or_cert}
$\OR_n$ and $\AND_n$ have two-sided $(n/2,n)$ junta certificates.  The negation of $\pOR_n$ 
has a one-sided $(n/2,0)$ junta certificate.

\label{fact:QdtComp}
Let $f : \B^n \rightarrow \{0,1,*\}$ and $g: \B^m \rightarrow \B$.  Then $\Qdt(f \circ g^n) = O(\Qdt(f) \Qdt(g))$ 
and $\QEdt(f \circ g^n) = O(\QEdt(f) \QEdt(g))$.

\label{lem:composition}
For any communication function $F$, the following bounds hold:

\vspace{0.5em}
\centering
\begin{minipage}[t]{0.5\textwidth}
\begin{itemize}[noitemsep]
\item $\N_0(\AND_n \circ F) \leq \N_0(F) + \log n$
\item $\N_1(\AND_n \circ F) \leq n \N_1(F)$
\item $\UN_0(\AND_n \circ F) \leq \UN_0(F)+(n-1)\UN_1(F)$
\item $\UN_1(\AND_n \circ F) \leq n \UN_1(F)$
\end{itemize}
\end{minipage}
\begin{minipage}[t]{0.5\textwidth}
\begin{itemize}[noitemsep]
\item $\N_0(\OR_n\circ F) \leq n \N_0(F)$
\item $\N_1(\OR_n \circ F) \leq \N_1(F) + \log n$
\item $\UN_0(\OR_n \circ F) \leq n\UN_0(F)$
\item $\UN_1(\OR_n \circ F) \leq (n-1)\UN_0(F)+\UN_1(F)$
\end{itemize}
\end{minipage}

\label{cor:tribes-composition}
Let $\TR_{n^2} = \OR_n \circ \AND_n$. For any function $F$, we have:
\begin{itemize}[noitemsep,topsep=5pt]
\item $\N(\TR_{n^2} \circ F) = O(n \N(F)+ n \log n)$
\item $\UN(\TR_{n^2} \circ F) \leq n \UN_0(F) + n^2 \UN_1(F)$
\end{itemize}

\label{cor:MIPS}
Assuming SETH, for all $\eps>0$, no algorithm can preprocess a set of $N$ vectors $p_1,\ldots,p_N \in D \subseteq \{0,1\}^m$ in polynomial time, and subsequently given a query vector $q \in \{0,1\}^m$ can distinguish in $O(N^{1-\eps})$ time between the cases:

\ifFULL

\begin{description}
\item [{Completeness}] there exist $p_i \in D$ such that $\langle p_i, q \rangle \geq s$;
and
\item [{Soundness}] for every $p_i \in D$, $\langle p_i, q \rangle \leq s/2^{(\log{N})^{1-o(1)}}$,
