\label{lem:gcircuit-special}
Let $\mathcal{G} = \{G_{\times 2},G_{1-},G_\phi\}$.
There exists a constant $\gceps > 0$ such that the problem $\gceps$-\gcircuit with gate-types $\mathcal{G}$ is \ppad-complete. Furthermore, \exactgcircuit with gate-types $\mathcal{G}$ is \fixp-complete.

\label{clm:base-gadget}
Let $\gamma_\ell, \gamma_r, \ell, r \in [0,1]$ with $\gamma_\ell, \gamma_r \geq 1/20$, $\gamma_\ell + \gamma_r < 1$ and $\ell < r$.
Consider a base gadget with input bidder $j$ and output bidder $i$, and parameters $(\gamma_\ell, \gamma_r, \ell, r)$. It holds that:
\begin{itemize}
	\item If the input bidder $j$ is almost-valid, then the output bidder $i$ is also almost-valid.
	\item If $\gamma_\ell,\gamma_r \geq 1/3$ and $j$ is almost-valid, then $i$ is valid and
	$$\val[i] = (3\gamma_\ell-1) + 3(1-\gamma_\ell-\gamma_r) \frac{T_{[2+\ell,2+r]}(\alpha_j(1)) - (2+\ell)}{r-\ell} \pm 6\varepsilon.$$
\end{itemize}

\label{clm:projection-gadget}
The projection gadget with input bidder $j$ and output bidder $i$ ensures that:
\begin{itemize}
	\item the output bidder $i$ is valid, and
	\item if the input bidder $j$ is valid, then $\val[i] = \val[j] \pm 18\varepsilon$.
\end{itemize}

\label{clm:mult-2-gadget}
The $G_{\times 2}$ gadget with input bidder $j$ and output bidder $i$ ensures that:
\begin{itemize}
	\item the output bidder $i$ is valid, and
	\item if the input bidder $j$ is valid, then $\val[i] = \trunc(2\cdot \val[j]) \pm 24\varepsilon$.
\end{itemize}

\label{clm:complement-gadget}
The $G_{1-}$ gadget with input bidder $j$ and output bidder $i$ ensures that:
\begin{itemize}
	\item the output bidder $i$ is valid, and
	\item if the input bidder $j$ is valid, then $\val[i] = 1 - \val[j] \pm 60\varepsilon$.
\end{itemize}

\label{clm:phi-gadget}
The $G_\phi$ gadget with input bidders $j_1,j_2$ and output bidder $i$ ensures that:
\begin{itemize}
	\item the output bidder $i$ is valid, and
	\item if the input bidders $j_1$ and $j_2$ are valid, then
	$$\val[i] = \phi(\val[j_1],\val[j_2]) \pm 86\varepsilon = \frac{1}{4}(\val[j_1]+1)(\val[j_2]+1) \pm 86\varepsilon.$$
\end{itemize}

\label{prop:overbidnonmonotone}
Let $\vec{\beta}$ be an exact equilibrium of a FPA. For a bid $b_i$ by player $i$, let $H_i(b_i,\vec{\beta}_{-i})$ denote the (perceived) probability that player $i$ gets the item, given this bid and the bidding strategies by the other players.
Then, strategies will always be no over-bidding and monotone non-decreasing except only possibly when the probability of winning is zero. Formally,  

\begin{enumerate}
    \item let $v_i$ be a valuation by player $i$ and $b_i=\beta_i(v_i)$. If $b_i>v_i$, then $H_i(b_i,\vec{\beta}_{-i})=0$;
    \item let $v_i,v'_i$ be valuations by player $i$ and $b_i=\beta_i(v_i)$, $b'_i=\beta_i(v'_i)$. If $v_i<v'_i$ and $b_i>b'_i$, then $H_i(b_i,\vec{\beta}_{-i})=H_i(b'_i,\vec{\beta}_{-i})=0$.
\end{enumerate}

\label{th:classical-est}
Let $P\in\Real[x]$ be a constant-degree polynomial.
For any constant $\epsilon>0$, there is a $O(\poly(\log N,s))$-time classical algorithm that, given query-access to an $s$-sparse matrix $A\in\Comp^{N\times N}$ with $\norm{A}\le 1$, query-access to a vector $u\in\Comp^N$, and sampling-access to a vector $v\in \Comp^N$, outputs with high probability an estimate of the quantity $v^\dagger P(\sqrt{A^\dagger A})u$ with additive precision~$\epsilon$.

\label{th:SVT}
For any interval $[t_1,t_2]\subseteq [0,1]$, any constant $\theta>0$ and any $s$-sparse matrix $A\in\Comp^{N\times N}$ with $\norm{A}\le 1$ given by query-access, consider the problem of deciding whether
\begin{itemize}
\item[(i)]
$A$ has a singular value in interval $[t_1,t_2]$, or
\item[(ii)]
$A$ has no singular value in interval $(t_1-\theta,t_2+\theta)$.
\end{itemize}
In addition, we are given as input sampling-access to a vector $u\in\Comp^N$, which we are promised in case~$(i)$ satisfies $\norm{\Pi_A^{[t_1,t_2]}u}=\Omega(1)$. Then, there is a $O(\poly(\log N,s))$-time classical algorithm that decides with high probability which of $(i)$ and $(ii)$ holds.

\label{th:qPCP}
Consider problem $\LH(k,a,b)$ with the following additional promise: the ground state of $H$ has constant overlap with a complex vector that has a succinct representation allowing sampling-access.
For any $k=O(\log n)$, any $a,b\in[-1,1]$ such that $b-a=\Omega(1)$, this variant of $\LH(k,a,b)$ is in the complexity class $\MA$.

\label{def:query-access}


We say that we have query-access to a vector $u\in \Comp^{N}$ if there exists an $O(\poly(\log N))$-time classical algorithm $\Qq_u$ that

on input $i\in\{1,\ldots,N\}$, outputs the entry $u_i$.

\label{def:sparsequery}
We say that we have query-access to an $s$-sparse matrix $A\in \Comp^{M\times N}$ if we have access to two $O(\poly(\log MN))$-time classical algorithms $\Qq_A^{\mathrm{row}}$ and $\Qq_A^{\mathrm{col}}$ such that
\begin{itemize}
\item
on input $(i,\ell)\in\{1,\ldots,M\}\times\{1,\ldots,s\}$, the algorithm $\Qq_A^{\mathrm{row}}$ outputs the $\ell$-th non-zero entry of the $i$-th row of $A$ if this row has at least $\ell$ non-zero entries, and outputs an error message otherwise;
\item
on input $(j,\ell)\in\{1,\ldots,N\}\times\{1,\ldots,s\}$, the algorithm $\Qq_A^{\mathrm{col}}$ outputs the $\ell$-th non-zero entry of the $j$-th column of $A$ if this column has at least $\ell$ non-zero entries, and outputs an error message otherwise.
\end{itemize}

\label{def:sample}
For a parameter $\zeta\in[0,1)$, we say that we have $\zeta$-sampling-access to a vector $u\in \Comp^{N}$ if the following three conditions are satisfied:
\begin{itemize}
\item[(i)]
we have access to an $O(\poly(\log N))$-time classical algorithm $\Qq_u$ that on input $i\in\{1,\ldots,N\}$, outputs the entry $u_i$;
\item[(ii)]
we have access to an $O(\poly(\log N))$-time classical algorithm $\Sq_u$ that samples from a probability distribution $p\colon\{1,\ldots,N\}\to [0,1]$ such that
\[
p(j)\in\left[(1-\zeta)\frac{|u_j|^2}{\norm{u}^2},(1+\zeta)\frac{|u_j|^2}{\norm{u}^2}\right]
\]
for all $j\in\{1,\ldots,N\}$;




\item[(iii)]
we are given a real number $m$ satisfying $|m-\norm{u}|\le \zeta \norm{u}$.
\end{itemize}

We simply say that we have sampling-access to $u$ (without specifying $\zeta$) if we have $0$-sampling-access.

