\label{fac:tracefidelityequi}
For quantum states $\rho$ and $\sigma$, it holds that
\[2(1-\fidelity{\rho}{\sigma})=2h^2\br{\rho,\sigma}\leq\onenorm{\rho-\sigma}\leq2\sqrt{1-\fidelity{\rho}{\sigma}^2}.\]
For pure states $\ket{\phi}$ and $\ket{\psi}$, we have
\begin{align*}
\onenorm{\ketbra{\phi} - \ketbra{\psi}}
&= \sqrt{1 - \fidelity{\ketbra{\phi}}{\ketbra{\psi}}^2} \\
&= \sqrt{1 - |\langle\phi|\psi\rangle|^2}.
\end{align*}

\label{fac:monotonequantumoperation}
For states $\rho$, $\sigma$, and quantum operation $\E(\cdot)$, it holds that
\begin{align*}
\onenorm{\E(\rho) - \E(\sigma)} &\leq \onenorm{\rho - \sigma}
\intertext{and}
\fidelity{\E(\rho)}{\E(\sigma)}&\geq \fidelity{\rho}{\sigma} .
\end{align*}
In particular, for any bipartite states $\rho_{AB}$ and $\sigma_{AB}$, it holds that
\[\onenorm{\rho_{AB}-\sigma_{AB}}\geq\onenorm{\rho_A-\sigma_A}, \fidelity{\rho_{AB}}{\sigma_{AB}}\leq\fidelity{\rho_A}{\sigma_A}~\mbox{and}~ h\br{\rho_{AB},\sigma_{AB}}\geq h\br{\rho_A,\sigma_A}.\]

\label{fac:jointlylinearity}
	Given bipartite states $\rho_{AB}=\sum_{i}p_i\ketbra{i}\otimes\rho_i$ and $\sigma_{AB}=\sum_iq_i\ketbra{i}\otimes\sigma_i$, where $\set{p_i}_i$ and $\set{q_i}_i$ are distributions, it holds that
	\[\fidelity{\rho_{AB}}{\sigma_{AB}}=\sum_i\sqrt{p_iq_i}~\fidelity{\rho_i}{\sigma_i}.\]

\label{def:entropy}
The {\em entropy} of a quantum state $\rho$ (in register $X$) is defined as $\mathrm{S}(\rho) \defeq - \Tr\rho\log\rho.$
We also let $\mathrm{S}\br{X}_{\rho}$ represent $\mathrm{S}(\rho)$.

\label{def:mutual entropy}
Let $\rho_{XY}$ be a quantum state in space $\H_X\otimes\H_Y$. The {\em mutual information} between registers $X$ and $Y$ is defined to be
\begin{align*}
\mutinf{X}{Y}_{\rho} &\defeq
\mathrm{S}\br{X}_{\rho}+\mathrm{S}\br{Y}_{\rho}-\mathrm{S}\br{XY}_{\rho}.
\end{align*}

\label{fac:arakilieb}\cite{ArakiL:1970}
	Given a bipartite state $\rho_{AB}$, it holds that
	\[\abs{\mathrm{S}\br{A}_{\rho}-\mathrm{S}\br{B}_{\rho}}\leq\mathrm{S}\br{AB}_{\rho}\leq\mathrm{S}\br{A}_{\rho}+\mathrm{S}\br{B}_{\rho}.\]

\label{fact:pinkser}
For quantum states $\rho$ and $\sigma$, it holds that
\[ \onenorm{\rho-\sigma} \leq \sqrt{\relent{\rho}{\sigma}} \quad \text{ and } \quad  1-\fidelity{\rho}{\sigma}=h^2\br{\rho,\sigma}\leq\relent{\rho}{\sigma} . \]

\label{lem:boundoncmi}
	Given a tripartite state $\rho_{ABC}$, it holds that
	$\condmutinf{A}{B}{C}_{\rho}\leq 2|B|.$

\label{lem:decoupling}
	Consider a tripartite pure state $\ket{\psi}_{ABC}$ which satisfies $\mutinf{A}{C}\leq\epsilon$. Then for any purifications $\ket{\psi_1}_{AB_1}$ and $\ket{\psi_2}_{B_2C}$ of $\psi_A$ and $\psi_C$,respectively, there exists an isometry $U$ mapping $\H_B$ to $\H_{B_1}\otimes\H_{B_2}$ such that
	\[\abs{\bra{\psi_1}\bra{\psi_2}\br{\id_{AC}\otimes U_B}\ket{\psi}}\geq1-\epsilon.\]
	Combining with Fact~\ref{fac:tracefidelityequi}
	we have
	\[h\br{\br{\id_{AC}\otimes U_B}\psi\br{\id_{AC}\otimes U^{\dagger}_B},\psi_1\otimes\psi_2}\leq\sqrt{\epsilon}.\]

For a protocol $\Pi$ and an input distribution $\mu$,
we define the {\em quantum communication cost} (QCC) and \emph{quantum information cost} (QIC) of $\Pi$ on input $\mu $ as
\begin{align*}
QCC (\Pi, \mu) &\defeq \sum_i |C_i|,
\end{align*}
and
\begin{align*}
	QIC (\Pi, \rho) &\defeq \sum_{i \geq 1,\ odd} \condmutinf{C_i}{ R_X R_Y}{ B_{i}} + \sum_{i \geq 1,\ even}  \condmutinf{C_i}{ R_X R_Y}{A_{i}},
\end{align*}
respectively.
For any function $f$, any input distribution $\mu$,  and any $\epsilon>0$,
\begin{align}\label{eq:defQCC}
QCC (f, \mu, \epsilon) \defeq \inf_{\Pi} QCC (\Pi, \mu),
\end{align}
and
	\begin{align}\label{eq:defQIComplexity}
		QIC (f, \mu, \epsilon) \defeq \inf_{\Pi} QIC (\Pi, \mu),
	\end{align}
	where the infimum is over the protocols $\Pi$ computing $f$ with error $\epsilon$ w.r.t $\mu$.

