 \label{prop:ls}
The dual block composition satisfies the following properties:
\paragraph{\emph{Preservation of $\ell_1$-norm}:} If $\|\Psi\|_1 = 1$, $\|\psi\|_1 = 1$, and $\langle \psi, \mathbf{1}\rangle = 0$, then
\begin{equation}\|\Psi \ls \psi\|_1 = 1. \label{eqn:ls-norm}\end{equation}

\paragraph{\emph{Multiplicativity of pure high degree}:} If $\langle \Psi, P \rangle = 0$ for every polynomial $P \colon \bits^M \to \bits$ of degree less than  $D$, and $\langle \psi, p \rangle = 0$ for every polynomial $p \colon \bits^m \to \bits$ of degree less than $d$, then
for every polynomial $q \colon \bits^{m \cdot M} \to \bits$,
\begin{equation}\deg q < D \cdot d \implies \langle \Psi \ls \psi, q \rangle = 0. \label{eqn:ls-phd} \end{equation}

\paragraph{\emph{Associativity}:} For every $\zeta: \bits^{m_\zeta} \to \R$, $\varphi: \bits^{m_\varphi} \to \R$, and $\psi: \bits^{m_\psi} \to \R$, we have
\begin{equation} (\zeta \ls \varphi) \ls \psi = \zeta \ls (\varphi \ls \psi). \label{eqn:ls-assoc} \end{equation}

Let $M \in \N$ and $\alpha, \beta > 0$. A function $\omega: [M]_0 \to \R$ satisfies the $(\alpha, \beta)$-decay condition if
\begin{align}
&\sum_{t = 0}^M \omega(t) = 0, \label{eqn:omega-balanced}\\
&\sum_{t = 0}^M |\omega(t)| = 1, \label{eqn:omega-norm}\\
&|\omega(t)| \le \alpha \exp (-\beta t) / t^2 \quad \forall t = 1, 2, \dots, M. \label{eqn:omega-decay}
\end{align}

{proposition}{btzeroing} \label{prop:btzeroing}
Let $R \in \N$ be sufficiently large, and let $\Phi : \bits^R \to \R$ with $\|\Phi\|_1 = 1$. For $M \le R$, let $\omega : [M]_0 \to \R$ satisfy the $(\alpha, \beta)$-decay condition with parameters $1 \leq \alpha \le R^2, \beta \in (4\ln^2 R/ \sqrt{\alpha} R, 1)$.

Let $N = \lceil 20 \sqrt{\alpha} \rceil R$, and define $\psi: \bits^N \to \R$ by $\psi(x) = \omega(|x|) / \binom{N}{|x|}$. If $D < N$ is such that
\begin{equation}
\text{ For every polynomial } p \text{ with } \deg p < D, \text{ we have } \langle \Phi \ls \psi, p \rangle = 0, \label{eqn:prelim-phd}
\end{equation}
then there exist $\Delta \ge \beta\sqrt{\alpha} R / 4\ln^2 R$ and a function $\zeta: (\bits^N)^R \to \R$ such that
\begin{align}& \text{ For every polynomial } p \text{ with } \deg p < \min\{D, \Delta\}, \text{ we have } \langle \zeta, p \rangle = 0, \label{eqn:final-phd} \\
&\|\zeta - \Phi \ls \psi\|_1 \le \frac{2}{9}, \label{eqn:final-corr} \\
&\|\zeta\|_1 = 1, \label{eqn:final-norm}\\
&\zeta \text{ is supported on } H^{N \cdot R}_{\le N}. \label{eqn:final-support}
\end{align}

 \label{prop:prelim-mass}
Let $\Phi : \bits^R \to \R$ and $\psi : \bits^n \to \R$ satisfy the conditions of \Cref{prop:btzeroing}. Then for sufficiently large $R$, there exists $\Delta \ge \beta \sqrt{\alpha} R / 4\ln^2 R$ such that, for $N = \lceil 20 \sqrt{\alpha} \rceil R$,
\begin{equation}
\sum_{x \notin H_{\le N}^{N \cdot R}} |(\Phi \ls \psi)(x)| \le (2NR)^{-2\Delta}. \label{eqn:prelim-mass}
\end{equation}

{lemma}{combinatorial} \label{lem:combinatorial}
Let $\alpha \le R^2$, let $\beta \in (4\ln^2 R/ \sqrt{\alpha} R, 1)$, and let $R$ be sufficiently large. Let $N = \lceil 20 \sqrt{\alpha}\rceil R$. Let $\eta_i :[M]_0 \to \R$, for $i = 1, \dots R$, be a sequence of non-negative functions where for every $i$,
\begin{align}&\sum_{r = 0}^M \eta_i(r) \le 1 / 2     \label{eqn:eta-bound} \\
&\eta_i(r) \le \alpha \exp(-\beta r) / r^2  \qquad \forall r = 1, \dots, M.     \label{eqn:eta-decay} 
\end{align}
Let $P = \{\vec{t} = (t_1, \dots, t_R) \in [M]_0^R : t_1 + \dots + t_R > N\}$. Then
\[\sum_{\vec{t} \in P} \prod_{i = 1}^R  \eta_i(t_i) \le 2^{-R} \cdot (2NR)^{-2\Delta}\]
where $\Delta \ge \beta\sqrt{\alpha} R / 4\ln^2 R$.

