& \sum_{\omega(t) < 0, t < k} |\omega(t)| \le \left(\frac{1}{2} - \frac{2}{4^k}\right)\label{eqn:thr-sym-neg-corr} \\
& \|\omega\|_1 := \sum_{t = 0}^{T} |\omega(t)| = 1 \label{eqn:thr-sym-norm} \\
& \text{For all univariate polynomials } q \colon \R \to \R\text{, } \notag \\
& \deg p < c_1\sqrt{k^{-1} \cdot T \cdot N^{-1/k}} \implies \sum_{t=0}^T \omega(t) \cdot q(t) = 0 \label{eqn:thr-sym-phd} \\
&  |\omega(t)| \le \frac{(2k)^k \exp(-c_2 t / \sqrt{k \cdot T \cdot N^{1/k}})}{t^2} \qquad \forall t = 1, 2, \dots, T.\label{eqn:thr-sym-decay}
\end{align}

 \label{prop:thr-dual}
Let $k, T, N\in \N$ with $k \le T \le N$. Define $\psi : \bits^N \to \R$ by $\psi(x) = \omega(|x|) / \binom{N}{ |x|}$ for $x \in H_{\le T}^N$ and $\psi(x) = 0$ otherwise, where $\omega$ is as constructed in \Cref{prop:thr-sym-dual}. Then
\begin{align}
&\sum_{x \in E_+(\psi, \THR^k_N)} |\psi(x)| \le \frac{1}{48  N}  \label{eqn:thr-pos-corr}\\
&\sum_{x \in E_-(\psi, \THR^k_N)} |\psi(x)| \le \frac{1}{2} - \frac{2}{4^k}  \label{eqn:thr-neg-corr} \\
&\|\psi\|_1 = 1   \label{eqn:thr-norm} \\
&\text{For any polynomial } p \colon \bits^N \to \R\text{, } \deg p < c_1 \sqrt{k^{-1} \cdot T \cdot N^{-1/k}} \implies \langle \psi, p \rangle = 0 \label{eqn:thr-phd} \\
&\sum_{|x| = t} |\psi(x)| \le (2k)^k \exp(-c_2 t / \sqrt{k \cdot T \cdot N^{1/k}})/t^2 \qquad \forall t = 1, 2, \dots, N.\label{eqn:thr-decay}
\end{align}

{proposition}{erroramp} \label{prop:error-amp}
Let $f : \bits^m \to \bits$ and $\psi : \bits^m \to \R$ be functions such that
\begin{align} &\sum_{x \in E_+(\psi, f)} |\psi(x)| \le \delta^+ \label{eqn:error-base-pos} \\
& \sum_{x \in E_-(\psi, f)} |\psi(x)| \le \delta^- \label{eqn:error-base-neg} \\
& \|\psi\|_1 = 1.\label{eqn:error-base-norm}
\end{align}
For every $M \in \N$, there exists a function $\varphi : \bits^M \to \bits$ with $\|\varphi\|_1 = 1$ and pure high degree $1$ such that
\begin{align} & \sum_{x \in E_+(\varphi \ls \psi, \OR_M \circ f)} |(\varphi \ls \psi)(x)| \le M \cdot \delta^+ \label{eqn:error-amp-pos} \\
& \sum_{x \in E_-(\varphi \ls \psi, \OR_M \circ f)} |(\varphi \ls \psi)(x)| \le  \frac{1}{2} \cdot (2\delta^-)^M.\label{eqn:error-amp-neg}
\end{align}

{proposition}{degreeamp} \label{prop:degree-amp}
Let $f : \bits^m \to \bits$ and $\psi : \bits^m \to \R$ be functions such that
\begin{align} & \sum_{x \in E_+(\psi, f)} |\psi(x)| \le \delta^+ \label{eqn:deg-base-pos} \\
& \sum_{x \in E_-(\psi, f)} |\psi(x)| \le \delta^- \label{eqn:deg-base-neg} \\
& \|\psi\|_1 = 1 \label{eqn:deg-base-norm}
\end{align}
For every $M \in \N$ there exists a function $\rho : \bits^M \to \R$ with $\|\rho\|_1 = 1$ and pure high degree $\Omega(\sqrt{M})$ such that
\begin{equation}
\langle \rho \ls \psi, \OR_M \circ f \rangle \ge \frac{9}{10} - 4  M \delta^+ - 4\delta^-. \label{eqn:deg-amp-corr}
\end{equation}

 \label{prop:dist-prelim}
Let $k, T, N, R \in \N$ with $k \le T \le R \le N$ and $R$ divisible by $4^k$. Let $\psi : \bits^N \to \R$ be a function with $\|\psi\|_1 = 1$ and
\begin{align*}
&\sum_{x \in E_+(\psi, \THR^k_N)} |\psi(x)| \le \frac{1}{48 N} \\
&\sum_{x \in E_-(\psi, \THR^k_N)} |\psi(x)| \le \frac{1}{2} - \frac{2}{4^k}. 
\end{align*}
Then there exists a function $\Phi : \bits^R \to \R$ with $\|\Phi\|_1 = 1$ and pure high degree $\Omega(2^{-k} \sqrt{R})$ such that
