\label{lem:exp_gap}
Suppose that for some constants $p \ge 1$, $\eps \in (0,1/2)$, and $\beta > 1$, the following holds. For every sufficiently large integer $n$, there exists a lattice $\lat_n \subset \R^{d_n}$ with $\rank(\lat_n) = n$ and $d_n \le \poly(n)$, target $\vec{t}_n \in \R^{d_n}$, and radius $r_n > 0$ such that
		\begin{equation}
		\label{eq:more_close_than_short}
		N_p(\lat_n, (1-\eps)^{1/p} \cdot r_n, \vec{t}_n) \geq \beta^n \cdot N_p(\lat_n, r_n, \vec0)
		\; .
		\end{equation}
		Then, for any constants $C \geq 1$ and $\eta \in (2\eps^2,1)$, there exist constants $\gamma > 1$, $C^\dagger > 0$ such that the following holds. 
		\begin{enumerate}
			\item \label{item:non-uniform} For any sufficiently large integers $m$ and $d$ satisfying $m/C \leq d \leq C d$, there exist distances $r, s > 0$ and $\vec{t}^\dagger \in \R^{d_{n^\dagger}}$ for $n^\dagger := \ceil{C^\dagger m}$
			such that 
			\begin{equation}
			\label{eq:good_gadget}
			N_p(\Z^m, r^*, \vec0) \cdot \big(N_p(\cL^\dagger, r^*, \vec0) 
			+ (r^*/s) \cdot D_{p}(\lat^\dagger, ((r^*)^p - d)^{1/p}) \big) < 2^{-m} \cdot N_p(\cL^\dagger, (r^p - \eta d)^{1/p}, \vec{t}^\dagger)
			\; ,
			\end{equation}
			where $r^* := \gamma (r^p + s^p)^{1/p}$ and $\lat^\dagger := \alpha \lat_{n^\dagger}$ for some $\alpha > 0$.
			\item \label{item:uniform}  If we also have 
			\begin{equation}
			\label{eq:target_not_dumb}
			N_p(\lat_n, (1-\eps)^{1/p}r_n, \vec{t}_n) \geq  \beta^n \cdot D_p(\lat_n, (1-\eps/\sqrt{\eta})^{1/p}r_n)
			\; ,
			\end{equation}
			 then we can take $r = (1-\eps/2)^{1/p}\alpha r_{n^\dagger}$, $\vec{t}^\dagger = \alpha \vec{t}_{n^\dagger}$, $s = 1$, and $\alpha = (2\eta d/(\eps r_{n^\dagger}^p))^{1/p}$.
		\end{enumerate}

\label{cor:gadget_to_hardness}
Suppose that for some constants $p \ge 1$, $\eps \in (0,1/2)$, and $\beta > 1$, the following holds. For every sufficiently large integer $n$, there exists a lattice $\lat_n \subset \R^{d_n}$ with $\rank(\lat_n) = n$ and $d_n \le \poly(n)$, target $\vec{t}_n \in \R^{d_n}$, and radius $r_n > 0$ such that
		\begin{equation}
		\label{eq:more_close_than_short_corollary}
		N_p(\lat_n, (1-\eps)^{1/p} \cdot r_n, \vec{t}_n) \geq \beta^n \cdot N_p(\lat_n, r_n, \vec{0})
		\; .
		\end{equation}
Then for any constant $C \geq 1$ and $\eta \in (0,1)$, there is a constant $\gamma > 1$, such that there is an efficient (non-uniform) reduction from from Gap-$3$-$\SAT_{\eta}^{\le C}$ on $n$ variables to $\SVP_{p, \gamma}$ on a lattice of rank $O(n)$ and dimension $O(n)+d_{O(n)}$, for some constant $\gamma > 1$.

Furthermore, if $\lat_n$, $\vec{t}_n$, and $r_n$ are computable in time $\poly(n)$ and	for any constant $\delta \in (\eps, 1)$, there exists a $\beta' > 1$ such that
\begin{equation}
\label{eq:target_not_dumb_corollary}
N_p(\lat_n, (1-\eps)^{1/p}r_n, \vec{t}_n) \geq  (\beta')^n \cdot D_p(\lat_n, (1-\eps/\delta)^{1/p}r_n)
\; ,
\end{equation}
then we may replace the non-uniform reduction with a randomized reduction.

\label{cor:Gap3SAT_to_SVP}
For any constants $p > 2$ and $C' \geq 1$,  there exists a constant $\gamma > 1$ such that there is an efficient (randomized) reduction from Gap-$3$-$\SAT_{\eta'}^{\le C'}$ on $n$ variables to $\SVP_{p, \gamma}$ on a lattice of rank and dimension $O(n)$

In particular, for some constant $\gamma > 1$, there is no $2^{o(n)}$-time algorithm for $\SVP_{p, \gamma}$ unless (randomized) Gap-ETH is false.

\label{thm:kissing_gives_hardness}
Suppose that for some constants $\beta,\alpha > 1$, the following holds. For every sufficiently large integer $n$, there exists a lattice $\lat_n \subset \R^n$, radii $0 < r_n \leq r_n' \leq \alpha r_n$, and a target $\vec{t}_n \in \R^n$  such that
\begin{equation}
\label{eq:kissing}
	N_2(\lat_n, r_n', \vec{t}_n) \geq  \beta^n \cdot (r_n'/r_n)^n \cdot N_2(\lat_n, r_n, \vec0)
	\; .
\end{equation}
Then for any constant $C \geq 1$ and $\eta \in (0,1)$, there is an efficient (non-uniform) reduction from from Gap-$3$-$\SAT_{\eta}^{\le C}$ on $n$ variables to $\SVP_{2, \gamma}$ on a lattice of rank and dimension $O(n)$, for some constant $\gamma > 1$.

In particular, if such a family of lattices and radii exists, then for some constant $\gamma > 1$, there is no $2^{o(n)}$-time algorithm for $\SVP_{2,\gamma}$ unless (non-uniform) Gap-ETH is false.

\label{thm:lb-3sum}
	For every \emph{non-adaptive} algorithm that uses space $S$ and query time $T$
	and solves $\SUMInd$, it holds that $S=\widetilde{\Omega}(N^{1+1/T})$.

	\label{prop:nu-ro}
	With probability at least $1-\frac{1}{N}$ over the choice of a random
	oracle $R:\zo^n\to\zo^n$, for all oracle circuits $C$ of size at most $T$:
\begin{displaymath}
	\Pr_{x\gets\zo^n}\bigg[
		C^{R}\big(R(x)\big)\in R^{-1}\big(R(x)\big)\bigg]
	\in \widetilde{O}\left(\frac{T^2}{N}\right) \ .
\end{displaymath}

	\label{prop:u-ro}
	Let $\cA$ be a uniform oracle Turing machine whose number of oracle queries
	is $T:\zo^n\to\NN$. For all $n\in\NN$ and $S\in\NN$, with probability at least
	$1-\frac{1}{N}$ over the choice of a random oracle $R:\zo^n\to\zo^n$:
\begin{displaymath}
	\forall\, P\in\zo^S,\;
	\Pr_{x\gets\zo^n}\bigg[
		\cA^{R,P}\big(R(x)\big)\in R^{-1}\big(R(x)\big)\bigg]
