\label{def:iter}
		\iter/:

		\noindent\textbf{Input}: Boolean circuit $C : [2^n] \to [2^n]$ with $C(1) > 1$.

		\noindent\textbf{Goal}: Find $v$ such that either
		\begin{itemize}
			\item $C(v) < v$, or
			\item $C(v) > v$ and $C(C(v)) = C(v)$.
		\end{itemize}

\label{def:clo}
		\clo/:

		\noindent\textbf{Input}:
		\begin{itemize}
			\item precision/stopping parameter $\varepsilon > 0$,
			\item well-behaved arithmetic circuits $p: [0,1]^n \to [0,1]$ and $g: [0,1]^n \to [0,1]^n$,
			\item Lipschitz constant $L > 0$.
		\end{itemize}

		\noindent\textbf{Goal}: Compute an approximate local optimum of $p$ with respect to $g$. Formally, find $x \in [0,1]^n$ such that
		$$p(g(x)) \geq p(x) - \varepsilon.$$
		Alternatively, we also accept one of the following violations as a solution:
		\begin{itemize}
			\item ($p$ is not $L$-Lipschitz) $x,y \in [0,1]^n$ such that $|p(x) - p(y)| > L \|x-y\|$,
			\item ($g$ is not $L$-Lipschitz) $x,y \in [0,1]^n$ such that $\|g(x) - g(y)\| > L \|x-y\|$.
		\end{itemize}

\label{def:gclo}
		\gclo/:

		\noindent\textbf{Input}:
		\begin{itemize}
			\item precision/stopping parameter $\varepsilon > 0$,
			\item $(A,b) \in \mathbb{R}^{m \times n} \times \mathbb{R}^m$ defining a bounded non-empty domain $D = \{x \in \mathbb{R}^n: Ax \leq b\}$,
			\item well-behaved arithmetic circuits $p: \mathbb{R}^n \to \mathbb{R}$ and $g: \mathbb{R}^n \to \mathbb{R}^n$,
			\item Lipschitz constant $L > 0$.
		\end{itemize}

		\noindent\textbf{Goal}: Compute an approximate local optimum of $p$ with respect to $g$ on domain $D$. Formally, find $x \in D$ such that
		$$p\bigl(\Pi_D(g(x))\bigr) \geq p(x) - \varepsilon.$$
		Alternatively, we also accept one of the following violations as a solution:
		\begin{itemize}
			\item ($p$ is not $L$-Lipschitz) $x,y \in D$ such that $|p(x) - p(y)| > L \|x-y\|$,
			\item ($g$ is not $L$-Lipschitz) $x,y \in D$ such that $\|g(x) - g(y)\| > L \|x-y\|$.
		\end{itemize}

\label{lem:taylor}
	Let $f: \mathbb{R}^n \to \mathbb{R}$ be continuously differentiable and let $D \subseteq \mathbb{R}^n$ be convex. If $\nabla f$ is $L$-Lipschitz-continuous (w.r.t.\ the $\ell_2$-norm) on $D$, then for all $x,y \in D$ we have
	$$\bigl|f(y) - f(x) - \langle \nabla f(x), y-x \rangle \bigr| \leq \frac{L}{2} \|y-x\|^2.$$

\label{lem:kkt-function-properties}
	The function $f: \mathbb{R}^2 \to \mathbb{R}$ we obtain by bicubic interpolation has the following properties:
	\begin{itemize}
		\item It is continuously differentiable on $\mathbb{R}^2$;
		\item $f$ and its gradient $\nabla f$ are Lipschitz-continuous on $[0,N]^2$ with Lipschitz-constant $L = 2^{18} N$;
		\item Well-behaved arithmetic circuits computing $f$ and $\nabla f$ can be constructed in polynomial time (in the size of the circuits $S,P$ and $C$).
	\end{itemize}

\label{lem:kkt-correct-solutions}
	Let $\varepsilon = 0.01$. We have that $(x, y)$ is an $\varepsilon$-KKT point of
	$f$ on the domain $[0,N]^2$ only if $(x,y)$ lies in a ``solution region'', namely:
	\begin{itemize}
		\item $(x,y)$ lies in a big square $B(v,v)$, such that $v \in [2^n] \setminus \{1\}$ is a source or sink of the \eol/ instance $S,P$, or
		\item $(x,y)$ lies in a medium square $M(u,u)$ of some PLS-Labyrinth gadget, such that $u \in [2^m]$ is a solution to the \iter/ instance $C$, i.e., $C(u)>u$ and $C(C(u))=C(u)$.
	\end{itemize}

\label{lem:projection-lemma}
	Let $D$ be a non-empty closed convex set in $\mathbb{R}^n$ and let $y \in \mathbb{R}^n$. Then for all $x \in D$ it holds that
	$$\langle y - \Pi_D(y), x - \Pi_D(y) \rangle \leq 0.$$

\label{lem:new-farkas}
	Let $A \in \mathbb{R}^{m \times n}$, $b \in \mathbb{R}^n$ and $\varepsilon \geq 0$. Then exactly one of the following two statements holds:
	\begin{enumerate}
		\item $\exists x \in \mathbb{R}^n: Ax \leq 0$, $\langle b, x \rangle > \varepsilon \|x\|$,
		\item $\exists y \in \mathbb{R}^m: \|A^Ty - b\| \leq \varepsilon$, $y \geq 0$.
	\end{enumerate}

\label{thm:lin-circuit-simple}
	Given a well-behaved arithmetic circuit $f: [0,1]^n \to \mathbb{R}^d$, a purported Lipschitz constant $L > 0$, and a precision parameter $\varepsilon > 0$, in polynomial time in $\sz(f)$, $\log L$ and $\log (1/\varepsilon)$, we can construct a linear arithmetic circuit $F: [0,1]^n \to \mathbb{R}^d$ such that for any $x \in [0,1]^n$ it holds that:
	\begin{itemize}
		\item $\|f(x)-F(x)\|_\infty \leq \varepsilon$, or
		\item given $x$, we can efficiently compute $y \in [0,1]^n$ such that
		$$\|f(x)-f(y)\|_\infty > L \|x-y\|_\infty.$$
	\end{itemize}
	Here ``efficiently'' means in polynomial time in $\sz(x)$, $\sz(f)$, $\log L$ and $\log(1/\varepsilon)$.

\label{thm:lin-circuit-general}
	Let $\mathcal{F}$ be a polynomially-approximately-computable class of functions. Given $f \in \mathcal{F}$ where $f: [0,1]^n \to \mathbb{R}^d$, $L > 0$ and $\varepsilon > 0$, in polynomial time in $\sz(f)$, $\log L$ and $\log(1/\varepsilon)$, we can construct a linear arithmetic circuit $F: [0,1]^n \to \mathbb{R}^d$ such that for any $x \in [0,1]^n$ it holds that:
	\begin{itemize}
		\item $\|f(x)-F(x)\|_\infty \leq \varepsilon$, or
		\item given $x$, we can efficiently compute $y \in [0,1]^n$ such that
		$$\|f(x)-f(y)\|_\infty > L \|x-y\|_\infty + \varepsilon/2.$$
	\end{itemize}
	Here ``efficiently'' means in polynomial time in $\sz(x)$, $\sz(f)$, $\log L$ and $\log(1/\varepsilon)$.

\label{lem:lin-circuit-approx}
	Assume that we are given a Boolean circuit $C : \{0,1\}^{kn} \to \{0,1\}^m$, interpreted as a function $C: [N]^n \to [2^m]$, where $N=2^k$. Then, in polynomial time in $\sz(C)$, we can construct a linear arithmetic circuit $F: [0,1]^n \to \mathbb{R}$ such that for all $x \in [0,1]^n$
	$$F(x) \in \left[ \min_{p \in S(x)} C(p), \max_{p \in S(x)} C(p) \right]$$
	where $S(x) \subseteq [N]^n$ is such that
	\begin{enumerate}
		\item $|S(x)| \leq n+1$,
		\item $\|x - \widehat{p}\|_\infty \leq 1/N$ for all $p \in S(x)$, and
		\item $S(x)$ can be computed in polynomial time in $\sz(x)$ and $\log N$.
	\end{enumerate}

Let $\mathcal{H}$ be a Hilbert space. For any two pure states $\ket{\psi},\ket{\phi}\in \mathcal{H}$, we define
\begin{itemize}
    \item (Fidelity) $F(\ket{\psi}, \ket{\phi}) := |\ipro{\psi}{\phi}|$;
    \item (Two-norm distance) $\|\ket{\psi} - \ket{\phi}\|$.
\end{itemize}

Let $\mathcal{H}$ be a Hilbert space. For any two mixed states $\rho,\rho'\in \mathcal{H}$, 
\begin{itemize}
    \item (Fidelity) $F(\rho,\rho') := tr(\sqrt{\sqrt{\rho} \rho'\sqrt{\rho}})$. 
    \item (Trace distance) $TD(\rho,\rho'):=\frac{1}{2} \Tr|\rho - \rho'|$. 
    \item (Bures distance) $B(\rho,\rho') := \sqrt{2-2F(\rho,\rho')}$.
\end{itemize}

\label{def:d_qc}
A $\class{QNC_d}$ quantum circuit family $\{C_n: n>0\}$ is defined as below: 
\begin{itemize}
    \item There exists a polynomial $p$ such that for all $n>0$, $C_n$ operates on $n$ input qubits and $p(n)$ ancilla qubits; 
    \item for $n>0$, $C_n$ has the initial state $\ket{0^{n+p(n)}}$, consists of $d$ layers of one- and two-qubit gates, and measures all qubits after the last layer.
\end{itemize}

The set of languages $L=\{L_n: n>0\}$ for which there exists a circuit family $\{C_n: n>0\}\in QNC_d$ such that for $n>0$, for any $x$ where $|x| =n$, 
\begin{itemize}
    \item if $x\in L_n$, then $\Pr[C_n(x)=1]\geq 2/3$; 
    \item otherwise, $\Pr[C_n(x)=1]\leq 1/3$. 
\end{itemize}

The set of languages $L=\{L_n: n>0\}$ for which there exists a circuit family $\{C_n: n>0\}\in QNC_d$ for $d=O(\log^k n)$ such that for $n>0$, for any $x$ where $|x| =n$, 
\begin{itemize}
    \item if $x\in L_n$, then $\Pr[C_n(x)=1]\geq 2/3$; 
    \item otherwise, $\Pr[C_n(x)=1]\leq 1/3$. 
\end{itemize}

The set of languages $\Lang=\{\Lang_n: n>0\}$ for which there exists a family of $d$-QC schemes $\{\A_n: n>0\}$ such that for $n>0$, for any $x$ where $|x| =n$, 
\begin{itemize}
    \item if $x\in \Lang_n$, then $\Pr[\A_n(x)=1]\geq 2/3$;
    \item otherwise, $\Pr[\A_n(x)=1]\leq 1/3$. 
\end{itemize}

The set of languages $\Lang^{\Ora}:=\{\Lang^{\Ora}_n: n>0\}$ for which there exists a family of $d$-QC schemes $\{\A^{\Ora}_n: n>0\}$ such that for $n>0$, for any $x$ where $|x| =n$, 
\begin{itemize}
    \item if $x\in \Lang^{\Ora}_n$, then $\Pr[\A^{\Ora}_n(x)=1]\geq 2/3$; 
    \item otherwise, $\Pr[\A^{\Ora}_n(x)=1]\leq 1/3$. 
\end{itemize}

The set of languages $\Lang=\{\Lang_n: n>0\}$ for which there exists a family of $d$-CQ schemes $\{\A_n: n>0\}$ such that for $n>0$, for any $x$ where $|x| =n$, 
\begin{itemize}
    \item if $x\in \Lang_n$, then $\Pr[\A_n(x)=1]\geq 2/3$;
    \item otherwise, $\Pr[\A_n(x)=1]\leq 1/3$. 
\end{itemize}

The set of languages $\Lang^{\Ora}=\{\Lang^{\Ora}_n: n>0\}$ for which there exists a family of $d$-CQ schemes $\{\A^{\Ora}_n: n>0\}$ such that for $n>0$, for any $x$ where $|x| =n$, 
\begin{itemize}
    \item if $x\in \Lang^{\Ora}_n$, then $\Pr[\A^{\Ora}_n(x)=1]\geq 2/3$; 
    \item otherwise, $\Pr[\A^{\Ora}_n(x)=1]\leq 1/3$. 
\end{itemize}

\label{def:shuffle}
A $(d,f)$-shuffling of $f$ is defined by $\vecf:=(f_0,\dots,f_d)$, where $f_0,\dots,f_{d-1}\in P(\Z_2^{(d+2)n},\Z_2^{(d+2)n})$ are chosen randomly, and then we choose $f_d$ be the function satisfying the following properties: Let  $S_d:=\{f_{d-1}\circ\cdots\circ f_0(x'):\; x'=0,\dots,2^n-1\}$.  
\begin{itemize}
    \item For $x\in S_d$, let $f_{d-1}\circ\cdots\circ f_0(x')=x$, and we choose the function $f_d:S_d\rightarrow [0,2^n-1]$ satisfying that $f_d\circ f_{d-1}\circ\cdots\circ f_0(x') = f(x')$.
    \item For $x\notin S_d$, we let $f_d(x)=\bot $. 
\end{itemize}
We let $\Sf(d,f)$ be the set of all $(d,f)$-shuffling functions of $f$. For simplicity, we denote $f_d$ on the subdomain $S_d$ as $f^*_d$.

~\label{def:language}
Let $\{f_i:\Z_2^i\rightarrow \Z_2^i;\; i>0\}$ be the set of functions satisfying the promise of the decision Simon's problem. Let $\Ora:=\{\Ora^{f_i,d(i)}_{unif}: i>0\}$, where $\Ora^{f_i,d(i)}_{unif}$ is the ($d(i),f_i$)-shuffling oracle for the function $f_i$ and $d(i)= i$. 
The language is defined as follows: 
\[
    \Lang(\Ora) := \{1^n: f_n\mbox{ is a Simon's function.}\} 
\]

\label{def:S}
Let $d,n\in \mathbb{N}$, $f: \Z_2^n\rightarrow \Z_2^{n}$, and $\vecf$ be a $(d,f)$-shuffling of $f$. Then, we define the sequence of hidden sets $\Sb=(\vecS^{(0)},\dots,\vecS^{(d)})$ as follows. 
\begin{enumerate}
    \item Let $S_j^{(0)}=\Z_2^{(d+2)n}$ for $j=0,\dots,d$. We define $\vecS^{(0)} = (S_0^{(0)},\dots,S_{d}^{(0)})$.
    \item For $\ell=1,\dots,d$, for $j=\ell,\dots, d$, we choose $S_j^{(\ell)}\subseteq S_j^{(\ell-1)}$ randomly satisfying that $\frac{|S_j^{(\ell)}|}{|S_j^{(\ell-1)}|}\leq \frac{1}{2^n}$, $f_j(S_{j-1}^{(\ell)})=S_{j}^{(\ell)}$, and $S_j\subseteq S_j^{(\ell)}$. We define $\vecS^{(\ell)} = (S_{\ell}^{(\ell)},\dots,S_{d}^{(\ell)})$.
\end{enumerate}

\label{def:shaving_f}
For $\ell=1,\dots,d$, we let $f_j^{(\ell)}$ be $f_j$ on $S_{j}^{(\ell-1)}\setminus S_{j}^{(\ell)}$ and $\hat{f}_j^{(\ell)}$ be $f_j$ on $S_{j}^{(\ell)}$. Then, we define 
\begin{align*}
    &\vecf^{(1)} := (f_0,f_1^{(1)},\dots,f_d^{(1)})\quad  \quad\vecf^{(d+1)} := (\hat{f}_d^{(d)}),\,\mbox{and}\\
    & \vecf^{(\ell)} := (\hat{f}^{(\ell)}_{\ell-1},f^{(\ell)}_{\ell},\dots,f_{d}^{(\ell)})
\end{align*}
for $\ell=2,\dots,d$. Also, we define 
\begin{align*}
    &\nvecf^{(0)} := (f_0,\dots,f_d)\,\mbox{and}\\
    &\nvecf^{(\ell)} := (\hat{f}_{\ell}^{(\ell)},\dots,\hat{f}_{d}^{(\ell)})
\end{align*}
for $\ell = 1,\dots,d$.

\label{ob:1}
Let $\vecf$ be an uniform $(d,f)$-shuffling of some function $f$.  
\begin{itemize}
    \item The key function $f^*_d$ is in $\vecf^{(d+1)}:= (\hat{f}_d^{(d)})$.
    \item Let $\vecg:= (f_1,\dots,f_{\ell-1},g_{\ell},\dots,g_{d})$ be the shadow of $\vecf$ in $\vecS^{(\ell)}$, $\vecg$ must be consistent with $\vecf$ on $\vecf^{(1)},\dots,\vecf^{(\ell)}$, and maps the elements in $\vecS^{(\ell)}$ to $\bot$. In other words, $\hat{\vecf}^{(\ell)}$ is totally blocked by $\bot$ when given $\vecg$.  
    \item For $\ell = 1,\dots,d$, conditioned on $\vecf^{(1)},\dots,\vecf^{(\ell)}$, the function $\hat{f}^{(\ell)}_{j}$ is still drawn uniformly randomly from $\mathcal{P}(S_{j}^{(\ell)},S_{j+1}^{(\ell)})$ for $j=\ell,\dots,d-1$ according to the definition of $\D(f,d)$.
\end{itemize}

~\label{def:semi_oracle_2}
Let $f$ be an arbitrary function and $\vecf$ be a random $(d,f)$-shuffling of $f$. Let $\Sb:= (\vecS^{(0)},\dots,\vecS^{(d)})$ be a sequence of hidden sets.  Let $U$ be single-depth quantum circuit. For $\ell\in [d]$, we define $U^{\vecf\setminus \vecS^{(\ell)}}$ to be an unitary operating on registers $(\regR, \regI)$ where $\regI$ is a single-qubit register.  $U^{\vecf\setminus \vecS^{(\ell)}}$ simulates $\vecf U$ and that: 
\begin{itemize}
    \item[] Before applying $\vecf$, $U^{\vecf\setminus \vecS^{(\ell)}}$ first applies $U_{\vecS^{(\ell)}}$ on $(\regR,\regI)$ and then performs $\vecf$. Here $U_{\vecS^{(\ell)}}$ is defined by: 
    \[
        U_{\vecS^{(\ell)}}\ket{(\ell,\X_{\ell}),\dots,(d,\X_d)}_{\regR}\ket{b}_{\regI}:=
        \left\{
            \begin{array}{ll}
            U_{\vecS^{(\ell)}}\ket{(\ell,\X_{\ell}),\dots,(d,\X_d)}\ket{b} \mbox{ if every }\X_i\cap S_i^{(\ell)}=\phi,&\\
            U_{\vecS^{(\ell)}}\ket{(\ell,\X_{\ell}),\dots,(d,\X_d)}\ket{b+1\mod 2} \mbox{ otherwise.}&
        \end{array}
        \right.
    \]
\end{itemize}

\label{lem:o2h}
Let $k,d\in \mathbb{N}$ satisfying that $k<d$. Let $U$ be any single depth quantum circuit and $\rho$ be any input state. Let $f$ be any function from $\Z_2^n$ to $\Z_2^{n}$. Let $\vecf$ be a random $(d,f)$-shuffling of $f$. Let $\Sb:=(\vecS^{(0)},\dots,\vecS^{(d)})$ be a sequence of random hidden sets as defined in Def.~\ref{def:S}. Let $\vecg$ be the shadow of $\vecf$ in $\vecS^{(k)}$. Then, for any binary string $t$,
\begin{eqnarray*}
    |\Pr[\Pi_{0/1}\circ \vecf  U(\rho) = t] - \Pr[\Pi_{0/1}\circ \vecg  U(\rho) = t]|&\leq& B(\vecf U(\rho),\vecg  U(\rho)) \\
    &\leq& \sqrt{2\Pr[find\;\vecS^{(k)}: U^{\vecf\setminus \vecS^{(k)}},\rho]}, 
\end{eqnarray*}
where $\Pi_{0/1}$ is the measurement in the standard basis. Here the probability is over $\vecf$, $\Sb$, and the randomness of the quantum mechanism.

\label{lem:find}
Suppose $\Pr[x\in S_i^{(k)}|x\in S_i^{(k-1)}] \leq p$ for $i=k,\dots,d$. Then for any single-depth quantum circuit $U$ and initial state $\rho$, which are promised to be uncorrelated to $\hat{\vecf}^{(k-1)}$ and $\vecS^{(k)}$,\footnote{Here, $\rho$ and $U$ can be arbitrarily correlated to $\vecf^{(1)},\dots,\vecf^{(k-1)}$, and $\vecf$ and $\vecS^{(k)}$can be sampled arbitrarily.}
\[
    \Pr[find\; \vecS^{(k)}: U^{\vecf\setminus \vecS^{(k)}},\rho]\leq q\cdot p, 
\]
where $q$ is the number of queries $U$ performs.

\label{thm:qcd}
