\label{def:sym-poly} 
Given a polynomial $f(\vx)\in\F[\vx]$ we say that 
\demph{$f(\vx)$ is symmetric} if $f(\vx)$ is invariant 
(i.e., stays the same) under permutation of all the  variables:
\begin{equation}
f(\vx) = f(\permutx),
\end{equation}
for every $\sigma\in S_n$.

\label{prop:fund-thm-sym-polynomials}
Every symmetric polynomial $f\in\F[\vx]$ with $n$ variables can be written as a \emph{polynomial} in the elementary symmetric polynomials. 
That is, there is a $g(\vy)\in\F[\vy]$ such that 
\begin{equation}
f(\vx) = g(y_1/\el_{1,n}(\vx),\dots,y_n/\el_{n,n}(\vx)).
\end{equation}




Moreover, if $f(\vx)$ is multilinear then $g(\vy)$ is linear, that is, $f(\vx)$
can be written as a \emph{linear} combination of elementary
symmetric polynomials:
\begin{equation}
f(\vx) = \sum_{i=0}^n \lambda_i \el_{i,n}(\vx), \text{~~~~with $\lambda_i\in\F$}.
\end{equation}

\label{def:IPS} Let $f_1(\vx),\ldots,f_m(\vx),p(\vx)$ be a collection of polynomials in $\F[x_1,\ldots,x_n]$ over the field \F. An \demph{IPS proof of $p(\vx)=0$ from axioms $\{f_j(\vx)=0\}_{j\in [m]}$}, showing that $p(\vx)=0$ is semantically  implied from the assumptions $\{f_j(\vx)=0\}_{j\in [m]}$ over $0$-$1$ assignments, is an algebraic circuit $C(\vx,\vy,\vz)\in\F[\vx,y_1,\ldots,y_m,z_1,\ldots,z_n]$ such that (the equalities in what follows stand for  formal polynomial identities\footnote{That is, $C(\vx,\vnz,\vnz)$ computes the zero polynomial and $C(\vx,f_1(\vx),\ldots,f_m(\vx),x_1^2-x_1,\ldots,x_n^2-x_n)$ computes the polynomial $p(\vx)$.}; recall the notation $\widehat C$ for the \emph{polynomial} computed by circuit $C$):
        \begin{enumerate}
                \item $\widehat C(\vx,\vnz,\vnz) = 0$;

                \item $\widehat C(\vx,f_1(\vx),\ldots,f_m(\vx),x_1^2-x_1,\ldots,x_n^2-x_n)=p(\vx)$.
        \end{enumerate}
        The \demph{size of the IPS proof} is the size of the circuit $C$. An \IPS\ proof  $C(\vx,\vy,\vz)$ of  $1=0$ from $\{f_j(\vx)=0\}_{j\in[m]}$ is called an \demph{IPS refutation} of $\{f_j(\vx)=0\}_{j\in[m]}$ (note that in this case  it must hold that  $\{f_j(\vx)=0\}_{j\in [m]}$ have no common solutions in $\bits^n$).
        If $\widehat C$ is of individual degree $\le 1$ in each $y_j$ and $z_i$, then this is a \demph{linear} IPS refutation (called \emph{Hilbert} IPS by Grochow-Pitassi~\cite{GP18}), which we will abbreviate as \lIPS. If $\widehat C$ is of individual degree $\le 1$ only in the $y_j$'s then we say this is an \lbIPS\ refutation (following \cite{FSTW21}). If  $\widehat C(\vx,\vy,\vnz)$ is of individual degree $\le k$ in each $x_j$ and $y_i$ variables, while $\widehat C(\vx,\vnz,\vz)$ is not necessarily bounded in its individual degree, then this is called an 
\demph{individual degree-$k$ \lbIPS\ refutation}. 

If $C$ is of depth at most $d$, then this is  called a \emph{depth-$d$ \IPS\ refutation}, and further called a \emph{depth-$d$ \lIPS\ refutation} if $\widehat C$ is linear in $\vy,\vz$, and a depth-$d$ \lbIPS\ refutation if $\widehat C$ is linear in $\vy$, and \emph{depth-$d$ multilinear \lbIPS} refutation if $\widehat C(\vx,\vy,\vnz)$ is linear in $\vx,\vy$.

\label{def:roABP}
        An \emph{algebraic branching program (ABP) with unrestricted weights} of \emph{depth} $D$ and \emph{width} $\le r$, on the variables $x_1,\ldots,x_n$, is a directed acyclic graph such that:
        \begin{itemize}
                \item The vertices are partitioned into $D+1$ layers $V_0,\ldots,V_D$, so that $V_0=\{s\}$ ($s$ is the source node), and $V_D=\{t\}$ ($t$ is the sink node). Further, each edge goes from $V_{i-1}$ to $V_{i}$ for some $0< i\le D$.
                \item $\max|V_i|\le r$.
                \item Each edge $e$ is weighted with a polynomial $f_e\in\F[\vx]$.
        \end{itemize}
The \demph{(individual) degree} $d$ of the ABP is the maximum (individual) degree of the edge polynomials $f_e$. The \demph{size} of the ABP is the product $n\cdot r\cdot d\cdot D$.
Each $s$-$t$ path is said to compute the polynomial which is the product of the labels of its edges, and the algebraic branching program itself computes the sum over all $s$-$t$ paths of such polynomials.

The following are restricted ABP variants:
        \begin{itemize}
                \item An algebraic branching program is said to be \demph{oblivious} if for every layer $\ell$, all the edge labels in that layer are \emph{univariate} polynomials in a \emph{single} variable $x_{i_\ell}$.
                \item An oblivious branching program is said to be a \demph{read-once} oblivious ABP (\textup{\textbf{roABP}}) if each $x_i$ appears in the edge label of exactly one layer, so that $D=n$. That is, each $x_i$ appears in the edge labels in  exactly one layer. The layers thus define a \demph{variable order}, which will be assumed to be  $x_1<\cdots<x_n$ unless otherwise specified.












\end{itemize}

\label{fact:roABP:closure}
        If $f,g\in\F[\vx]$ are computable by width-$r$ and width-$s$ \emph{roABPs} respectively, then
        \begin{itemize}
                \item $f+g$ is computable by a width-$(r+s)$ roABP.
                \item $f\cdot g$ is computable by a width-$(rs)$ roABP.
        \end{itemize}

        \noindent Further, roABPs are also closed under the following operations.
        \begin{itemize}
                \item If $f(\vx,\vy)\in\F[\vx,\vy]$ is computable by a width-$r$ roABP in some variable order then the partial substitution $f(\vx,\vaa)$, for $\vaa\in\F^{|\vy|}$, is computable by a width-$r$ roABP in the induced order on $\vx$, where the degree of this roABP is bounded by the degree of the roABP for $f$.
                \item If $f(z_1,\ldots,z_n)$ is computable by a width-$r$ roABP in variable order $z_1<\cdots<z_n$, then $f(x_1y_1,\ldots,x_ny_n)$ is computable by a $\poly(r,\ideg f)$-width roABP in variable order $x_1<y_1<\cdots<x_n<y_n$.
        \end{itemize}

