{theorem}{ChenMUCQ}
    \label{thm:implicit_UCQ_dicho}
Let $C$ be a recursively enumerable class of UCQs of bounded arity. If the treewidth of $\Gamma(C)$ and of $\contract{\Gamma(C)}$ is bounded, then $\#\ucq(C)$ is fixed-parameter tractable. Otherwise, $\#\ucq(C)$ is $\ccW{1}$-hard.

{theorem}{maindichosimple}\label{thm:main_dicho_quantifier_free}
Let $C$ be recursively enumerable class of quantifier-free UCQs of bounded arity. If $\conjunctclass{C}$ has bounded treewidth then $\#\ucq(C)$ is fixed-parameter tractable. 
If $\conjunctclass{C}$ has unbounded treewidth  and $C$ is closed under deletions then $\#\ucq(C)$ is $\ccW{1}$-hard.

{theorem}{maindichogeneral}\label{thm:main_dicho_quantifiers}
Let $C$ be a recursively enumerable class of UCQs of bounded arity. If $\conjunctclass{C}$ and $\contract{\conjunctclass{C}}$ have bounded treewidth then $\#\ucq(C)$ is fixed-parameter tractable.  Otherwise, if  (I)--(III) are satisfed, then
$\#\ucq(C)$ is $\ccW{1}$-hard. 
\begin{enumerate}
    \item[(I)] $C$ is closed under deletions.
    \item[(II)] The number of existentially quantified variables of queries in $C$ is bounded.
    \item[(III)] The UCQs in $C$ are unions of self-join-free conjunctive queries.
\end{enumerate}

\label{thm:CQ_dichointro}
Let $\varphi$ be a quantifier-free conjunctive query.
If $\varphi$ is acyclic, then the number of answers of $\varphi$ in a given database $\calD$ can be computed in time linear in the size of $\calD$. Otherwise, if $\varphi$ has arity $2$, then the number of answers cannot be computed in linear time in the size of $\calD$, unless \emph{the Triangle Conjecture} fails.

{theorem}{mainmeta}  
\label{thm:main_meta}
Assume that the Triangle Conjecture is true.
When restricted to input queries of arity at most $2$, $\meta$ can be solved in time $2^{O(\ell)} \cdot |\Psi|^{\mathsf{poly}(\log|\Psi|)}$, where~$\ell$ is the number of conjunctive queries in the union. Moreover, $\meta$ is $\mathrm{NP}$-hard and the following conditional lower bounds apply:
    \begin{itemize}
        \item If ETH is true, then $\meta$ cannot be solved in time $2^{o(\ell)}$.
        \item If the non-uniform ETH is true then
    $\meta \notin \bigcap_{\varepsilon>0} \mathrm{DTime}(2^{\varepsilon \cdot \ell})$.
    \end{itemize}
The lower bounds remain true even if $\Psi$ is a union of self-join-free and acyclic conjunctive queries over a binary signature (that is, of arity~$2$).

\label{def:WLdim}
Let $\Psi$ be a UCQ on labelled graphs. The \emph{WL-dimension} of~$\Psi$, denoted by $\mathsf{dim}_{\mathrm{WL}}(\Psi)$, is the minimum $k$ such that, for any pair of labelled graphs $\calD_1$ and $\calD_2$ with $\calD_1 \cong_k \calD_2$, it holds that the number of answers to $\Psi$ in $\calD_1$ is the same as in $\calD_2$.
If no such $k$ exists, then the WL-dimension is $\infty$.

{theorem}{WLone}  
\label{thm:WL1}
There is an algorithm that computes a $O(\sqrt{\log k})$-approximation of the WL-dimension~$k$ of a quantifier-free UCQ on labelled graphs $\Psi=\varphi_1\vee\dots\vee\varphi_\ell$ in time $|\Psi|^{O(1)}\cdot O(2^\ell)$.

Moreover, let $f:\mathbb{Z}_{>0}\to\mathbb{Z}_{>0}$ be any computable function. 
The problem of computing an $f$-approximation of $\mathsf{dim}_{\mathrm{WL}}(\Psi)$
given an  input UCQ $\Psi=\varphi_1\vee\dots\vee\varphi_\ell$  is NP-hard, and, assuming ETH, an $f$-approximation of $\mathsf{dim}_{\mathrm{WL}}(\Psi)$ cannot be computed in time~$2^{o(\ell)}$.

{theorem}{WLtwo}  
\label{thm:WL2}
Let $k$ be any \emph{fixed} positive integer. 
The problem of deciding whether the WL-dimension of a quantifier-free UCQ on labelled graphs $\Psi=\varphi_1\vee\dots\vee\varphi_\ell$ is at most $k$ can be solved in time $|\Psi|^{O(1)}\cdot O(2^\ell)$.

Moreover, the problem is $\mathrm{NP}$-hard and, assuming ETH, cannot be solved in time $2^{o(\ell)}$.

\label{obs:cminimalequivalent}
The following are equivalent:
\begin{enumerate}
\item A conjunctive query $(\mathcal{A},X)$ is \emph{$\cminimal$}.
\item $(\mathcal{A},X)$ has no $\cequivalent$ substructure that is induced by a set $U$ with $X\subseteq U\subset U(\mathcal{A})$.
\item Every homomorphism from $\mathcal{A}$ to itself 
that is the identity on~$X$ is surjective.
\end{enumerate}

\label{fact:easy_fact}
Let $((\mathcal{A}_1,,\dots,\mathcal{A}_\ell),X)$ be a UCQ, and let $\emptyset\neq J\subseteq[\ell]$. For each database $\mathcal{D}$ and assignment $a: X \to U(\mathcal{D})$ we have
\[ a \in \Ans{\conjuncts{\Psi}{J}}{\mathcal{D}} \Leftrightarrow \forall j \in J : a \in \Ans{\Psi_j}{\mathcal{D}}.\]

\label{def:coefUCQ}
Let $\Psi = ((\mathcal{A}_1,,\dots,\mathcal{A}_\ell),X)$ be a UCQ. For each conjunctive query $(\mathcal{A},X)$, we set $\mathcal{I}(\mathcal{A},X) = \{J \subseteq [\ell] \mid  (\mathcal{A},X) \cequiv \conjuncts{\Psi}{J}\}$, and we define the \emph{coefficient function} of $\Psi$ as follows: 
    \[ c_\Psi(\mathcal{A},X) = \sum_{J \in \mathcal{I}(\mathcal{A},X)} (-1)^{|J|+1} \,.\]

\label{lem:new_meta_help}
    There is a deterministic algorithm that on input a quantifier-free UCQ $\Psi = (\mathcal{A}_1,\dots,\mathcal{A}_\ell)$ decides in time $|\Psi|^{\mathsf{poly}(\log|\Psi|)}\cdot 2^{O(\ell)}$ whether all structures $\mathcal{A}$ with
    $c_\Psi(\mathcal{A})\neq 0$ are acyclic.

\label{lem:I_have_the_power!}
Let $\Delta=(\Omega,\mathcal{I})$ be a non-trivial irreducible complex. It is possible to
compute, in polynomial time in $|\Delta|$, a set $\mathcal{U}$ and a set $\hat{\Omega}\subseteq 2^\mathcal{U}$ with $\mathcal{U}\notin \hat{\Omega}$ such that $\Delta$ is isomorphic to the power complex $\Delta_{\hat{\Omega},\mathcal{U}}$.

\label{lem:main_reduct_meta_help}
    For each positive integer $t$, there is a polynomial-time algorithm $\hat{\mathbb{A}}_t$ that, when given as input a non-trivial irreducible complex $\Delta=(\Omega,\mathcal{I})$ with $\Omega\notin \mathcal{I}$,  computes a union of quantifier-free conjunctive queries $\Psi=(\mathcal{B}_1,\dots,\mathcal{B}_\ell)$ satisfying the following constraints:
    \begin{enumerate}
        \item $\conjunctfull{\Psi} \cong \mathcal{K}_t^k$ for some $k\geq 1$.
        \item $c_\Psi(\conjunctfull{\Psi}) = - \hat{\chi}(\Delta)$. 
        \item For all relational structures $\mathcal{B}\ncong \conjunctfull{\Psi}$, $c_\Psi(\mathcal{B})\neq 0$ implies that $\mathcal{B}$ is acyclic.
        \item $\ell\leq|\Omega|$.
        \item For all $i\in [\ell]$ the conjunctive query $\mathcal{B}_i$ is acyclic and self-join-free, and has arity $2$.
    \end{enumerate}
    Moreover, the algorithm $\hat{\mathbb{A}}_t$ can be explicitly constructed from~$t$.

\label{lem:main_reduct_meta}
    For each positive integer $t$, there is a polynomial-time algorithm $\mathbb{A}_t$ that, when given as input a complex $\Delta=(\Omega,\mathcal{I})$, either computes $\hat{\chi}(\Delta)$, or computes a union of quantifier-free conjunctive queries $\Psi=(\mathcal{B}_1,\dots,\mathcal{B}_\ell)$ satisfying the following constraints:
    \begin{enumerate}
        \item $\conjunctfull{\Psi} \cong \mathcal{K}_t^k$ for some $k\geq 1$.
        \item $c_\Psi(\conjunctfull{\Psi}) = - \hat{\chi}(\Delta)$. 
        \item For all relational structures $\mathcal{B}\ncong \conjunctfull{\Psi}$, $c_\Psi(\mathcal{B})\neq 0$ implies that $\mathcal{B}$ is acyclic.
        \item $\ell\leq|\Omega|$.
        \item For all $i\in [\ell]$ the conjunctive query $\mathcal{B}_i$ is acyclic and self-join-free, and has arity $2$.
    \end{enumerate}

\label{thm: lower bounds vs missing strings}
	The following are equivalent:\begin{itemize}
		\item $\Sigma_2\E^A\not\subset \io\SIZE^A[2^{\Omega(n)}]$ for every oracle $A$;
		\item for $m = 2^{\Omega(n)}$, the $\MissingString$ problem can be solved by a uniform family of size-$2^{O(n)}$ depth-$3$ $\AC^0$ circuits. 
