\label{def: symmetric time}
	Let $T\colon \N \to \N$. We say a language $L \in \S_2\TIME[T(n)]$, if there exists an $O(T(n))$-time verifier $V(x,\pi_1,\pi_2)$ that takes $x \in \bs{n}$ and $\pi_1,\pi_2 \in \bs{T(n)}$ as input, satisfying that
	\begin{itemize}
		\item if $x \in L$, then there exists $\pi_1$ such that for every $\pi_2$, $V(x,\pi_1,\pi_2) = 1$, and
		\item if $x \not\in L$, then there exists $\pi_2$ such that for every $\pi_1$, $V(x,\pi_1,\pi_2) = 0$.
	\end{itemize}

	Moreover, we say $L \in \S_2\E$ if $L \in \S_2\TIME[T(n)]$ for some $T(n) \le 2^{O(n)}$, and $L \in \S_2\P$ if $L \in \S_2\TIME[p(n)]$ for some polynomial $p$.

~\label{def: single-valued algorithms}
	A single-valued $\mathsf{F}\Sigma_2\P$ algorithm $A$ is specified by a polynomial $\ell(\cdot)$ together with a polynomial-time algorithm $V_A(x, \pi_1, \pi_2)$. On an input $x \in \bs{*}$, we say that $A$ outputs $y_x \in \bs{*}$, if the following hold:
	\begin{enumerate}
		\item[(a)] There is a $\pi_1\in\{0, 1\}^{\ell(|x|)}$ such that for every $\pi_2\in\{0, 1\}^{\ell(|x|)}$, $V_A(x, \pi_1, \pi_2)$ outputs $y_x$.
		\item[(b)] For every $\pi_1\in\{0, 1\}^{\ell(|x|)}$, there is a $\pi_2\in\{0, 1\}^{\ell(|x|)}$ such that the output of $V_A(x, \pi_1, \pi_2)$ is either $y_x$ or $\bot$ (where $\bot$ indicates ``I don't know'').
	\end{enumerate}

	A single-valued $\mathsf{F}\S_2\P$ algorithm $A$ is specified similarly, except that 
 we replace the second condition above with the following:
	\begin{enumerate}
			\item[(b')] There is a $\pi_2\in\{0, 1\}^{\ell(|x|)}$ such that for every $\pi_1\in\{0, 1\}^{\ell(|x|)}$, $V_A(x, \pi_1, \pi_2)$ outputs $y_x$.
	\end{enumerate}

	\label{defi:sv-algos}

\label{lemma:Kor-prop-sigma2}
	Let $n,T \in \N$ be such that $\log T \le n \le T$. Let $C\colon\{0, 1\}^n \to \{0, 1\}^{2n}$ be a circuit and $f\in\bs{T} \setminus \Range(\GGM_T[C])$. Let $h \coloneqq \HisKor(C, f)$ and $z \coloneqq \Kor(C, f)$.

	\begin{enumerate}
		\item {\bf (history contains input/output)} There is a $\poly(\log T)$-time one-query oracle algorithm $\In$ and an $O(n)$-time oracle algorithm $\Out$, both having input parameters $T, n$ and taking a string $\tilde{h} \in \bs{5T}$ as oracle, such that the following hold:\label{item: Input-Output}

		\begin{enumerate}
			\item When given $h$ as the oracle, $\In_{T,n}$ takes an additional input $i \in \zeroUpto{5T-1}$ and outputs $f_i$. \label{item: history-contain-input}

			\item When given $h$ as the oracle, $\Out_{T,n}$ outputs $z = \Kor(C, f)$. \label{item: history-contain-output}
		\end{enumerate}

		\item {\bf ($\Pi_1$ verification of the history)} There is an oracle algorithm $V$ with input parameters $T,n$ such that the following holds:\label{item: Pi1 verification of history}

