			\item $h = \HisKor(C,f)$ is the unique string from $\bs{5 T}$ satisfying the following: \label{item: uniquely verifiable history}
			\[
			V^{f,h}(C, w) = 1 \qquad\text{for every $w \in \bs{5 \cdot (\log T + n)}$.}
			\]
		\end{enumerate}
	\end{enumerate}

