For two tensors $t \in \FF^{n_1 \times n_2 \times n_3}$ and $s \in \FF^{m_1 \times m_2 \times m_3}$ we define the \emph{relative exponent from $t$ to $s$}~as
\begin{align}
\relexp(t, s) &\coloneqq \lim_{n\to \infty} \tfrac1n \min\{ m \in \NN_{\geq 1} : t^{\otimes m} \geq s^{\otimes n} \}\\
&= \sup_n \tfrac1n \min\{ m \in \NN_{\geq1} : t^{\otimes m} \geq s^{\otimes n} \}.
\end{align}

We define the \emph{irreversibility} of a tensor $t$ as the product of the relative exponent from $\langle 2\rangle$ to $t$ and the relative exponent from $t$ to $\langle 2\rangle$, i.e.
\begin{equation}
\irr(t) \coloneqq \relexp(\langle 2\rangle, t) \relexp(t, \langle2\rangle).
\end{equation}
Thus $\irr(t)$ measures the extent to which the asymptotic conversion from $\langle 2\rangle$ to $t$ is irreversible, explaining the name.
Equivalently, the irreversibility is the ratio of the logarithms of the asymptotic rank and the asymptotic subrank, i.e.
\begin{equation}
\irr(t) = \frac{\log_2 \asymprank(t)}{\log_2 \asympsubrank(t)}.
\end{equation}

\label{biggerthanone} For any tensor $t$ it holds that
\begin{equation}
\irr(t) \geq 1.
\end{equation}

\label{th1} For any tensor $t$ it holds that
\begin{equation}
\relexp(\langle 2\rangle, t) \relexp(t, \langle 2,2,2\rangle) \geq 2 \irr(t).
\end{equation}

\label{th2}
For any tensor $t$ and $\alpha, \beta \in \NN$ it holds that 
\begin{equation}
\frac{\relexp(\langle2\rangle, t) \relexp(t, \langle 2\rangle^\alpha \langle 2,2,2\rangle^\beta) - \alpha}{\beta}\geq 2 \irr(t) + \frac{\alpha}{\beta}\bigl( \irr(t) - 1\bigr) \geq 2 \irr(t).
\end{equation}

\label{barrierth}
 For any tensor $t$ and $\alpha \in \NN$ and $a,b,c\in \NN_{\geq1}$ it holds that
\begin{align}
\frac{\relexp(\langle2\rangle, t) \relexp(t, \langle 2\rangle^\alpha \langle a,b,c\rangle) - \alpha}{\tfrac13 \log_2(abc)} &\geq 2 \irr( \cyc(t)) + \frac{\alpha}{\tfrac13\log_2(abc)}(\irr(\cyc(t)) - 1)\\
&\geq 2\irr(\cyc(t)).
\end{align}

 For any tensor $t$ it holds that
\begin{equation}
