\label{month2}
For any tensor $t$ and $\alpha, \beta \in \NN$ it holds that
\begin{equation}
\frac{\relexp(\langle2\rangle, t) \monrelexp(t, \langle 2\rangle^\alpha \langle 2,2,2\rangle^\beta) - \alpha}{\beta}\geq 2 \monirr(t) + \frac{\alpha}{\beta}\bigl( \monirr(t) - 1\bigr) \geq 2 \monirr(t).
\end{equation}

\label{monbarrierth}
 For any tensor $t$ and $\alpha \in \NN$ and $a,b,c\in \NN_{\geq1}$ it holds that
\begin{align}
\frac{\relexp(\langle2\rangle, t) \monrelexp(t, \langle 2\rangle^\alpha \langle a,b,c\rangle) - \alpha}{\tfrac13 \log_2(abc)} &\geq 2 \monirr( \cyc(t)) + \frac{\alpha}{\tfrac13\log_2(abc)}(\monirr(\cyc(t)) - 1)\\
&\geq 2\monirr(\cyc(t)).
\end{align}

 Let $t$ be a tensor in $S$. Then
\begin{equation}
\irr(t) = \frac{\max_{F \in \aspec(S)} \log F(t)}{\min_{G \in \aspec(S)} \log G(t)}.
\end{equation}

Let $t$ be a tensor. Then
\begin{equation}
\irr(t) \geq \frac{\max_{i} \log_2 \rank(t_i)}{\min_{\theta} \rho^\theta(t)}. 
\end{equation}

\label{cweasy}
For any integer $q\geq 2$, the irreversibility of the small Copper\-smith--Winograd tensor
\begin{equation}
\cw_q \coloneqq \sum_{i=1}^q e_{0,i,i} + e_{i,0,i} + e_{i,i,0} 
\end{equation}
is lower bounded by
\begin{equation}\label{th9b}
2\irr(\cw_q) \geq 2\cdot \frac{\log_2(q+1)}{\log_2 3 - \tfrac23 + \tfrac 23 \log_2 q}.
\end{equation}

\label{cwhard}
For any integer $q \geq 1$ the irreversibility of the big Coppersmith--Winograd tensor
\begin{equation}
\CW_q \coloneqq e_{0,0,q+1} + e_{0,q+1,0} + e_{q+1,0,0} + \sum_{i=1}^q e_{0,i,i} + e_{i,0,i} + e_{i,i,0}
\end{equation}
is lower bounded by
\begin{equation}\label{CWb}
2\irr(\CW_q) \geq 
\begin{dcases}
\frac{2\log_2(3)}{f_1(\tfrac{1}{18}(\sqrt{33} - 3))} = 2.16.. & \textnormal{if } q = 1\\[0.5em]
\frac{2\log_2(4)}{f_2(\tfrac19)} = 2.17.. & \textnormal{if }q=2\\[0.5em]
\frac{2\log_2(q+2)}{f_q\bigl( \frac{3q - \sqrt{32+q^2}}{6(q^2-4)}\bigr)} & \textnormal{if }q \geq 3\\
\end{dcases}
\end{equation}
where 
\begin{equation}
f_q(x) \coloneqq - \Bigl(\frac23 - qx\Bigr)\log_2\Bigl(\frac23 - qx\Bigr) - q\cdot 2x \log_2(2x) - \Bigl(\frac13 - qx\Bigr)\log_2\Bigl(\frac13 - qx\Bigr).
\end{equation}

Let $t$ be a tensor over the complex numbers. Then
\begin{equation}
\irr(t) \geq \frac{\max_{i} \log_2 \rank(t_i)}{\min_\theta \log_2 F^\theta(t)}.
\end{equation}

 \label{lem:HS-to-hardness}
  Let $H$ be an explicit hitting set for $\mathcal{C}(n,d,s)$.
Then, for any $k\leq n$ such that $k|H|^{\frac{1}{k}} \leq d$, there is a polynomial $Q(z_1,\ldots, z_k)$ of individual degree smaller than $|H|^{\frac{1}{k}}$ that is computable in time $\poly(|H|)$ that requires formulas of size~$s$ to compute it. Furthermore, given the set $H$, there is an algorithm to output a formula of size $|H| \cdot d$ for $Q$ in time $\poly(|H|)$.

{lemma}{stepzerolemma}
  \label{lem:step-zero}
  Let $\epsilon >0$ and $n \geq 2$ be constants. Suppose that for all large enough $s$ there is an explicit hitting set of size $s^{n - \epsilon}$, for all degree-$s$, size-$s$ algebraic formulas over $n$ variables.

  Then for a large enough $m \geq n^8$, and for all $s \geq m$, there is an explicit hitting set of size $s^{\frac{m}{50}}$ for all degree-$s$, size-$s$ algebraic formulas over $m$ variables.

{lemma}{bootstraplemma}
  \label{lem:main-bootstrap}
  Let $n_0$ be large enough, and $n$ be any power of two that is larger than $n_0$. Suppose for all $s \geq n$ there are explicit hitting sets of size $s^{g(n)}$ for $\mathcal{C}(n,s,s)$, the class of $n$-variate degree-$s$ polynomials computed by size-$s$ formulas.
  \begin{enumerate}
    \item\label{lbl:main-bootstrap-a} Suppose $g(n) \leq \frac{n}{50}$, then for $m = n^{10}$ and all $s \geq m$, there are explicit hitting sets of size $s^{h(m)}$ for $\mathcal{C}(m,s,s)$ where $h(m) \leq \pfrac{1}{10} \cdot m^{\frac{1}{4}}$.
    \item\label{lbl:main-bootstrap-b} Suppose $g(n) \leq \pfrac{1}{10} \cdot n^{\frac{1}{4}}$, then for $m = 2^{n^{\frac{1}{4}}}$ and all $s \geq m$, there are explicit hitting sets of size $s^{h(m)}$ for $\mathcal{C}(m,s,s)$ where $h(m) = 20\cdot \inparen{g(\log^{4}m)}^{2}$.

      Furthermore, $h(m)$ also satisfies $h(m) \leq \pfrac{1}{10} \cdot m^{\frac{1}{4}}$.
  \end{enumerate}

\label{lem:bootstrapping-growing-s}
  Let $g,t:\N\rightarrow \N$ be non-decreasing functions such that $g(k) \leq k^{1/4}$ and $t(x^{\log x}) \leq 2 t(x)$ for all $x$. Let $1\leq m\leq s$ such that 
  \begin{equation}\label{eqn:bootstrapping-growing-s-constraint}
    20 \cdot g\inparen{(\log m)^4} \cdot t(s) \leq \log m.
  \end{equation}

  \noindent

  Let $(k_1, s_1) = \inparen{(\log m)^4,  s^5}$ and $(k_2, s_2) = \inparen{(\log m)^4, s^{100 g((\log m)^2) t(s)}}$. Suppose $\mathcal{C}(k_1,s_1, s_1)$ and $\mathcal{C}(k_2, s_2, s_2)$ have explicit hitting sets of size at most $s_1^{g(k_1) t(s_1)}$ and $s_2^{g(k_2)t(s_2)}$, respectively. 

  Then, we have an explicit hitting set for $\mathcal{C}(m,s,s)$ of size at most $s^{g'(m) t'(s)}$, where
  \begin{align*}
    g'(m) & \leq 400 \cdot \inparen{g\inparen{(\log m)^4}}^2\\
    t'(s) & \leq t(s)^2.
  \end{align*}

\label{def.sv}
The \emph{Shpilka--Volkovich (SV) Generator} for \(\FF[x_1,\dots,x_n]\) is paramet\-rized by the following data:    

\begin{itemize}
    \item A positive integer \(l\).
    \item For each \(i \in [n]\), a distinct abscissa \(a_i\in \FF\).
\end{itemize}
The generator \(\SVl\) takes as seed \(l\) pairs of fresh variables
\((y_1,z_1),\ldots,(y_l,z_l)\) and substitutes
\begin{equation}\label{eq-sv-sub}
x_i\gets\sum_{t=1}^l  z_t \cdot L_i(y_t),
\end{equation}
where the \emph{Lagrange interpolant} $L_i$ is the unique univariate polynomial of degree at most $n-1$ satisfying $L_i(a_i)=1$ and $L_i(a_j) = 0$ for $j \in [n] \setminus \{i\}$.

\label{cor.rfe.degree}
The minimum {\em degree} of a nonzero polynomial in $\VanIdeal{\RFEkl}$
equals $l+1$.

\label{cor.rfe.sparseness}
The minimum {\em sparseness}, \ie, number of monomials, of a nonzero
polynomial in $\VanIdeal{\RFEkl}$ equals $\binom{k+l+2}{l+1}$.

\label{cor.rfe.partition-class-size}
The minimum {\em partition class size} of a nonzero set-multilinear
polynomial of degree $l+1$ in $\VanIdeal{\RFEkl}$ equals $k+2$.

\label{thm.ideal.membership}
  Let $k, l, n \in \N$ and let $a_i$ for $i \in [n]$ be distinct elements of $\FF$.
  A multilinear polynomial $p \in \FF[x_1,\dots,x_n]$ belongs to
  $\VanIdeal{\RFEkl}$ if and only if both of the following conditions hold:
  \begin{enumerate}
    \item\label{thm.ideal.membership.cond1}
      There are no monomials of degree $l$ or less,
      nor of degree $n-k$ or more, in \(p\).
    \item\label{thm.ideal.membership.cond2}
      For all disjoint subsets $K,L \subseteq [n]$ with $|K|=k$ and $|L|=l$,
      $\PartialZero{L}{K}{p}$ is zero upon the following
      substitution for each \(i\in[n]\setminus (K\cup L)\), where $z$ denotes a fresh variable:
      \begin{equation}\label{eq.thm.ideal.membership.sub}
        x_i \gets z\cdot \frac
          { \prod_{j \in K} (a_i - a_{j}) }
          { \prod_{j \in L} (a_i - a_{j}) }.
      \end{equation}
  \end{enumerate}

\label{lemma.vangen-vanishes}
For every \(k,l \in \N\) and $i_1,i_2,\dots,i_{k+l+2} \in [n]$,
\(\VanGenkl[i_1, \ldots, i_{k+l+2}] \in \VanIdeal{\RFEkl}\).

For $T=\{i_1, \dots, i_t\} \subseteq [n]$  with $i_1 < \dots < i_t$, we abbreviate the Vandermonde matrix built from $a_i$ for $i \in T$ in increasing order as
\begin{equation}
  \label{eq.vandermonde-rep}
  \Amat{T}
  \doteq
  \begin{bmatrix}
    a_{i_1}^{t-1} & \cdots & 1 \\
    \vdots & & \vdots \\
    a_{i_t}^{t-1} & \cdots & 1
  \end{bmatrix}.
\end{equation}

\label{prop.vangen.basic}
  For every \(k,l \in \N\), 
  \(\VanGenkl\) is skew-symmetric in that,
  for any \(i_1,\ldots,i_{k+l+2} \in [n]\) and permutation \(\pi\) of $[k+l+2]$,
  \[
    \VanGenkl[i_1,\ldots, i_{k+l+2}]
    =
    \sgn(\pi)\cdot
    \VanGenkl[i_{\pi(1)},\ldots,i_{\pi(k+l+2)})].
  \]
  For any $S \subseteq [n]$ with $|S|=k+l+2$, $\VanGenkl[S]$ is a nonzero, multilinear, and homogeneous polynomial of total degree \(l+1\),
  and every multilinear monomial of degree $l+1$ in
  \(x_{i_1},\ldots,x_{i_{k+l+2}}\) appears with a nonzero coefficient. More specifically, for $S = \{i_1, \dots, i_{k+l+2}\} \subseteq [n]$ with $i_1 < i_2 < \dots, i_{k+l+2}$,
  \begin{equation}
    \label{eq.EVC.expanded}
      \VanGenkl[S] = \sum_{\substack{K\sqcup L= S \\ |L|=l+1}}
      \gamma_{K,L} \cdot \prod_{i \in L} x_i,
  \end{equation}
  where
  \begin{equation} \label{eq-EVC-coef}
    \gamma_{K,L} \doteq (-1)^{\XInv(K,L)} \cdot \Adet{K} \cdot \Adet{L}.
\end{equation}

\label{lem.rfe-hits-cored}
Let \(k,l,n\in\N\) and let $r \in \FF[x_1,\dots,x_n]$ be nonzero and \((k+1,l)\)-cored.
Then \(\RFEkl\) hits \(r\).

\label{def.extremal}
  Let \(K, L \subseteq [n]\).
  A degree pattern $d^* \in \N^{K \cup L}$ is \emph{$(K,L)$-extremal} in
  a polynomial $p \in \FF[x_1,\dots,x_n]$
  if $d^*$ is the unique degree pattern $d \in \N^{K \cup L}$ in $p$ that satisfies both
  \begin{itemize}
    \item[(i)] $d_j \le d^*_j$ for all $j \in K$, and
    \item[(ii)] $d_j \ge d^*_j$ for all $j \in L$.
  \end{itemize}

\label[zoom-lemma]{lem.multi-zsub-deriv}
  Let \(K,L \subseteq [n]\),
  let \(p \in \FF[x_1,\ldots,x_n]\),
  and let $d^* \in \N^{K\cup L}$ be a degree pattern that is $(K,L)$-extremal
  in $p$.
  If the coefficient $p_{d^*}$ is nonzero upon the substitution
  \begin{equation}
    \label{eq.multi-zsub-deriv.sub}
    x_i \gets
    z \cdot
      \frac{
        \prod_{j \in K\setminus L} ( a_i - a_j )
      }{
        \prod_{j \in L\setminus K} ( a_i - a_j )
      }
      \qquad \forall i\in [n]\setminus (K\cup L)
  \end{equation}
  where $z$ is a fresh variable, 
  then \(\RFEkl\) hits \(p\) for any \(k\ge|K|\) and \(l\ge|L|\).

\label{prop.ideal.membership.degree-bound}
If a polynomial $p$ contains a monomial of support at most $l$, then $\RFEkl$ hits $p$. 
If a multilinear polynomial $p$ in the variables $x_1,\dots,x_n$ contains a monomial of support at least $n-k$, then $\RFEkl$ hits $p$.

\label{lem.multi-zsub-deriv.mlin}
  Let \(K,L \subseteq [n]\) be disjoint,
  and
  let \(p\in\FF[x_1,\ldots,x_n]\) be a multilinear polynomial.
  If
  \(\PartialZero{L}{K}{p}\)
  is nonzero upon the substitution
  \begin{equation}
    \label{eq.multi-zsub-deriv.mlin.sub}
    x_i \gets
    z \cdot
      \frac{
        \prod_{j\in K} ( a_i - a_{j} )
      }{
        \prod_{j\in L} ( a_i - a_{j} )
      }
      \qquad \forall i\in [n]\setminus (K\sqcup L),
  \end{equation}
  where $z$ is a fresh variable,
  then \(\RFEkl\) hits \(p\) for any \(k\ge|K|\) and \(l\ge|L|\).

\label{prop.zsub-deriv-power}
Let $\Class = \bigcup_{k,l \in \N} \Class_{k,l}$ be a class of polynomials that satisfies the grading hypothesis and such that each $\Class_{k,l}$ is closed under variable rescaling. If $\RFEparam{0}{0}$ hits $\Class_{0,0}$ then 
\(\RFEkl\) hits \(\Class_{k,l}\) for every \(k,l \in \N\).

\label{prop.zsub-deriv-power-variant}
Let $\Class = \bigcup_{k,l \in \N} \Class_{k,l}$ be a class of polynomials that satisfies the grading hypothesis. If $\RFEparam{0}{0}$ hits $\Class_{0,0}$ then 
\(\RFEparam{k+l}{k+l}\) hits \(\Class_{k,l}\) for every \(k,l \in \N\).

\label{prop.roabp-homog}
\def\pdn{p^{(\min)}}
Let \(p\in\FF[x_1,\ldots,x_n]\) be any nonzero polynomial,
and let \(\pdn\) be the nonzero homogeneous component of \(p\) of least degree.
If \(p\) can be computed by an ROABP of width \(w\),
then so can \(\pdn\).

\label{thm.application.roabp.hardpart}
For any integer $l \ge 1$,
every nonzero multilinear homogeneous polynomial of degree $l+1$ in the vanishing ideal of $\SVl$ requires ROABP width at least $(l/3)+1$.

\label{prop.application.roabp.coef-eqns}
Let \(p\in\VanIdeal{\RFEparam{l-1}{l}}\) be multilinear,
and homogeneous of degree \(l+1\),
let \(U\sqcup V\) be a partition of \([n]\),
and let $C \doteq \CMat{U}{V}(p)$.
For every \(I\subseteq U\) and \(J\subseteq V\)
with \(|I|+|J|=l\),
and for every \(j^*\in I\cup J\),
\begin{equation}
  \label{eq.application.roabp.coef-eqns}
  \sum_{i\in U\setminus I}
    \frac{C(\{i\}\cup I, J)}
      {a_i - a_{j^*}}
  +
  \sum_{i\in V\setminus J}
    \frac{C(I,\{i\}\cup J)}
      {a_i - a_{j^*}}
  =0.
\end{equation}

\label{claim.existence}
    There exists $j^* \in [n]$ such that $p_{j^*} \ne 0$ and
    \begin{equation} \label{eq.claim.application.roabp.core}
      \rank(\CMat{U}{V}(p)) \ge \rank(\CMat{U}{V}(p_{j^*})) + 1.
    \end{equation}

\label{prop.bdry-multiple-kernel-image}
For $k, \Delta \in \N$ and any linearly independent linear functions $w_1,\dots,w_{k+\Delta+1}: \SpanVertices \to \FF$
\begin{equation}\label{eq.bdry-kernel-image.general}
\linspan_{\substack{B \subseteq [k+\Delta+1]\\ |B|=k+1}}\im(\bdry_{w^B}) = 
\bigcap_{\substack{B \subseteq [k+\Delta+1] \\ |B|=\Delta+1}}
\ker(\bdry_{w^B}). 
\end{equation}

\label{prop.composed-bdrys}
Let $w_1,\dots, w_{k+1}:\SpanVertices\to\FF$ be linear functions, $T$ a set of indices, and $u_i \in \SpanVertices$ for $i \in T$.
\begin{equation}\label{eq.prop.composed-bdrys}
\bdry_{w^{[k+1]}}(u^T) = \sum_{\substack{I\sqcup J=T \\ |I|=k+1}} 
(-1)^{\XInv(I,J)} \cdot 
\det \begin{bmatrix}
    w_{r}(u_i)
\end{bmatrix}_{i\in I}^{r\in [k+1]}
\cdot u^J, 
\end{equation}
where in the determinant, the rows from top to bottom and the columns from left to right are in increasing order of index $i$ and $r$, respectively.

\label{def.Srepr-prim}
\(\Srepr : \bigoplus_{t=0}^{n}\Simplicest \to \FF[x_1,\ldots,x_n]\) is the linear
map extending
\begin{equation}\label{eq.decoder-mapping}
  v^T
  \;\mapsto\;
  \Adet{T}\,\cdot\,x^T
\end{equation}
for every $T \subseteq [n]$.

\label{cor.simplicial-vangen}
For any \(k,l \in \N\), the set of polynomials of degree $l+1$ in \(\VanIdeal{\RFEkl}\) is given by
\[\Srepr(\bdry_{\alpha^k\wedgecdots\alpha^0}(\Simplicesparam{k+l+2})). \]

\label{lem.simplicial-vangen-high-degree}
For any \(k,l \in \N\), \(S\sqcup M \subseteq [n]\) with $|S|=k+l+2$, and $\mu_M(\alpha) \doteq \prod_{j \in M}(\alpha - a_j)$, 
\begin{equation} \label{eq.simplicial-vangen-high-degree}
  \VanGenkl[S]\cdot x^M = 
  \frac{\Adet{S}}{\Adet{S \sqcup M}} \cdot \Srepr(\bdry_{\mu_M(\alpha)\alpha^k\wedgecdots \mu_M(\alpha)\alpha^0}(v^{S \sqcup M})).
\end{equation}

\label{prop.simplicial-vangen-high-degree}
Let \(k+1,m,t \in \N\) with $t \ge k+1$, $\nu \in \Simplicest$, and $N \subseteq [n]$ with $|N|=k+m+1$. Let $L_{N,j}$ for $j \in N$ denote the Lagrange interpolants for the subset of abscissas $\{a_i\}_{i \in N}$, \ie, $L_{N,j}$ denotes the unique univariate polynomial of degree at most $|N|-1$ satisfying $L_{N,j}(a_i)=1$ for $i=j$ and $L_{N,j}(a_i) = 0$ for $i \in N \setminus \{j\}$.
For all weight functions $w_1, \dots, w_{k+1}$ of degree at most $k+m$, 
\begin{equation}\label{eq.prop.simplicial-vangen-high-degree}
\linspan_{\substack{M \subseteq N \\ |M|=m}} \bdry_{\mu_M(\alpha)\alpha^k\wedgecdots\mu_M(\alpha)\alpha^0}(\nu) \; \;
= 
\linspan_{\substack{w_1, \dots, w_{k+1} \in \FF[\alpha] \\ \deg(w_1), \dots \deg(w_{k+1}) \le k+m}}
\bdry_{w^{[k+1]}}(\nu) \;
=
\linspan_{\substack{B \subseteq N \\ |B|=k+1}} \bdry_{L_N^B}(\nu).
\end{equation}

\label{cor.simplicial-vangen-high-degree}
For any \(k,l \in \N\), the set of multilinear polynomials $p \in \FF[x_1,\dots,x_n]$ in \(\VanIdeal{\RFEkl}\) is given by the direct sum $\oplus_{d=0}^{n-k-1} H_d$ of homogeneous components of degree $d \in \{0,\dots,n-k-1\}$ given by 
\begin{equation}\label{eq.cor.simplicial-vangen-high-degree}
H_d \doteq \linspan \Srepr (\bdry_{w^{[k+1]}}(\Simplicesparam{k+d+1})), 
\end{equation}
where $w_1, \dots, w_{k+1}$ range over all weight functions of degree at most $k+d-l-1$.

\label{thm.vanideal-char.multilinear}
Let \(k,l \in \N\).
For any multilinear polynomial
\(p\in\FF[x_1,\ldots,x_n]\),
\(p(\RFEkl) = 0\) if and only if the homogeneous components $p^{(d)}$ of $p$ for all degrees $d$ satisfy the following requirements:
\begin{enumerate}
    \item $p^{(d)}=0$ if $d \le l$ or $d \ge n-k$. \label{cond.thm.vanideal-char.multilinear-1}
    \item For all $d = l+\Delta+1$ with $\Delta \in \{0, \dots, n-k-l-2\}$ and all weight functions \(w_1,\ldots,w_{\Delta+1}\) of degree at most \(k+\Delta\) \label{cond.thm.vanideal-char.multilinear-2},
    \begin{equation}\label{eq.thm.vanideal-char.multilinear}
    \bdry_{w_1\wedgecdots w_{\Delta+1}}( \Srepr^{-1}(p^{(d)})  ) = 0.
    \end{equation}
\end{enumerate}

\label{prop.ideal.membership.altalg}
Let $p \in \FF[x_1,\dots,x_n]$ be a multilinear polynomial, let $K,L \subseteq [n]$ be disjoint subsets with $|K|=k$ and $|L|=l$, and $\Delta \in \N$. Let $c_{K,L}$ denote the coefficient of $v^L$ in $\bdry_{\mu_K(\alpha)\alpha^{\Delta} \wedgecdots \mu_K(\alpha)\alpha^0}(\Srepr^{-1}(p))$, and $e_{K,L}$ denote the value of $\PartialZero{L}{K}{p}$
upon the substitution $x_i\gets \mu_K(a_i)/\mu_L(a_i)$ for $i \in [n]\setminus (K \sqcup L)$. Then $c_{K,L} = e_{K,L} / \Adet{L}$.

\label{def:orig-IPS}
	Let $f_1(\vx),\ldots,f_m(\vx)\in\F[x_1,\ldots,x_n]$ be a system of polynomials. An \demph{IPS refutation} for showing that the polynomials $\{f_j\}_j$ have no common solution in $\bits^n$ is an algebraic circuit $C(\vx,\vy,\vz)\in\F[\vx,y_1,\ldots,y_m,z_1,\ldots,z_n]$, such that
	\begin{enumerate}
		\item $C(\vx,\vnz,\vnz) = 0$.
		\item $C(\vx,f_1(\vx),\ldots,f_m(\vx),x_1^2-x_1,\ldots,x_n^2-x_n)=1$.
	\end{enumerate}
	The \demph{size} of the IPS refutation is the size of the circuit $C$. If $C$ is of individual degree $\le 1$ in each $y_j$ and $z_i$, then this is a \demph{linear} IPS refutation (called \emph{Hilbert} IPS by Grochow-Pitassi~\cite{GrochowPitassi14}), which we will abbreviate as \lIPS. If $C$ is of individual degree $\le 1$ only in the $y_j$ then we say this is a \lbIPS refutation. If $C$ comes from a restricted class of algebraic circuits $\cC$, then this is a called a $\cC$-IPS refutation, and further called a $\cC$-\lIPS refutation if $C$ is linear in $\vy,\vz$, and a $\cC$-\lbIPS refutation if $C$ is linear in $\vy$.

\label{thm:GrochowPitassi14}
	Let $\varphi=C_1\wedge\cdots\wedge C_m$ be an unsatisfiable CNF on $n$-variables, and let $f_1,\ldots,f_m\in\F[x_1,\ldots,x_m]$ be its encoding as a polynomial system of equations. If there is a size-$s$ Frege proof (resp.\ Extended Frege) that $\{f_j\}_j,\{x_i^2-x_i\}_i$ is unsatisfiable, then there is a formula-\lIPS (resp.\ circuit-\lIPS) refutation of size $\poly(n,m,s)$ that is checkable in randomized $\poly(n,m,s)$ time.\footnote{We note that Grochow and Pitassi~\cite{GrochowPitassi14} proved this for Extended Frege and circuits, but essentially the same proof relates Frege and formula size.} 

	Further, $\{f_j\}_j,\{x_i^2-x_i\}_i$ has a \lIPS refutation, where the refutation uses multilinear polynomials in $\VNP$.  Thus, if every IPS refutation of $\{f_j\}_j,\{x_i^2-x_i\}_i$ requires formula (resp.\ circuit) size $\ge s$, then there is an explicit polynomial (that is, in $\VNP$) that requires size $\ge s$ algebraic formulas (resp.\ circuits).

We obtain the following lower bounds for subclasses of IPS.

\begin{itemize}
	\item In characteristic zero, the system of polynomials $x_1\cdots x_n,x_1+\cdots+x_n-n,\{x_i^2-x_i\}_{i=1}^n$ is unsatisfiable, and any $\sumpowsum$-IPS refutation requires $\exp(\Omega(n))$-size.

	\item In characteristic $>n$, the system of polynomials, $\prod_{i<j}(x_i+x_j-1),x_1+\cdots+x_n-n,\{x_i^2-x_i\}_i$ is unsatisfiable, and any roABP-IPS refutation (in any variable order) must be of size $\exp(\Omega(n))$.
		\qedhere
\end{itemize}

\label{defn:generator}
	Let $\cC\subseteq\F[x_1,\ldots,x_n]$ be a set of polynomials.  A polynomial $\cvG:\F^\ell\to\F^n$ is a \demph{generator for $\cC$} with \demph{seed length $\ell$} if for all $f\in\cC$,
	$f\equiv 0 \text{ iff } f\circ \cvG\equiv 0$. That is, $f(\vx)=0$ in $\F[\vx]$ iff $f(\cvG(\vy))=0$ in $\F[\vy]$.

\label{fact:roABP:closure}
	If $f,g\in\F[\vx]$ are computable by width-$r$ and width-$s$ roABPs respectively, then
	\begin{itemize}
		\item $f+g$ is computable by a width-$(r+s)$ roABP\@.
		\item $f\cdot g$ is computable by a width-$(rs)$ roABP\@.
	\end{itemize}

	\noindent Further, roABPs are also closed under the follow operations.
	\begin{itemize}
		\item If $f(\vx,\vy)\in\F[\vx,\vy]$ is computable by a width-$r$ roABP in some variable order then the partial substitution $f(\vx,\vaa)$, for $\vaa\in\F^{|\vy|}$, is computable by a width-$r$ roABP in the induced order on $\vx$, where the degree of this roABP is bounded by the degree of the roABP for $f$.
		\item If $f(z_1,\ldots,z_n)$ is computable by a width-$r$ roABP in variable order $z_1<\cdots<z_n$, then $f(x_1y_1,\ldots,x_ny_n)$ is computable by a $\poly(r,\ideg f)$-width roABP in variable order $x_1<y_1<\cdots<x_n<y_n$.
	\end{itemize}
	Further, these operations preserve the explicitness of the roABPs up to polynomial factors in all relevant parameters.

\label{thm:read-k-eval-dim}
	Let $f \in \F[x_1, \ldots, x_n]$ be a polynomial computed by a width-$w$ read-$k$ oblivious ABP\@. Then there exists a partition $\vx=(\vu,\vv,\vw)$ such that
	\begin{enumerate}
		\item $|\vu|, |\vv| \ge n/k^{O(k)}$.
		\item $|\vw| \le n/10$.
		\item $\dim_{\F(\vw)} \coeffs{\vu|\vv}(f_\vw) \le w^{2k}$, where $f_\vw$ is $f$ as a polynomial in $\F(\vw)[\vu,\vv]$.
			\qedhere
	\end{enumerate}

\label{res:h-ips_v_ips}
	Let $f_1,\ldots,f_m\in\F[x_1,\ldots,x_n]$ be unsatisfiable polynomials with an IPS refutation $C\in\F[\vx,y_1,\ldots,y_m]$.  Then $f_1,\ldots,f_m$ have a linear-IPS refutation $C'\in\F[\vx,\vy]$ under the following conditions.
	\begin{enumerate}
		\item Suppose $f_1,\ldots,f_m,C$ are computed by size-$s$ formulas, have degree at most $d$, and $|\F|\ge d+1$. Then $C'$ is computable by a $\poly(s,d,m)$-size formula of depth-$O(D)$, and $C'$ is $\poly(s,d,m)$-explicit given $d$ and the formulas for $f_1,\ldots,f_m,C$.
