[Informal version of \Cref{thm:main_qpf}]
\label{thm:main_qpf_informal}
Assuming SETH (resp. QSETH), approximating the quantum partition function for 3-local Hamiltonians to within any constant relative error cannot be done by any classical algorithm in time $O\bigl(2^{n(1-\varepsilon)}\bigr)$ (resp. quantum algorithm in time $O\bigl(2^{n(1-\varepsilon)/2}\bigr)$) for any constant $\varepsilon > 0$.

\label{def:klocalH}
We say a Hamiltonian $H$ acting on $n$ qubits is $k$-local if $H$ can be written as $H = \sum_{i=1}^m H_i$ for $m=\poly(n)$ and for all $i$, the following holds.
\begin{itemize}
    \item $H_i$ is a Hamiltonian.
    \item $H_i$ non-trivially acts on at most $k$ qubits.
    \item $\|H_i\|\le \poly(n)$.
\end{itemize}

\label{def:LHP}
The local Hamiltonian problem is a decision problem that asks whether the ground-state energy of a $k$-local Hamiltonian is greater or less than given energy thresholds.

\begin{itemize}
    \item \textbf{Inputs:} a $k$-local Hamiltonian $H$ such that acting on $n$ qubits where $k=O(1)$, and two energy thresholds $\EnergyYes,\EnergyNo$ satisfying $\EnergyNo-\EnergyYes\ge \Omega(1)$.
    \item  \textbf{Outputs:}
    \begin{itemize}
        \item YES, if there exists a quantum state $\ket{\psi}\in\mathbb{C}^{2^n}$ such that $\expec{\psi}{H}\le \EnergyYes$.
        \item NO, if $\expec{\psi}{H}\ge \EnergyNo$ for all $\ket{\psi}\in\mathbb{C}^{2^n}$.
    \end{itemize}
\end{itemize}
In other words, the $\kLH$ problem asks to decide whether $\lambda(H)\le \EnergyYes$ or $\lambda(H)\ge \EnergyNo$.
We say an algorithm $\mathcal{A}_{\LH}$ solves $\kLH(H, \EnergyYes, \EnergyNo)$ if $\mathcal{A}_{\LH}$ decides $(H,\EnergyYes,\EnergyNo)$ correctly.

\label{def:QPF}
The quantum partition function problem is to approximate the partition function of a $k$-local Hamiltonian up to a multiplicative error under a certain temperature.
\begin{itemize}
    \item \textbf{Inputs:} a $k$-local Hamiltonian $H$ acting on $n$ qubits where $k=O(1)$, an inverse temperature $\beta\le \poly(n)$, and an error parameter $\delta\in(0,1)$.
    \item \textbf{Outputs:} $\zout\in\mathbb{R}$ such that
    \begin{equation}
        (1-\delta)Z \leq \zout \leq (1+\delta)Z,
    \end{equation}

    where $Z:= \tr[e^{-\beta H}]$.
    \end{itemize}
    We say an algorithm $\mathcal{A}_{\QPF}$ solves $\kQPF(H, \beta, \delta)$ if $\mathcal{A}_{\QPF}$ outputs such $\zout$ on the inputs $H, \beta, \delta$.

\label{def:kCNF}
Let $\Phi$ be a Boolean formula that consists of $n$ variables $x_1,x_2,\dots, x_k$.
We say $\Phi$ is a $k$CNF formula if $\Phi$ is in the form of $m=\poly(n)$ smaller formulas connected by $\wedge$.
Each smaller formula contains at most $k$ variables, and the variables are connected by $\vee$.

To be more precise, $\Phi=\varphi_1\wedge \varphi_2 \wedge\cdots \wedge \varphi_m$ where $m=\poly(n)$, and for all $i\in [m]$, the following constrains hold.
\begin{itemize}
    \item $\varphi_{i} = (\ell_{i,1}\vee \ell_{i_2}\vee\cdots\vee\ell_{i,k_{i}})$, where $\ell_{i,p}$ can be $x_j$ or $\neg x_j$ for all $p\in[k_i]$ and $j\in[n]$.
    \item $k_i\le k$.
    \item For each $j\in[n]$, $x_j$ and $\neg x_j$ do not appear in $\varphi_i$ at the same time;
    $x_j$, $\neg x_j$ appears in $\varphi_i$ at most once.
\end{itemize}
We say $\varphi_i$ is a clause of $\Phi$ for all $i\in[m]$.

\label{def:kSAT}
The satisfiability problem is a decision problem that asks whether there is an assignment satisfying the given $k$CNF formula.
\begin{itemize}
    \item \textbf{Inputs:} a $\kCNF$ formula $\Phi$ that contains $n$ variables. The number of clauses of $\Phi$ is $m=\poly(n)$.
    \item \textbf{Outputs:}
    \begin{itemize}
        \item YES, if there exists an assignment $x\in\{0,1\}^n$ such that $\Phi(x)=1$.
        \item No, if $\Phi(x)=0$ for all $x\in\{0,1\}^n$. 
    \end{itemize}
\end{itemize}
We say an algorithm $\mathcal{A}_{\SAT}$ solves $\kSAT(\Phi)$ if $\mathcal{A}_{\SAT}$ decides $\Phi$ correctly.

\label{theorem:main}
    Let $x \in \{0,1\}^n$ be an input and $U_x$ be a $\QMA$ verification quantum circuit $U_x$ acting on $N$ qubits, and suppose $U_x$ consists of $T = \poly(n)$ gates. Then, for any integer $d\geq1$, there exists a $(d+1)$-local Hamiltonian $H_x$ acting on $N+O(T^{1/d})$ qubits and $\norm{H_x} \leq \poly(n)$ such that for all $\cerr\in(0,1)$, the following two hold.
    \begin{itemize}
        \item If there exists a quantum proof $\ket{\psi}$ such that $\Pr[U_x \,\mathrm{accepts}\, \ket{\psi}] \ge 1-\cerr$, then $\lambda(H_x) \le \cerr$.
        \item If $\Pr[U_x \,\mathrm{accepts}\, \ket{\psi}]\le \cerr$ for any quantum proof $\ket{\psi}$, then $\lambda(H_x) \ge \frac{1}{2}-\cerr$.
    \end{itemize}

\label{prop:KKR}
	If Conditions $(\textrm{C}_1)\sim(\textrm{C}_6)$ are satisfied, coefficients $\alpha_{\mathrm{in}}$, $\alpha_{\mathrm{out}}$, $\alpha_{A}$, $\alpha_{B}$, $\alpha_{\mathrm{clock}}$ can be chosen in the range $[0,\poly(n)]$ so that the following holds:
	\begin{itemize}
        \item If there exists a quantum proof $\ket{\psi}$ such that $\Pr[U_x \,\mathrm{accepts}\, \ket{\psi}] \ge 1-\varepsilon$, then $\lambda(H_x) \le \varepsilon$.
        \item If $\Pr[U_x \,\mathrm{accepts}\, \ket{\psi}]\le \varepsilon$ for any quantum proof $\ket{\psi}$, then $\lambda(H_x) \ge \frac{1}{2}-\varepsilon$.
    \end{itemize}

\label{def:Johnson}
Let $n,d\in\mathbb{N}$ and $d<n$. We say a Johnson graph $J(n,d)=(V,E)$ is a graph that satisfies the following requirement.
\begin{itemize}
    \item $V=\{S\subseteq[n]:|S|=k\}$.
    \item $E=\{(S,S')\in V^2:|S\cap S'|=k-1\}$.
\end{itemize}

\label{thm:SETH hardness for 3LH}
    Assume that SETH (resp. QSETH) holds.
    Then, for any constant $\xi>0$, for any classical (resp. quantum) algorithm $\mathcal{A}_{LH}$, there exists a $3$-local Hamiltonian $H$ acting on $n_H$ qubits associated with $\EnergyYes,\EnergyNo$ satisfying $\EnergyNo-\EnergyYes \geq \Omega(1)$ such that $\mathcal{A}_{\LH}$ cannot decide $\lambda(H)\geq \EnergyNo$ or $\lambda(H)\leq \EnergyYes$ with probability greater than $2/3$ in $O(2^{n_H(1-\xi)})$ (resp. $O(2^{n_H(1-\xi)/2})$) time.

\label{lem:U_compute_Phi}
For any positive integer $k$ and $c>0$, for all $n\in\mathbb{N}$, for any $\kCNF$ formula $\Phi$ that contains $n$ variables and $m=O(n^c)$ clauses, there exists a quantum circuit $U_\Phi$ that acts on $n$ input qubits and at most $2c\log n +2$ ancilla qubits, and $U_\Phi$ consists of at most $34c^2 n^c \log^2 n + (70k+2)n^c + 35c\log n$ elementary gates such that $U_{\Phi}\ket{x}\reg{in}\otimes\ket{0}\reg{anc}=\ket{\Phi(x)}\reg{out}\otimes\ket{\psi_x}\reg{\overline{out}}$ for all $x\in\{0,1\}^n$, where $\ket{\psi_x}$ is some quantum state depending on $x$.
The construction of $U_{\Phi}$ can be done in $\poly(n)$ time.\footnote{It is worth noting that an alternative quantum circuit for computing $k$CNF appears in~\cite{huang2020explicit}, Corollary 10. That construction has width $k + 2\bigl(\lceil \log n \rceil + \lceil c\log n \rceil\bigr)\text{ and size at most } 4 \times 3^{\lceil \log_2 n \rceil + \lceil c\log_2 n \rceil - 1}$. However, its circuit size is $O(n^{c+1})$, whereas ours is $O(n^{c}\log^2 n)$. This gap impacts the locality of the resulting Hamiltonian, which is why \cref{lem:U_compute_Phi} is necessary for our results.}

\label{thm:main_qpf}
Assume SETH (resp. QSETH) holds.
For any $\xi>0$ and any $\delta\in(0,1)$, 
for any quantum algorithm $\mathcal{A}_{\QPF}$, for infinitely many $n$,
there exists a $3$-local Hamiltonian $H$ acting on $n$ qubits, associated with an inverse temperature $\beta_0=O(n)$, such that for all $\beta\ge \beta_0$, the algorithm $\mathcal{A}_{\QPF}$ cannot solve $\QPF(H,\beta, \delta)$ in $O(2^{n(1-\xi)})$ classical time (resp. $O(2^{\frac{n}{2}(1-\xi)})$ quantum time) with probability greater than $2/3$.

\label{lem:Hsim}
    Given the description of a local Hamiltonian $H\in\mathbb{C}^{2^c\times 2^n}$, the evolution time $t\in \mathbb{R}^{+}$, the tolerated error $\varepsilon\in(0,1)$, there exists a quantum circuit $U_{\operatorname{sim}}(H,t,\varepsilon)$ running in $\poly(n,t,\log(\frac{1}{\varepsilon}))$ such that for any quantum state $\ket{\psi}\in\mathbb{C}^{2^n}$, it holds that
    \begin{equation}\label{eq:sim}
        \|(U_{\operatorname{sim}}(H,t,\varepsilon)-e^{-iHt}\otimes I)\ket{\psi}\otimes\ket{0^{a_{\operatorname{sim}}}}\|_2\le\varepsilon,
    \end{equation}
    where $a_{\operatorname{sim}}$ is the number of ancilla qubits of $U_{\operatorname{sim}}(H,t,\varepsilon)$.

\label{lem:energy_estimation}
    Let $H\in\mathbb{C}^{2^n\times 2^n}$ be a Hamiltonian acting on $n$ qubits and $\delta E = 1/\poly(n)$ be the tolerated error.
    There exists a energy estimation circuit $U_{\operatorname{EE}}(H,\delta E)$ that runs in $\poly(n)$ time.

\label{lem:amplitude_estimation}
    Let a quantum circuit $U$ taking a $n$-qubit input state $\ket{\psi}$ satisfy $U\ket{\psi}\ket{0^a}
    =\sqrt{\frac{M}{N}}\ket{1}\ket{\xi^1} 
    + \sqrt{\frac{N-M}{N}}\ket{0}\ket{\xi^0}$,
    where $N=2^n$, $M\le N$\footnote{Actually it requires that $M<N/2$. We can overcome this issue by adding an additional qubit.}, and $a$ is the number of ancilla qubits.

    If $U$ runs in $\poly(n)$ time and $\ket{\psi}$ can be prepared in $\poly(n)$ time,
    then for any $c\in\mathbb{N}$, there is a quantum circuit that runs in $O(\poly(n)\cdot 2^{\frac{n}{2}})$ times outputs $\widetilde{M}$ such that $(1-\Theta(\frac{1}{n^c}))M\le\widetilde{M}\le(1+\Theta(\frac{1}{n^c}))M$ with probability $1-\negl(n)$.

\label{lem:choi}
    For any complete orthogonal basis of $n$-qubit system $\{\ket{\psi_i}\}_{j=1}^{N}$,i.e., $\sum_{j=1}^{N}\proj{\psi_j}=I$ and $\inner{\psi_j}{\psi_{j'}}=\delta_{j,j'}$ where $N=2^n$, it holds that
    \begin{equation}
        \sum_{j=1}^{N}\sqrt{\frac{1}{N}}\ket{\psi_j}\ket{\psi_j^{\ast}} = \sum_{k=1}^{N}\sqrt{\frac{1}{N}}\ket{k}\ket{k}.
    \end{equation}
    where $\ket{\psi_j^\ast}$ is the complex conjugate of $\ket{\psi_j}$.

\label{prob: plethysm}\
\begin{description}
    \item[~~~Input:]
    Three partitions~$\lambda$, $\mu$, $\nu$, encoded as lists of positive integers, in unary.
    \item [~~~Task:]   Compute the plethysm coefficient $a^\la_{\mu,\nu}$.
\end{description}

\label{thm:plethysm}
\cref{prob: plethysm} is in $\#\BQP$.
As a consequence, the problem of deciding if a plethysm coefficient is positive, $a^\lambda_{\mu\nu} > 0$, is in $\QMA$.

\label{thm: general}
    Computing branching multiplicities for products of general linear groups (\cref{prob:branching_computational}) is in $\#\BQP$.
    As a consequence, deciding their positivity is in $\QMA$.

\label{prob:branching_computational}
\
\begin{description}
    \item[~~~Input:]
    \
    \begin{itemize}
        \item The specification of the groups $H = \GL(n_1) \times \dots \times \GL(n_\h)$ and $G=\GL(d_1)\times\cdots\times\GL(d_\g)$
        \footnote{In fact, we will see that the dimensions $d_1,\dots,d_\g$ can be inferred from the specification of the group homomorphism, as such they need not be specified explicitly in this step, and we can assume that they are not given to our quantum algorithm.}
        \item The specification of a group homomorphism $\varphi \colon H \to G$
        \item The specification of irreducible representations $\irr{\vla}{H}$ and $\irr{\vmu}{G}$ for $H$ and $G$ respectively
    \end{itemize}
    \item [~~~Task:]   Compute the branching multiplicity $m_{\vmu,\vla}$, defined as the multiplicity of the irreducible module $\irr{\vla}{H}$ in the restriction $\{\vmu\}\restr$ along the group homomorphism~$\varphi \colon H \to G$~(\cref{eq:restr repeat}).
\end{description}

\label{def:specification}
Given $H=\GL(n_1)\times\cdots\times\GL(n_\h)$ and $G=\GL(d_1)\times\cdots\times\GL(d_\g)$, we will specify a group homomorphism by the following data:
\begin{itemize}
\item natural numbers~$t_i \in \N$ for $i\in\{1,\dots,\g\}$.
\item natural number~$m_{ij} \in \N$ for $i\in\{1,\dots,\g\}$ and $j\in\{1,\dots,t_i\}$, and
\item partition tuples $\vnu(i,j) \in \mathcal P_{n_1} \times \dots \times \mathcal P_{n_\h}$ for $i\in\{1,\dots,\g\}$ and $j\in\{1,\dots,t_i\}$
\end{itemize}
such that $d_i = \sum_{j=1}^{t_i} m_{ij} \dim \{\vnu(i,j)\}_H$.
This data determines a group homomorphism $\varphi \colon H \to G$, as follows:
For $i=1,\dots,\g$, define the $H$-modules $V_i := \bigoplus_{j=1}^{t_i} \{\vnu(i,j)\}_H \ot \C^{m_{ij}}$. Identify~$V_i \cong \C^{d_i}$, to obtain group homomorphisms $\varphi_i \colon H \to \GL(d_i)$, and define $\varphi := (\varphi_1,\dots,\varphi_\g)$.

\label{def: QMA}
    A language (with promise) $L \subseteq \{0,1\}^*$ is in the complexity class $\QMA$ if there exists an uniform family of polynomial-time quantum circuits
    $\{V_n\}_{n\in\N}$ and a polynomial $p(n)$ such that for any input string $x$ of length $n$ respecting the promise:
    \begin{align*}
        &\forall x \in L, \quad \exists \ket{\psi}\in (\C^2)^{\ot p(n)} : \Pr[V_n(\ket{x}, \ket{\psi}) \text{ accepts}] \geq \frac{2}{3},
        \\
        &\forall x \notin L, \quad \forall \ket{\psi}\in(\C^2)^{\ot p(n)} : \Pr[V_n(\ket{x}, \ket{\psi}) \text{ accepts}] \leq \frac{1}{3}.
    \end{align*}

\label{def: count BQP}
 A (partial) function $f: \{0,1\}^* \to \mathbbm{N}$ is in $\#\BQP$ if there exists a uniform family of polynomial-size quantum circuits $\{V_n\}_{n\in \N}$ and a polynomial $p(n)$ such that for any input string $x$ of length $n$, the witness space for $V_n$ being $\mathcal{H}=(\C^2)^{\ot p(n)}$ decomposes as
 \[
\mathcal{H}=\mathcal{H}_{\text{acc}}(x)\op \mathcal{H}_{\text{rej}}(x),
 \]
 with $\dim \mathcal{H}_{\text{acc}}(x)= f(x)$ and
 \begin{align*}
     &\forall \ket{\psi}\in \mathcal{H}_{\text{acc}}(x)\quad \Pr[V_n(\ket{x},\ket{\psi})\ \text{accepts}]\ge \frac{2}{3},\\
     &\forall \ket{\psi}\in\mathcal{H}_{\text{rej}}(x)\quad \Pr[V_n(\ket{x},\ket{\psi})\ \text{accepts}]\leq \frac{1}{3}.
 \end{align*}

\label{thm:main}
For any $\delta\in (0,1-\Omega(1/\poly(n)))$, constant $k \geq 2$ and some integer $0\leq c \leq \mathcal{O}(poly(n))$, there exist $a,b\in [-1,1]$ with $b-a\in \Omega(1/\poly(n))$ such that k-$\text{GLHLE}$ is $\BQP$-hard.
Moreover, it is still $\BQP$-hard if the 2-local Hamiltonian is restricted to any of the following families of Hamiltonians:
\begin{itemize}
    \item non-2SLD Hamiltonian on a 2D square lattice
    \item antiferromagnetic Heisenberg model
    \item antiferromagnetic $XY$ model on a 2D triangular lattice.
\end{itemize}

\label{lemma:sampling}
    Given the description of an $m$-qubit semi-classical encoded state $\ket{u}$, we can classically efficiently sample from the probability distribution
   that outputs $x\in\{0,1\}^m$ with probability $|\langle x|u\rangle|^2$.

 [Guided Local Hamiltonian Low Energy] $\glh$
\label{def:GLHLE}
\begin{description}
\item[Input:] A $k$-local Hamiltonian $H$ on $n$ qubits such that $\|H\|\leq 1$ and the description of a semi-classical encoded state $\ket{u}\in \mathbb{C}^{2^n}$, a constant $c\in \mathbb{N}_\geq{0}$.
\item[Promise:]  $\|\Pi_{c}\ket{u}\|^2 \geq \delta$,
where $\Pi_{c}$ denotes the projection on the subspace spanned by the $c$th eigenstates, ordered in order of non-decreasing energy, of $H$, and either $\lambda_c(H) \leq a$ or $\lambda_c(H) \geq b$ holds.
\item[Goal:] Decide whether $\lambda_c(H)\leq a$ or $\lambda_c(H) \geq b$.
\end{description}

\label{proposition:overlap}
For any $\delta\in (0,1-\Omega(1/\poly(n)))$, there exist $a,b\in [0,1]$ with $b-a\in \Omega(1/\poly(n))$ such that the problem $\text{GLHLE}(5,0,a,b,\delta)$ is $\BQP$-hard.
Moreover, it is still $\BQP$-hard with the additional two promises that
\begin{enumerate}
    \item $H$ has a non-degenerate ground state separated from the first excited state by a spectral gap $\gamma\in \Omega(1/\poly(n))$ in both the cases $\lambda_0(H) \leq a$ and $\lambda_0(H) \geq b$.(We call such instances $\gamma$-gapped $\GLHdes(k,a,b,\delta)$.)
    \item  The guiding state is restricted to be a semi-classical subset state.
\end{enumerate}

\label{proposition:Low Enery states}
 For any $\delta \in \Omega(0,1-1/\text{poly}(n))$ there exist $a,b \in [-1,1]$ with $b-a \in \Omega(1/\text{poly}(n))$ and some number $0 \leq c \leq \text{poly}(n)$ such that $\text{GLHLE}(6,c,a,b,\delta)$ is \BQP-hard even when,
 \begin{enumerate}
     \item the $c$'th eigenvalue of $H$, $\lambda_c(H)$, is non-degenerate and is separated by a gap $\gamma \in \Omega(1/\text{poly}(n))$ from both $\lambda_{c-1}(H)$ and $\lambda_{c+1}(H)$. (We call such instances $\gamma$-gapped \\$\text{GLHLE}(k,c,a,b,\delta)$.)
     \item The guiding state is restricted to be a semi-classical subset state.
 \end{enumerate}

\label{def:approxsimulation}
We say that an $m$-qubit Hamiltonian $H'$ is a $(\Delta,\eta,\epsilon)$-simulation of an $n$-qubit Hamiltonian $H$ if there exists a local encoding $\mathcal{E}(M)=V(M\otimes P+ \bar{M}\otimes Q)V^\dagger$ such that
\begin{enumerate}
    \item There exists an encoding $\Tilde{\mathcal{E}}(M)=\tilde{V}(M\otimes P+ \bar{M}\otimes Q)\tilde{V}^\dagger$ such that
    $\tilde{\mathcal{E}}(\mathbbm{1})=P_{\leq \Delta(H')}$ and $\|\tilde{V}-V\|\leq \eta$, where $P_{\leq \Delta(H')}$ is the projector onto the subspace spanned by eigenvectors of $H'$ with eigenvalue below $\Delta$,
    \item $\|H'_{\leq \Delta}-\tilde{\mathcal{E}}(H)\|\leq \epsilon$, where $H'_{\leq \Delta}\coloneqq P_{\leq \Delta(H')}H'$.
\end{enumerate}
Here, $V$ is a local isometry that can be written as $V=\bigotimes_iV_i$ where each $V_i$ is an isometry acting on at most 1 qubit, and $P$ and $Q$ are locally orthogonal projectors (i.e. for all $i$ there exist orthogonal projectors $P_i$ and $Q_i$ acting on the same subsystem as $V_i$ such that $P_iQ_i=0$, $P_iP=P$ and $Q_iQ=Q$) such that $P+Q=I$, and $\bar{M}$ is the complex conjugate of $M$.
Moreover, we say that the simulation is efficient if $m$ and $\|H'\|$ are at most $\mathcal{O}(\poly(n,\eta^{-1},\epsilon^{-1},\Delta))$, and the description of $H'$ can be computable in $\poly(n)$ time given the description of $H$.

 Given tensors $\psi \in V_1\otimes \cdots \otimes V_k$ and $\phi\in W_1\otimes \cdots \otimes W_k$, we say that $\psi$ can be transformed into $\phi$ via SLOCC operations, if there exist linear transformations $A_i : V_i \to K_i$ such that $\phi = (A_1 \otimes \cdots \otimes A_k)\psi$; and we write $\psi \xrightarrow{\mathrm{SLOCC}} \phi$.
Define
\begin{align*}
\omega_n(\psi,\phi) &= \frac{1}{n} \inf\{m \in \NN_{\geq1} \mid \psi^{\otimes m} \xrightarrow{\mathrm{SLOCC}} \phi^{\otimes n}\}\\
\shortintertext{and}
\omega(\psi,\phi) &= \lim_{n\to\infty}\omega_n(\psi,\phi).
\end{align*}

\label{def:oneconnected}
Let $G = (\mu,V)$ be a $k$-player game with question set $\X = \X^1 \times \cdots \X^k$. The \textbf{$(k-1)$-connection graph of $G$} is the weighted graph $H_G = (V_H, \rho)$ with vertex set $V_H = \X$ and weight function $\rho: \X \times \X \to [0,1]$, defined as follows: for every $x,x' \in \X$,
\begin{align*}
	\rho(x, x') = \left \{ \begin{array}{ll}
		 \frac{1}{k}~ \P_{X}(x) \left [ \sum_{t\in[k]} \P_{X^t | x^{\mt}}(x^t)\right ] 	& \mbox{ if } x = x',\\

	\frac{1}{k}~ \P_{X^\mt}(x^\mt) \cdot \P_{X^t|x^{\mt}} (x^{t})\cdot \P_{X^t|x^{\mt}} (x'^t) &  \mbox{ if $\exists \, t$ s.t. } x^{\mt} = x'^{\mt} \mbox{, } x^t \neq x'^t ,\\
		0 & \mbox{ otherwise. }
	\end{array}
\right.
\end{align*}

 Let $H$ be a weighted graph where $\rho(u,v) \leq 1$ is the weight between vertices $u$ and $v$.  The normalized Laplacian $L_H\in \R ^{|V| \times |V|}$ of $H$ is defined to be
\begin{align*}
	(L_H)_{u,v} = \left \{ \begin{array}{ll}
		1 - \frac{\rho(u,v)}{\rho(v)} 	& \mbox{ if } u = v \mbox { and } \rho(v) \neq 0 \\
		- \frac{\rho(u,v)}{\sqrt{\rho(u)\rho(v)}} & \mbox { if } \rho(u),\rho(v) \neq 0 \\
		0 & \mbox{ otherwise }
	\end{array}
	\right.
\end{align*}
where $\rho(u) = \sum_v \rho(u,v)$ and $\rho(v) = \sum_u \rho(u,v)$.

\label{lem:r}
	\begin{align*}
	\frac{1}{m} \sum_i \, \sum_{x_i,\xhat_i \in \X} \rho(x_i,\xhat_i) \left \| \P_{R_\mi | x_i, W_S} - \P_{R_\mi | \xhat_i, W_S} \right \|_1 \leq O(\sqrt{\delta})
	\end{align*}
	where $\rho(\cdot,\cdot)$ is the weight function of the $(k-1)$-connection graph $H_G$.

\label{thm:cong-lb}
For any set of canonical paths $\mP$,
\[\lambda(H_G) \geq \frac{1}{\zeta(\mP)}\]

\label{def:quantum marginal}
Given a matrix $\rho$ acting on $\cH_S \otimes \cH_T$, where $\cH_S$ and $\cH_T$ are Hilbert spaces of dimensions $n_S$ and $n_T$, respectively (e.g., $\cH_S = \C^{n_S}$ and $\cH_T = \C^{n_T}$).
Then there is a unique matrix $\rho_S$ acting on $\cH_S$, called the \emph{quantum marginal} (or reduced density matrix) of $S$, such that
\begin{equation}\label{eq:rdm}
\tr \left[\left( M_S \otimes I_T\right) \rho\right] = \tr \left[ M_S \rho_S\right]
\end{equation}
for every $M_S$ acting on $\cH_S$.

\label{lem:single tensor factor}
If $n$ divides $m$ then the linear forms $p_{n,\pi}$ for $\pi\in S_m$ span the space of $\SL(n)$-invariant forms in $( ( \C^{n} )^{\ot m} )^*$.
If $n$ does not divide $m$ then no nonzero $\SL(n)$-invariant linear forms exist.

\label{def:ins}
Given a set $S\subseteq[n_1]\times\dots\times[n_d]$, we define its \emph{deficiency} as
\begin{align*}
  \defi(S) & := \max_{(a_{i,j}) \in \Gamma} \frac {\min_{(j_1,\dots,j_{d}) \in S}\left(\sum_{i=1}^{d} a_{i,j_i}\right)} {\sqrt{\sum_{i=1}^{d} \sum_{j=1}^{n_i} a_{i,j}^2}}.
\end{align*}
where we recall that the set $\Gamma$ was defined in \cref{eq:abelian 1PSG}.
We then define the \emph{instability} of a tensor~$X\in\Ten(n_0,\dots,n_d)$ by
\[ \ins(X) := \max_{\substack{U=(U_1,\dots,U_{d}) \text{ tuple}\\ \text{of unitary matrices}}} \defi(\supp(U \cdot X)), \]

\label{prb:eps-instability}
  For $\eps>0$, the problem \emph{$\eps$-instability} is defined as follows:
  Given a tensor $X\in\Ten(n_0,\dots,n_d)$ with integer coordinates such that either
  \begin{enumerate}
    \item $X$ is not in the null cone $($i.e., $\ins(X)\leq0)$, or
    \item $\ins(X)\geq\eps$,
  \end{enumerate}
  decide which is the case.

{lemma}{insvsds}\label{lem:ins vs ds}
For all tensors $X\in\Ten(n_0,\dots,n_d)$,
\[ \ins(X) \leq \sqrt{\dds(X)}. \]

For a reductive group~$G$ acting on a vector space~$V$, the Reynolds operator~$\RO$ is a $G$-invariant projection
\begin{align*}
\RO: \mathbb{C}[V] \rightarrow \mathbb{C}[V]^G.
\end{align*}
That is, it is a linear map satisfying the following properties for every polynomial $p \in \mathbb{C}[V]$:
\begin{itemize}
\item $\RO(p) = p$ if $p \in \mathbb{C}[V]^G$,

\item $\RO(g\cdot p) = \RO(p)$ for all $g \in G$.
\end{itemize}

\label{def:omega}
Given a polynomial $q$ in the variables
$(Z_{i,j})_{i,j=1}^m$, we define
\begin{align*}
\Omega(q) := \sum_{\sigma \in S_m}(-1)^{\sign(\sigma)} \frac{\partial^m q}{\partial Z_{1,\sigma(1)} \cdots \partial Z_{m,\sigma(m)}}.
\end{align*}
We also denote by $\Omega^r(q)$ the result of applying the differential operator~$\Omega$ $r$ times, starting with~$q$.

{\label{Omega_process}} Let $q$ be a homogeneous polynomial of degree $rm$ in the variables $(Z_{i,j})_{i,j=1}^m$ and $A \in \GL(m)$.
Then,
\begin{align*}
\Omega^r(A \star q) = \det(A)^r \cdot \Omega^r(q).
\end{align*}

\label{le:Cay-prop}

\begin{enumerate}
\item $c_{\ell t,m} :=\Omega^{\ell t}\big(\det(Z)^{\ell t} \big)$ is a nonzero constant.
\item For all $p \in \mathbb{C}[V]$, $\cR(p)$ is an $\SL(m)$-invariant polynomial.
\item For all $p \in \mathbb{C}[V]^{\SL(m)}$ we have $\cR(p) = c_{\ell t,m} \, p$.
\end{enumerate}

\label{lem:omega-coeff}
  Let $Z = (Z_{i,j})_{i,j=1}^m$ be a matrix of variables and $p(Z) \in \C[Z]$ be a polynomial of degree $d$ with integer coefficients whose absolute values are bounded by~$R$.
  Then the coefficients of $\Omega^s(p)$ have absolute value bounded by $R \,(d^m \,m!)^s$.

\label{thm:coefficient-bounds}
  The space $\C[V]^G_D$ of homogeneous invariants of degree $D$ is spanned by invariants with integer coefficients
        of absolute value at most~$L$, where
  \begin{align*}
   \ln L =O\left( dD \ln(Rn) +  \ell D \ln \Big(D \max_{i\ge 1} \ell_i n_i\Big) \right) .

  \end{align*}

  For the tensor action of~$G$ on $\Ten(n_0,\ldots, n_d)$, this bound becomes $O(d D \ln(D n))$.

\label{lem:degree bound}
The null cone of the $G$-representation~$V$ is the zero set of homogeneous $G$-invariant polynomials of degree
\begin{align*}
D
\leq \ell^{\sum_{i=1}^d (n_i^2 - 1)} \cdot \max_{i\ge 1} n_i^d
\leq \exp(2 d \ln(\ell) \cdot \max_{i\ge 1} n_i^2 ).
\end{align*}
For the tensor action of $G$ on $\Ten(n_0,\ldots, n_{d})$, the bound becomes $D \leq \exp(2 d \ln(d) \cdot \max_{i\ge 1} n_i^2).$

\label{def:QCMASPACEinformal}
    A promise problem $A=(\ayes,\ano)$ is in $\SQCMASPACE(p,q,r)$ for polynomially-bounded functions $p,q,r$, if there exist thresholds $\alpha(n),\beta(n)$ satisfying $\alpha(n)-\beta(n)\geq 2^{-r(n)}$, and a polynomial-space uniform family of quantum circuits $\set{Q_n}$ such that, for any input $x\in\Sigma^n$:
    \begin{itemize}
    \item If $x\in\ayes$, there exists a streaming proof $y\in\set{0,1}^{2^{p(n)}}$ such that $Q_n$ accepts $(x,y)$ with probability at least $\alpha$.
    \item If $x\in\ano$, then for all streaming proofs ${y}\in \set{0,1}^{2^{p(n)}}$, $Q_n$ accepts $(x,{y})$ with probability at most $\beta$.
    \end{itemize}

Given a $k$-local Hamiltonian $H$ with ground states $\ket\psi$ and $\ket\phi$ (represented succinctly via quantum circuits), and parameters $m,l$, does there exist a sequence of $l$-local unitaries $U_1,\dots,U_m$ such that:
\begin{enumerate}
    \item ($\ket\psi$ mapped to $\ket\phi$) $U_m\dotsm U_1\ket\phi \approx \ket\psi$, and
    \item (intermediate states have low energy) $\forall i\in[m], U_i\dotsm U_1 \ket\psi$ has low energy relative to $H$?
\end{enumerate}

\label{thm:qmaspace}
    $\SQMASPACE$ with $2^{\poly(n)}$ proof bits, $\poly(n)$ ancilla qubits, completeness $2/3$, and soundness $1/3$, equals \QMAEXP, i.e. $\SQMASPACE(\poly,\poly,1)=\QMAEXP$.
    With $\poly(n)$ proof bits, $O(\log(n))$, ancilla bits, it equals \QMA, i.e. $\SQMASPACE(\log,\log,0) = \QMA$.

{lemma}{theoremPathInterpolation}\label{l:path-interpolation}
    Set $d:=2^n$, and let $f:[0,1]\to S^{d-1}$ be a $K$-Lipschitz continuous path.
    For every $\epsilon > 0$, there exists a sequence of $M\in O((\frac{n^2d^2}{\epsilon})^{2n})$ $2$-local unitaries $U=U_M\cdots U_1$ which ``$\epsilon$-approximately simulates'' the path $f$ as follows. Define $\ket{\psi_t}=U_t\cdots U_1\ket{\psi_0}$ for $t\in\set{0,\ldots, M}$ and $\ket{\psi_0}:=f(0)$. Then, for all $t$,
    \begin{equation}\label{eqn:pointerror}
        \enorm{\ket{\psi_t}-f(t/M)}\leq \epsilon.
    \end{equation}

Let $p,q,r,m,\alpha,\beta:\R\mapsto\R$, where $p,q,r$ are poly-bounded. Let $Q$ be a quantum circuit consisting of $m$ $2$-qubit gates, taking in (1) input $x\in\Sigma^n$, (2) a classical streaming proof ${y}\in \set{0,1}^{2^{p}}$, and (3) $q$ ancilla qubits initialized to all zeroes. We are promised that either there exists a streaming proof $y$ causing $Q$ to accept with probability at least $\alpha$, or all streaming proofs are accepted with probability at most $\beta$, for $\alpha-\beta\geq 2^{-r}$. Then, there exists a poly-time many-one reduction from $(Q,x)$ to a Separable Sparse Hamiltonian $H$ instance with norm $\snorm{H}\in\poly(m,2^r)$, and with thresholds $\alpha',\beta'$, such that:
\begin{enumerate}
    \item $H$ acts on $O(q+\log m)$ qubits.
    \item The promise gap scales as $\abs{\alpha'-\beta'}\in\Omega\left(\frac{1}{m2^r}\right)$.
\end{enumerate}

\label{def:stream}
    Let $U$ be a quantum circuit acting on an $n_1$-qubit input register $R_1$, $n_2$-qubit ancilla register $R_2$, and $1$-qubit proof register $R_3$, for some $n_1,n_2>0$. Registers $R_2$ and $R_3$ are initialized to all zeroes. At a high level, the idea is to stream a classical proof in register $R_3$ one bit at a time. To do so, we view the entire execution of $U$ as a sequence of $1$- and $2$-qubit gates, but where certain $1$-qubit gates on $R_3$ are \emph{a priori} unknown. Formally:
    \begin{enumerate}
        \item There are two main phases in the circuit, which repeat until the circuit completes. In iteration $i$:
        \begin{enumerate}
            \item (Computation phase) A sequence of $1$- and $2$-qubit gates acts solely on registers $R_1$ and $R_2$.
            \item (Proof phase)
            \begin{enumerate}
                \item (Compute) Single-qubit gate $W_i\in\set{I,X}$ is applied to $R_3$, for $X$ the Pauli NOT gate. \label{step:proof1}
                \item (Copy) $R_3$ is classically copied into $R_2$ via CNOT gate (controlled from $R_3$ onto $R_2$).\label{step:proof2}
                \item (Uncompute) $W_i$ is applied to $R_3$ to return $R_3$ to $\ket{0}$.\label{step:proof3}
            \end{enumerate}
        \end{enumerate}
    \end{enumerate}

{definition}{definitionQCMASPACE}\label{def:QCMASPACE}
    A promise problem $A=(\ayes,\ano)$ is in $\SQCMASPACE(p,q,r)$ for polynomially-bounded functions $p,q,r$, if there exist thresholds $\alpha(n),\beta(n)$ satisfying $\alpha(n)-\beta(n)\geq 2^{-r(n)}$, and a $q(n)$-space uniform family of quantum circuits $\set{Q_n}$ with properties as follows. $Q_n$ takes as input a string $x\in\Sigma^n$, a classical streaming proof ${y}\in \set{0,1}^{2^{p(n)}}$, and $q(n)$ ancilla qubits in state $\ket{0}^{\otimes q(n)}$. We say $Q_n$ accepts $(x,y)$ with probability $p$ if on input $(x,y)$, measuring $Q_n$'s dedicated output wire in the standard basis yields $1$ with probability $p$. Then:
    \begin{itemize}
    \item (Completeness) If $x\in\ayes$, there exists a streaming proof $y\in\set{0,1}^{2^{p(n)}}$ such that $Q_n$ accepts $(x,y)$ with probability at least $\alpha$.
    \item (Soundness) If $x\in\ano$, for all streaming proofs ${y}\in \set{0,1}^{2^{p(n)}}$, $Q_n$ accepts $(x,{y})$ with probability at most $\beta$.
    \end{itemize}
    Finally, let the input, ancilla, and proof registers be denoted $R_1$, $R_2$, $R_3$ respectively. To enforce that $R_1$ and $R_3$ are not used as ancilla, we require that $Q_n$ only acts on $R_1$ and $R_3$ via CNOTs with the control in $R_1$ or $R_3$ and the target in $R_2$.

\label{def:sepsparse}
    Let $g:\N\mapsto\R$ be an efficiently computable function. Given as input a sparse Hamiltonian $H$, a bipartition $L$ versus $R$ of the $n$ qubits $H$ acts on, and threshold parameters $\alpha,\beta$ satisfying $\beta-\alpha\geq 1/g(n)$, decide:
    \begin{itemize}
        \item (YES case) If there exists $\LR$ such that $\RL H \LR\leq \alpha$, output YES.
        \item (NO case) If for all $\LR$, $\RL H \LR\geq \beta$, output NO.
    \end{itemize}

\label{def:QMAt}
    A promise problem $A=(\ayes,\ano)$ is in $\QMA(2,p,q,r)$ for polynomially bounded functions $p,q,r$ if there exist thresholds $\alpha(n),\beta(n)$ satisfying $\alpha(n)-\beta(n)\geq 2^{-r(n)}$, and a poly-time uniform family of quantum circuits $\set{Q_n}$ with properties as follows. $Q_n$ takes as input a string $x\in\Sigma^n$, a quantum proof $\ket{\psi_1}_L\otimes\ket{\psi_2}_R\in\C^{2^{p(n)}}\otimes \C^{2^{p(n)}}$, and $q(n)$ ancilla qubits in state $\ket{0}^{\otimes q(n)}$. We say $Q_n$ accepts $(x,y)$ with probability $p_{\textup{acc}}$ if on input $(x,\LR)$, measuring $Q_n$'s dedicated output wire in the standard basis yields $1$ with probability $p_{\textup{acc}}$. Then:
    \begin{itemize}
    \item (Completeness) If $x\in\ayes$, there exists a $\LR$ such that $Q_n$ accepts $(x,\LR)$ with probability at least $\alpha$.
    \item (Soundness) If $x\in\ano$, for all $\LR$, $Q_n$ accepts $(x,\LR)$ with probability at most $\beta$.
    \end{itemize}

{definition}{definitionSQMASPACE}\label{def:SQMASPACE}
  A promise problem $A=(\ayes,\allowbreak\ano)$ is in $\SQMASPACE(p,q,r)$ for polynomially-bounded functions $p,q,r$, if there exist thresholds $\alpha(n),\beta(n)$ satisfying $\alpha(n)-\beta(n)\geq 2^{-r(n)}$, and a $q(n)$-space uniform family of quantum circuits $\{Q_n\}$

  with properties as follows.
  $Q_n$ takes as input a string $x\in\Sigma^n$, a $2^{p(n)}$-qubit proof $\ket{\psi}$ in register $\Y$, a $q(n)$-bit ancilla register $\X$ initialized to $\ket{0}^{\otimes q(n)}$, and is of form (see \Cref{fig:sqma})
  \begin{equation}
    Q_n= \prod_{i=m}^1 \bigl((V_i)_\X\cdot\SWAP_{\X_1,\Y_i}\bigr)\cdot(V_0)_\X.
  \end{equation}
  Then,
  \begin{itemize}
    \item (Completeness) If $x\in\ayes$: $\exists\ket\psi\in\Y:\bra{0^q}\bra{\psi}\bigl(Q_n^\dagger\ketbra11_{\X_1}Q_n\bigr)\ket{0^q}\ket{\psi}\ge \alpha(n)$.
    \item (Soundness) If $x\in\ano$: $\forall\ket\psi\in\Y:\bra{0^q}\bra{\psi}\bigl(Q_n^\dagger\ketbra11_{\X_1}Q_n\bigr)\ket{0^q}\ket{\psi}\le \beta(n)$.
  \end{itemize}
  As in \Cref{def:QCMASPACE}, we do not allow $Q_n$ to alter the contents of its input register (to avoid using said register as additional ancilla space).

\label{def:QMAEXP}
    A promise problem $A=(\ayes,\ano)$ is in $\QMAEXP(p(n),q(n))$ for polynomially bounded functions $p, q$ if there exists an exponential time uniform family of quantum circuits $\set{Q_n}$ with properties as follows. $Q_n$ takes as input a string $x\in\Sigma^n$, a quantum proof $\ket{\psi_1}\in (\C^2)^{\otimes 2^{p(n)}}$, and ancilla qubits in state $\ket{0}^{\otimes 2^{q(n)}}$. We say $Q_n$ accepts $(x,\ket\psi)$ with probability $p_{\textup{acc}}$ if on input $(x,\ket\psi)$, measuring $Q_n$'s dedicated output wire in the standard basis yields $1$ with probability $p_{\textup{acc}}$. Then:
    \begin{itemize}
    \item (Completeness) If $x\in\ayes$, there exists a $\ket{\psi}$ such that $Q_n$ accepts $(x,\ket\psi)$ with probability at least $2/3$.
    \item (Soundness) If $x\in\ano$, for all $\ket\psi$, $Q_n$ accepts $(x,\ket\psi)$ with probability at most $1/3$.
    \end{itemize}

\label{def:1D-TIH}
    Fix a constant $d$. The input is the length of the chain $N$ encoded in binary, a single Hamiltonian constraint $H\in\Herm(\C^{d}\otimes \C^{d})$ specified with a constant number of bits, and polynomials $\alpha,\beta$ such that $\beta-\alpha\ge 1/\poly(N)$.
    The full Hamiltonian is thus $H^{(N)} := \sum_{i=1}^{N-1} H_{i,i+1}$ (i.e. $H$ acts on each pair of qudits on a line). Decide:
    \begin{itemize}
        \item (YES case) If $\lmin(H^{(N)})\le \alpha(N)$, output YES.
        \item (NO case)  If $\lmin(H^{(N)})\ge \beta(N)$, output NO.
    \end{itemize}

\label{def:mip}
    A promise problem $A=(\ayes,\ano)$ is in $\MIP(t,p,r,c,s)$ if there exist polynomial $t$ and polynomially bounded functions $u$ and $v$, and a classical verifier $V$ using $\poly(n)$ time, $u(n)$ space, $v(n)$ bits of randomness, and interacting with $p$ non-communicating provers via $r$ rounds of interaction, where each round consists of $t(n)$ bits of communication between verifier and provers, and where $n=\abs{x}$ is the size of input $x$, such that
    \begin{itemize}
        \item If $x\in \ayes$, then there exists a strategy for the provers that is accepted by the verifier with probability at least $c$.
        \item If $x\in \ano$, any strategy of the provers is accepted by the verifier with probability at most $s$.
    \end{itemize}

\label{thm:mipnexp}
    For any polynomial $r$,
    \begin{equation}
        \MIP(\poly, \poly, \poly, \poly, \poly, 2/3, 1/3)=\MIP(\poly,\poly, \poly, 2,1,1,2^{-r})=\NEXP.
    \end{equation}

\label{def:pcp}
    A language $L$ is in $\PCP[r(n),q(n)]$ if there exists verifier Turing machine $M$ that behaves as follows:
    \begin{enumerate}
        \item $M$ receives input $x$, a proof $y\in\bin^{*}$, and a random string $z\in\bin^{r(n)}$ on separate tapes.
        \item $M$ computes indices $i_1,\dots,i_{q(n)}$ without accessing $y$ (it may access $z$) in polynomial time.
        \item $M$ copies proof bits $y_{i_1},\dots,y_{i_{q(n)}}$ to its work tape.
        \item $M$ accepts or rejects in polynomial time without accessing $y$.
    \end{enumerate}
    $M$ must also satisfy the following conditions for all $x\in\bin^n$:
    \begin{itemize}
        \item If $x\in L$, $\exists y:\Pr_z[M(x,y,z)=1]=1$, where $z\in\bin^{r(n)}$ is chosen uniformly at random.
        \item If $x\notin L$, $\forall y:\Pr_z[M(x,y,z)=1]\le 1/2$.
    \end{itemize}

