	define \sLH{} as the problem $\kLH$ with the additional promise that any input is of the form $\sum_{i=1}^m w_i H_i$ where each $H_i$ is an element of $\calS$ assigned to act on some subset of qubits and the \emph{weights} $w_i \in \reals$ have magnitude polynomially-bounded in $n$.

\label{fact:local_rot}
  Let $H$ be a 2-qubit Hamiltonian term with Pauli decomposition
  $H=\sum_{i,j=1}^{3} M_{ij} \sigma_i \sigma_j + \sum_{k=1}^{3} \paren{v_k \sigma_k I
  + w_k I \sigma_k}$. For any single-qubit unitary $U$,
	\begin{equation}\label{eq:rot_pauli_decomp}
    U^{\otimes 2} H (U^\dagger)^{\otimes 2}=\sum_{i,j=1}^{3} (R M R^T)_{ij}
    \sigma_i  \sigma_j + \sum_{k=1}^{3}\paren{(Rv)_k \sigma_k I + (Rw)_k I
    \sigma_k}
	\end{equation}
  for some $R\in SO(3)$.  Likewise, for any $R\in SO(3)$, there exists a
  single-qubit $U$ such that the Pauli decomposition of $U^{\otimes 2} H
  (U^\dagger)^{\otimes 2}$ matches \cref{eq:rot_pauli_decomp}.

